// ─── Helper for Safe Token Extraction ──────────────────────────────────────────
function extractToken(req) {
  const authHeader = req.headers["authorization"] || "";
  let token = authHeader;
  
  if (authHeader.startsWith("Bearer ")) {
    token = authHeader.substring(7);
  } else if (authHeader.startsWith("AdminBearer ")) {
    token = authHeader.substring(12);
  }
  
  if (!token && req.query && req.query.token) {
    if (req.method === "GET" && (
      req.path.includes("/document") || 
      req.path.includes("/concierge-image") || 
      req.path.includes("/proxy") || 
      req.path.includes("/ws")
    )) {
      token = req.query.token;
    }
  }
  
  if (token) {
    token = token.replace(/^["']|["']$/g, '').trim();
  }
  return token;
}

// ─── Security Headers ──────────────────────────────────────────────────────────
app.use((req, res, next) => {
  res.setHeader("X-Content-Type-Options", "nosniff");
  if (req.path.includes("/api/zoho/document/") || req.path.includes("/api/concierge-image/") || req.path.includes("/document")) {
    res.removeHeader("X-Frame-Options");
    res.removeHeader("Content-Security-Policy");
  } else {
    res.setHeader("X-Frame-Options", "SAMEORIGIN");
  }
  res.setHeader("X-XSS-Protection", "1; mode=block");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  if (req.secure || req.headers["x-forwarded-proto"] === "https") {
    res.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
  }
  next();
});
app.use(express.json({ limit: "10mb" }));
app.use(express.urlencoded({ extended: true }));

