const ALLOWED_ORIGINS = [
  "https://deploy-3or5.onrender.com", "https://secureapp-nine.vercel.app",
  "https://*.vercel.app", "https://*.onrender.com",
  ...(PRODUCTION_URL ? [PRODUCTION_URL] : []),
  ...(NODE_ENV === "development" ? ["http://localhost:4000","http://localhost:3000","http://localhost:8081","exp://","exp+"] : []),
];
app.use(cors({
  origin(origin, cb) {
    if (!origin) return cb(null, true);
    if (origin.includes('localhost') || origin.includes('127.0.0.1')) return cb(null, true);
    if (ALLOWED_ORIGINS.some(o => origin === o || origin.startsWith(o) || origin.includes("vercel.app") || origin.includes("onrender.com"))) return cb(null, true);
    if (origin.startsWith("exp://") || origin.startsWith("exp+")) return cb(null, true);
    cb(null, true);
  },
  credentials: true,
  methods: ["GET","POST","OPTIONS","PUT","PATCH","DELETE"],
  allowedHeaders: [
    "Content-Type",
    "Authorization",
    "Accept",
    "X-Requested-With",
    "x-client-type",
    "x-app-version",
    "Cache-Control",
    "Pragma",
    "x-admin-token",
    "X-Admin-Token"
  ],
  exposedHeaders: ["Content-Disposition", "Content-Length", "Content-Type"],
}));
