// ─── SESSION RESTORE MIDDLEWARE ──────────────────────────────────────────────
app.use(async (req, res, next) => {
  if (!req.path.includes("/api/zoho/") && !req.path.includes("/api/auth/") && 
      !req.path.includes("/api/recruit/") && !req.path.includes("/api/messaging/") &&
      !req.path.includes("/api/documents/") && !req.path.includes("/api/pipeline/")) {
    return next();
  }

  const token = extractToken(req);
  if (!token) return next();
  if (userTokens.has(token)) return next();
  
  if (mongoConnected) {
    try {
      const session = await UserSession.findOne({ token });

      if (session) {
        const persistentExpiry =
          new Date("2099-12-31T23:59:59.999Z");

        await UserSession.findByIdAndUpdate(
          session._id,
          {
            $set: {
              status: "active",
              sessionExpiresAt:
                persistentExpiry,
              lastActive: new Date()
            }
          }
        );

        userTokens.set(token, {
          email: session.email,
          candidateName:
            session.candidateName,
          arrivalDate:
            session.arrivalDate || null,
          sessionExpiresAt:
            persistentExpiry.getTime(),
          createdAt:
            session.createdAt instanceof Date
              ? session.createdAt.getTime()
              : Date.now()
        });

        console.log(
          `[Auth] Restored persistent candidate session for ${session.email}`
        );
      }
    } catch (err) {
      console.error("[Auth] Failed to restore session from DB:", err.message);
    }
  }
  
  next();
});

// ─── Rate Limiting ─────────────────────────────────────────────────────────────
const rateLimitStore = new Map();
function rateLimit({ windowMs, max, keyFn, message }) {
  return (req, res, next) => {
    const key = keyFn(req), now = Date.now(), entry = rateLimitStore.get(key);
    if (!entry || now > entry.resetAt) { rateLimitStore.set(key, { count: 1, resetAt: now + windowMs }); return next(); }
    if (entry.count >= max) { res.setHeader("Retry-After", Math.ceil((entry.resetAt - now) / 1000)); return res.status(429).json({ success: false, message }); }
    entry.count++; next();
  };
}
setInterval(() => { const now = Date.now(); for (const [k, e] of rateLimitStore.entries()) if (now > e.resetAt) rateLimitStore.delete(k); }, 5 * 60 * 1000);

const otpRequestLimiter  = rateLimit({ windowMs:15*60*1000, max:5,  keyFn:(req)=>`otp:${(req.body?.email||"").toLowerCase().trim()}`, message:"Too many OTP requests. Please wait 15 minutes." });
const otpVerifyLimiter   = rateLimit({ windowMs:15*60*1000, max:10, keyFn:(req)=>`verify:${req.ip}`, message:"Too many verification attempts. Please wait 15 minutes." });
const loginLimiter       = rateLimit({ windowMs:15*60*1000, max:10, keyFn:(req)=>`login:${(req.body?.email||"").toLowerCase().trim()}`, message:"Too many login attempts. Please wait 15 minutes." });

