async function sendEmailViaBrevo(to, subject, html) {
  if (!brevoReady) return false;
  try {
    const toList = Array.isArray(to) ? to.map(e=>({email:e})) : [{email:to}];
    await axios.post("https://api.brevo.com/v3/smtp/email", 
      { sender:{name:"Infinity Care Partners",email:EMAIL_FROM}, to:toList, subject, htmlContent:html }, 
      { headers:{"api-key":BREVO_API_KEY,"Content-Type":"application/json",Accept:"application/json"}, timeout:10000 }
    );
    return true;
  } catch (err) { 
    const brevoError = err.response?.data ? JSON.stringify(err.response.data) : err.message;
    console.error(`[Brevo Error] Email send failed for ${JSON.stringify(to)}:`, brevoError); 
    return false; 
  }
}

