// Prevent multiple routes/components from independently forcing the same
// candidate back to Recruit. A live Recruit refresh is allowed at most once
// per configured interval unless a write explicitly invalidates the cache.
const recruitLiveRefreshAt = new Map();
const pipelineFieldStatusResponseCache = new Map();
const pipelineLiveRefreshAt = new Map();
const recruitRefreshInFlight = new Map();

let zohoQuotaBlockedUntil = 0;

// Small in-process queue to prevent many portal tabs from bursting Zoho at the
// same moment. This does not create extra API calls; it coalesces cached reads
// and spaces unavoidable live calls.
const ZOHO_MAX_CONCURRENT_REQUESTS =
  Math.max(
    1,
    Number(
      process.env
        .ZOHO_MAX_CONCURRENT_REQUESTS ||
      2
    )
  );

const ZOHO_MIN_REQUEST_GAP_MS =
  Math.max(
    0,
    Number(
      process.env
        .ZOHO_MIN_REQUEST_GAP_MS ||
      150
    )
  );

let zohoActiveRequestCount = 0;
let zohoLastRequestAt = 0;
const zohoRequestQueue = [];

function drainZohoRequestQueue() {
  while (
    zohoActiveRequestCount <
      ZOHO_MAX_CONCURRENT_REQUESTS &&
    zohoRequestQueue.length >
      0
  ) {
    const job =
      zohoRequestQueue.shift();

    zohoActiveRequestCount +=
      1;

    const waitMs =
      Math.max(
        0,
        ZOHO_MIN_REQUEST_GAP_MS -
          (
            Date.now() -
            zohoLastRequestAt
          )
      );

    setTimeout(
      async () => {
        zohoLastRequestAt =
          Date.now();

        try {
          const value =
            await job.fn();

          job.resolve(value);
        } catch (error) {
          job.reject(error);
        } finally {
          zohoActiveRequestCount -=
            1;

          drainZohoRequestQueue();
        }
      },
      waitMs
    );
  }
}

function runZohoQueued(fn) {
  return new Promise(
    (resolve, reject) => {
      zohoRequestQueue.push({
        fn,
        resolve,
        reject
      });

      drainZohoRequestQueue();
    }
  );
}

function normalizeCacheEmail(email) {
  return String(email || "")
    .trim()
    .toLowerCase();
}

function canPerformRecruitLiveRefresh(
  email,
  requested = false
) {
  if (!requested) {
    return false;
  }

  const key =
    normalizeCacheEmail(email);

  if (!key) {
    return false;
  }

  const last =
    recruitLiveRefreshAt.get(
      key
    ) ||
    0;

  return (
    Date.now() - last >=
    RECRUIT_MIN_LIVE_REFRESH_INTERVAL_MS
  );
}

function markRecruitLiveRefresh(
  email
) {
  const key =
    normalizeCacheEmail(email);

  if (key) {
    recruitLiveRefreshAt.set(
      key,
      Date.now()
    );
  }
}


function stableSerialize(value) {
  if (
    value === undefined ||
    value === null
  ) {
    return "";
  }

  if (typeof value !== "object") {
    return String(value);
  }

  if (Array.isArray(value)) {
    return JSON.stringify(
      value.map(stableSerialize)
    );
  }

  const ordered = {};
  for (
    const key of
    Object.keys(value).sort()
  ) {
    ordered[key] = value[key];
  }

  return JSON.stringify(ordered);
}

function getMemoryCacheEntry(
  map,
  key,
  ttlMs,
  {
    allowStale = false
  } = {}
) {
  const entry = map.get(key);
  if (!entry) return null;

  const age =
    Date.now() -
    entry.fetchedAt;

  if (age <= ttlMs) {
    return {
      ...entry,
      stale: false
    };
  }

  if (
    allowStale &&
    age <=
      ZOHO_STALE_CACHE_MAX_AGE_MS
  ) {
    return {
      ...entry,
      stale: true
    };
  }

  map.delete(key);
  return null;
}

function setMemoryCacheEntry(
  map,
  key,
  data
) {
  map.set(key, {
    data,
    fetchedAt: Date.now()
  });
}

function isZohoQuotaError(error) {
  const status =
    error?.response?.status;

  const bodyText =
    JSON.stringify(
      error?.response?.data ||
      {}
    ).toLowerCase();

  const message =
    String(
      error?.message || ""
    ).toLowerCase();

  return (
    status === 429 ||
    bodyText.includes("api_limit") ||
    bodyText.includes("api limit") ||
    bodyText.includes("quota") ||
    bodyText.includes("daily limit") ||
    bodyText.includes("request limit") ||
    message.includes("quota") ||
    message.includes("too many requests") ||
    message.includes("daily limit")
  );
}

function markZohoQuotaBlocked(error) {
  if (!isZohoQuotaError(error)) {
    return;
  }

  zohoQuotaBlockedUntil =
    Math.max(
      zohoQuotaBlockedUntil,
      Date.now() +
        ZOHO_QUOTA_COOLDOWN_MS
    );

  console.warn(
    `[Zoho Quota] Circuit open until ${new Date(
      zohoQuotaBlockedUntil
    ).toISOString()}. Serving cache where possible.`
  );
}

function isZohoQuotaCircuitOpen() {
  return (
    Date.now() <
    zohoQuotaBlockedUntil
  );
}

async function getPersistentApiCache(
  key,
  ttlMs,
  {
    allowStale = false
  } = {}
) {
  if (
    !mongoConnected ||
    !mongoose.connection?.db
  ) {
    return null;
  }

  try {
    const row =
      await mongoose.connection.db
        .collection(
          "zoho_api_cache"
        )
        .findOne({
          cache_key: key
        });

    if (!row) {
      return null;
    }

    const fetchedAt =
      new Date(
        row.fetched_at ||
        0
      ).getTime();

    const age =
      Date.now() -
      fetchedAt;

    if (age <= ttlMs) {
      return {
        data: row.data,
        fetchedAt,
        stale: false
      };
    }

    if (
      allowStale &&
      age <=
        ZOHO_STALE_CACHE_MAX_AGE_MS
    ) {
      return {
        data: row.data,
        fetchedAt,
        stale: true
      };
    }

    return null;
  } catch (error) {
    console.warn(
      "[API Cache] Mongo read failed:",
      error.message
    );
    return null;
  }
}

async function setPersistentApiCache(
  key,
  data,
  metadata = {}
) {
  if (
    !mongoConnected ||
    !mongoose.connection?.db
  ) {
    return;
  }

  try {
    await mongoose.connection.db
      .collection(
        "zoho_api_cache"
      )
      .updateOne(
        {
          cache_key: key
        },
        {
          $set: {
            cache_key: key,
            data,
            metadata,
            fetched_at: new Date(),
            updated_at: new Date()
          },
          $setOnInsert: {
            created_at: new Date()
          }
        },
        {
          upsert: true
        }
      );
  } catch (error) {
    console.warn(
      "[API Cache] Mongo write failed:",
      error.message
    );
  }
}

async function deletePersistentApiCacheByPrefix(
  prefix
) {
  if (
    !mongoConnected ||
    !mongoose.connection?.db
  ) {
    return;
  }

  try {
    const escaped =
      String(prefix).replace(
        /[.*+?^${}()|[\]\\]/g,
        "\\$&"
      );

    await mongoose.connection.db
      .collection(
        "zoho_api_cache"
      )
      .deleteMany({
        cache_key: {
          $regex:
            `^${escaped}`
        }
      });
  } catch (error) {
    console.warn(
      "[API Cache] Mongo invalidation failed:",
      error.message
    );
  }
}

async function readThroughZohoCache({
  key,
  ttlMs =
    ZOHO_READ_CACHE_TTL_MS,
  fetcher,
  metadata = {},
  bypassCache = false
}) {
  if (!bypassCache) {
    const memory =
      getMemoryCacheEntry(
        zohoReadCache,
        key,
        ttlMs,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (memory) {
      return memory.data;
    }

    const persistent =
      await getPersistentApiCache(
        key,
        ttlMs,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (persistent) {
      setMemoryCacheEntry(
        zohoReadCache,
        key,
        persistent.data
      );
      return persistent.data;
    }
  }

  if (
    isZohoQuotaCircuitOpen()
  ) {
    const stale =
      getMemoryCacheEntry(
        zohoReadCache,
        key,
        0,
        {
          allowStale: true
        }
      ) ||
      await getPersistentApiCache(
        key,
        0,
        {
          allowStale: true
        }
      );

    if (stale) {
      return stale.data;
    }

    const error =
      new Error(
        "Zoho API quota is exhausted and no cached data is available."
      );

    error.code =
      "ZOHO_QUOTA_CACHE_MISS";

    throw error;
  }

  if (
    zohoReadInFlight.has(key)
  ) {
    return zohoReadInFlight.get(
      key
    );
  }

  const promise = (async () => {
    try {
      const data =
        await fetcher();

      setMemoryCacheEntry(
        zohoReadCache,
        key,
        data
      );

      await setPersistentApiCache(
        key,
        data,
        metadata
      );

      return data;
    } catch (error) {
      markZohoQuotaBlocked(error);

      const stale =
        getMemoryCacheEntry(
          zohoReadCache,
          key,
          0,
          {
            allowStale: true
          }
        ) ||
        await getPersistentApiCache(
          key,
          0,
          {
            allowStale: true
          }
        );

      if (stale) {
        console.warn(
          `[API Cache] Serving stale cached response for ${key}.`
        );
        return stale.data;
      }

      throw error;
    } finally {
      zohoReadInFlight.delete(
        key
      );
    }
  })();

  zohoReadInFlight.set(
    key,
    promise
  );

  return promise;
}

function getCachedCandidateDetails(
  email
) {
  const key =
    normalizeCacheEmail(email);

  const entry =
    candidateDetailsCache.get(
      key
    );

  if (
    entry &&
    Date.now() -
      entry.fetchedAt <
      CANDIDATE_CACHE_TTL_MS
  ) {
    return entry.data;
  }

  return null;
}

async function getPersistentCandidateDetails(
  email,
  {
    allowStale = false
  } = {}
) {
  const key =
    normalizeCacheEmail(email);

  const cached =
    await getPersistentApiCache(
      `candidate:${key}`,
      CANDIDATE_CACHE_TTL_MS,
      {
        allowStale
      }
    );

  if (!cached) {
    return null;
  }

  candidateDetailsCache.set(
    key,
    {
      data: cached.data,
      fetchedAt:
        cached.fetchedAt
    }
  );

  return cached.data;
}

function setCachedCandidateDetails(
  email,
  data
) {
  const key =
    normalizeCacheEmail(email);

  candidateDetailsCache.set(
    key,
    {
      data,
      fetchedAt:
        Date.now()
    }
  );

  setPersistentApiCache(
    `candidate:${key}`,
    data,
    {
      type: "candidate",
      email: key
    }
  ).catch(() => {});
}

function invalidateCandidateDetailsCache(
  email
) {
  const key =
    normalizeCacheEmail(email);

  candidateDetailsCache.delete(
    key
  );

  if (
    typeof userDetailsCache !==
    "undefined"
  ) {
    userDetailsCache.delete(
      key
    );
  }

  deletePersistentApiCacheByPrefix(
    `candidate:${key}`
  ).catch(() => {});
}

setInterval(() => { const now = Date.now(); for (const [k, e] of candidateDetailsCache.entries()) if (now - e.fetchedAt >= CANDIDATE_CACHE_TTL_MS) candidateDetailsCache.delete(k); }, 15 * 60 * 1000);

