// ─── Bank-detail transport encryption ────────────────────────────────────────
// TLS remains mandatory in production. This additional envelope encryption keeps
// bank details unreadable to intermediaries and generic request/body loggers.
function normalizePem(value) {
  return value ? String(value).replace(/\\n/g, "\n").trim() : null;
}

let BANK_DETAILS_PRIVATE_KEY = normalizePem(process.env.BANK_DETAILS_PRIVATE_KEY);
let BANK_DETAILS_PUBLIC_KEY = normalizePem(process.env.BANK_DETAILS_PUBLIC_KEY);

if (!BANK_DETAILS_PRIVATE_KEY || !BANK_DETAILS_PUBLIC_KEY) {
  const generated = crypto.generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: { type: "spki", format: "pem" },
    privateKeyEncoding: { type: "pkcs8", format: "pem" }
  });
  BANK_DETAILS_PRIVATE_KEY = generated.privateKey;
  BANK_DETAILS_PUBLIC_KEY = generated.publicKey;
  console.warn("[Security] BANK_DETAILS_PRIVATE_KEY/PUBLIC_KEY not set; using an in-memory key pair for this server process.");
}

function decodeBase64Field(value, fieldName) {
  if (!value || typeof value !== "string") throw new Error(`Missing encrypted field: ${fieldName}`);
  return Buffer.from(value, "base64");
}

function decryptBankEnvelope(envelope) {
  if (!envelope || envelope.version !== 1 || envelope.algorithm !== "RSA-OAEP-256+A256GCM") {
    throw new Error("Unsupported or missing encrypted payload");
  }

  const aesKey = crypto.privateDecrypt(
    {
      key: BANK_DETAILS_PRIVATE_KEY,
      padding: crypto.constants.RSA_PKCS1_OAEP_PADDING,
      oaepHash: "sha256"
    },
    decodeBase64Field(envelope.encryptedKey, "encryptedKey")
  );

  if (aesKey.length !== 32) throw new Error("Invalid encrypted session key");

  const iv = decodeBase64Field(envelope.iv, "iv");
  const ciphertext = decodeBase64Field(envelope.ciphertext, "ciphertext");
  const authTag = decodeBase64Field(envelope.authTag, "authTag");
  if (iv.length !== 12 || authTag.length !== 16) throw new Error("Invalid encrypted payload parameters");

  const decipher = crypto.createDecipheriv("aes-256-gcm", aesKey, iv);
  decipher.setAuthTag(authTag);
  const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");
  return JSON.parse(plaintext);
}

