const guessTimeZone = (location) => {
  if (!location) return "UTC";
  const loc = String(location).toLowerCase();
  if (loc.match(/new york|jfk|ewr|lga|boston|bos|atlanta|atl|miami|mia|washington|iad|dca|philadelphia|phl|charlotte|clt|orlando|mco|detroit|dtw|toronto|yyz|ohio|cleveland/)) return "America/New_York";
  if (loc.match(/chicago|ord|mdw|dallas|dfw|houston|iah|hou|minneapolis|msp|austin|aus|nashville|bna|memphis/)) return "America/Chicago";
  if (loc.match(/denver|den|salt lake|slc/)) return "America/Denver";
  if (loc.match(/phoenix|phx/)) return "America/Phoenix";
  if (loc.match(/los angeles|lax|san francisco|sfo|seattle|sea|las vegas|las|san diego|san/)) return "America/Los_Angeles";
  if (loc.match(/london|lhr|lgw/)) return "Europe/London";
  if (loc.match(/dubai|dxb|abudhabi|auh|abu dhabi/)) return "Asia/Dubai";
  if (loc.match(/doha|doh/)) return "Asia/Qatar";
  if (loc.match(/amsterdam|ams|paris|cdg|frankfurt|fra|munich|muc/)) return "Europe/Amsterdam";
  if (loc.match(/manila|mnl|philippines/)) return "Asia/Manila";
  if (loc.match(/nairobi|kenya|nbo/)) return "Africa/Nairobi";
  return "UTC";
};

function formatAirportTime(dateStr, airportCity) {
  if (!dateStr || dateStr === "—") return "—";
  let cleanStr = String(dateStr).trim();
  cleanStr = cleanStr.replace(/(Z|[+-]\d{2}:\d{2})$/, "");
  if (cleanStr.includes(" ") && !cleanStr.includes("T")) cleanStr = cleanStr.replace(" ", "T");
  if (cleanStr.length === 16) cleanStr += ":00";
  const d = new Date(cleanStr + "Z");
  if (isNaN(d.getTime())) return dateStr;
  d.setUTCHours(d.getUTCHours() - 8);
  const tz = guessTimeZone(airportCity);
  let abbr = "";
  if (tz !== "UTC") {
    try {
      const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'short' }).formatToParts(d);
      const tzPart = parts.find(p => p.type === 'timeZoneName');
      if (tzPart) abbr = tzPart.value;
    } catch (e) {}
  }
  try {
    const formatter = new Intl.DateTimeFormat('en-US', { timeZone: "UTC", month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });
    let formatted = formatter.format(d);
    if (abbr) formatted += ` ${abbr}`;
    return formatted.replace(", ", " • ").replace(", ", " ");
  } catch (e) { return dateStr; }
}

function parsePlatformInfo(ua) {
  if (!ua) return { platform: "Unknown", version: "—" };
  let platform = "Unknown";
  let version = "—";
  const match = ua.match(/^\[(.*?)\/(.*?)\]/);
  let customType = null;
  if (match) {
    customType = match[1].toLowerCase().trim();
    version = match[2].trim();
    ua = ua.replace(/^\[.*?\/.*?\]\s*/, '');
  }
  const lower = ua.toLowerCase();
  const isWebBrowser = (lower.includes("mozilla/") || lower.includes("applewebkit/") || lower.includes("safari/") || lower.includes("chrome/"))
                       && !lower.includes("exponent");
  if (isWebBrowser && customType !== "mobile" && customType !== "ios" && customType !== "android") {
    return { platform: "Web", version: "—" };
  }
  const expMatch = lower.match(/exponent\/([\d\.]+)/);
  if (expMatch && version === "—") version = "Expo " + expMatch[1];
  if (lower.includes("android") || lower.includes("dalvik") || lower.includes("okhttp") || customType === "android") {
    platform = "Android";
  } else if (lower.includes("iphone") || lower.includes("ipad") || lower.includes("ios") || lower.includes("cfnetwork") || lower.includes("darwin") || customType === "ios") {
    platform = "iOS";
  } else if (customType === "mobile" || customType === "app") {
    platform = "Mobile App";
  } else if (lower.includes("postman") || lower.includes("insomnia") || lower.includes("curl") || lower.includes("axios")) {
    platform = "API Client";
  }
  return { platform, version };
}

// ─── Session persistence ──────────────────────────────────────────────────────
async function loadPersistentSessions() {
  if (!mongoConnected) return;
  try {
    const persistentExpiry =
      new Date("2099-12-31T23:59:59.999Z");

    const sessions = await UserSession.find({
      token: { $exists: true, $ne: "" }
    });

    for (const s of sessions) {
      await UserSession.findByIdAndUpdate(
        s._id,
        {
          $set: {
            status: "active",
            sessionExpiresAt:
              persistentExpiry
          }
        }
      );

      userTokens.set(s.token, {
        email: s.email,
        candidateName:
          s.candidateName,
        arrivalDate:
          s.arrivalDate || null,
        sessionExpiresAt:
          persistentExpiry.getTime(),
        createdAt:
          s.createdAt instanceof Date
            ? s.createdAt.getTime()
            : Date.now()
      });
    }
    console.log(`Loaded ${userTokens.size} persistent sessions from MongoDB`);
  } catch (err) { console.error("Failed to load persistent sessions:", err.message); }
}

async function savePersistentSession(token, sessionData) {
  if (!mongoConnected) return;
  try {
    await UserSession.findOneAndUpdate({ token }, { 
      token, 
      email:sessionData.email, 
      candidateName:sessionData.candidateName, 
      arrivalDate:sessionData.arrivalDate?new Date(sessionData.arrivalDate):null, 
      sessionExpiresAt:new Date(sessionData.sessionExpiresAt), 
      createdAt:sessionData.createdAt?new Date(sessionData.createdAt):new Date(), 
      lastActive:new Date(), 
      ip:sessionData.ip||null, 
      userAgent:sessionData.userAgent||null, 
      loginTime:sessionData.loginTime?new Date(sessionData.loginTime):new Date(), 
      status:"active" 
    }, { upsert:true, new:true });
  } catch (err) { console.error("Failed to save persistent session:", err.message); }
}

async function deletePersistentSession(token) {
  if (!mongoConnected) return;
  try { await UserSession.findOneAndDelete({ token }); } catch {}
}

async function updateSessionLastActive(token) {
  if (!mongoConnected) return;
  try { await UserSession.findOneAndUpdate({ token }, { lastActive:new Date() }); } catch {}
}

async function deletePushTokensForEmail(email) {
  if (!mongoConnected || !email) return;
  try { await PushToken.deleteMany({ email }); } catch (e) { console.error("Failed to delete push tokens:", e.message); }
}

function updateSessionOnLogout(token) {
  const sd = sessionHistory.get(token);
  if (sd) { sd.logoutTime = new Date().toISOString(); sd.status = "ended"; sessionHistory.set(token, sd); }
  deletePersistentSession(token);
  if (mongoConnected) UserSession.findOneAndUpdate({ token }, { status:"ended", logoutTime:new Date() }).catch(()=>{});
}

async function isEmailActive(email) {
  for (const [, td] of userTokens.entries()) {
    const e = typeof td === "string" ? td : td.email;
    const exp = typeof td === "string" ? null : td.sessionExpiresAt;
    if (e === email && (!exp || Date.now() < exp)) return true;
  }
  if (!mongoConnected) return false;
  try {
    const now = new Date();
    const [session, arrival] = await Promise.all([
      UserSession.findOne({ email, status: "active", sessionExpiresAt: { $gt: now } }),
      Arrival.findOne({ email, sessionExpiresAt: { $gt: now } }),
    ]);
    return !!(session || arrival);
  } catch { return false; }
}

async function getArrivalExpiry(email) {
  const cached = arrivalExpiryCache.get(email);
  if (cached && Date.now() - cached.fetchedAt < 5 * 60 * 1000) return cached.expiresAt;
  if (!mongoConnected) return null;
  try { const doc = await Arrival.findOne({ email }); const expiresAt = doc?.sessionExpiresAt?doc.sessionExpiresAt.getTime():null; arrivalExpiryCache.set(email, { expiresAt, fetchedAt:Date.now() }); return expiresAt; } catch { return null; }
}

