// ─── Zoho token persistence ──────────────────────────────────────────────────
async function saveZohoTokenToDb(refresh_token) {
  if (!mongoConnected) { console.warn("[Zoho] ⚠️ MongoDB not connected — token NOT persisted."); return false; }
  try {
    await ZohoToken.findOneAndUpdate({ _id:"zoho_auth" }, { refresh_token, updatedAt:new Date() }, { upsert:true });
    const verify = await ZohoToken.findById("zoho_auth");
    if (!verify || verify.refresh_token !== refresh_token) throw new Error("Read-back mismatch");
    console.log("[Zoho] ✓ Refresh token securely verified and saved in MongoDB.");
    return true;
  } catch (e) { console.error("[Zoho] ❌ CRITICAL: Failed to persist refresh token:", e.message); return false; }
}

async function getZohoTokenFromDb() {
  if (!mongoConnected) return null;
  try { const doc = await ZohoToken.findById("zoho_auth"); if (doc?.refresh_token) return doc.refresh_token; } catch (e) { console.error("Failed to get Zoho token from MongoDB:", e.message); }
  return null;
}

// ─── Zoho API Functions ──────────────────────────────────────────────────────
async function refreshZohoAccessToken() {
  const refresh_token = zohoTokenStore.get("refresh_token");
  if (!refresh_token) throw new Error("No refresh token available. Need to re-authenticate.");
  console.log(`[Zoho] Refreshing access token at ${new Date().toISOString()}`);
  const response = await axios.post(`${ZOHO_ACCOUNTS_URL}/oauth/v2/token`, null, {
    params: { grant_type: "refresh_token", client_id: ZOHO_CLIENT_ID, client_secret: ZOHO_CLIENT_SECRET, refresh_token },
    timeout: 30000
  });
  if (response.data.error) {
    if (response.data.error === "invalid_grant") {
      console.error("[Zoho] Refresh token has expired or is invalid! Need to re-authenticate.");
      throw new Error("REFRESH_TOKEN_EXPIRED");
    }
    throw new Error(`Zoho token error: ${response.data.error}`);
  }
  const { access_token, refresh_token: new_refresh_token, expires_in } = response.data;
  zohoTokenStore.set("access_token", access_token);
  zohoTokenStore.set("expires_at", Date.now() + (expires_in || 3600) * 1000);
  if (new_refresh_token && new_refresh_token !== refresh_token) {
    console.log("[Zoho] Received new refresh token - saving to persistent storage.");
    zohoTokenStore.set("refresh_token", new_refresh_token);
    zohoTokenHistory.unshift({ token: new_refresh_token, receivedAt: Date.now() });
    if (zohoTokenHistory.length > 5) zohoTokenHistory.pop();
    await saveZohoTokenToDb(new_refresh_token);
    try {
      const backupPath = path.join(__dirname, ".zoho_token_backup.json");
      fs.writeFileSync(backupPath, JSON.stringify({ refresh_token: new_refresh_token, savedAt: Date.now() }));
    } catch (e) { console.warn("[Zoho] Could not backup token to local file:", e.message); }
  }
  isZohoConnected = true;
  console.log(`[Zoho] ✓ Token refreshed successfully. Expires in ${expires_in || 3600}s`);
  return access_token;
}

async function requestNewAuthCode() {
  if (authCodeRequested) { console.log("[Zoho] Auth code already requested recently, waiting..."); return; }
  authCodeRequested = true;
  console.log("[Zoho] ⚠️ Refresh token expired. Need new authorization.");
  console.log("[Zoho] Please visit the following URL to re-authorize:");
  console.log(ZOHO_CONNECTION_URL);
  if (brevoReady && process.env.ALERT_EMAIL) {
    try {
      await sendEmailViaBrevo(process.env.ALERT_EMAIL, "Zoho Connection Needs Re-authorization",
        `<h2>Zoho CRM Connection Expired</h2><p>The Zoho refresh token has expired. Please re-authorize:</p><a href="${ZOHO_CONNECTION_URL}">${ZOHO_CONNECTION_URL}</a><p>Timestamp: ${new Date().toISOString()}</p>`
      );
    } catch (e) { console.error("Failed to send alert email:", e.message); }
  }
  setTimeout(() => { authCodeRequested = false; }, 5 * 60 * 1000);
}

async function getValidZohoToken() {
  let at = zohoTokenStore.get("access_token");
  let ea = zohoTokenStore.get("expires_at");
  if (at && ea && Date.now() < ea - 5 * 60 * 1000) return at;
  if (isRefreshing && refreshPromise) { console.log("[Zoho] Token refresh already in progress, waiting..."); return await refreshPromise; }
  isRefreshing = true;
  refreshPromise = (async () => {
    try {
      return await refreshZohoAccessToken();
    } catch (error) {
      if (error.message === "REFRESH_TOKEN_EXPIRED") {
        for (const backup of zohoTokenHistory) {
          if (backup.token !== zohoTokenStore.get("refresh_token")) {
            console.log("[Zoho] Attempting fallback with historical token from memory");
            zohoTokenStore.set("refresh_token", backup.token);
            try { return await refreshZohoAccessToken(); } catch (e) {}
          }
        }
        const dbToken = await getZohoTokenFromDb();
        if (dbToken && dbToken !== zohoTokenStore.get("refresh_token")) {
          console.log("[Zoho] Attempting fallback with token from MongoDB");
          zohoTokenStore.set("refresh_token", dbToken);
          try { return await refreshZohoAccessToken(); } catch (e) {}
        }
        isZohoConnected = false;
        requestNewAuthCode();
        throw new Error("All refresh tokens expired. Please re-authorize the application.");
      }
      throw error;
    } finally {
      isRefreshing = false;
      refreshPromise = null;
    }
  })();
  return await refreshPromise;
}

async function cachedZohoJsonGet(
  url,
  {
    headers = {},
    ttlMs =
      ZOHO_STATIC_CACHE_TTL_MS,
    forceRefresh = false
  } = {}
) {
  const key =
    `direct-json:${url}`;

  return readThroughZohoCache({
    key,
    ttlMs,
    bypassCache:
      forceRefresh,
    metadata: {
      source:
        "direct-zoho-json",
      url
    },
    fetcher: () =>
      runZohoQueued(
        async () => {
          const response =
            await axios.get(
              url,
              {
                headers,
                timeout:
                  30000
              }
            );

          return response.data;
        }
      )
  });
}

async function makeZohoRecruitApiRequest(
  endpoint,
  options = {}
) {
  const method =
    String(
      options.method ||
      "GET"
    ).toUpperCase();

  const endpointPath =
    endpoint.startsWith("/")
      ? endpoint
      : "/" + endpoint;

  const cacheKey =
    `recruit:get:${endpointPath}:${stableSerialize(
      options.params ||
      {}
    )}`;

  const execute =
    async () => {
      const maxRetries =
        method === "GET"
          ? 1
          : 3;

      let lastError = null;

      for (
        let attempt = 1;
        attempt <= maxRetries;
        attempt += 1
      ) {
        try {
          const at =
            await getValidZohoToken();

          const url =
            `${ZOHO_RECRUIT_URL}${endpointPath}`;

          const response =
            await axios({
              method,
              url,
              headers: {
                Authorization:
                  `Zoho-oauthtoken ${at}`,
                "Content-Type":
                  "application/json",
                ...options.headers
              },
              data:
                options.data,
              params:
                options.params,
              timeout: 30000
            });

          return response.data;
        } catch (error) {
          lastError = error;
          markZohoQuotaBlocked(
            error
          );

          if (
            error.response?.status ===
              401 &&
            attempt < maxRetries
          ) {
            zohoTokenStore.delete(
              "access_token"
            );
            zohoTokenStore.delete(
              "expires_at"
            );
            continue;
          }

          break;
        }
      }

      throw lastError;
    };

  if (
    method !== "GET" ||
    options.noCache === true
  ) {
    return runZohoQueued(
      execute
    );
  }

  const requestedTtl =
    Number(
      options.cacheTtlMs
    ) ||
    RECRUIT_READ_CACHE_TTL_MS;

  return readThroughZohoCache({
    key: cacheKey,
    ttlMs:
      Math.max(
        requestedTtl,
        RECRUIT_READ_CACHE_TTL_MS
      ),
    fetcher: () =>
      runZohoQueued(
        execute
      ),
    metadata: {
      source: "recruit",
      endpoint: endpointPath
    },
    // Normal portal reads never bypass Recruit cache. A caller must explicitly
    // opt in with allowRecruitLiveRefresh, which is reserved for controlled
    // refresh flows after the minimum refresh interval.
    bypassCache:
      options.forceRefresh ===
        true &&
      options.allowRecruitLiveRefresh ===
        true
  });
}

async function makeZohoApiRequest(
  endpoint,
  options = {}
) {
  const method =
    String(
      options.method ||
      "GET"
    ).toUpperCase();

  const cacheKey =
    `crm:get:${endpoint}:${stableSerialize(
      options.params ||
      {}
    )}`;

  const execute =
    async () => {
      const maxRetries =
        method === "GET"
          ? 1
          : 3;

      let lastError = null;

      for (
        let attempt = 1;
        attempt <= maxRetries;
        attempt += 1
      ) {
        try {
          const at =
            await getValidZohoToken();

          const response =
            await axios({
              method,
              url:
                `${ZOHO_CRM_URL}${endpoint}`,
              headers: {
                Authorization:
                  `Zoho-oauthtoken ${at}`,
                "Content-Type":
                  "application/json",
                ...options.headers
              },
              data:
                options.data,
              params:
                options.params,
              timeout: 30000
            });

          return response.data;
        } catch (error) {
          lastError = error;
          markZohoQuotaBlocked(
            error
          );

          if (
            error.response?.status ===
              401 &&
            attempt < maxRetries
          ) {
            zohoTokenStore.delete(
              "access_token"
            );
            zohoTokenStore.delete(
              "expires_at"
            );
            continue;
          }

          break;
        }
      }

      throw lastError;
    };

  if (
    method !== "GET" ||
    options.noCache === true
  ) {
    return runZohoQueued(
      execute
    );
  }

  return readThroughZohoCache({
    key: cacheKey,
    ttlMs:
      Number(
        options.cacheTtlMs
      ) ||
      ZOHO_READ_CACHE_TTL_MS,
    fetcher: () =>
      runZohoQueued(
        execute
      ),
    metadata: {
      source: "crm",
      endpoint
    },
    bypassCache:
      options.forceRefresh ===
      true
  });
}

// ─── Search Functions ─────────────────────────────────────────────────────────
async function searchDealsByEmail(
  email,
  {
    forceRefresh = false
  } = {}
) {
  const safeEmail =
    normalizeCacheEmail(email);

  if (!safeEmail) {
    return [];
  }

  const key =
    `search:crm:deals:${safeEmail}`;

  if (!forceRefresh) {
    const memory =
      getMemoryCacheEntry(
        zohoSearchCache,
        key,
        ZOHO_SEARCH_CACHE_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (memory) {
      return memory.data;
    }

    const persistent =
      await getPersistentApiCache(
        key,
        ZOHO_SEARCH_CACHE_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (persistent) {
      setMemoryCacheEntry(
        zohoSearchCache,
        key,
        persistent.data
      );

      return persistent.data;
    }
  }

  if (
    zohoSearchInFlight.has(key)
  ) {
    return zohoSearchInFlight.get(
      key
    );
  }

  const promise = (async () => {
    try {
      const emailFields = [
        "Email",
        "Alt_Email",
        "Secondary_Email",
        "Work_Email",
        "Personal_Email",
        "Contact_Email",
        "Account_Email",
        "Email_Address",
        "Primary_Email",
        "Other_Email"
      ];

      for (
        const field of emailFields
      ) {
        if (
          isZohoQuotaCircuitOpen()
        ) {
          break;
        }

        try {
          const criteria =
            encodeURIComponent(
              `(${field}:equals:${safeEmail})`
            );

          const response =
            await makeZohoApiRequest(
              `/crm/v2/Deals/search?criteria=${criteria}`,
              {
                cacheTtlMs:
                  ZOHO_SEARCH_CACHE_TTL_MS,
                forceRefresh
              }
            );

          const records =
            response?.data ||
            [];

          if (
            records.length > 0
          ) {
            // Critical early exit: stop immediately after first matching field.
            setMemoryCacheEntry(
              zohoSearchCache,
              key,
              records
            );

            await setPersistentApiCache(
              key,
              records,
              {
                type:
                  "crm-email-search",
                email:
                  safeEmail,
                matchedField:
                  field
              }
            );

            return records;
          }
        } catch (error) {
          markZohoQuotaBlocked(
            error
          );
        }
      }

      const empty = [];

      setMemoryCacheEntry(
        zohoSearchCache,
        key,
        empty
      );

      await setPersistentApiCache(
        key,
        empty,
        {
          type:
            "crm-email-search",
          email:
            safeEmail
        }
      );

      return empty;
    } finally {
      zohoSearchInFlight.delete(
        key
      );
    }
  })();

  zohoSearchInFlight.set(
    key,
    promise
  );

  return promise;
}

/**
 * Search a Zoho Recruit module for records linked to an email address.
 *
 * Recruit installations often use different email API names in custom modules,
 * so each module is checked against a small set of likely email fields. Invalid
 * field criteria are ignored and the next field is attempted.
 */
async function searchRecruitModuleByEmail(
  moduleApiName,
  email,
  {
    forceRefresh = false,
    allowRecruitLiveRefresh = false
  } = {}
) {
  const safeEmail =
    normalizeCacheEmail(email);

  if (
    !moduleApiName ||
    !safeEmail
  ) {
    return [];
  }

  try {
    // Zoho Recruit's dedicated email parameter searches ALL email fields in
    // the selected module. We also explicitly include converted and
    // unapproved records; Recruit otherwise defaults to converted=false and
    // approved=true, which can hide a real Candidate/Application from the
    // portal even though the email is visibly present in Recruit.
    const response =
      await makeZohoRecruitApiRequest(
        `/recruit/v2/${moduleApiName}/search`,
        {
          params: {
            email:
              safeEmail,
            converted:
              "both",
            approved:
              "both",
            page:
              1,
            per_page:
              200
          },
          cacheTtlMs:
            RECRUIT_SEARCH_CACHE_TTL_MS,
          forceRefresh:
            forceRefresh ===
            true,
          allowRecruitLiveRefresh:
            allowRecruitLiveRefresh ===
            true
        }
      );

    return (
      response?.data ||
      []
    )
      .filter(record =>
        record?.id
      )
      .map(record => ({
        ...record,
        _recruitModule:
          moduleApiName,
        _matchedEmailField:
          "all-email-fields",
        _matchedEmail:
          safeEmail,
        _recordEmail:
          extractRecruitRecordEmail(
            record,
            safeEmail
          ),
        _emailMatchMethod:
          "Recruit-email-parameter-converted-both-approved-both"
      }));
  } catch (error) {
    const status =
      error.response?.status;

    const code =
      error.response?.data?.code;

    if (
      status === 204 ||
      status === 400 ||
      code === "INVALID_QUERY" ||
      code === "INVALID_DATA" ||
      code === "INVALID_MODULE"
    ) {
      return [];
    }

    throw error;
  }
}

function extractRecruitRecordEmail(
  record,
  fallbackEmail = ""
) {
  if (!record) {
    return normalizePipelineEmail(
      fallbackEmail
    );
  }

  const possibleValues = [
    record.Email,
    record.email,
    record.Candidate_Email,
    record.Candidate_Email_Address,
    record?._recordEmail,
    record?._matchedEmail,
    record?.Candidate_Name?.Email,
    record?.Candidate_Name?.email,
    fallbackEmail
  ];

  for (
    const candidate of
    possibleValues
  ) {
    if (
      candidate === null ||
      candidate === undefined
    ) {
      continue;
    }

    let value =
      candidate;

    if (
      typeof candidate ===
      "object"
    ) {
      value =
        candidate.value ??
        candidate.email ??
        candidate.Email ??
        "";
    }

    const normalized =
      normalizePipelineEmail(
        value
      );

    if (normalized) {
      return normalized;
    }
  }

  return "";
}

function getRecruitModuleEmailIndexCacheKey(
  moduleApiName
) {
  return `recruit-module-email-index:${String(
    moduleApiName ||
    ""
  )
    .trim()
    .toLowerCase()}`;
}

function shouldRefreshRecruitModuleEmailIndex(
  moduleApiName,
  forceRefresh = false
) {
  if (!forceRefresh) {
    return false;
  }

  const key =
    String(
      moduleApiName ||
      ""
    )
      .trim()
      .toLowerCase();

  const last =
    recruitModuleEmailIndexLastLiveRefresh.get(
      key
    ) ||
    0;

  return (
    Date.now() -
      last >=
    RECRUIT_MODULE_EMAIL_INDEX_REFRESH_FLOOR_MS
  );
}

async function buildRecruitModuleEmailIndex(
  moduleApiName,
  {
    forceRefresh = false
  } = {}
) {
  const moduleName =
    String(
      moduleApiName ||
      ""
    ).trim();

  if (!moduleName) {
    return {
      module:
        "",
      recordsByEmail:
        {},
      emails: [],
      fetchedAt:
        null
    };
  }

  const cacheKey =
    getRecruitModuleEmailIndexCacheKey(
      moduleName
    );

  const liveRefreshAllowed =
    shouldRefreshRecruitModuleEmailIndex(
      moduleName,
      forceRefresh
    );

  if (!liveRefreshAllowed) {
    const memory =
      getMemoryCacheEntry(
        zohoSearchCache,
        cacheKey,
        RECRUIT_MODULE_EMAIL_INDEX_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (memory?.data) {
      return memory.data;
    }

    const persistent =
      await getPersistentApiCache(
        cacheKey,
        RECRUIT_MODULE_EMAIL_INDEX_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (persistent?.data) {
      setMemoryCacheEntry(
        zohoSearchCache,
        cacheKey,
        persistent.data
      );

      return persistent.data;
    }
  }

  const inFlightKey =
    String(
      moduleName
    )
      .trim()
      .toLowerCase();

  if (
    recruitModuleEmailIndexInFlight.has(
      inFlightKey
    )
  ) {
    return recruitModuleEmailIndexInFlight.get(
      inFlightKey
    );
  }

  const promise =
    (async () => {
      const recordsByEmail =
        {};
      const recordsByCandidateId =
        {};

      let page = 1;
      let moreRecords =
        true;

      // Zoho Recruit supports up to 200 records per page. Only the fields
      // needed for portal identity/status are requested.
      while (
        moreRecords &&
        page <= 100
      ) {
        const response =
          await makeZohoRecruitApiRequest(
            `/recruit/v2/${moduleName}`,
            {
              // Use the normal record payload. Restricting the fallback with
              // fields=Email caused some Recruit module responses to omit or
              // reject the field and made a real module match look absent.
              params: {
                page,
                per_page:
                  200,
                converted:
                  "both",
                approved:
                  "both"
              },
              cacheTtlMs:
                RECRUIT_MODULE_EMAIL_INDEX_TTL_MS,
              forceRefresh:
                liveRefreshAllowed,
              allowRecruitLiveRefresh:
                liveRefreshAllowed
            }
          );

        const rows =
          Array.isArray(
            response?.data
          )
            ? response.data
            : [];

        for (
          const record of
          rows
        ) {
          const candidateLookup =
            record?.Candidate_Name ??
            record?.Candidate ??
            record?.Candidate_ID ??
            record?.Candidate_Id ??
            null;

          const candidateId =
            String(
              candidateLookup?.id ??
              candidateLookup?.value ??
              candidateLookup ??
              ""
            ).trim();

          if (candidateId) {
            if (!recordsByCandidateId[candidateId]) {
              recordsByCandidateId[candidateId] = [];
            }

            recordsByCandidateId[candidateId].push({
              ...record,
              _recruitModule: moduleName,
              _matchedCandidateId: candidateId,
              _emailMatchMethod: "candidate-lookup-index"
            });
          }

          const normalizedEmail =
            extractRecruitRecordEmail(
              record
            );

          if (!normalizedEmail) {
            continue;
          }

          if (
            !recordsByEmail[
              normalizedEmail
            ]
          ) {
            recordsByEmail[
              normalizedEmail
            ] = [];
          }

          recordsByEmail[
            normalizedEmail
          ].push({
            ...record,
            _recruitModule:
              moduleName,
            _matchedEmailField:
              "Email",
            _matchedEmail:
              normalizedEmail,
            _recordEmail:
              normalizedEmail,
            _emailMatchMethod:
              "module-email-index"
          });
        }

        moreRecords =
          response?.info
            ?.more_records ===
          true;

        page += 1;

        if (
          rows.length === 0
        ) {
          moreRecords =
            false;
        }
      }

      const result = {
        module:
          moduleName,
        recordsByEmail,
        recordsByCandidateId,
        emails:
          Object.keys(
            recordsByEmail
          ),
        fetchedAt:
          new Date()
            .toISOString()
      };

      setMemoryCacheEntry(
        zohoSearchCache,
        cacheKey,
        result
      );

      await setPersistentApiCache(
        cacheKey,
        result,
        {
          type:
            "recruit-module-email-index",
          module:
            moduleName
        }
      );

      if (
        liveRefreshAllowed
      ) {
        recruitModuleEmailIndexLastLiveRefresh.set(
          inFlightKey,
          Date.now()
        );
      }

      return result;
    })().finally(() => {
      recruitModuleEmailIndexInFlight.delete(
        inFlightKey
      );
    });

  recruitModuleEmailIndexInFlight.set(
    inFlightKey,
    promise
  );

  return promise;
}

async function findRecruitRecordsByEmailRobust(
  moduleApiName,
  email,
  {
    forceRefresh = false
  } = {}
) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  if (!normalizedEmail) {
    return [];
  }

  // First use the efficient exact Search endpoint.
  const searched =
    await searchRecruitModuleByEmail(
      moduleApiName,
      normalizedEmail,
      {
        forceRefresh,
        allowRecruitLiveRefresh:
          forceRefresh
      }
    ).catch(() => []);

  const exactSearchRows =
    (searched || [])
      .filter(record => {
        // The Search API itself was called with email=<normalizedEmail>.
        // _matchedEmail therefore remains authoritative even if a Recruit
        // layout omits Email from the returned record payload.
        const matchedEmail =
          normalizePipelineEmail(
            record?._matchedEmail
          );

        const recordEmail =
          extractRecruitRecordEmail(
            record,
            matchedEmail ||
            normalizedEmail
          );

        return (
          matchedEmail ===
            normalizedEmail ||
          recordEmail ===
            normalizedEmail
        );
      })
      .map(record => ({
        ...record,
        _matchedEmail:
          normalizedEmail,
        _recordEmail:
          normalizedEmail
      }));

  if (
    exactSearchRows.length >
    0
  ) {
    return exactSearchRows;
  }

  // Fallback: shared cached module index. This handles cases where Recruit's
  // Search endpoint returns 204 / INVALID_QUERY / no rows even though the Email
  // value is visible in the module.
  let index =
    await buildRecruitModuleEmailIndex(
      moduleApiName
    ).catch(() => null);

  let indexedRows =
    index
      ?.recordsByEmail
      ?.[normalizedEmail] ||
    [];

  // If the cached index does not contain a newly-associated candidate and the
  // caller explicitly requested freshness, refresh the shared index once.
  if (
    indexedRows.length ===
      0 &&
    forceRefresh
  ) {
    index =
      await buildRecruitModuleEmailIndex(
        moduleApiName,
        {
          forceRefresh:
            true
        }
      ).catch(
        () =>
          index
      );

    indexedRows =
      index
        ?.recordsByEmail
        ?.[normalizedEmail] ||
      [];
  }

  return indexedRows.map(
    record => ({
      ...record,
      _matchedEmail:
        normalizedEmail,
      _recordEmail:
        normalizedEmail,
      _emailMatchMethod:
        record
          ?._emailMatchMethod ||
        "module-email-index"
    })
  );
}


async function findNCLEXCustomModule1Records(
  email,
  {
    candidate = null,
    application = null,
    forceRefresh = false
  } = {}
) {
  const normalizedEmail =
    normalizePipelineEmail(email);

  const byEmail =
    await findRecruitRecordsByEmailRobust(
      "CustomModule1",
      normalizedEmail,
      { forceRefresh }
    ).catch(() => []);

  if (Array.isArray(byEmail) && byEmail.length > 0) {
    return byEmail;
  }

  const applicationLookup =
    typeof extractApplicationCandidateLookup === "function"
      ? extractApplicationCandidateLookup(application)
      : null;

  const candidateIds = [
    candidate?.id,
    applicationLookup?.id,
    application?.Candidate_Name?.id,
    application?.Candidate?.id,
    application?.Candidate_ID,
    application?.Candidate_Id
  ]
    .map(value => String(value || "").trim())
    .filter(Boolean);

  if (candidateIds.length === 0) {
    return [];
  }

  const index =
    await buildRecruitModuleEmailIndex(
      "CustomModule1",
      { forceRefresh }
    ).catch(() => null);

  const matches = [];
  for (const candidateId of [...new Set(candidateIds)]) {
    matches.push(
      ...(index?.recordsByCandidateId?.[candidateId] || [])
    );
  }

  const unique = new Map();
  for (const record of matches) {
    if (!record?.id) continue;
    unique.set(String(record.id), record);
  }

  return [...unique.values()];
}

