function getNewestZohoRecord(records) {
  return [...(records || [])]
    .sort(
      (a, b) =>
        new Date(
          b?.Modified_Time ||
          b?.Created_Time ||
          0
        ) -
        new Date(
          a?.Modified_Time ||
          a?.Created_Time ||
          0
        )
    )[0] || {};
}

function readMappedZohoField(
  record,
  apiName,
  fallback = null
) {
  if (!record || !apiName) {
    return fallback;
  }

  const value =
    record[apiName];

  if (
    value === undefined ||
    value === null ||
    (
      typeof value === "string" &&
      value.trim() === ""
    )
  ) {
    return fallback;
  }

  return value;
}

async function fetchFullRecruitRecord(
  moduleApiName,
  record,
  {
    forceRefresh = false
  } = {}
) {
  if (!record?.id) {
    return record || {};
  }

  try {
    const response =
      await makeZohoRecruitApiRequest(
        `/recruit/v2/${moduleApiName}/${record.id}`,
        {
          cacheTtlMs:
            RECRUIT_READ_CACHE_TTL_MS,
          forceRefresh:
            forceRefresh === true,
          allowRecruitLiveRefresh:
            forceRefresh === true
        }
      );

    return (
      response?.data?.[0] ||
      record
    );
  } catch (error) {
    console.warn(
      `[Zoho Source Map] Full Recruit ${moduleApiName} read failed:`,
      error.message
    );

    return record;
  }
}

async function getCanonicalZohoSourceRecords(
  candidateEmail,
  {
    forceRefresh = false
  } = {}
) {
  const canonicalEmail =
    await resolveCanonicalPipelineEmail(
      candidateEmail
    );

  const knownEmails =
    typeof getCandidatePipelineEmails ===
      "function"
      ? await getCandidatePipelineEmails(
          canonicalEmail
        ).catch(
          () => [
            canonicalEmail
          ]
        )
      : [
          canonicalEmail
        ];

  const aliases = [
    ...new Set(
      [
        canonicalEmail,
        ...(knownEmails || [])
      ]
        .map(
          normalizePipelineEmail
        )
        .filter(Boolean)
    )
  ];

  const deals = [];
  const candidates = [];
  const applications = [];
  const customModule1 = [];

  for (
    const alias of
    aliases
  ) {
    const [
      dealRows,
      candidateRows,
      applicationRows,
      nclexRows
    ] =
      await Promise.all([
        searchDealsByEmail(
          alias,
          {
            forceRefresh
          }
        ).catch(
          () => []
        ),

        findRecruitRecordsByEmailRobust(
          "Candidates",
          alias,
          {
            forceRefresh
          }
        ).catch(
          () => []
        ),

        findRecruitRecordsByEmailRobust(
          "Applications",
          alias,
          {
            forceRefresh
          }
        ).catch(
          () => []
        ),

        findRecruitRecordsByEmailRobust(
          "CustomModule1",
          alias,
          {
            forceRefresh
          }
        ).catch(
          () => []
        )
      ]);

    deals.push(
      ...(dealRows || [])
    );
    candidates.push(
      ...(candidateRows || [])
    );
    applications.push(
      ...(applicationRows || [])
    );
    customModule1.push(
      ...(nclexRows || [])
    );
  }

  let deal =
    getNewestZohoRecord(
      deals
    );

  let candidate =
    getNewestZohoRecord(
      candidates
    );

  let application =
    getNewestZohoRecord(
      applications
    );

  let nclex =
    getNewestZohoRecord(
      customModule1
    );

  if (deal?.id) {
    try {
      const response =
        await makeZohoApiRequest(
          `/crm/v3/Deals/${deal.id}`,
          {
            cacheTtlMs:
              ZOHO_READ_CACHE_TTL_MS,
            forceRefresh
          }
        );

      deal =
        response?.data?.[0] ||
        deal;
    } catch (error) {
      console.warn(
        "[Zoho Source Map] Full CRM Deal read failed:",
        error.message
      );
    }
  }

  [
    candidate,
    application,
    nclex
  ] =
    await Promise.all([
      fetchFullRecruitRecord(
        "Candidates",
        candidate,
        {
          forceRefresh
        }
      ),
      fetchFullRecruitRecord(
        "Applications",
        application,
        {
          forceRefresh
        }
      ),
      fetchFullRecruitRecord(
        "CustomModule1",
        nclex,
        {
          forceRefresh
        }
      )
    ]);

  return {
    email:
      canonicalEmail,
    aliases,
    crmDeal:
      deal || {},
    recruitCandidate:
      candidate || {},
    recruitApplication:
      application || {},
    recruitNCLEX:
      nclex || {},
    sourcePresence: {
      crmDeals:
        Boolean(
          deal?.id
        ),
      candidates:
        Boolean(
          candidate?.id
        ),
      applications:
        Boolean(
          application?.id
        ),
      customModule1:
        Boolean(
          nclex?.id
        )
    },
    recordIds: {
      crmDeal:
        deal?.id ||
        null,
      candidate:
        candidate?.id ||
        null,
      application:
        application?.id ||
        null,
      customModule1:
        nclex?.id ||
        null
    }
  };
}

function getPortalRecruitModules() {
  return [
    ...new Set(
      String(
        process.env
          .RECRUIT_PORTAL_MODULES ||
        "Candidates,Applications,CustomModule1"
      )
        .split(",")
        .map(value =>
          value.trim()
        )
        .filter(Boolean)
    )
  ];
}

async function getAccessibleRecruitModules() {
  // No settings/modules read: metadata lookups also consume API credits.
  return getPortalRecruitModules();
}

async function searchAllRecruitModulesByEmail(
  email,
  {
    includeDiagnostics = false,
    forceRefresh = false
  } = {}
) {
  const safeEmail =
    normalizeCacheEmail(email);

  if (!safeEmail) {
    const empty = {
      records: [],
      checkedModules: [],
      successfulModules: [],
      failedModules: [],
      recruitAvailable: false
    };

    return includeDiagnostics
      ? empty
      : [];
  }

  const key =
    `search:recruit:${safeEmail}`;

  const liveRefreshAllowed =
    canPerformRecruitLiveRefresh(
      safeEmail,
      forceRefresh
    );

  if (!liveRefreshAllowed) {
    const memory =
      getMemoryCacheEntry(
        zohoSearchCache,
        key,
        RECRUIT_SEARCH_CACHE_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (memory) {
      return includeDiagnostics
        ? memory.data
        : memory.data.records;
    }

    const persistent =
      await getPersistentApiCache(
        key,
        RECRUIT_SEARCH_CACHE_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (persistent) {
      setMemoryCacheEntry(
        zohoSearchCache,
        key,
        persistent.data
      );

      return includeDiagnostics
        ? persistent.data
        : persistent.data.records;
    }
  }

  if (
    zohoSearchInFlight.has(key)
  ) {
    const result =
      await zohoSearchInFlight.get(
        key
      );

    return includeDiagnostics
      ? result
      : result.records;
  }

  const promise = (async () => {
    const modules =
      getPortalRecruitModules();

    const records = [];
    const successfulModules = [];
    const failedModules = [];
    const seen = new Set();

    for (
      const moduleApiName of modules
    ) {
      if (
        isZohoQuotaCircuitOpen()
      ) {
        break;
      }

      try {
        const matches =
          await searchRecruitModuleByEmail(
            moduleApiName,
            safeEmail,
            {
              forceRefresh:
                liveRefreshAllowed
            }
          );

        successfulModules.push(
          moduleApiName
        );

        for (
          const record of matches
        ) {
          const uniqueKey =
            `${moduleApiName}:${record.id}`;

          if (
            seen.has(uniqueKey)
          ) {
            continue;
          }

          seen.add(uniqueKey);
          records.push(record);
        }
      } catch (error) {
        markZohoQuotaBlocked(
          error
        );

        failedModules.push({
          module:
            moduleApiName,
          error:
            error.response?.data ||
            error.message
        });
      }
    }

    if (
      liveRefreshAllowed
    ) {
      markRecruitLiveRefresh(
        safeEmail
      );
    }

    const result = {
      records,
      checkedModules:
        modules,
      successfulModules,
      failedModules,
      recruitAvailable:
        successfulModules.length > 0
    };

    setMemoryCacheEntry(
      zohoSearchCache,
      key,
      result
    );

    await setPersistentApiCache(
      key,
      result,
      {
        type:
          "recruit-email-search",
        email:
          safeEmail
      }
    );

    return result;
  })().finally(() => {
    zohoSearchInFlight.delete(
      key
    );
  });

  zohoSearchInFlight.set(
    key,
    promise
  );

  const result =
    await promise;

  return includeDiagnostics
    ? result
    : result.records;
}

/**
 * Search all Recruit modules used by the candidate portal.
 *
 * The returned array keeps the historical function contract, while adding
 * `_recruitModule` and `_matchedEmailField` metadata to each result.
 */
async function searchRecruitCandidatesByEmail(
  email,
  options = {}
) {
  return searchAllRecruitModulesByEmail(
    email,
    options
  );
}


async function searchRecruitCandidateRecordsOnly(
  email,
  { forceRefresh = false } = {}
) {
  const safeEmail =
    normalizeCacheEmail(email);

  if (!safeEmail) {
    return [];
  }

  const direct =
    await searchRecruitModuleByEmail(
      "Candidates",
      safeEmail,
      { forceRefresh }
    ).catch(error => {
      console.warn(
        "[Recruit Candidates Only] Candidates lookup failed:",
        error?.message || error
      );
      return [];
    });

  const candidateOnly =
    (direct || []).filter(record =>
      String(
        record?._recruitModule ||
        "Candidates"
      )
        .trim()
        .toLowerCase() ===
        "candidates"
    );

  if (candidateOnly.length > 0) {
    return candidateOnly;
  }

  const applications =
    await searchRecruitModuleByEmail(
      "Applications",
      safeEmail,
      { forceRefresh }
    ).catch(() => []);

  const ids =
    new Set();

  for (const application of applications || []) {
    const lookup =
      typeof extractApplicationCandidateLookup === "function"
        ? extractApplicationCandidateLookup(application)
        : (
            application?.Candidate_Name ||
            application?.Candidate ||
            null
          );

    const id =
      String(
        lookup?.id || ""
      ).trim();

    if (id) {
      ids.add(id);
    }
  }

  const resolved = [];

  for (const id of ids) {
    try {
      const response =
        await makeZohoRecruitApiRequest(
          `/recruit/v2/Candidates/${id}`,
          { noCache: true }
        );

      const record =
        response?.data?.[0];

      if (record?.id) {
        resolved.push({
          ...record,
          _recruitModule:
            "Candidates"
        });
      }
    } catch (error) {
      console.warn(
        `[Recruit Candidates Only] Candidate ${id} verification failed:`,
        error?.message || error
      );
    }
  }

  return resolved;
}

async function resolveRecruitCandidateRecordForAttachments(
  email,
  {
    preferredCandidateId = null,
    forceRefresh = true
  } = {}
) {
  const candidates =
    await searchRecruitCandidateRecordsOnly(
      email,
      { forceRefresh }
    );

  const preferred =
    String(
      preferredCandidateId || ""
    ).trim();

  if (preferred) {
    const exact =
      candidates.find(candidate =>
        String(candidate?.id || "") ===
        preferred
      );

    if (exact) {
      return exact;
    }

    try {
      const response =
        await makeZohoRecruitApiRequest(
          `/recruit/v2/Candidates/${preferred}`,
          { noCache: true }
        );

      const record =
        response?.data?.[0];

      if (record?.id) {
        return {
          ...record,
          _recruitModule:
            "Candidates"
        };
      }
    } catch {
      // supplied ID is not a Candidates-module ID
    }
  }

  return (
    [...candidates].sort(
      (a, b) =>
        new Date(
          b.Modified_Time ||
          b.Created_Time ||
          0
        ) -
        new Date(
          a.Modified_Time ||
          a.Created_Time ||
          0
        )
    )[0] ||
    null
  );
}


