// Normalizes every CRM-driven Immigration checklist field into one response shape.
// Restored from the original working backend. Raw Zoho API names are preserved,
// together with stable aliases used by existing frontend code.
function normalizeZohoFieldName(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

function unwrapZohoFieldValueGlobal(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    if (Object.prototype.hasOwnProperty.call(value, "value")) return value.value;
    if (Object.prototype.hasOwnProperty.call(value, "display_value")) return value.display_value;
    if (Object.prototype.hasOwnProperty.call(value, "displayValue")) return value.displayValue;
    if (Object.prototype.hasOwnProperty.call(value, "name")) return value.name;
    if (Object.prototype.hasOwnProperty.call(value, "label")) return value.label;
    if (Object.prototype.hasOwnProperty.call(value, "checked")) return value.checked;
  }
  return value;
}

// Backward-compatible alias used by older dashboard/aftercare helpers.
const unwrapZohoFieldValue = unwrapZohoFieldValueGlobal;

function readZohoField(source, ...apiNames) {
  if (!source) return undefined;

  for (const apiName of apiNames) {
    if (Object.prototype.hasOwnProperty.call(source, apiName)) {
      const value = unwrapZohoFieldValueGlobal(source[apiName]);
      if (value !== undefined && value !== null && value !== "") return value;
    }
  }

  const normalized = new Map(
    Object.entries(source).map(([key, value]) => [
      normalizeZohoFieldName(key),
      unwrapZohoFieldValueGlobal(value)
    ])
  );

  for (const apiName of apiNames) {
    const value = normalized.get(normalizeZohoFieldName(apiName));
    if (value !== undefined && value !== null && value !== "") return value;
  }

  return undefined;
}

