            Payment_2: deal.Payment_2 || "",
            Payment_2_Paid: deal.Payment_2_Paid || false,
            Payment_2_Total: deal.Payment_2_Total || 0,
            Payment_3: deal.Payment_3 || "",
            Payment_3_Paid: deal.Payment_3_Paid || false,
            Payment_3_Total: deal.Payment_3_Total || 0,
            Payment_4: deal.Payment_4 || "",
            Payment_4_Paid: deal.Payment_4_Paid || false,
            Payment_4_Total: deal.Payment_4_Total || 0,
            Total_Due_to_ICP_RN: deal.Total_Due_to_ICP_RN || 0,
            Pay_Reimbursement_Total: deal.Pay_Reimbursement_Total || 0,
            Bank_Account_Number: deal.Bank_Account_Number || "",
