function generateChatResponse(userMessage, userName, candidateData) {
  const msg  = userMessage.toLowerCase().trim();
  const name = candidateData?.prefferedName || candidateData?.firstName || userName || "there";
  const appTopics = ["flight","depart","arriv","layover","airline","airport","ticket","boarding","passport","visa","document","immigration","customs","cbp","port of entry","concierge","icp","infinity care","deploymate","relocation","travel","pack","luggage","bag","medication","vaccine","vaccination","otp","login","portal","session","account","profile","appointment","welcome","hospital","specialty","nurse","credential","nclex","cgfns","contact","phone","email","address","hi","hey","hello","help","thank","who am i","my name","what can you","deployment","hotel","meet and greet","welcome packet","flight cost"];
  if (!appTopics.some(t=>msg.includes(t)) && msg.length > 5) return `I'm Deploymate — your ICP Travel Assistant. I can only help with relocation, flights, documents, immigration, or your ICP profile.\n\nFor anything else, contact your concierge or ICP at 615-881-5321.`;
  if (msg.match(/^(hi|hey|hello|good morning|good afternoon|good evening)/)) return `Hey ${name}! I'm Deploymate, your ICP Travel Assistant. I can help with flight details, documents, immigration, packing, or anything about your relocation. What do you need?`;
  if (msg.includes("my name")||msg.includes("who am i")) return candidateData?.firstName ? `You're logged in as ${candidateData.prefferedName||candidateData.firstName} ${candidateData.lastName||""}. Check your full profile in the Profile tab.` : `Your profile info is in the Profile tab.`;
  if (msg.includes("flight cost")||msg.includes("rn flight cost")) { let r="Flight cost:\n"; if (candidateData?.RN_Flight_Cost&&candidateData.RN_Flight_Cost!=="—") r+=`\nRN: ${candidateData.RN_Flight_Cost}`; if (candidateData?.Dependent_Flight_Cost&&candidateData.Dependent_Flight_Cost!=="—") r+=`\nDependent(s): ${candidateData.Dependent_Flight_Cost}`; if (r==="Flight cost:\n") r+="No info yet."; return r; }
  if (msg.includes("flight booked")||msg.includes("flight status")) return candidateData?.Flight_Booked_Emailed&&candidateData.Flight_Booked_Emailed!=="—"?`Flight status: ${candidateData.Flight_Booked_Emailed}`:"Flight booking status not available yet.";
  if (msg.includes("hotel")||msg.includes("accommodation")) return candidateData?.hotel_booked&&candidateData.hotel_booked!=="—"?`Hotel: ${candidateData.hotel_booked}`:"Hotel info not available yet.";
  if (msg.includes("welcome packet")) return candidateData?.welcome_packet_emailed&&candidateData.welcome_packet_emailed!=="—"?`Welcome packet: ${candidateData.welcome_packet_emailed}`:"Welcome packet info not available yet.";
  if (msg.includes("my flight")||msg.includes("flight info")||msg.includes("flight number")) { if (candidateData?.primaryairline||candidateData?.departcity) { const airline=candidateData.primaryairline||"TBD", fnums=[candidateData.fligtnumber1,candidateData.fligtnumber2,candidateData.fligtnumber3,candidateData.fligtnumber4].filter(f=>f&&f!=="—").join(", ")||"TBD", layovers=[candidateData.layover1location,candidateData.layover2location,candidateData.layover3location].filter(l=>l&&l!=="—").join(", ")||"None"; return `Your flight info:\n\nAirline: ${airline}\nFlight(s): ${fnums}\nDeparture: ${candidateData.departcity||"TBD"} on ${candidateData.scheduleddeparturedate||"TBD"}\nArrival: ${candidateData.entryport||"TBD"} on ${candidateData.scheduledarrivaldate||"TBD"}\nConfirmation: ${candidateData.confirmationnumbers||"TBD"}\nLayovers: ${layovers}\n\nSee the Flight Info tab for full details.`; } return "Flight details aren't available yet. Check the Flight Info tab."; }
  if (msg.includes("visa packet")||(msg.includes("visa")&&msg.includes("packet"))) return `Visa Packet Instructions:\n1. DO NOT OPEN IT\n2. Keep in carry-on\n3. Hand to CBP officer on arrival\n4. If lost — contact ICP immediately`;
  if (msg.includes("concierge")||msg.includes("contact")||msg.includes("reach")) { const cName=candidateData?.conciergeName; let r=cName&&cName!=="—"?`Your concierge is ${cName}. Reach ICP at 615-881-5321 or customerservice@infinitycarepartners.com.`:`ICP: 615-881-5321 | customerservice@infinitycarepartners.com`; return r; }
  if (msg.includes("document")||msg.includes("passport")||msg.includes("pack")) return `Travel with:\n- Passport (6+ months valid)\n- Sealed visa envelope (DO NOT OPEN)\n- Employment contract\n- Nursing credentials\n- Vaccination records\n\nKeep physical and digital copies.`;
  if (msg.includes("immigration")||msg.includes("customs")||msg.includes("cbp")) return `At U.S. immigration:\n1. Primary inspection\n2. Secondary inspection (normal for professionals)\n3. Customs declaration\n4. Baggage claim`;
  if (msg.includes("thank")) return `Happy to help! Safe travels, ${name}!`;
  if (msg.includes("help")||msg.includes("what can you")) return `I can help with:\n- Flight details\n- Document checklist\n- Immigration process\n- Packing\n- Concierge contact\n- Flight/hotel status\n\nJust ask!`;
  return `Could you give more detail? You can also contact your concierge at ${candidateData?.conciergePhone||"615-881-5321"}.`;
}

// ─── Document Helper Functions ───────────────────────────────────────────────
const DOCUMENT_MIME_TYPES = {
  pdf: "application/pdf", doc: "application/msword",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  xls: "application/vnd.ms-excel",
  xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  ppt: "application/vnd.ms-powerpoint",
  pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
  jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", gif: "image/gif",
  webp: "image/webp", heic: "image/heic",
  txt: "text/plain; charset=utf-8", csv: "text/csv; charset=utf-8",
  zip: "application/zip",
};

function getFileExtension(fileName = "") {
  const clean = String(fileName || "").split("?")[0].split("#")[0];
  const last = clean.split("/").pop() || "";
  if (!last.includes(".")) return "";
  return last.split(".").pop().toLowerCase();
}

function mimeTypeFromFileName(fileName = "") {
  return DOCUMENT_MIME_TYPES[getFileExtension(fileName)] || "application/octet-stream";
}

function cleanDocumentFileName(fileName, fallback = "document") {
  const raw = decodeURIComponent(String(fileName || fallback)).split("?")[0].split("#")[0].split("/").pop();
  return (raw || fallback).replace(/[\r\n"]/g, "_").trim() || fallback;
}

function contentDispositionValue(type, fileName) {
  const safe = cleanDocumentFileName(fileName);
  return `${type}; filename="${safe}"; filename*=UTF-8''${encodeURIComponent(safe)}`;
}

function normalizeDocumentMime(contentType, fileName) {
  const headerType = String(contentType || "").split(";")[0].trim().toLowerCase();
  if (headerType && !["application/octet-stream", "binary/octet-stream", "application/unknown"].includes(headerType)) return headerType;
  const fromName = mimeTypeFromFileName(fileName);
  if (fromName && fromName !== "application/octet-stream") return fromName;
  return "application/pdf";
}

function sendDocumentResponse(res, req, buffer, contentType, fileName, forDownload = false) {
  const safeFileName = cleanDocumentFileName(fileName, `document_${Date.now()}`);
  const finalContentType = normalizeDocumentMime(contentType, safeFileName);
  const clientType = req.headers["x-client-type"] || req.query.clientType || req.headers["user-agent"] || "";
  const isMobile = clientType === "mobile" || clientType.toLowerCase().includes("mobile") || clientType.toLowerCase().includes("expo") || req.query.mobile === "true";
  if (isMobile) {
    return res.json({ success:true, base64:buffer.toString("base64"), mimeType:finalContentType, contentType:finalContentType, fileName:safeFileName, extension:getFileExtension(safeFileName), size:buffer.length, download:forDownload||true, fileData:{ name:safeFileName, type:finalContentType, size:buffer.length, lastModified:Date.now() } });
  }
  const dispositionType = forDownload ? "attachment" : "inline";
  res.set({
    "Content-Type": finalContentType, "Content-Length": buffer.length,
    "Content-Disposition": contentDispositionValue(dispositionType, safeFileName),
    "Cache-Control": "private, no-cache, no-store, must-revalidate",
    "Pragma": "no-cache", "Expires": "0",
    "Access-Control-Expose-Headers": "Content-Disposition, Content-Length, Content-Type"
  });
  return res.status(200).send(buffer);
}

function fileNameFromContentDisposition(contentDisposition) {
  const cd = String(contentDisposition || "");
  const utf8Match = cd.match(/filename\*=UTF-8''([^;]+)/i);
  if (utf8Match?.[1]) return cleanDocumentFileName(decodeURIComponent(utf8Match[1]));
  const normalMatch = cd.match(/filename="?([^";]+)"?/i);
  if (normalMatch?.[1]) return cleanDocumentFileName(normalMatch[1]);
  return "";
}

async function getZohoAttachmentFileName(module, recordId, attachmentId, accessToken) {
  try {
    const list = await axios.get(`${ZOHO_CRM_URL}/crm/v3/${module}/${recordId}/Attachments`, { headers:{ Authorization:`Zoho-oauthtoken ${accessToken}` }, timeout:15000 });
    const items = list.data?.data || [];
    const found = items.find((item) => String(item.id) === String(attachmentId) || String(item.$file_id || "") === String(attachmentId));
    return cleanDocumentFileName(found?.File_Name || found?.file_name || found?.name || attachmentId);
  } catch (_) { return cleanDocumentFileName(attachmentId); }
}

const axiosDocsInstance = axios.create();
async function safeZohoFileFetch(url, accessToken) {
  try {
    const res = await axiosDocsInstance.get(url, { headers:{ Authorization:`Zoho-oauthtoken ${accessToken}` }, responseType:"arraybuffer", timeout:30000, maxRedirects:0, validateStatus:(status)=>status>=200&&status<400 });
    if (res.status >= 300 && res.status < 400 && res.headers.location) {
      const redirectedRes = await axiosDocsInstance.get(res.headers.location, { responseType:"arraybuffer", timeout:30000 });
      return redirectedRes;
    }
    return res;
  } catch (error) {
    if (error.response && error.response.status >= 300 && error.response.status < 400 && error.response.headers.location) {
      const redirectedRes = await axiosDocsInstance.get(error.response.headers.location, { responseType:"arraybuffer", timeout:30000 });
      return redirectedRes;
    }
    throw error;
  }
}

async function streamDocumentFromZoho(module, recordId, attachmentId) {
  const accessToken = await getValidZohoToken();
  const listedFileName = await getZohoAttachmentFileName(module, recordId, attachmentId, accessToken);
  const urlsToTry = [
    `${ZOHO_CRM_URL}/crm/v3/${module}/${recordId}/actions/download_fields_attachment?fields_attachment_id=${attachmentId}`,
    `${ZOHO_CRM_URL}/crm/v3/${module}/${recordId}/Attachments/${attachmentId}`,
    `${ZOHO_CRM_URL}/crm/v2/${module}/${recordId}/Attachments/${attachmentId}`,
  ];
  let lastError = null;
  for (const url of urlsToTry) {
    try {
      const response = await safeZohoFileFetch(url, accessToken);
      if (response.status === 204) continue;
      const buffer = Buffer.from(response.data || []);
      if (!buffer.length) { lastError = new Error("Zoho returned an empty file"); continue; }
      const rawContentType = String(response.headers["content-type"] || "application/octet-stream").toLowerCase();
      const looksLikeJson = rawContentType.includes("application/json") || rawContentType.includes("text/html");
      if (looksLikeJson) { lastError = new Error(`Zoho returned ${rawContentType} instead of a file`); continue; }
      const headerFileName = fileNameFromContentDisposition(response.headers["content-disposition"]);
      const fileName = cleanDocumentFileName(headerFileName || listedFileName || attachmentId, `document_${Date.now()}`);
      const contentType = normalizeDocumentMime(rawContentType, fileName);
      return { buffer, contentType, fileName };
    } catch (error) { lastError = error; }
  }
  console.error("[DOC] Failed to fetch Zoho document:", lastError?.message || lastError);
  return null;
}

