function normalizeApplicationStatus(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[–—]/g, "-")
    .replace(/\s*-\s*/g, "-")
    .replace(/\s+/g, " ");
}

function extractRecruitPicklistValue(
  value
) {
  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  if (
    typeof value ===
    "object"
  ) {
    return String(
      value.value ??
      value.name ??
      value.display_value ??
      value.displayValue ??
      value.label ??
      ""
    ).trim();
  }

  return String(value)
    .trim();
}

function isTransferToICPUSRNStatus(
  value
) {
  const normalized =
    normalizeApplicationStatus(
      extractRecruitPicklistValue(
        value
      )
    );

  if (
    [
      "transfer to icp usrn school",
      "transfer to ivp usrn school"
    ].includes(
      normalized
    )
  ) {
    return true;
  }

  return (
    normalized.includes(
      "transfer"
    ) &&
    (
      normalized.includes(
        "icp"
      ) ||
      normalized.includes(
        "ivp"
      )
    ) &&
    normalized.includes(
      "usrn"
    ) &&
    normalized.includes(
      "school"
    )
  );
}


