async function ensureHistoricalNCLEXEligibility(
  candidateEmail
) {
  if (!mongoConnected) {
    return false;
  }

  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  const history =
    await PipelineStage.find({
      candidate_email:
        email,
      stage_name: {
        $in:
          NCLEX_HISTORICAL_STAGE_NAMES
      },
      is_deleted: {
        $ne: true
      }
    })
      .sort({
        stage_order: 1,
        updated_at: 1
      })
      .lean();

  const transferRows =
    await PipelineStage.find({
      candidate_email:
        email,
      stage_name:
        "Transfer to ICP USRN School",
      is_deleted: {
        $ne: true
      }
    })
      .sort({
        updated_at: -1
      })
      .lean();

  const hasNCLEXHistory =
    history.some(stage => {
      const status =
        String(
          stage.status ||
          ""
        )
          .trim()
          .toLowerCase();

      return (
        isStoredStageComplete(
          stage
        ) ||
        status ===
          "in progress" ||
        status ===
          "in-progress" ||
        stage.nclex_eligible ===
          true ||
        stage.nclex_branch_visible ===
          true
      );
    });

  const hasTransferHistory =
    transferRows.some(
      isStoredTransferReached
    );

  const hasHistory =
    hasNCLEXHistory ||
    hasTransferHistory;

  if (!hasHistory) {
    return false;
  }

  const dates =
    [
      ...history,
      ...transferRows
    ]
      .map(
        stage =>
          stage.completed_date ||
          stage.completed_at ||
          stage.started_at ||
          stage.created_at
      )
      .filter(Boolean)
      .map(value =>
        new Date(value)
      )
      .filter(
        value =>
          !Number.isNaN(
            value.getTime()
          )
      )
      .sort(
        (a, b) =>
          a.getTime() -
          b.getTime()
      );

  const historicalDate =
    dates[0] ||
    new Date();

  await PipelineStage.findOneAndUpdate(
    {
      candidate_email:
        email,
      stage_name:
        "Transfer to ICP USRN School"
    },
    {
      $set: {
        candidate_email:
          email,
        stage_name:
          "Transfer to ICP USRN School",
        stage_category:
          "Hiring",
        status:
          "Completed",
        completed:
          true,
        is_completed:
          true,
        nclex_eligible:
          true,
        nclex_branch_visible:
          true,
        transfer_status_verified:
          true,
        completion_source:
          "historical_nclex_progress",
        is_deleted:
          false,
        updated_at:
          new Date()
      },
      $setOnInsert: {
        completed_date:
          historicalDate,
        created_at:
          historicalDate
      }
    },
    {
      upsert: true,
      new: true
    }
  );

  return true;
}

