function extractApplicationCandidateLookup(application) {
  if (!application) return { id: null, name: "", email: "" };
  const possibleLookups = [
    application.Candidate_Name,
    application.Candidate,
    application.Candidate_ID,
    application.Candidate_Id,
    application.Candidate_Details,
    application.Candidate_Record
  ];
  for (const lookup of possibleLookups) {
    if (!lookup) continue;
    if (typeof lookup === "string") {
      const value = lookup.trim();
      if (/^[0-9]{8,}$/.test(value)) return { id: value, name: "", email: "" };
      continue;
    }
    if (typeof lookup === "object") {
      const id = lookup.id ?? lookup.ID ?? lookup.record_id ?? lookup.recordId ?? null;
      if (id) {
        return {
          id: String(id),
          name: String(lookup.name ?? lookup.display_value ?? ""),
          email: normalizePipelineEmail(lookup.Email ?? lookup.email ?? "")
        };
      }
    }
  }
  return { id: null, name: "", email: "" };
}

async function verifyApplicationCandidateLink(applications, validEmails, { forceRefresh = false } = {}) {
  const normalizedValidEmails = new Set([...(validEmails || [])].map(normalizePipelineEmail).filter(Boolean));
  const evidence = [];
  for (const application of applications || []) {
    if (!application?.id) continue;
    let fullApplication = application;
    let lookup = extractApplicationCandidateLookup(fullApplication);
    if (!lookup.id) {
      try {
        const applicationResponse = await makeZohoRecruitApiRequest(
          `/recruit/v2/Applications/${application.id}`,
          {
            cacheTtlMs: RECRUIT_HIRING_STATE_TTL_MS,
            forceRefresh: forceRefresh === true,
            allowRecruitLiveRefresh: forceRefresh === true
          }
        );
        fullApplication = applicationResponse?.data?.[0] || application;
        lookup = extractApplicationCandidateLookup(fullApplication);
      } catch (error) {
        console.warn(`[Hiring] Application ${application.id} linked Candidate lookup failed:`, error.message);
      }
    }
    if (!lookup.id) continue;
    let linkedCandidate = null;
    try {
      const candidateResponse = await makeZohoRecruitApiRequest(
        `/recruit/v2/Candidates/${lookup.id}`,
        {
          cacheTtlMs: RECRUIT_HIRING_STATE_TTL_MS,
          forceRefresh: forceRefresh === true,
          allowRecruitLiveRefresh: forceRefresh === true
        }
      );
      linkedCandidate = candidateResponse?.data?.[0] || null;
    } catch (error) {
      console.warn(`[Hiring] Linked Candidate ${lookup.id} read failed:`, error.message);
    }
    const linkedCandidateEmail = extractRecruitRecordEmail(linkedCandidate, lookup.email);
    const applicationEmail = extractRecruitRecordEmail(fullApplication, application?._matchedEmail);
    const matchedApplicationEmail = normalizePipelineEmail(application?._matchedEmail);
    const applicationEmailMatches = Boolean(applicationEmail && normalizedValidEmails.has(applicationEmail));
    const candidateEmailMatches = Boolean(linkedCandidateEmail && normalizedValidEmails.has(linkedCandidateEmail));
    const verified = Boolean(candidateEmailMatches && (applicationEmailMatches || (matchedApplicationEmail && normalizedValidEmails.has(matchedApplicationEmail))));
    evidence.push({
      applicationId: String(application.id),
      candidateId: String(lookup.id),
      applicationEmail: applicationEmail || matchedApplicationEmail || null,
      candidateEmail: linkedCandidateEmail || null,
      applicationEmailMatches,
      candidateEmailMatches,
      verified
    });
  }
  return {
    verified: evidence.some(item => item.verified === true),
    evidence,
    verifiedLink: evidence.find(item => item.verified === true) || null
  };
}

const getNewestRecruitRecord =
  records =>
    [...(records || [])]
      .sort(
        (a, b) =>
          new Date(
            b.Modified_Time ||
            b.Created_Time ||
            0
          ) -
          new Date(
            a.Modified_Time ||
            a.Created_Time ||
            0
          )
      )[0] ||
    null;

async function getRecruitHiringState(
  candidateEmail,
  {
    forceRefresh = false
  } = {}
) {
  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  if (!email) {
    return {
      email: "",
      applicationsFound: false,
      candidatesFound: false,
      associatedWithJob: false,
      applicationStatus: "",
      normalizedApplicationStatus:
        "",
      completedStages: [],
      currentStage: null,
      nclexEligible: false,
      source:
        "none"
    };
  }

  const cacheKey =
    `recruit-hiring-state:v5:${email}`;

  if (!forceRefresh) {
    const memory =
      getMemoryCacheEntry(
        zohoSearchCache,
        cacheKey,
        RECRUIT_HIRING_STATE_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (memory) {
      return memory.data;
    }

    const persistent =
      await getPersistentApiCache(
        cacheKey,
        RECRUIT_HIRING_STATE_TTL_MS,
        {
          allowStale:
            isZohoQuotaCircuitOpen()
        }
      );

    if (persistent) {
      setMemoryCacheEntry(
        zohoSearchCache,
        cacheKey,
        persistent.data
      );

      return persistent.data;
    }
  }

  if (
    recruitHiringStateInFlight.has(
      email
    )
  ) {
    return recruitHiringStateInFlight.get(
      email
    );
  }

  const promise = (async () => {
    const candidateEmails =
      typeof getCandidatePipelineEmails ===
        "function"
        ? await getCandidatePipelineEmails(
            email
          )
        : [email];

    const aliases = [
      ...new Set(
        [
          email,
          ...(candidateEmails || [])
        ]
          .map(
            normalizePipelineEmail
          )
          .filter(Boolean)
      )
    ];

    const applications = [];
    const candidates = [];

    // This is the only controlled live Recruit read used by the hiring
    // pipeline. It is cached as one hiring-state snapshot, so Dashboard,
    // Pipeline and NCLEX do not independently reopen Recruit calls.
    for (
      const alias of aliases
    ) {
      const [
        applicationRows,
        candidateRows
      ] =
        await Promise.all([
          findRecruitRecordsByEmailRobust(
            "Applications",
            alias,
            {
              forceRefresh:
                forceRefresh ===
                true
            }
          ).catch(() => []),
          findRecruitRecordsByEmailRobust(
            "Candidates",
            alias,
            {
              forceRefresh:
                forceRefresh ===
                true
            }
          ).catch(() => [])
        ]);

      applications.push(
        ...(applicationRows || [])
      );

      candidates.push(
        ...(candidateRows || [])
      );
    }

    const applicationsWithStatus =
      applications.map(
        record => ({
          record,
          status:
            extractRecruitPicklistValue(
              record
                ?.Application_Status ??
              record
                ?.Lead_Management_Status ??
              record
                ?.leadManagementStatus
            )
        })
      );

    const transferApplications =
      applicationsWithStatus
        .filter(
          item =>
            isTransferToICPUSRNStatus(
              item.status
            )
        )
        .map(
          item =>
            item.record
        );

    const applicationsHavingStatus =
      applicationsWithStatus
        .filter(
          item =>
            Boolean(
              item.status
            )
        )
        .map(
          item =>
            item.record
        );

    let latestApplication =
      getNewestRecruitRecord(
        transferApplications
      ) ||
      getNewestRecruitRecord(
        applicationsHavingStatus
      ) ||
      getNewestRecruitRecord(
        applications
      );

    const latestCandidate =
      getNewestRecruitRecord(
        candidates
      );

    let applicationStatus =
      extractRecruitPicklistValue(
        latestApplication
          ?.Application_Status ??
        latestApplication
          ?.Lead_Management_Status ??
        latestApplication
          ?.leadManagementStatus
      );

    // Search responses may omit the picklist. Read exactly one Applications
    // record when necessary. This read is also cached by record URL.
    if (
      latestApplication?.id &&
      !applicationStatus
    ) {
      try {
        const response =
          await makeZohoRecruitApiRequest(
            `/recruit/v2/Applications/${latestApplication.id}`,
            {
              cacheTtlMs:
                RECRUIT_HIRING_STATE_TTL_MS,
              forceRefresh:
                forceRefresh ===
                true,
              allowRecruitLiveRefresh:
                forceRefresh ===
                true
            }
          );

        latestApplication =
          response?.data?.[0] ||
          latestApplication;

        applicationStatus =
          extractRecruitPicklistValue(
            latestApplication
              ?.Application_Status ??
            latestApplication
              ?.Lead_Management_Status ??
            latestApplication
              ?.leadManagementStatus
          );
      } catch (error) {
        console.warn(
          "[Recruit Hiring State] Full Applications record failed:",
          error.message
        );
      }
    }

    if (
      applications.length > 0 &&
      !isTransferToICPUSRNStatus(
        applicationStatus
      )
    ) {
      const rowsToInspect =
        applications
          .filter(
            record =>
              record?.id &&
              !extractRecruitPicklistValue(
                record
                  ?.Application_Status ??
                record
                  ?.Lead_Management_Status ??
                record
                  ?.leadManagementStatus
              )
          )
          .slice(
            0,
            5
          );

      for (
        const application of
        rowsToInspect
      ) {
        try {
          const response =
            await makeZohoRecruitApiRequest(
              `/recruit/v2/Applications/${application.id}`,
              {
                cacheTtlMs:
                  RECRUIT_HIRING_STATE_TTL_MS,
                forceRefresh:
                  forceRefresh ===
                    true,
                allowRecruitLiveRefresh:
                  forceRefresh ===
                    true
              }
            );

          const fullRecord =
            response?.data?.[0];

          const fullStatus =
            extractRecruitPicklistValue(
              fullRecord
                ?.Application_Status ??
              fullRecord
                ?.Lead_Management_Status ??
              fullRecord
                ?.leadManagementStatus
            );

          if (
            isTransferToICPUSRNStatus(
              fullStatus
            )
          ) {
            latestApplication =
              fullRecord ||
              application;

            applicationStatus =
              fullStatus;

            break;
          }

          if (
            !applicationStatus &&
            fullStatus
          ) {
            latestApplication =
              fullRecord ||
              application;

            applicationStatus =
              fullStatus;
          }
        } catch (error) {
          console.warn(
            "[Recruit Hiring State] Application detail read failed:",
            error.message
          );
        }
      }
    }

    const normalizedStatus =
      normalizeApplicationStatus(
        applicationStatus
      );

    const statusProgress =
      isTransferToICPUSRNStatus(
        applicationStatus
      )
        ? HIRING_STATUS_PROGRESS_MAP[
            "transfer to icp usrn school"
          ]
        : (
            HIRING_STATUS_PROGRESS_MAP[
              normalizedStatus
            ] ||
            {
              completed: [],
              current: null
            }
          );

    const completedStages =
      new Set(
        statusProgress.completed ||
        []
      );

    const applicationCandidateLink =
      await verifyApplicationCandidateLink(
        applications,
        aliases,
        { forceRefresh: forceRefresh === true }
      ).catch(error => {
        console.warn("[Hiring] Application -> linked Candidate verification failed:", error.message);
        return { verified: false, evidence: [], verifiedLink: null };
      });

    const dedupeRecruitRecords =
      rows => {
        const seen =
          new Set();

        return (rows || [])
          .filter(record => {
            const key =
              String(
                record?.id ||
                [
                  record?._recruitModule,
                  record?._recordEmail,
                  record?.Modified_Time
                ]
                  .filter(Boolean)
                  .join(":")
              );

            if (
              seen.has(key)
            ) {
              return false;
            }

            seen.add(key);
            return true;
          });
      };

    const uniqueApplications =
      dedupeRecruitRecords(
        applications
      );

    const uniqueCandidates =
      dedupeRecruitRecords(
        candidates
      );

    const applicationEmailSet =
      new Set(
        uniqueApplications
          .map(record =>
            extractRecruitRecordEmail(
              record
            )
          )
          .filter(Boolean)
      );

    const candidateEmailSet =
      new Set(
        uniqueCandidates
          .map(record =>
            extractRecruitRecordEmail(
              record
            )
          )
          .filter(Boolean)
      );

    const savedAssociationRows =
      mongoConnected
        ? await PipelineStage.find({
            candidate_email:
              email,
            stage_name: {
              $in: [
                "Applied",
                "Associated with Job"
              ]
            },
            is_deleted: {
              $ne: true
            }
          })
            .lean()
            .catch(() => [])
        : [];

    const savedAppliedComplete =
      savedAssociationRows.some(
        stage =>
          stage.stage_name ===
            "Applied" &&
          isStoredStageComplete(
            stage
          )
      );

    const savedAssociatedComplete =
      savedAssociationRows.some(
        stage =>
          stage.stage_name ===
            "Associated with Job" &&
          isStoredStageComplete(
            stage
          )
      );

    const applicationsFound =
      applicationEmailSet.size >
        0 ||
      savedAppliedComplete ||
      savedAssociatedComplete;

    const candidatesFound =
      candidateEmailSet.size >
        0 ||
      applicationCandidateLink.verified === true ||
      savedAssociatedComplete;

    const matchingModuleEmails =
      [
        ...applicationEmailSet
      ].filter(email =>
        candidateEmailSet.has(
          email
        )
      );

    // Applied = candidate identity exists in Applications.
    // Associated with Job = the same canonical candidate identity/aliases exists
    // in BOTH Applications and Candidates. Exact literal intersection is only
    // diagnostic because Recruit can return an old/current email alias or omit
    // Email from one search response.
    const associatedWithJob =
      (
        applicationsFound &&
        (
          candidatesFound ||
          applicationCandidateLink.verified === true
        )
      ) ||
      savedAssociatedComplete;

    if (applicationsFound) {
      completedStages.add(
        "Applied"
      );
    }

    if (associatedWithJob) {
      completedStages.add(
        "Associated with Job"
      );
    }

    const transferStatusSelected =
      isTransferToICPUSRNStatus(
        applicationStatus
      );

    const durableNCLEXHistory =
      await hasDurableNCLEXBranchHistory(
        email
      );

    const result = {
      email,
      applicationRecordId:
        latestApplication?.id ||
        null,
      candidateRecordId:
        latestCandidate?.id ||
        null,
      applicationsFound,
      candidatesFound,
      associatedWithJob,
      matchingModuleEmails,
      matchedAssociationEmail:
        matchingModuleEmails[0] ||
        (
          associatedWithJob
            ? email
            : null
        ),
      applicationRecordCount:
        uniqueApplications.length,
      candidateRecordCount:
        uniqueCandidates.length,
      applicationMatchMethods: [
        ...new Set(
          uniqueApplications
            .map(
              record =>
                record
                  ?._emailMatchMethod
            )
            .filter(Boolean)
        )
      ],
      candidateMatchMethods: [
        ...new Set(
          uniqueCandidates
            .map(
              record =>
                record
                  ?._emailMatchMethod
            )
            .filter(Boolean)
        )
      ],
      applicationCandidateLinkVerified:
        applicationCandidateLink.verified === true,
      applicationCandidateLink:
        applicationCandidateLink.verifiedLink || null,
      applicationCandidateLinkEvidence:
        applicationCandidateLink.evidence || [],
      searchedEmailAliases:
        aliases,
      applicationStatus:
        applicationStatus ||
        "",
      normalizedApplicationStatus:
        normalizedStatus,
      completedStages:
        [...completedStages],
      currentStage:
        statusProgress.current ||
        null,
      mappedStage:
        LEAD_MANAGEMENT_STATUS_STAGE_MAP.get(
          normalizedStatus
        ) ||
        null,
      transferStatusSelected,
      durableNCLEXHistory,
      nclexEligible:
        transferStatusSelected ||
        durableNCLEXHistory,
      source:
        "Recruit Applications.Application_Status + exact Email module presence",
      fetchedAt:
        new Date()
          .toISOString()
    };

    setMemoryCacheEntry(
      zohoSearchCache,
      cacheKey,
      result
    );

    await setPersistentApiCache(
      cacheKey,
      result,
      {
        type:
          "recruit-hiring-state",
        email
      }
    );

    applicationStatusAccessCache.set(
      email,
      {
        status:
          result.applicationStatus,
        fetchedAt:
          Date.now(),
        source:
          result.source
      }
    );

    return result;
  })().finally(() => {
    recruitHiringStateInFlight.delete(
      email
    );
  });

  recruitHiringStateInFlight.set(
    email,
    promise
  );

  return promise;
}

async function syncRecruitHiringPresenceStages({
  email,
  hiringState
}) {
  if (
    !mongoConnected ||
    !PipelineStage ||
    !hiringState
  ) {
    return;
  }

  const now =
    new Date();

  const markCompleted =
    async (
      stageName,
      completionSource
    ) => {
      const existing =
        await PipelineStage.findOne({
          candidate_email:
            email,
          stage_name:
            stageName,
          is_deleted: {
            $ne: true
          }
        })
          .sort({
            completed_date: -1,
            updated_at: -1
          });

      const payload = {
        candidate_email:
          email,
        stage_name:
          stageName,
        stage_category:
          "Hiring",
        status:
          "Completed",
        completed:
          true,
        is_completed:
          true,
        completed_date:
          existing?.completed_date ||
          existing?.completed_at ||
          now,
        completion_source:
          completionSource,
        recruit_application_status:
          hiringState
            .applicationStatus ||
          "",
        updated_at:
          now,
        is_deleted:
          false
      };

      const update =
        await PipelineStage.updateMany(
          {
            candidate_email:
              email,
            stage_name:
              stageName
          },
          {
            $set:
              payload
          }
        );

      if (
        update.matchedCount ===
        0
      ) {
        await PipelineStage.create({
          ...payload,
          created_at:
            now
        });
      }
    };

  if (
    hiringState.applicationsFound
  ) {
    await markCompleted(
      "Applied",
      "recruit_applications_email_match"
    );
  }

  if (
    hiringState.associatedWithJob
  ) {
    console.log(
      `[Hiring] Associated with Job verified for ${email}: Applications=${hiringState.applicationsFound}, Candidates=${hiringState.candidatesFound}, matched=${hiringState.matchedAssociationEmail || "candidate-alias"}`
    );

    await markCompleted(
      "Associated with Job",
      `recruit_applications_candidates_email_match:${
        hiringState
          .matchedAssociationEmail ||
        email
      }`
    );
  }
}

async function getCandidateApplicationStatus(
  email,
  forceRefresh = false
) {
  const key =
    normalizePipelineEmail(
      email
    );

  if (!key) {
    return "";
  }

  const cached =
    applicationStatusAccessCache.get(
      key
    );

  if (
    !forceRefresh &&
    cached &&
    Date.now() -
      cached.fetchedAt <
      APPLICATION_STATUS_ACCESS_CACHE_MS
  ) {
    return cached.status;
  }

  try {
    const hiringState =
      await getRecruitHiringState(
        key,
        {
          forceRefresh:
            forceRefresh ===
            true
        }
      );

    return (
      hiringState
        ?.applicationStatus ||
      cached?.status ||
      ""
    );
  } catch (error) {
    console.warn(
      `[Access] Could not fetch Recruit Application_Status for ${key}:`,
      error.message
    );

    return (
      cached?.status ||
      ""
    );
  }
}

async function isCandidatePortalBlocked(email, forceRefresh = false) {
  const status = await getCandidateApplicationStatus(email, forceRefresh);
  const normalizedStatus = normalizeApplicationStatus(status);

  // Qualified Candidate Pool is an active holding stage. It must never revoke
  // an existing session or prevent a new login.
  const explicitlyAllowed =
    normalizedStatus === "qualified candidate pool" ||
    normalizedStatus === "qualified-candidate pool";

  return {
    blocked:
      !explicitlyAllowed &&
      PORTAL_BLOCKED_APPLICATION_STATUSES.has(normalizedStatus),
    status,
    mappedHiringStage: getHiringStageFromLeadManagementStatus(status)
  };
}

// Converts Zoho CRM file-upload field values into the same document shape used
// by ordinary Recruit/CRM attachments.
const CRM_DOCUMENT_FILE_FIELDS = [
  { apiName: "Birth_Certificate", label: "Birth Certificate" },
  { apiName: "Called_1_Yr_Results", label: "Called 1 Yr Results" },
  { apiName: "COE_Letter_of_Empl", label: "COE/Letter of Employment" },
  { apiName: "Concierge_biography", label: "Concierge Biography" },
  { apiName: "Debrief_Survey", label: "Debrief Survey" },
  { apiName: "Emp_Contract", label: "Employment Contract" },
  { apiName: "Flight_Confirmation", label: "Flight Confirmation" },
  { apiName: "Immigration_Pathway_Acknowledgement", label: "Immigration Pathway Acknowledgement" },
  { apiName: "Passport", label: "Passport" },
  { apiName: "Signed_ICP", label: "Service Agreement" },
  { apiName: "Signed_Offer", label: "Signed Offer" },
  { apiName: "Updated_Resume_Doc", label: "Updated Resume" },
  { apiName: "Welcome_Appointments", label: "Welcome Appointments" },
  { apiName: "Advance_Agreement", label: "Expense Report" }
];

function normalizeCRMFileUploadFields(deal) {
  const docs = [];
  if (!deal?.id) return docs;
  for (const field of CRM_DOCUMENT_FILE_FIELDS) {
    const raw = deal[field.apiName];
    const values = Array.isArray(raw) ? raw : raw ? [raw] : [];
    values.forEach((file, index) => {
      const fileId = typeof file === "string"
        ? file
        : file?.file_Id || file?.file_id || file?.id || file?.attachment_id;
      if (!fileId) return;
      const fileName = typeof file === "object"
        ? (file?.File_Name || file?.file_name || file?.name || file?.display_value)
        : null;
      docs.push({
        id: fileId,
        attachment_id: fileId,
        document_name: fileName || `${field.label}${values.length > 1 ? ` ${index + 1}` : ""}`,
        source: "crm",
        sourceLabel: "CRM",
        sourceIcon: "📤",
        sourceColor: "bg-green-100 text-green-700 border-green-200",
        uploaded_at: deal.Modified_Time || deal.Created_Time || new Date().toISOString(),
        file_size: file?.Size || file?.size || 0,
        file_type: file?.File_Type || file?.type || "application/pdf",
        deal_id: deal.id,
        module: "Deals",
        crm_field_api_name: field.apiName,
        crm_file_upload_field: true,
        status: "Available",
      });
    });
  }
  return docs;
}

const isDocumentApprovalExempt = document => {
  const searchable = [
    document?.document_name,
    document?.document_type,
    document?.document_category,
    document?.pipeline_section,
    document?.section,
    document?.form_type
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  return (
    searchable.includes("relocation") ||
    searchable.includes("r&l") ||
    searchable.includes("r and l") ||
    searchable.includes("housing") ||
    searchable.includes("behavioral assessment") ||
    searchable.includes("behavioural assessment") ||
    searchable.includes("behavior assessment")
  );
};

const buildDocumentApprovalKey = document => {
  const source =
    String(
      document?.source ||
      "unknown"
    )
      .trim()
      .toLowerCase();

  const field =
    String(
      document?.crm_field_api_name ||
      ""
    )
      .trim()
      .toLowerCase();

  const fieldName =
    String(
      document
        ?.crm_field_api_name ||
      field ||
      ""
    )
      .trim()
      .toLowerCase();

  const recordId =
    String(
      document?.deal_id ||
      document?.candidate_id ||
      ""
    ).trim();

  const id =
    String(
      document?.attachment_id ||
      document?.id ||
      document?.document_id ||
      document?._id ||
      ""
    )
      .trim();

  return [
    source,
    fieldName,
    recordId || id
  ].join(":");
};

async function collectCandidateDocuments(
  requestedEmail
) {
  const email =
    await resolveCanonicalPipelineEmail(
      requestedEmail
    );

  const documents = [];
  const token =
    await getValidZohoToken();

  // Recruit attachments from every matching candidate record.
  try {
    const candidates =
      await searchRecruitCandidateRecordsOnly(
        email,
        {
          forceRefresh: false
        }
      );

    for (const candidate of candidates || []) {
      if (!candidate?.id) continue;

      try {
        const responseData =
          await makeZohoRecruitApiRequest(
            `/recruit/v2/Candidates/${candidate.id}/Attachments`,
            {
              cacheTtlMs:
                RECRUIT_STATIC_CACHE_TTL_MS
            }
          );

        for (
          const attachment of
          responseData?.data || []
        ) {
          const id =
            attachment.id ||
            attachment.attachment_id;

          if (!id) continue;

          documents.push({
            id,
            attachment_id: id,
            document_name:
              attachment.File_Name ||
              attachment.name ||
              `Recruit Document ${id}`,
            document_type:
              attachment.attachments_category ||
              "Recruit Attachment",
            source: "recruit",
            uploaded_at:
              attachment.Created_Time ||
              attachment.created_at ||
              new Date().toISOString(),
            file_size:
              attachment.Size ||
              0,
            file_type:
              attachment.File_Type ||
              "application/octet-stream",
            candidate_id:
              candidate.id,
            module:
              "Candidates",
            status:
              "Available"
          });
        }
      } catch (candidateError) {
        console.warn(
          `[Documents] Recruit record ${candidate.id} could not be read:`,
          candidateError.message
        );
      }

      // Proof_of_NCLEX and Birth_Certificate are Recruit text fields.
      // They are evaluated by /api/pipeline/field-status as stage triggers
      // and must not be represented as uploaded documents.
    }
  } catch (recruitError) {
    console.warn(
      "[Documents] Recruit collection failed:",
      recruitError.message
    );
  }

  // CRM ordinary attachments and all configured CRM file-upload fields.
  try {
    const deals =
      await searchDealsByEmail(email);

    for (const deal of deals || []) {
      if (!deal?.id) continue;

      try {
        const response = await axios.get(
          `${ZOHO_CRM_URL}/crm/v3/Deals/${deal.id}/Attachments`,
          {
            headers: {
              Authorization:
                `Zoho-oauthtoken ${token}`
            },
            timeout: 30000
          }
        );

        for (
          const attachment of
          response.data?.data || []
        ) {
          const id =
            attachment.id ||
            attachment.attachment_id;

          if (!id) continue;

          documents.push({
            id,
            attachment_id: id,
            document_name:
              attachment.File_Name ||
              attachment.name ||
              `CRM Document ${id}`,
            document_type:
              "CRM Attachment",
            source:
              "crm",
            uploaded_at:
              attachment.Created_Time ||
              attachment.created_at ||
              deal.Modified_Time ||
              new Date().toISOString(),
            file_size:
              attachment.Size ||
              0,
            file_type:
              attachment.File_Type ||
              "application/octet-stream",
            deal_id:
              deal.id,
            module:
              "Deals",
            status:
              "Available"
          });
        }
      } catch (attachmentError) {
        console.warn(
          `[Documents] CRM attachments for Deal ${deal.id} could not be read:`,
          attachmentError.message
        );
      }

      let fullDeal =
        deal;

      try {
        const fullDealResponse =
          await axios.get(
            `${ZOHO_CRM_URL}/crm/v3/Deals/${deal.id}`,
            {
              headers: {
                Authorization:
                  `Zoho-oauthtoken ${token}`
              },
              timeout: 30000
            }
          );

        fullDeal =
          fullDealResponse
            .data?.data?.[0] ||
          deal;
      } catch (fieldError) {
        console.warn(
          `[Documents] Full CRM Deal ${deal.id} could not be read:`,
          fieldError.message
        );
      }

      documents.push(
        ...normalizeCRMFileUploadFields(
          fullDeal
        )
      );
    }
  } catch (crmError) {
    console.warn(
      "[Documents] CRM collection failed:",
      crmError.message
    );
  }

  // Recruiting uploads awaiting admin approval are stored locally until approved.
  if (
    mongoConnected &&
    mongoose.connection?.db
  ) {
    try {
      const pendingRecruitDocuments =
        await mongoose.connection.db
          .collection(
            "pending_recruit_document_uploads"
          )
          .find({
            candidate_email:
              normalizePipelineEmail(
                email
              ),
            approval_status: {
              $in: [
                "pending",
                "rejected"
              ]
            }
          })
          .sort({
            uploaded_at:
              -1
          })
          .toArray();

      for (
        const pending of
        pendingRecruitDocuments
      ) {
        documents.push({
          id:
            String(
              pending._id
            ),
          attachment_id:
            String(
              pending._id
            ),
          pending_upload_id:
            String(
              pending._id
            ),
          document_name:
            pending.document_name ||
            pending.original_name ||
            "Recruiting Document",
          document_type:
            pending.document_type ||
            "Recruiting Document",
          document_category:
            pending.document_category ||
            null,
          requirement_key:
            pending.requirement_key ||
            null,
          pipeline_section:
            pending.pipeline_section ||
            "hiring",
          source:
            "pending",
          destination:
            "recruit",
          uploaded_at:
            pending.uploaded_at ||
            pending.created_at ||
            new Date()
              .toISOString(),
          file_size:
            pending.file_size ||
            0,
          file_type:
            pending.file_type ||
            "application/octet-stream",
          status:
            pending.approval_status ===
              "rejected"
              ? "Rejected"
              : "Awaiting Approval",
          approval_status:
            pending.approval_status ||
            "pending",
          rejection_reason:
            pending.rejection_reason ||
            null,
          candidate_uploaded:
            true,
          uploaded_via:
            "documents"
        });
      }
    } catch (pendingError) {
      console.warn(
        "[Documents] Pending Recruit document collection failed:",
        pendingError.message
      );
    }
  }

  // Locally logged uploads fill temporary gaps in Zoho responses.
  if (mongoConnected) {
    try {
      const loggedDocuments =
        await Documents.find({
          candidate_email: email
        })
          .sort({
            uploaded_at: -1
          })
          .lean();

      for (
        const document of
        loggedDocuments
      ) {
        documents.push({
          ...document,
          id:
            document.attachment_id ||
            document._id,
          attachment_id:
            document.attachment_id ||
            document.crm_attachment_id ||
            document.recruit_attachment_id ||
            String(document._id),
          document_name:
            document.document_name ||
            "Uploaded Document",
          source:
            (
              String(
                document.destination ||
                ""
              )
                .trim()
                .toLowerCase() ===
                "recruit" ||
              Boolean(
                document.recruit_attachment_id ||
                document.recruit_record_id ||
                document.candidate_id
              )
            )
              ? "recruit"
              : "crm",
          uploaded_at:
            document.uploaded_at ||
            new Date().toISOString(),
          candidate_id:
            document.candidate_id ||
            document.recruit_record_id ||
            null,
          deal_id:
            document.deal_id ||
            document.crm_record_id ||
            document.crm_deal_id ||
            null,
          crm_field_api_name:
            document.crm_field_api_name ||
            null,
          crm_file_upload_field:
            document.crm_file_upload_field === true,
          pipeline_section:
            document.pipeline_section ||
            null,
          document_category:
            document.document_category ||
            null,
          form_type:
            document.form_type ||
            null
        });
      }
    } catch (mongoError) {
      console.warn(
        "[Documents] Mongo fallback failed:",
        mongoError.message
      );
    }
  }

  const unique = Array.from(
    new Map(
      documents.map(document => {
        const key =
          buildDocumentApprovalKey(
            document
          );

        return [
          key,
          {
            ...document,
            approval_key: key
          }
        ];
      })
    ).values()
  );

  let approvals = new Map();

  if (mongoConnected) {
    try {
      const rows =
        await mongoose.connection.db
          .collection(
            "document_approvals"
          )
          .find({
            candidate_email:
              email
          })
          .toArray();

      approvals = new Map(
        rows.map(row => [
          row.approval_key,
          row
        ])
      );
    } catch (approvalError) {
      console.warn(
        "[Documents] Approval lookup failed:",
        approvalError.message
      );
    }
  }

  return unique
    .map(document => {
      const approval =
        approvals.get(
          document.approval_key
        );

      const approvalExempt =
        isDocumentApprovalExempt(
          document
        );

      const sourceApprovalStatus =
        String(
          document.approval_status ||
          ""
        )
          .trim()
          .toLowerCase();

      return {
        ...document,
        approval_exempt:
          approvalExempt,
        approval_status:
          approvalExempt
            ? "approved"
            : (
                approval?.approval_status ||
                (
                  [
                    "pending",
                    "rejected",
                    "approved"
                  ].includes(
                    sourceApprovalStatus
                  )
                    ? sourceApprovalStatus
                    : "pending"
                )
              ),
        approved_at:
          approval?.approved_at ||
          null,
        approved_by:
          approval?.approved_by ||
          null,
        approval_required:
          !approvalExempt,
        already_approved:
          (
            approvalExempt ||
            approval
              ?.approval_status ===
              "approved"
          ),
        rejected_at:
          approval?.rejected_at ||
          null,
        rejection_reason:
          approval?.rejection_reason ||
          null
      };
    })
    .sort(
      (a, b) =>
        new Date(
          b.uploaded_at ||
          0
        ) -
        new Date(
          a.uploaded_at ||
          0
        )
    );
}

// ─── FIXED Authentication Middleware ──────────────────────────────────────────
async function optionalAdminOrUserAuth(
  req,
  res,
  next
) {
  const authorization =
    String(
      req.headers.authorization ||
      ""
    );

  const adminToken =
    String(
      req.headers["x-admin-token"] ||
      (
        authorization.startsWith(
          "AdminBearer "
        )
          ? authorization.slice(
              "AdminBearer ".length
            )
          : ""
      )
    ).trim();

  if (adminToken) {
    return adminAuth(
      req,
      res,
      next
    );
  }

  return authenticateToken(
    req,
    res,
    next
  );
}

async function authenticateToken(req, res, next) {
  const token = extractToken(req);
  
  console.log(`[Auth] authenticateToken called for ${req.path}`);
  
  // Handle admin bypass
  const cookieHeader = req.headers.cookie || "";
  const authHeader = req.headers["authorization"] || "";
  const isAdminRequest = cookieHeader.includes("admin_session=authenticated") || 
                         (authHeader.startsWith("AdminBearer ") && token);
  
  if (isAdminRequest && req.query.email) {
    console.log(`[Auth] Admin bypass for ${req.query.email}`);
    req.userEmail = req.query.email.toLowerCase().trim();
    req.authToken = "admin_bypass";
    return next();
  }
  
  if (!token) {
    console.log(`[Auth] No token provided for ${req.method} ${req.path}`);
    return res.status(401).json({ 
      success: false, 
      message: "Authentication required" 
    });
  }
  
  let tokenData = userTokens.get(token);
  
  if (!tokenData && mongoConnected) {
    try {
      const session = await UserSession.findOne({ 
        token, 
        status: "active",
        sessionExpiresAt: { $gt: new Date() }
      });
      
      if (session) {
        tokenData = { 
          email: session.email, 
          candidateName: session.candidateName, 
          arrivalDate: session.arrivalDate || null, 
          sessionExpiresAt: session.sessionExpiresAt.getTime(), 
          createdAt: session.createdAt instanceof Date ? session.createdAt.getTime() : Date.now() 
        };
        userTokens.set(token, tokenData);
        console.log(`[Auth] ✅ Restored session from DB for ${session.email}`);
      } else {
        const expiredSession = await UserSession.findOne({ token });
        if (expiredSession) {
          console.log(`[Auth] ⚠️ Found expired session for ${expiredSession.email}, clearing...`);
          await UserSession.deleteOne({ token });
        }
      }
    } catch (err) {
      console.error("[Auth] Failed to restore session from DB:", err.message);
    }
  }
  
  if (!tokenData) {
    console.log(`[Auth] ❌ Token not found: ${token.substring(0, 10)}...`);
    return res.status(403).json({ 
      success: false, 
      message: "Invalid or expired token", 
      sessionExpired: true 
    });
  }
  
  const email = typeof tokenData === "string" ? tokenData : tokenData.email;
  if (!email) {
    console.log(`[Auth] Token data missing email for: ${token.substring(0, 10)}...`);
    return res.status(403).json({ 
      success: false, 
      message: "Invalid token data", 
      sessionExpired: true 
    });
  }
  
  if (
    mongoConnected &&
    mongoose.connection?.db
  ) {
    try {
      const accessState =
        await mongoose.connection.db
          .collection(
            "candidate_pipeline_access"
          )
          .findOne({
            candidate_email:
              normalizePipelineEmail(
                email
              )
          });

      const status =
        String(
          accessState
            ?.application_status ||
          ""
        )
          .trim()
          .toLowerCase();

      const unqualified =
        [
          "unqualified",
          "not qualified to close",
          "not qualified - to close",
          "not qualified-to close",
          "not qualified-to-close"
        ].includes(
          status
        );

      const lockAt =
        accessState
          ?.lock_at
          ? new Date(
              accessState.lock_at
            )
          : null;

      const portalLocked =
        unqualified &&
        (
          accessState
            ?.portal_locked ===
            true ||
          (
            lockAt &&
            !Number.isNaN(
              lockAt.getTime()
            ) &&
            Date.now() >=
              lockAt.getTime()
          )
        );

      if (
        portalLocked
      ) {
        userTokens.delete(
          token
        );

        await UserSession
          .updateMany(
            {
              email,
              status:
                "active"
            },
            {
              $set: {
                status:
                  "ended",
                logoutTime:
                  new Date()
              }
            }
          )
          .catch(
            () => {}
          );

        return res
          .status(403)
          .json({
            success:
              false,
            message:
              "Your portal access has ended because you do not currently meet the qualification criteria.",
            portalAccessBlocked:
              true,
            qualificationStatus:
              "Unqualified"
          });
      }
    } catch (
      accessError
    ) {
      console.warn(
        "[Auth] Qualification access check failed:",
        accessError.message
      );
    }
  }

  console.log(`[Auth] ✅ Authentication successful for ${email}`);
  
  updateSessionLastActive(token);
  req.userEmail = email;
  req.authToken = token;
  next();
}

// ─── Helper Functions for Sessions ────────────────────────────────────────────
async function computeSessionExpiry(email, userDetails) {
  return new Date(
    "2099-12-31T23:59:59.999Z"
  ).getTime();
}

async function _createSessionAndRespond(key, req, res) {
  const userDetails = await getUserComprehensiveDetails(key);
  const sessionExpiresAt = await computeSessionExpiry(key, userDetails);
  

  const token = generateToken();
  console.log(`[Auth] Creating session for ${key} with token: ${token.substring(0, 15)}...`);
  
  const cName =
    userDetails?.user?.candidateName ||
    userDetails?.user?.Full_Name ||
    userDetails?.user?.fullName ||
    [
      userDetails?.user?.First_Name ||
        userDetails?.user?.firstName,
      userDetails?.user?.Last_Name ||
        userDetails?.user?.lastName
    ]
      .filter(Boolean)
      .join(" ") ||
    key.split("@")[0];
  const sessionData = { 
    email: key, 
    candidateName: cName, 
    arrivalDate: null, 
    sessionExpiresAt, 
    warningEmailSentAt: null, 
    createdAt: Date.now(), 
    loginTime: new Date().toISOString(), 
    ip: req.clientIp, 
    userAgent: req.userAgent 
  };
  
  userTokens.set(token, sessionData);
  console.log(`[Auth] Token stored in userTokens Map. Total tokens: ${userTokens.size}`);
  
  await savePersistentSession(token, sessionData);
  
  const logEntry = logLoginAttempt(key, cName, "success", token, null, req);
  sessionHistory.set(token, { ...sessionData, logId: logEntry.id });
  
  const expiryRule =
    "Continuous candidate portal access";
  
  const response = { 
    success: true, 
    message: "Login successful", 
    token: token,
    user: { 
      email: key, 
      name: cName, 
      organization: "Deploymate" 
    }, 
    sessionInfo: { 
      sessionExpiresAt, 
      arrivalDate: null, 
      expiryRule 
    } 
  };
  
  console.log(`[Auth] Login response includes token: ${!!response.token}`);
  console.log(`[Auth] Response token preview: ${response.token ? response.token.substring(0, 15) + '...' : 'None'}`);
  
  return res.json(response);
}

