function startSessionExpiryScheduler() {
  console.log(
    "[Auth] Candidate portal expiry scheduler disabled; access is continuous."
  );
}


async function triggerArrivalSession(
  email,
  arrivalDateStr
) {
  if (!mongoConnected) return;

  try {
    const now = new Date();
    let parsedArrivalDate = now;

    if (arrivalDateStr) {
      const normalized =
        String(arrivalDateStr)
          .replace(" • ", ", ");
      const parsed =
        new Date(normalized);

      if (
        !Number.isNaN(
          parsed.getTime()
        )
      ) {
        parsedArrivalDate =
          parsed;
      }
    }

    const permanentExpiry =
      new Date(
        "2099-12-31T23:59:59.999Z"
      );

    let candidateName =
      email.split("@")[0];

    for (
      const [, tokenData] of
      userTokens.entries()
    ) {
      const tokenEmail =
        typeof tokenData === "string"
          ? tokenData
          : tokenData.email;

      if (
        tokenEmail === email &&
        typeof tokenData === "object"
      ) {
        candidateName =
          tokenData.candidateName ||
          candidateName;

        tokenData.arrivalDate =
          parsedArrivalDate;
        tokenData.sessionExpiresAt =
          permanentExpiry.getTime();

        await savePersistentSession(
          null,
          tokenData
        ).catch(() => {});
      }
    }

    await Arrival.findOneAndUpdate(
      { email },
      {
        email,
        candidateName,
        arrivalDate:
          parsedArrivalDate,
        sessionExpiresAt:
          permanentExpiry,
        warningEmailSentAt:
          null,
        confirmedAt:
          now
      },
      { upsert: true }
    );

    arrivalExpiryCache.delete(
      email
    );

    console.log(
      `[AutoArrival] Arrival recorded for ${email}; portal access remains continuous.`
    );

    try {
      const details =
        await getUserComprehensiveDetails(
          email
        );

      if (
        !details.error &&
        details.user
      ) {
        await sendArrivalConfirmation(
          details.user,
          email
        );
      }
    } catch {
      // Arrival email is non-critical.
    }
  } catch (error) {
    console.error(
      `[AutoArrival] Failed for ${email}:`,
      error.message
    );
  }
}


// ─── ZOHO CONNECTION ENGINE ──────────────────────────────────────────────────
async function initializeZohoConnection() {
  if (!ZOHO_CLIENT_ID || !ZOHO_CLIENT_SECRET) {
    console.log("[Zoho] Missing credentials — connection disabled");
    return;
  }
  let refreshToken = await getZohoTokenFromDb();
  if (refreshToken) {
    console.log("[Zoho] Loaded robust refresh token from MongoDB");
  } else if (ZOHO_REFRESH_TOKEN_ENV) {
    refreshToken = ZOHO_REFRESH_TOKEN_ENV;
    console.log("[Zoho] Fallback: Using refresh token from Environment Variable");
    await saveZohoTokenToDb(refreshToken);
  } else {
    try {
      const backupPath = path.join(__dirname, ".zoho_token_backup.json");
      if (fs.existsSync(backupPath)) {
        const backup = JSON.parse(fs.readFileSync(backupPath, "utf8"));
        if (backup.refresh_token) {
          refreshToken = backup.refresh_token;
          console.log("[Zoho] Fallback: Loaded refresh token from local backup");
          await saveZohoTokenToDb(refreshToken);
        }
      }
    } catch (e) {
      console.warn("[Zoho] Could not read backup file:", e.message);
    }
  }
  if (!refreshToken) {
    console.log("[Zoho] ❌ No refresh token found. Please authorize at:", ZOHO_CONNECTION_URL);
    return;
  }
  zohoTokenStore.set("refresh_token", refreshToken);
  try {
    await getValidZohoToken();
    isZohoConnected = true;
    console.log("[Zoho] ✓ Initial connection successful (Token covers CRM & Recruit)");
  } catch (error) {
    console.error("[Zoho] Initial connection failed:", error.message);
    isZohoConnected = false;
    if (error.message.includes("expired") || error.message.includes("invalid_grant")) {
      requestNewAuthCode();
    }
  }
}

function startZohoKeepalive() {
  setInterval(async () => {
    const ea = zohoTokenStore.get("expires_at");
    if (ea && Date.now() > ea - 30 * 60 * 1000) {
      try { await getValidZohoToken(); } catch (e) {}
    }
  }, 25 * 60 * 1000);
  setInterval(async () => {
    if (!isZohoConnected) {
      console.log("[Zoho] Connection dropped, attempting to reconnect...");
      try {
        await getValidZohoToken();
        isZohoConnected = true;
        console.log("[Zoho] ✓ Reconnected successfully");
      } catch (e) {
        console.error("[Zoho] Reconnect failed:", e.message);
      }
    } else {
      // No CRM/Recruit read ping. OAuth refresh is enough; avoid spending API credits.
    }
  }, ZOHO_KEEPALIVE_INTERVAL_MS);
}

function startRenderKeepAlive() {
  if (PRODUCTION_URL) {
    console.log(`[KeepAlive] Setting up self-ping to ${PRODUCTION_URL}/health`);
    setInterval(() => {
      axios.get(`${PRODUCTION_URL}/health`).catch(() => {});
    }, 14 * 60 * 1000);
  }
}

async function getRecentlyActiveCandidateEmails() {
  const cutoff =
    new Date(
      Date.now() -
      ACTIVE_SESSION_WINDOW_MS
    );

  const emails =
    new Set();

  if (
    mongoConnected
  ) {
    try {
      const sessions =
        await UserSession.find({
          status: "active",
          lastActive: {
            $gte: cutoff
          }
        })
          .select({
            email: 1
          })
          .lean();

      for (
        const session of sessions
      ) {
        if (session?.email) {
          emails.add(
            normalizeCacheEmail(
              session.email
            )
          );
        }
      }
    } catch (error) {
      console.warn(
        "[Polling] Active-session lookup failed:",
        error.message
      );
    }
  }

  return [
    ...emails
  ];
}

async function startZohoDataPolling() {
  if (!ENABLE_ZOHO_POLLING) {
    console.log(
      "[Polling] Zoho polling disabled. Data is cache/on-demand/webhook driven."
    );
    return;
  }

  const intervalMs =
    Math.max(
      ZOHO_POLL_INTERVAL_MS,
      12 * 60 * 60 * 1000
    );

  const runCycle =
    async () => {
      if (
        isZohoQuotaCircuitOpen()
      ) {
        console.log(
          "[Polling] Skipped: Zoho quota circuit is open."
        );
        return;
      }

      const emails =
        await getRecentlyActiveCandidateEmails();

      if (
        emails.length === 0
      ) {
        console.log(
          "[Polling] No recently active users. Zero Zoho API reads."
        );
        return;
      }

      for (
        const email of emails
      ) {
        try {
          await getUserComprehensiveDetails(
            email,
            {
              forceRefresh: true
            }
          );
        } catch (error) {
          console.warn(
            `[Polling] ${email}:`,
            error.message
          );

          if (
            isZohoQuotaCircuitOpen()
          ) {
            break;
          }
        }
      }
    };

  setInterval(
    runCycle,
    intervalMs
  );

  console.log(
    `[Polling] Enabled for active sessions only every ${Math.round(
      intervalMs / 60000
    )} minutes.`
  );
}


const ADMIN_COOKIE_NAME = "admin_session";
const ADMIN_COOKIE_VALUE = "authenticated";
const ADMIN_COOKIE_MAX_AGE_SECONDS = 24 * 60 * 60;

function isLocalAdminRequest(req) {
  const hostname = String(req.hostname || "").toLowerCase();
  return hostname === "localhost" || hostname === "127.0.0.1";
}

function setAdminCookie(req, res) {
  const parts = [
    `${ADMIN_COOKIE_NAME}=${ADMIN_COOKIE_VALUE}`,
    "HttpOnly",
    "Path=/",
    `Max-Age=${ADMIN_COOKIE_MAX_AGE_SECONDS}`
  ];

  if (isLocalAdminRequest(req)) {
    parts.push("SameSite=Lax");
  } else {
    // Cross-site production cookie + CHIPS fallback for browsers that block
    // ordinary third-party cookies.
    parts.push("SameSite=None", "Secure", "Partitioned");
  }

  res.setHeader("Set-Cookie", parts.join("; "));
}

function clearAdminCookie(req, res) {
  const parts = [
    `${ADMIN_COOKIE_NAME}=`,
    "HttpOnly",
    "Path=/",
    "Max-Age=0"
  ];

  if (isLocalAdminRequest(req)) {
    parts.push("SameSite=Lax");
  } else {
    parts.push("SameSite=None", "Secure", "Partitioned");
  }

  res.setHeader("Set-Cookie", parts.join("; "));
}

function extractAdminToken(req) {
  const headerToken = String(req.headers["x-admin-token"] || "").trim();
  if (headerToken) return headerToken;

  const auth = String(req.headers.authorization || "").trim();

  if (auth.startsWith("AdminBearer ")) {
    return auth.slice("AdminBearer ".length).trim();
  }

  if (auth.startsWith("Bearer ")) {
    return auth.slice("Bearer ".length).trim();
  }

  return "";
}

function cleanExpiredAdminTokens() {
  for (const [key, value] of adminTokens.entries()) {
    if (
      Date.now() - Number(value?.createdAt || 0) >
      ADMIN_TOKEN_EXPIRY_MS
    ) {
      adminTokens.delete(key);
    }
  }
}

function issueAdminToken(username) {
  cleanExpiredAdminTokens();

  const token = generateAdminToken(username);

  adminTokens.set(token, {
    username,
    createdAt: Date.now()
  });

  return token;
}

// ─── ADMIN HELPER ────────────────────────────────────────────────────────────
function generateAdminToken(username) {
  const secret = process.env.ADMIN_SECRET || 'your-admin-secret-key-change-this';
  return crypto.createHmac('sha256', secret)
    .update(`${username}:${Date.now()}`)
    .digest('hex');
}

function adminAuth(req, res, next) {
  cleanExpiredAdminTokens();

  const cookieHeader = String(req.headers.cookie || "");
  const adminToken = extractAdminToken(req);

  const hasValidCookie = cookieHeader
    .split(";")
    .some(
      cookie =>
        cookie.trim() ===
        `${ADMIN_COOKIE_NAME}=${ADMIN_COOKIE_VALUE}`
    );

  const hasValidToken =
    Boolean(adminToken && adminTokens.has(adminToken));

  if (!hasValidCookie && !hasValidToken) {
    console.log("[Admin] Unauthorized access attempt", {
      origin: req.headers.origin || null,
      cookiePresent: cookieHeader.includes(`${ADMIN_COOKIE_NAME}=`),
      tokenPresent: Boolean(adminToken)
    });

    return res.status(403).json({
      success: false,
      message: "Admin access required",
      code: "ADMIN_AUTH_REQUIRED"
    });
  }

  req.adminAuthMode = hasValidToken ? "token" : "cookie";
  req.adminUsername = hasValidToken
    ? adminTokens.get(adminToken)?.username || "admin"
    : "admin";

  next();
}

async function isUserAdmin(email) {
  try {
    if (db) {
      const snapshot = await db.collection('Users').where('user', '==', email).get();
      if (!snapshot.empty) {
        const userData = snapshot.docs[0].data();
        if (userData.role === 'admin' || userData.isAdmin === true) {
          return true;
        }
      }
    }
    const adminEmails = ['info@infinitycarepartners.com', 'customercare@infinitycarepartners.com'];
    return adminEmails.includes(email);
  } catch (error) {
    console.error('[isUserAdmin] Error:', error);
    return false;
  }
}

