app.get("/api/auth/verify-token", authenticateToken, async (req, res) => {
  try {
    const token = req.authToken;
    const tokenData = userTokens.get(token);
    
    if (!tokenData) {
      return res.status(403).json({ 
        success: false, 
        valid: false, 
        message: "Invalid token" 
      });
    }
    
    const email = typeof tokenData === "string" ? tokenData : tokenData.email;
    const expiresAt = typeof tokenData === "string" ? null : tokenData.sessionExpiresAt;
    const isValid = expiresAt ? Date.now() < expiresAt : true;
    
    // Check if session exists in DB
    let dbValid = true;
    if (mongoConnected) {
      try {
        const session = await UserSession.findOne({ 
          token, 
          status: "active",
          sessionExpiresAt: { $gt: new Date() }
        });
        dbValid = !!session;
      } catch (e) {
        dbValid = false;
      }
    }
    
    res.json({
      success: true,
      valid: isValid && dbValid,
      email,
      expiresAt,
      user: tokenData
    });
  } catch (error) {
    console.error('[Auth] Token verification error:', error);
    res.status(500).json({ success: false, message: error.message });
  }
});

