app.post("/api/auth/refresh-session", authenticateToken, async (req, res) => {
  try {
    const token = req.authToken;
    const tokenData = userTokens.get(token);
    
    if (!tokenData) {
      return res.status(403).json({ 
        success: false, 
        message: "Invalid session",
        isActive: false
      });
    }
    
    const email = typeof tokenData === "string" ? tokenData : tokenData.email;
    const expiresAt = typeof tokenData === "string" ? null : tokenData.sessionExpiresAt;
    
    // Extend session if close to expiry (within 7 days)
    const LOGIN_EXPIRY_MS = LOGIN_SESSION_DAYS * 24 * 60 * 60 * 1000;
    const now = Date.now();
    const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
    
    if (expiresAt && (expiresAt - now) < sevenDaysMs) {
      // Extend the session
      const newExpiry = now + LOGIN_EXPIRY_MS;
      if (typeof tokenData !== "string") {
        tokenData.sessionExpiresAt = newExpiry;
        userTokens.set(token, tokenData);
        await savePersistentSession(token, tokenData);
      }
      
      return res.json({
        success: true,
        message: "Session refreshed",
        isActive: true,
        expiresAt: newExpiry
      });
    }
    
    res.json({
      success: true,
      message: "Session is valid",
      isActive: true,
      expiresAt
    });
  } catch (error) {
    console.error('[Auth] Refresh session error:', error);
    res.status(500).json({ success: false, message: error.message });
  }
});

