app.post(
  "/api/auth/test-recruit-email",
  otpRequestLimiter,
  async (req, res) => {
    const email =
      String(
        req.body?.email ||
        ""
      )
        .trim()
        .toLowerCase();

    if (!email) {
      return res.status(400).json({
        success: false,
        error:
          "Email is required"
      });
    }

    const modules = [
      "Candidates",
      "Applications",
      "CustomModule1"
    ];

    const results = {};

    for (
      const moduleApiName of
      modules
    ) {
      try {
        const matches =
          await searchRecruitModuleByEmail(
            moduleApiName,
            email
          );

        results[
          moduleApiName
        ] = {
          found:
            matches.length > 0,
          count:
            matches.length,
          ids:
            matches.map(
              record =>
                record.id
            ),
          methods:
            [
              ...new Set(
                matches.map(
                  record =>
                    record
                      ._emailMatchMethod
                )
              )
            ]
        };
      } catch (error) {
        results[
          moduleApiName
        ] = {
          found:
            false,
          count:
            0,
          error:
            error.response?.data ||
            error.message
        };
      }
    }

    const exists =
      Object.values(
        results
      ).some(
        result =>
          result.found ===
          true
      );

    return res.json({
      success: true,
      email,
      exists,
      field:
        "Email",
      apiName:
        "Email",
      modules:
        results
    });
  }
);

app.post("/api/auth/check-email", otpRequestLimiter, async (req, res) => {
  try {
    const { email } = req.body;
    if (!email || !email.includes("@")) return res.status(400).json({ success:false, message:"Valid email required." });

    const key = email.toLowerCase().trim();

    const lookup =
      await emailExistsInZoho(
        key,
        {
          includeDetails:
            true
        }
      );

    if (
      lookup.exists === null
    ) {
      return res.status(503).json({
        success: false,
        message:
          "Your email could not be verified because one of the Zoho sources is unavailable. Please try again.",
        requiresZohoConnection:
          true,
        sources: {
          crm:
            lookup.crm,
          recruit:
            lookup.recruit,
          crmAvailable:
            lookup.crmAvailable,
          recruitAvailable:
            lookup.recruitAvailable,
          previouslyVerified:
            lookup.previouslyVerified
        },
        diagnostics: {
          recruitModulesChecked:
            lookup
              .recruitModulesChecked ||
            [],
          recruitSuccessfulModules:
            lookup
              .recruitSuccessfulModules ||
            [],
          errors:
            lookup.errors ||
            []
        }
      });
    }

    if (!lookup.exists) {
      console.warn(
        `[Auth] Email ${key} not found. CRM records=${lookup.crmRecordCount || 0}; Recruit records=${lookup.recruitRecordCount || 0}; Recruit modules=${(lookup.recruitModules || []).join(",") || "none"}; errors=${JSON.stringify(lookup.errors || [])}`
      );

      return res.status(404).json({
        success: false,
        message:
          "Email not found in CRM or Recruit. Contact customerservice@infinitycarepartners.com.",
        lookup: {
          crm:
            lookup.crm,
          recruit:
            lookup.recruit,
          crmRecordCount:
            lookup.crmRecordCount ||
            0,
          recruitRecordCount:
            lookup.recruitRecordCount ||
            0,
          recruitModules:
            lookup.recruitModules ||
            [],
          errors:
            lookup.errors ||
            []
        }
      });
    }

    console.log(
      `[Auth] Login email accepted for ${key}. CRM=${lookup.crm}, Recruit=${lookup.recruit}, Recruit modules=${lookup.recruitModules.join(",") || "none"}`
    );

    const userAuth = mongoConnected ? await UserAuth.findOne({ email:key }) : null;
    const hasPassword = !!(userAuth?.passwordHash);

    if (hasPassword) {
      return res.json({
        success: true,
        requiresOTP: false,
        needsPasswordSetup: false,
        hasPassword: true,
        foundIn: {
          crm:
            lookup.crm,
          recruit:
            lookup.recruit,
          recruitModules:
            lookup.recruitModules
        }
      });
    } else {
      const otp = generateOTP();
      const otpHash = await bcrypt.hash(otp, 10);
      const otpExpiry = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60 * 1000);

      if (mongoConnected) {
        await UserAuth.findOneAndUpdate(
          { email: key },
          { email: key, otpHash, otpExpiry, otpAttempts: 0, otpPurpose: "login" },
          { upsert: true, new: true }
        );
      } else {
        authorizedUsers.set(key, { otp, otpExpiry: otpExpiry.getTime(), attempts: 0 });
      }

      if (brevoReady) sendOTPEmail(key, otp).catch(e => console.error("OTP email error:", e.message));

      return res.json({
        success: true,
        requiresOTP: true,
        needsPasswordSetup: true,
        hasPassword: false,
        message:
          "OTP sent to your email.",
        foundIn: {
          crm:
            lookup.crm,
          recruit:
            lookup.recruit,
          recruitModules:
            lookup.recruitModules
        }
      });
    }
  } catch (e) {
    console.error("check-email error:", e);
    res.status(500).json({ success:false, message:e.message||"Server error" });
  }
});

