app.post(
  "/api/zoho/webhook",
  async (req, res) => {
    try {
      const secret =
        process.env
          .ZOHO_WEBHOOK_SECRET;

      if (secret) {
        const supplied =
          req.headers[
            "x-zoho-webhook-secret"
          ] ||
          req.query.secret ||
          req.body?.secret;

        if (
          supplied !== secret
        ) {
          return res.status(401).json({
            success: false,
            error:
              "Invalid webhook secret"
          });
        }
      }

      const emails =
        new Set();

      const walk =
        value => {
          if (
            value === null ||
            value === undefined
          ) {
            return;
          }

          if (
            typeof value === "string"
          ) {
            const candidate =
              value
                .trim()
                .toLowerCase();

            if (
              /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
                candidate
              )
            ) {
              emails.add(
                candidate
              );
            }

            return;
          }

          if (
            Array.isArray(value)
          ) {
            value.forEach(walk);
            return;
          }

          if (
            typeof value === "object"
          ) {
            Object.values(
              value
            ).forEach(walk);
          }
        };

      walk(req.body);

      for (
        const email of emails
      ) {
        invalidateCandidateDetailsCache(
          email
        );

        zohoSearchCache.delete(
          `search:crm:deals:${email}`
        );

        zohoSearchCache.delete(
          `search:recruit:${email}`
        );

        await deletePersistentApiCacheByPrefix(
          `search:crm:deals:${email}`
        );

        await deletePersistentApiCacheByPrefix(
          `search:recruit:${email}`
        );
      }

      return res.json({
        success: true,
        invalidated:
          [...emails]
      });
    } catch (error) {
      return res.status(500).json({
        success: false,
        error:
          error.message
      });
    }
  }
);


const AFTERCARE_SURVEY_WEBHOOK_MAP = {
  relocation: {
    stageName: "Relocation Survey",
    categoryKey: "relocation-survey"
  },
  "30day": {
    stageName: "U.S. Integration Call (30 Day Call / Survey)",
    categoryKey: "thirty-day-survey"
  },
  "1year": {
    stageName: "1 Year Survey",
    categoryKey: "one-year-survey"
  }
};

function flattenSurveyWebhookPayload(value, prefix = "", rows = []) {
  if (value === null || value === undefined) return rows;

  if (Array.isArray(value)) {
    value.forEach((item, index) => {
      flattenSurveyWebhookPayload(
        item,
        prefix ? `${prefix} ${index + 1}` : String(index + 1),
        rows
      );
    });
    return rows;
  }

  if (typeof value === "object") {
    for (const [key, child] of Object.entries(value)) {
      const cleanKey = String(key)
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();

      flattenSurveyWebhookPayload(
        child,
        prefix ? `${prefix} - ${cleanKey}` : cleanKey,
        rows
      );
    }
    return rows;
  }

  const text = String(value).trim();
  if (!text) return rows;

  rows.push({
    question: prefix || "Response",
    answer: text
  });

  return rows;
}

function findSurveyCandidateEmail(payload) {
  const found = [];

  const walk = value => {
    if (value === null || value === undefined) return;

    if (Array.isArray(value)) {
      value.forEach(walk);
      return;
    }

    if (typeof value === "object") {
      for (const [key, child] of Object.entries(value)) {
        if (/email/i.test(key) && typeof child === "string") {
          found.push(child);
        }
        walk(child);
      }
      return;
    }

    if (
      typeof value === "string" &&
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
    ) {
      found.push(value.trim());
    }
  };

  walk(payload);

  return found
    .map(normalizePipelineEmail)
    .find(Boolean) || "";
}

function sanitizeSurveyRows(rows) {
  const blocked = [
    "token",
    "authorization",
    "signature",
    "webhook secret",
    "secret"
  ];

  return rows.filter(row => {
    const question = String(row.question || "")
      .trim()
      .toLowerCase();

    return (
      question &&
      !blocked.some(item => question.includes(item))
    );
  });
}

function wrapPdfText(text, maxChars = 82) {
  const words = String(text || "")
    .split(/\s+/)
    .filter(Boolean);

  const lines = [];
  let current = "";

  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word;

    if (candidate.length > maxChars && current) {
      lines.push(current);
      current = word;
    } else {
      current = candidate;
    }
  }

  if (current) lines.push(current);
  return lines.length ? lines : [""];
}

async function createActualAftercareSurveyResponseDocument({
  email,
  stageName,
  categoryKey,
  payload,
  submittedAt = new Date()
}) {
  const normalizedEmail = normalizePipelineEmail(email);

  if (!normalizedEmail || !stageName || !categoryKey) {
    throw new Error(
      "Survey response is missing candidate or survey information."
    );
  }

  const rows = sanitizeSurveyRows(
    flattenSurveyWebhookPayload(payload)
  );

  if (!rows.length) {
    throw new Error(
      "Zoho Survey webhook did not include any response data."
    );
  }

  const responseFingerprint = crypto
    .createHash("sha256")
    .update(JSON.stringify({
      email: normalizedEmail,
      stageName,
      payload
    }))
    .digest("hex");

  if (mongoConnected && mongoose.connection?.db) {
    const existing = await mongoose.connection.db
      .collection("document_library_uploads")
      .findOne({
        candidate_email: normalizedEmail,
        survey_response_fingerprint: responseFingerprint
      });

    if (existing?.crm_attachment_id) {
      return {
        existing: true,
        categoryKey,
        filename: existing.document_name,
        crm: {
          success: true,
          attachment_id: existing.crm_attachment_id,
          record_id: existing.crm_record_id
        }
      };
    }
  }

  const pdf = await PDFDocument.create();
  const regular = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);

  let page = pdf.addPage([612, 792]);
  let y = 735;

  const ensureSpace = required => {
    if (y - required < 54) {
      page = pdf.addPage([612, 792]);
      y = 735;
    }
  };

  page.drawText(stageName, {
    x: 54,
    y,
    size: 18,
    font: bold
  });

  y -= 30;

  page.drawText("Survey Response", {
    x: 54,
    y,
    size: 12,
    font: bold
  });

  y -= 24;

  page.drawText(`Candidate: ${normalizedEmail}`, {
    x: 54,
    y,
    size: 10,
    font: regular
  });

  y -= 18;

  page.drawText(
    `Submitted: ${new Date(submittedAt).toLocaleString("en-US")}`,
    {
      x: 54,
      y,
      size: 10,
      font: regular
    }
  );

  y -= 30;

  for (const row of rows) {
    const questionLines = wrapPdfText(row.question, 78);
    const answerLines = wrapPdfText(row.answer, 84);
    const required = (questionLines.length + answerLines.length) * 14 + 20;

    ensureSpace(required);

    for (const line of questionLines) {
      page.drawText(line, {
        x: 54,
        y,
        size: 10,
        font: bold
      });
      y -= 14;
    }

    for (const line of answerLines) {
      page.drawText(line, {
        x: 66,
        y,
        size: 10,
        font: regular
      });
      y -= 14;
    }

    y -= 10;
  }

  const bytes = await pdf.save();

  const safeStage = String(stageName)
    .replace(/[^a-zA-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  const filename =
    `${safeStage}_Actual_Response_${new Date(submittedAt)
      .toISOString()
      .slice(0, 10)}.pdf`;

  const crm = await uploadBufferToCrmDeal({
    email: normalizedEmail,
    buffer: Buffer.from(bytes),
    filename,
    mimetype: "application/pdf"
  });

  if (crm?.success !== true || !crm?.attachment_id) {
    throw new Error(
      crm?.error ||
      "Actual survey response PDF could not be attached to CRM."
    );
  }

  await upsertDocumentLibraryUpload({
    email: normalizedEmail,
    categoryKey,
    documentName: filename,
    documentType: stageName,
    destination: "crm",
    crm,
    recruit: null,
    uploadedAt: new Date(submittedAt),
    approvalExempt: true,
    uploadedVia: "zoho_survey_webhook",
    extra: {
      survey_submission: true,
      survey_stage_name: stageName,
      actual_survey_response: true,
      survey_response_fingerprint: responseFingerprint,
      survey_submitted_at: new Date(submittedAt),
      visible_in_library: true,
      approval_status: "approved",
      already_approved: true,
      approval_exempt: true
    }
  });

  return {
    existing: false,
    categoryKey,
    filename,
    crm
  };
}

app.post(
  "/api/webhooks/zoho/survey/:surveyKey",
  express.json({ limit: "5mb" }),
  async (req, res) => {
    try {
      const surveyKey = String(req.params.surveyKey || "")
        .trim()
        .toLowerCase();

      const mapping =
        AFTERCARE_SURVEY_WEBHOOK_MAP[surveyKey];

      if (!mapping) {
        return res.status(404).json({
          success: false,
          error: "Unknown survey webhook."
        });
      }

      const configuredSecret = String(
        process.env.ZOHO_SURVEY_WEBHOOK_SECRET || ""
      ).trim();

      if (configuredSecret) {
        const receivedSecret = String(
          req.headers["x-zoho-survey-secret"] ||
          req.query?.secret ||
          ""
        ).trim();

        if (receivedSecret !== configuredSecret) {
          return res.status(401).json({
            success: false,
            error: "Invalid survey webhook secret."
          });
        }
      }

      const email =
        findSurveyCandidateEmail(req.body);

      if (!email) {
        return res.status(400).json({
          success: false,
          error:
            "No candidate email was found in the Zoho Survey response payload. Include candidate email/custom variable in the webhook data."
        });
      }

      const submittedAt = new Date();

      const document =
        await createActualAftercareSurveyResponseDocument({
          email,
          stageName: mapping.stageName,
          categoryKey: mapping.categoryKey,
          payload: req.body,
          submittedAt
        });

      await saveAftercareSurveySubmission(
        email,
        mapping.stageName
      );

      broadcastToUsers(
        [email],
        {
          type: "documents-updated",
          event: "actual-survey-response-saved",
          candidateEmail: email,
          stageName: mapping.stageName,
          documentName: document.filename,
          timestamp: submittedAt.toISOString()
        }
      );

      return res.json({
        success: true,
        stage_name: mapping.stageName,
        candidate_email: email,
        document: {
          name: document.filename,
          category: document.categoryKey,
          attachment_id: document.crm?.attachment_id || null,
          actual_response: true
        }
      });
    } catch (error) {
      console.error(
        "[Zoho Survey Webhook]",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message ||
          "Unable to save Zoho Survey response."
      });
    }
  }
);


app.post(
  "/api/pipeline/aftercare-survey-submitted",
  authenticateToken,
  async (req, res) => {
    try {
      const email = normalizePipelineEmail(req.userEmail);
      const stageName = String(req.body?.stage_name || "").trim();

      const submittedAt =
        await saveAftercareSurveySubmission(email, stageName);

      const sources =
        await getCanonicalZohoSourceRecords(email, {
          forceRefresh: false
        });

      const deal = sources.crmDeal || {};
      const field = AFTERCARE_SURVEY_STAGE_FIELDS[stageName];
      const crmValue = field ? deal[field] : null;

      const crmMet =
        crmValue !== undefined &&
        crmValue !== null &&
        String(unwrapZohoFieldValue(crmValue) ?? "").trim() !== "";

      const completed =
        crmMet === true;

      let completedDate =
        null;

      if (
        completed &&
        PipelineStage
      ) {
        const savedStage =
          await PipelineStage.findOne({
            candidate_email:
              email,
            stage_name:
              stageName,
            is_deleted: {
              $ne: true
            }
          });

        completedDate =
          savedStage?.completed_date ||
          null;
      }

      broadcastToUsers(
        [email],
        {
          type:
            "documents-updated",
          event:
            "aftercare-survey-submitted",
          candidateEmail:
            email,
          stageName,
          timestamp:
            new Date(
              submittedAt
            ).toISOString()
        }
      );

      return res.json({
        success: true,
        submitted: true,
        submitted_at: submittedAt,
        crm_field: field,
        crm_met: crmMet,
        completed,
        completed_date: completedDate,
        completion_source:
          "crm_only",
        document:
          null,
        actual_response_document:
          "The actual survey response is created only from the Zoho Survey webhook."
      });
    } catch (error) {
      return res.status(400).json({
        success: false,
        error: error.message
      });
    }
  }
);

app.get(
  "/api/updates",
  authenticateToken,
  async (req, res) => {
    try {
      if (
        !mongoConnected ||
        !mongoose.connection?.db
      ) {
        return res.json({
          success: true,
          updates: [],
          total: 0,
          unread: 0
        });
      }

      const email =
        normalizePipelineEmail(
          req.userEmail
        );

      const limit =
        Math.min(
          Math.max(
            Number(
              req.query.limit ||
              100
            ),
            1
          ),
          200
        );

      const collection =
        mongoose.connection.db
          .collection(
            "candidate_updates"
          );

      const updates =
        await collection
          .find({
            candidate_email:
              email,
            $or: [
              {
                update_type: {
                  $in: [
                    "urgent",
                    "rfe",
                    "expiry",
                    "expired",
                    "document-required",
                    "pipeline",
                    "stage",
                    "access",
                    "request"
                  ]
                }
              },
              {
                source: {
                  $regex: /^pipeline:/i
                }
              }
            ]
          })
          .sort({
            created_at: -1
          })
          .limit(limit)
          .toArray();

      const unread =
        await collection.countDocuments({
          candidate_email:
            email,
          is_read: {
            $ne: true
          },
          update_type: {
            $in: [
              "urgent",
              "rfe",
              "expiry",
              "expired",
              "document-required",
              "pipeline",
              "stage",
              "access",
              "request"
            ]
          }
        });

      const total =
        await collection.countDocuments({
          candidate_email:
            email,
          update_type: {
            $in: [
              "urgent",
              "rfe",
              "expiry",
              "expired",
              "document-required",
              "pipeline",
              "stage",
              "access",
              "request"
            ]
          }
        });

      return res.json({
        success: true,
        updates:
          updates.map(
            update => ({
              ...update,
              id:
                String(
                  update._id
                ),
              created_date:
                update.created_at
            })
          ),
        total,
        unread
      });
    } catch (error) {
      return res.status(500).json({
        success: false,
        error:
          error.message
      });
    }
  }
);

