async function getCandidateUnreadMessageCount(
  candidateEmail
) {
  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  const conversations =
    await Conversation.find({
      participants:
        email
    })
      .select({
        _id: 1
      })
      .lean();

  if (
    conversations.length ===
    0
  ) {
    return 0;
  }

  return Message.countDocuments({
    conversationId: {
      $in:
        conversations.map(
          conversation =>
            conversation._id
        )
    },
    senderEmail: {
      $ne:
        email
    },
    isRead:
      false
  });
}

async function getCanonicalSavedPipeline(
  candidateEmail
) {
  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  if (
    !mongoConnected ||
    !PipelineStage
  ) {
    return [];
  }

  const rows =
    await PipelineStage.find({
      candidate_email:
        email,
      is_deleted: {
        $ne: true
      }
    })
      .sort({
        stage_order: 1,
        updated_at: 1
      })
      .lean();

  const strongest =
    getStrongestPipelineStages(
      rows
    );

  const now =
    new Date();

  return strongest
    .map(stage => {
      const complete =
        isStoredStageComplete(
          stage
        );

      const targetDate =
        stage.target_date ||
        stage.targetDate ||
        null;

      const startedAt =
        stage.started_at ||
        stage.startedAt ||
        null;

      return {
        ...stage,
        status:
          complete
            ? "Completed"
            : (
                stage.status ||
                "Not Started"
              ),
        completed:
          complete,
        is_completed:
          complete,
        completed_date:
          complete
            ? (
                stage.completed_date ||
                stage.completed_at ||
                null
              )
            : null,
        started_at:
          startedAt,
        target_date:
          targetDate,
        hidden_from_main_flow:
          LEGACY_FLOW_SUPPORT_STAGE_NAMES.has(
            stage.stage_name
          ) ||
          stage.hidden_from_main_flow ===
            true,
        timing_status:
          complete
            ? "Good Standing"
            : getTimingStanding(
                {
                  ...stage,
                  target_date:
                    targetDate,
                  started_at:
                    startedAt
                },
                now
              )
      };
    })
    .sort(
      (a, b) =>
        Number(
          a.stage_order ||
          0
        ) -
        Number(
          b.stage_order ||
          0
        )
    );
}

app.get(
  "/api/candidate/dashboard-summary",
  authenticateToken,
  async (req, res) => {
    try {
      const email =
        normalizePipelineEmail(
          req.userEmail
        );

      const [
        candidateResult,
        documentResult,
        pipelineResult,
        unreadMessageResult,
        updatesResult,
        hiringStateResult
      ] =
        await Promise.allSettled([
          getUserComprehensiveDetails(
            email
          ),
          collectCandidateDocuments(
            email
          ),
          getCanonicalSavedPipeline(
            email
          ),
          getCandidateUnreadMessageCount(
            email
          ),
          mongoConnected &&
          mongoose.connection?.db
            ? mongoose.connection.db
                .collection(
                  "candidate_updates"
                )
                .find({
                  candidate_email:
                    email,
                  $or: [
                    {
                      update_type: {
                        $in: [
                          "urgent",
                          "rfe",
                          "expiry",
                          "expired",
                          "document-required",
                          "pipeline",
                          "stage",
                          "access"
                        ]
                      }
                    },
                    {
                      source: {
                        $regex: /^pipeline:/i
                      }
                    }
                  ]
                })
                .sort({
                  created_at: -1
                })
                .limit(5)
                .toArray()
            : Promise.resolve(
                []
              ),
          getRecruitHiringState(
            email,
            {
              forceRefresh:false
            }
          )
        ]);

      const candidate =
        candidateResult.status ===
          "fulfilled"
          ? candidateResult.value
          : {
              user: {}
            };

      const hiringState =
        hiringStateResult.status === "fulfilled"
          ? hiringStateResult.value
          : null;

      const applicationStatus =
        extractRecruitPicklistValue(
          hiringState?.applicationStatus ||
          candidate?.user?.Application_Status ||
          candidate?.user?.applicationStatus ||
          ""
        );

      const accessPolicy =
        await getCandidatePipelineAccessPolicy(
          email,
          applicationStatus
        );

      const allDocuments =
        documentResult.status ===
          "fulfilled"
          ? documentResult.value
          : [];

      const visibleDocuments =
        allDocuments.filter(
          document =>
            document.already_approved ===
              true ||
            document.approval_status ===
              "approved" ||
            document.approval_exempt ===
              true
        );

      const pipeline =
        pipelineResult.status ===
          "fulfilled"
          ? pipelineResult.value
          : [];

      const complete =
        stage => {
          const status =
            String(
              stage?.status ||
              ""
            )
              .trim()
              .toLowerCase();

          return (
            status ===
              "completed" ||
            status ===
              "complete" ||
            stage?.completed ===
              true ||
            stage?.is_completed ===
              true ||
            Boolean(
              stage?.completed_date
            )
          );
        };

      const qualificationProgressMarkers = new Set([
        "Transfer to ICP USRN School",
        "Select Prescreen Time",
        "Prescreen Scheduled",
        "Prescreen Completed",
        "Client Documents & Video Provided",
        "Pending Interview Selection",
        "Mandatory Pre-Interview Coaching Call",
        "Interview Scheduled",
        "Interview Attended",
        "Offer Made",
        "Offer Accepted",
        "Employment Contract Sent",
        "Employment Contract Signed",
        "Documents Received",
        "Hired"
      ]);

      const progressedPastQualification = pipeline.some(stage => {
        if (!qualificationProgressMarkers.has(stage?.stage_name)) return false;
        const status = String(stage?.status || "").trim().toLowerCase();
        return status === "completed" || status === "complete" || status === "in progress" ||
          stage?.completed === true || Boolean(stage?.completed_date);
      });

      const countedStages =
        pipeline.filter(
          stage =>
            stage.is_gate !== true &&
            stage.hidden_from_main_flow !== true &&
            !(progressedPastQualification &&
              ["Qualified Candidate Pool", "Not Qualified - to close"].includes(stage.stage_name)) &&
            ![
              "NCLEX Roadmap",
              "NCLEX Prescreen"
            ].includes(stage.stage_category)
        );

      const completedStages =
        countedStages.filter(
          complete
        );

      const ordered =
        [...countedStages].sort(
          (a, b) =>
            Number(
              a.stage_order ||
              0
            ) -
            Number(
              b.stage_order ||
              0
            )
        );

      const isStageActive = stage => {
        if (!stage || complete(stage)) return false;
        const status = String(stage.status || "").trim().toLowerCase();
        return status === "in progress" ||
          stage.unlocked === true ||
          stage.is_unlocked === true ||
          stage.source_trigger_unlocked === true ||
          Boolean(stage.started_at || stage.startedAt);
      };

      const furthestReached =
        ordered.reduce(
          (furthest, stage) => {
            const reached =
              complete(stage) ||
              stage.source_trigger_unlocked === true ||
              stage.trigger_unlocked === true ||
              stage.crm_unlocked === true ||
              stage.recruit_unlocked === true ||
              stage.nclex_unlocked === true ||
              String(stage.status || "").trim().toLowerCase() === "in progress";

            if (!reached) return furthest;

            return !furthest ||
              Number(stage.stage_order || 0) > Number(furthest.stage_order || 0)
              ? stage
              : furthest;
          },
          null
        );

      const normalizedApplicationStatus =
        normalizeApplicationStatus(
          applicationStatus
        );

      let nclexDashboardCurrentStage = null;
      let nclexDashboardNextStage = null;

      const nclexDashboardEligible =
        hiringState?.nclexEligible === true ||
        hiringState?.transferStatusSelected === true ||
        isTransferToICPUSRNStatus(applicationStatus);

      if (nclexDashboardEligible) {
        try {
          const sources =
            await getCanonicalZohoSourceRecords(
              email,
              { forceRefresh: false }
            );

          const nclex = sources.recruitNCLEX || {};

          const unwrap = value =>
            unwrapZohoFieldValueGlobal(value);

          const norm = value =>
            String(unwrap(value) ?? "")
              .trim()
              .toLowerCase();

          const present = value => {
            const raw = unwrap(value);
            if (raw === null || raw === undefined || raw === false) return false;
            if (Array.isArray(raw)) return raw.some(present);
            return !["", "none", "null", "undefined", "—", "-"].includes(
              String(raw).trim().toLowerCase()
            );
          };

          const truthy = value =>
            value === true ||
            value === 1 ||
            ["true", "yes", "checked", "1"].includes(norm(value));

          const count = value => {
            const parsed = Number.parseInt(norm(value).replace(/[^0-9]/g, ""), 10);
            return Number.isFinite(parsed) ? parsed : 0;
          };

          const acceptedSponsor = new Set([
            "paid by icp",
            "sponsored by icp",
            "to be sponsored by infinity",
            "paid by infinity"
          ]);

          const ratingPass =
            ["high", "very high"].includes(norm(nclex.Performance_Rating));

          const gate = (assessments, assignments) =>
            count(nclex.Assessments_Completed) >= assessments &&
            count(nclex.Assignments_Completed) >= assignments &&
            ratingPass;

          const nclexStages = [
            ["Complete Pre-assessment",
              ["1st attempt pass", "2nd attempt pass"].includes(norm(nclex.NCLEX_Pre_Exam))],
            ["Program Prescreen", norm(nclex.Prescreen_Status) === "attended"],
            ["Document Review", present(nclex.Documents_Submitted)],
            ["Educational Program Agreement", truthy(nclex.Sponsorship_Agreement)],
            ["Program Approval", norm(nclex.Program_Status) === "approved"],
            ["Credential Evaluation Set-up", acceptedSponsor.has(norm(nclex.Credential_Service))],
            ["Credential Evaluation Completed", present(nclex.Credential_Registration_Date)],
            ["CES Report Issued", present(nclex.Date_Report_Issued)],
            ["Performance Check 1", gate(2, 6)],
            ["Board Registration", acceptedSponsor.has(norm(nclex.State_License_Board_of_Registration))],
            ["Select Meeting Time", false],
            ["Performance Check 2", gate(4, 15)],
            ["Board Approval", present(nclex.Board_Username)],
            ["Pearson Vue Registration", norm(nclex.Pearson_Vue_Status) === "complete"],
            ["Performance Check 3", gate(5, 0)],
            ["ATT Received", present(nclex.ATT_Received_Date)],
            ["Performance Check 4", gate(6, 0)],
            ["Exam Scheduled", present(nclex.NCLEX_Exam_Date)],
            ["Exam Results", norm(nclex.NCLEX_Status) === "passed"]
          ];

          let furthestCompletedIndex = -1;
          nclexStages.forEach(([, completed], index) => {
            if (completed) {
              furthestCompletedIndex =
                Math.max(furthestCompletedIndex, index);
            }
          });

          const currentIndex =
            Math.min(
              furthestCompletedIndex + 1,
              nclexStages.length - 1
            );

          const currentName =
            nclexStages[currentIndex]?.[0] ||
            "Complete Pre-assessment";

          const nextName =
            nclexStages[currentIndex + 1]?.[0] ||
            null;

          nclexDashboardCurrentStage = {
            stage_name: currentName,
            stage_category: "NCLEX Program",
            stage_order: 6 + ((currentIndex + 1) / 100),
            status:
              nclexStages[currentIndex]?.[1] === true
                ? "Completed"
                : "In Progress",
            completed:
              nclexStages[currentIndex]?.[1] === true,
            is_completed:
              nclexStages[currentIndex]?.[1] === true,
            unlocked: true,
            nclex_stage: true
          };

          if (nextName) {
            nclexDashboardNextStage = {
              stage_name: nextName,
              stage_category: "NCLEX Program",
              stage_order: 6 + ((currentIndex + 2) / 100),
              status: "Not Started",
              completed: false,
              is_completed: false,
              nclex_stage: true
            };
          }
        } catch (nclexDashboardError) {
          console.warn(
            "[Dashboard] NCLEX current-stage calculation unavailable:",
            nclexDashboardError?.message || nclexDashboardError
          );
        }
      }


      const qualificationHoldStageName =
        [
          "qualified-candidate pool",
          "qualified candidate pool"
        ].includes(normalizedApplicationStatus)
          ? "Qualified Candidate Pool"
          : [
              "not qualified-to close",
              "not qualified - to close",
              "not qualified to close",
              "unqualified"
            ].includes(normalizedApplicationStatus)
            ? "Not Qualified - to close"
            : null;

      const qualificationHoldStage =
        qualificationHoldStageName
          ? (
              ordered.find(stage =>
                stage.stage_name ===
                qualificationHoldStageName
              ) || {
                stage_name:
                  qualificationHoldStageName,
                stage_category:
                  "Hiring",
                stage_order:
                  qualificationHoldStageName ===
                    "Qualified Candidate Pool"
                    ? 5
                    : 3,
                status:"In Progress",
                completed:false,
                is_completed:false,
                unlocked:true
              }
            )
          : null;

      const currentStage =
        qualificationHoldStage ||
        nclexDashboardCurrentStage ||
        (
          furthestReached &&
          !complete(furthestReached)
            ? furthestReached
            : ordered.find(stage =>
                Number(stage.stage_order || 0) >
                  Number(furthestReached?.stage_order || -Infinity) &&
                !complete(stage) &&
                isStageActive(stage)
              ) ||
              ordered.find(stage =>
                !complete(stage) &&
                isStageActive(stage)
              ) ||
              ordered.find(stage =>
                Number(stage.stage_order || 0) >
                  Number(furthestReached?.stage_order || -Infinity) &&
                !complete(stage)
              ) ||
              ordered.find(stage =>
                !complete(stage)
              ) ||
              furthestReached ||
              null
        );

      const nextStage =
        qualificationHoldStage
          ? null
          : nclexDashboardCurrentStage
            ? nclexDashboardNextStage
            : currentStage
              ? ordered.find(stage =>
                  Number(stage.stage_order || 0) >
                    Number(currentStage.stage_order || 0) &&
                  !complete(stage)
                ) || null
              : null;

      const welcomeStage =
        pipeline.find(
          stage =>
            stage.stage_name ===
            "Arrival Itinerary"
        );

      const unreadUpdates =
        mongoConnected &&
        mongoose.connection?.db
          ? await mongoose.connection.db
              .collection(
                "candidate_updates"
              )
              .countDocuments({
                candidate_email:
                  email,
                is_read: {
                  $ne: true
                },
                $or: [
                  {
                    update_type: {
                      $in: [
                        "urgent",
                        "rfe",
                        "expiry",
                        "expired",
                        "document-required",
                        "pipeline",
                        "stage",
                        "access"
                      ]
                    }
                  },
                  {
                    source: {
                      $regex: /^pipeline:/i
                    }
                  }
                ]
              })
          : 0;

      return res.json({
        success: true,
        counts: {
          documents:
            visibleDocuments.length,
          documentPending:
            allDocuments.filter(
              document =>
                document.approval_status ===
                "pending"
            ).length,
          documentApproved:
            visibleDocuments.length,
          updates:
            unreadUpdates,
          messages:
            unreadMessageResult.status ===
              "fulfilled"
              ? unreadMessageResult.value
              : 0
        },
        documents:
          visibleDocuments
            .slice(0, 4),
        updates:
          updatesResult.status ===
            "fulfilled"
            ? updatesResult.value
                .map(
                  update => ({
                    ...update,
                    id:
                      String(
                        update._id
                      ),
                    created_date:
                      update.created_at
                  })
                )
            : [],
        pipeline: {
          stages:
            pipeline,
          completed:
            completedStages.length,
          total:
            countedStages.length,
          progress:
            countedStages.length
              ? Math.round(
                  (
                    completedStages.length /
                    countedStages.length
                  ) *
                    100
                )
              : 0,
          currentStage,
          nextStage,
          authoritativeCurrentStage:
            currentStage,
          authoritativeNextStage:
            nextStage,
          applicationStatus,
          hiringState,
          accessPolicy,
          timer:
            currentStage?.target_date
              ? {
                  stageName:
                    currentStage.stage_name,
                  startedAt:
                    currentStage.started_at ||
                    null,
                  targetDate:
                    currentStage.target_date,
                  timingStatus:
                    currentStage.timing_status ||
                    getTimingStanding(
                      currentStage,
                      new Date()
                    )
                }
              : null
        },
        welcomePacket: {
          completed:
            complete(
              welcomeStage
            ),
          status:
            welcomeStage?.status ||
            "Not Started",
          stage:
            welcomeStage ||
            null
        },
        deploymentDate:
          candidate?.user
            ?.initial_departure_time ||
          null,
        candidate:
          candidate?.user ||
          {}
      });
    } catch (error) {
      console.error(
        "[Dashboard Summary]",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message ||
          "Unable to load dashboard summary"
      });
    }
  }
);

