// Canonical module diagnostic. This is safe for the logged-in candidate and
// shows which exact Zoho records own each portal field.
app.get("/api/zoho/source-map", authenticateToken, async (req, res) => {
  try {
    const forceRefresh =
      req.query.refresh ===
        "1" ||
      req.query.refresh ===
        "true";

    const sources =
      await getCanonicalZohoSourceRecords(
        req.userEmail,
        {
          forceRefresh
        }
      );

    return res.json({
      success: true,
      email:
        sources.email,
      aliases:
        sources.aliases,
      presence:
        sources.sourcePresence,
      recordIds:
        sources.recordIds,
      fieldOwnership:
        ZOHO_PORTAL_FIELD_MAP,
      applicationStatus:
        extractRecruitPicklistValue(
          sources
            .recruitApplication
            ?.Application_Status
        ),
      customModule1FieldsPresent:
        Object.keys(
          ZOHO_PORTAL_FIELD_MAP
            .recruitNCLEX
            .fields
        ).filter(key => {
          const apiName =
            ZOHO_PORTAL_FIELD_MAP
              .recruitNCLEX
              .fields[key];

          const value =
            sources
              .recruitNCLEX
              ?.[apiName];

          return (
            value !==
              undefined &&
            value !==
              null &&
            String(value)
              .trim() !==
              ""
          );
        })
    });
  } catch (error) {
    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});

// ─── CANDIDATE REQUESTS ───────────────────────────────────────────────────────
// Make a Request supports:
// - License Endorsement Assistance
// - Embassy Change -> CRM Deals.Embassy_Location
// - Add Dependants -> candidate_extended_profiles
app.get("/api/requests", authenticateToken, async (req, res) => {
  try {
    const email =
      normalizePipelineEmail(
        req.userEmail
      );

    const sources =
      await getCanonicalZohoSourceRecords(
        email,
        {
          forceRefresh:
            forceLive
        }
      );

    const profile =
      mongoConnected &&
      mongoose.connection?.db
        ? await mongoose.connection.db
            .collection(
              "candidate_extended_profiles"
            )
            .findOne({
              candidate_email:
                email
            })
        : null;

    const requests =
      mongoConnected &&
      mongoose.connection?.db
        ? await mongoose.connection.db
            .collection(
              "candidate_requests"
            )
            .find({
              candidate_email:
                email
            })
            .sort({
              created_at: -1
            })
            .limit(100)
            .toArray()
        : [];

    return res.json({
      success: true,
      licenseEndorsementUrl:
        String(
          process.env.LICENSE_ENDORSEMENT_ASSISTANCE_URL ||
          ""
        ).trim(),
      embassyLocation:
        sources
          .crmDeal
          ?.Embassy_Location ||
        "",
      dependants:
        Array.isArray(
          profile?.dependants
        )
          ? profile.dependants
          : [],
      requests
    });
  } catch (error) {
    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});

app.post(
  "/api/requests/dependant-passport",
  authenticateToken,
  upload.single("passport"),
  async (req, res) => {
    try {
      const email =
        normalizePipelineEmail(
          req.userEmail
        );

      const file =
        req.file;

      if (!file) {
        return res.status(400).json({
          success: false,
          error:
            "Select a passport image."
        });
      }

      if (
        !String(file.mimetype || "")
          .toLowerCase()
          .startsWith("image/")
      ) {
        return res.status(400).json({
          success: false,
          error:
            "The dependant passport must be uploaded as an image."
        });
      }

      if (
        file.size >
        10 * 1024 * 1024
      ) {
        return res.status(400).json({
          success: false,
          error:
            "Passport image must be smaller than 10MB."
        });
      }

      const safeName =
        `Dependent_Passport_${Date.now()}_${String(
          file.originalname ||
          "passport.jpg"
        ).replace(
          /[^a-zA-Z0-9._-]+/g,
          "_"
        )}`;

      const crm =
        await uploadBufferToCrmDeal({
          email,
          buffer:
            file.buffer,
          filename:
            safeName,
          mimetype:
            file.mimetype
        });

      if (
        crm?.success !== true ||
        !crm?.attachment_id ||
        !crm?.record_id
      ) {
        return res.status(502).json({
          success: false,
          error:
            crm?.error ||
            "The passport image could not be uploaded for approval."
        });
      }

      return res.json({
        success: true,
        passport: {
          name:
            file.originalname,
          storedName:
            safeName,
          source:
            "crm",
          attachmentId:
            crm.attachment_id,
          dealId:
            crm.record_id,
          mimeType:
            file.mimetype,
          size:
            file.size
        }
      });
    } catch (error) {
      console.error(
        "[Requests] Dependant passport upload failed:",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message ||
          "Unable to upload dependant passport."
      });
    }
  }
);

app.post("/api/requests", authenticateToken, async (req, res) => {
  try {
    const email =
      normalizePipelineEmail(
        req.userEmail
      );

    const requestType =
      String(
        req.body?.requestType ||
        ""
      )
        .trim()
        .toLowerCase();

    const allowed =
      new Set([
        "embassy_change",
        "add_dependant"
      ]);

    if (
      !allowed.has(
        requestType
      )
    ) {
      return res.status(400).json({
        success: false,
        error:
          "Unsupported request type."
      });
    }

    const requestedAt =
      new Date();

    const requestRecord = {
      candidate_email:
        email,
      request_type:
        requestType,
      status:
        "Pending Approval",
      details:
        req.body?.details ||
        {},
      requested_at:
        requestedAt,
      created_at:
        requestedAt,
      updated_at:
        requestedAt
    };

    if (
      requestType ===
      "embassy_change"
    ) {
      const embassyLocation =
        String(
          req.body?.details
            ?.embassyLocation ||
          ""
        ).trim();

      const reason =
        String(
          req.body?.details
            ?.reason ||
          ""
        ).trim();

      if (
        !embassyLocation ||
        !reason
      ) {
        return res.status(400).json({
          success: false,
          error:
            "Embassy location and reason are required."
        });
      }

      requestRecord.details = {
        embassyLocation,
        reason,
        crm_field:
          "Embassy_Location"
      };

      // IMPORTANT: CRM is not updated here. An admin must approve first.
    }

    if (
      requestType ===
      "add_dependant"
    ) {
      if (
        !mongoConnected ||
        !mongoose.connection?.db
      ) {
        return res.status(503).json({
          success: false,
          error:
            "Profile storage is temporarily unavailable."
        });
      }

      const dependant = {
        name: String(req.body?.details?.name || "").trim(),
        age: String(req.body?.details?.age || "").trim(),
        relationship: String(req.body?.details?.relationship || "").trim(),
        passport: String(
          req.body?.details?.passportDocumentName ||
          req.body?.details?.passport ||
          ""
        ).trim(),
        passport_uploaded:
          req.body?.details?.passportUploaded === true ||
          req.body?.details?.passportUploaded === "true",
        passport_source:
          String(
            req.body?.details?.passportSource ||
            ""
          ).trim(),
        passport_attachment_id:
          String(
            req.body?.details?.passportAttachmentId ||
            ""
          ).trim(),
        passport_deal_id:
          String(
            req.body?.details?.passportDealId ||
            ""
          ).trim(),
        passport_mime_type:
          String(
            req.body?.details?.passportMimeType ||
            ""
          ).trim()
      };

      if (
        !dependant.name ||
        !dependant.age ||
        !dependant.relationship ||
        !dependant.passport ||
        !dependant.passport_uploaded
      ) {
        return res.status(400).json({
          success: false,
          error: "Dependant name, age, relationship and passport image upload are required."
        });
      }

      // Profile is updated only after admin approval.
      requestRecord.details = dependant;
    }

    if (
      !mongoConnected ||
      !mongoose.connection?.db
    ) {
      return res.status(503).json({
        success: false,
        error:
          "Request storage is temporarily unavailable. The request was not submitted."
      });
    }

    const result =
      await mongoose.connection.db
        .collection(
          "candidate_requests"
        )
        .insertOne(
          requestRecord
        );

    if (
      !result?.acknowledged ||
      !result?.insertedId
    ) {
      throw new Error(
        "The request could not be saved for admin review."
      );
    }

    const savedRequest = {
      ...requestRecord,
      _id:
        result.insertedId
    };

    await mongoose.connection.db
      .collection("candidate_updates")
      .updateOne(
        {
          candidate_email: email,
          notification_key:
            `request-submitted:${String(result.insertedId)}`
        },
        {
          $setOnInsert: {
            candidate_email: email,
            notification_key:
              `request-submitted:${String(result.insertedId)}`,
            title: "Request submitted",
            message:
              "Your request was submitted successfully and is awaiting admin review.",
            update_type: "request",
            source: "candidate-request",
            is_read: false,
            created_at: requestedAt
          },
          $set: {
            updated_at: requestedAt
          }
        },
        { upsert: true }
      )
      .catch(() => null);

    broadcastToUsers(
      [email],
      {
        type: "candidate-data-updated",
        event: "request-submitted",
        requestId: String(result.insertedId),
        timestamp: requestedAt.toISOString()
      }
    );

    return res.status(201).json({
      success: true,
      submittedToAdmin: true,
      requestId:
        String(
          result.insertedId
        ),
      crmUpdated: false,
      message:
        requestType === "add_dependant"
          ? "Your dependant request was submitted successfully and is awaiting admin approval."
          : "Your request was submitted successfully and is awaiting admin approval.",
      request:
        savedRequest
    });
  } catch (error) {
    console.error(
      "[Requests] Submission failed:",
      error
    );

    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});

app.post("/api/admin/requests/:requestId/decision", adminAuth, async (req, res) => {
  try {
    if (
      !mongoConnected ||
      !mongoose.connection?.db
    ) {
      return res.status(503).json({
        success: false,
        error:
          "Request storage is unavailable."
      });
    }

    const requestId =
      String(
        req.params.requestId ||
        ""
      ).trim();

    const decision =
      String(
        req.body?.decision ||
        ""
      )
        .trim()
        .toLowerCase();

    if (
      !["approve", "reject"].includes(
        decision
      )
    ) {
      return res.status(400).json({
        success: false,
        error:
          "Decision must be approve or reject."
      });
    }

    const collection =
      mongoose.connection.db
        .collection(
          "candidate_requests"
        );

    const request =
      await collection.findOne({
        _id:
          new mongoose.Types.ObjectId(
            requestId
          )
      });

    if (!request) {
      return res.status(404).json({
        success: false,
        error:
          "Request not found."
      });
    }

    if (
      request.status !==
      "Pending Approval"
    ) {
      return res.status(409).json({
        success: false,
        error:
          `Request is already ${request.status}.`
      });
    }

    let crmUpdated =
      false;

    if (
      decision === "approve" &&
      request.request_type ===
        "add_dependant"
    ) {
      const email = normalizePipelineEmail(request.candidate_email);

      await mongoose.connection.db
        .collection("candidate_extended_profiles")
        .updateOne(
          { candidate_email: email },
          {
            $push: {
              dependants: {
                name: String(request.details?.name || "").trim(),
                age: String(request.details?.age || "").trim(),
                relationship: String(request.details?.relationship || "").trim(),
                passport: String(request.details?.passport || "").trim(),
                passport_uploaded:
                  request.details?.passport_uploaded === true ||
                  request.details?.passportUploaded === true,
                passport_source:
                  request.details?.passport_source ||
                  request.details?.passportSource ||
                  null,
                passport_attachment_id:
                  request.details?.passport_attachment_id ||
                  request.details?.passportAttachmentId ||
                  null,
                passport_deal_id:
                  request.details?.passport_deal_id ||
                  request.details?.passportDealId ||
                  null,
                passport_mime_type:
                  request.details?.passport_mime_type ||
                  request.details?.passportMimeType ||
                  null,
                approved_at: new Date()
              }
            },
            $set: { updated_at:new Date() },
            $setOnInsert: { candidate_email:email, created_at:new Date() }
          },
          { upsert:true }
        );

      invalidateCandidateDetailsCache(email);

      broadcastToUsers([email], {
        type:"candidate-data-updated",
        event:"dependant-approved",
        candidateEmail:email,
        timestamp:new Date().toISOString()
      });
    }

    if (
      decision === "approve" &&
      request.request_type ===
        "embassy_change"
    ) {
      const email =
        normalizePipelineEmail(
          request.candidate_email
        );

      const sources =
        await getCanonicalZohoSourceRecords(
          email,
          {
            forceRefresh: true
          }
        );

      const dealId =
        sources.crmDeal?.id;

      if (!dealId) {
        return res.status(404).json({
          success: false,
          error:
            "No CRM Deal was found for this candidate."
        });
      }

      const embassyLocation =
        String(
          request.details
            ?.embassyLocation ||
          ""
        ).trim();

      const response =
        await makeZohoApiRequest(
          `/crm/v3/Deals/${dealId}`,
          {
            method: "PUT",
            data: {
              data: [
                {
                  id:
                    dealId,
                  Embassy_Location:
                    embassyLocation
                }
              ],
              trigger: [
                "workflow"
              ]
            }
          }
        );

      const result =
        response?.data?.[0] ||
        response?.data?.data?.[0] ||
        response?.data ||
        {};

      const status =
        String(
          result.status ||
          response?.status ||
          ""
        )
          .trim()
          .toLowerCase();

      if (
        status &&
        status !==
          "success"
      ) {
        return res.status(502).json({
          success: false,
          error:
            result.message ||
            "CRM rejected the Embassy Location update."
        });
      }

      crmUpdated =
        true;

      const approvedAt =
        new Date();

      await mongoose.connection.db
        .collection(
          "candidate_extended_profiles"
        )
        .updateOne(
          {
            candidate_email:
              email
          },
          {
            $set: {
              embassyLocation:
                embassyLocation,
              embassyTransfer: {
                location:
                  embassyLocation,
                status:
                  "Approved",
                requestId:
                  String(
                    request._id
                  ),
                approvedAt:
                  approvedAt
              },
              updated_at:
                approvedAt
            },
            $setOnInsert: {
              candidate_email:
                email,
              created_at:
                approvedAt
            }
          },
          {
            upsert:
              true
          }
        );

      invalidateCandidateDetailsCache(
        email
      );

      broadcastToUsers(
        [email],
        {
          type:
            "candidate-data-updated",
          event:
            "embassy-transfer-approved",
          embassyLocation:
            embassyLocation,
          requestId:
            String(
              request._id
            ),
          timestamp:
            approvedAt.toISOString()
        }
      );
    }

    const now =
      new Date();

    const nextStatus =
      decision ===
      "approve"
        ? "Approved"
        : "Rejected";

    await collection.updateOne(
      {
        _id:
          request._id
      },
      {
        $set: {
          status:
            nextStatus,
          admin_note:
            String(
              req.body?.note ||
              ""
            ).trim(),
          decided_at:
            now,
          updated_at:
            now,
          crm_updated:
            crmUpdated
        }
      }
    );

    const requestCandidateEmail =
      normalizePipelineEmail(
        request.candidate_email
      );

    if (
      requestCandidateEmail &&
      mongoConnected &&
      mongoose.connection?.db
    ) {
      await mongoose.connection.db
        .collection("candidate_updates")
        .updateOne(
          {
            candidate_email:
              requestCandidateEmail,
            notification_key:
              `request:${String(request._id)}:${nextStatus}`
          },
          {
            $setOnInsert: {
              candidate_email:
                requestCandidateEmail,
              notification_key:
                `request:${String(request._id)}:${nextStatus}`,
              title:
                (
                  nextStatus === "Approved" &&
                  request.request_type === "embassy_change"
                )
                  ? "Embassy transfer approved"
                  : nextStatus === "Approved"
                    ? "Request approved"
                    : "Request update",
              message:
                (
                  nextStatus === "Approved" &&
                  request.request_type === "embassy_change"
                )
                  ? `Your embassy transfer to ${String(
                      request.details?.embassyLocation || "the approved location"
                    ).trim()} has been approved.`
                  : nextStatus === "Approved"
                    ? "Your request has been approved."
                    : "Your request was not approved. Review the admin note or contact ICP.",
              update_type:
                "request",
              source:
                "admin-request",
              is_read:
                false,
              created_at:
                now
            },
            $set: {
              updated_at:
                now
            }
          },
          {
            upsert:
              true
          }
        )
        .catch(() => null);

      broadcastToUsers(
        [requestCandidateEmail],
        {
          type:
            "candidate-data-updated",
          event:
            "request-decision",
          requestId:
            String(request._id),
          status:
            nextStatus,
          timestamp:
            now.toISOString()
        }
      );
    }

    return res.json({
      success: true,
      status:
        nextStatus,
      crmUpdated,
      message:
        `Request ${nextStatus.toLowerCase()} successfully.`
    });
  } catch (error) {
    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});

app.get("/api/admin/requests", adminAuth, async (req, res) => {
  try {
    if (
      !mongoConnected ||
      !mongoose.connection?.db
    ) {
      return res.status(503).json({
        success: false,
        requests: [],
        error:
          "Request storage is unavailable."
      });
    }

    const requestFilter = {};

    const candidateEmail =
      normalizePipelineEmail(
        req.query?.candidateEmail ||
        req.query?.email ||
        ""
      );

    if (candidateEmail) {
      requestFilter.candidate_email =
        candidateEmail;
    }

    if (
      String(
        req.query?.pendingOnly ||
        ""
      ).toLowerCase() === "true"
    ) {
      requestFilter.status =
        "Pending Approval";
    }

    const requests =
      await mongoose.connection.db
        .collection(
          "candidate_requests"
        )
        .find(requestFilter)
        .sort({
          created_at: -1
        })
        .limit(500)
        .toArray();

    return res.json({
      success: true,
      requests
    });
  } catch (error) {
    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});


