app.get("/api/admin/receipts", adminAuth, async (req, res) => {
  try {
    if (!mongoConnected || !mongoose.connection?.db) {
      return res.status(503).json({
        success:false,
        receipts:[],
        error:"Receipt storage is unavailable."
      });
    }

    const filter = {
      uploaded_via:
        "documents",
      document_library_upload:
        true
    };
    const candidateEmail =
      normalizePipelineEmail(
        req.query?.candidateEmail ||
        req.query?.email ||
        ""
      );

    if (candidateEmail) {
      filter.candidate_email =
        candidateEmail;
    }

    const receipts =
      await mongoose.connection.db
        .collection("reimbursement_receipt_uploads")
        .find(filter)
        .sort({ uploaded_at:-1 })
        .limit(1000)
        .toArray();

    return res.json({
      success:true,
      receiptTypes:REIMBURSEMENT_RECEIPT_TYPES,
      receipts:receipts.map(item => ({
        ...item,
        id:String(item._id)
      }))
    });
  } catch (error) {
    return res.status(500).json({
      success:false,
      error:error.message
    });
  }
});

