function expenseReportString(value) {
  const unwrapped =
    typeof unwrapZohoFieldValue === "function"
      ? unwrapZohoFieldValue(value)
      : value;

  if (
    unwrapped === null ||
    unwrapped === undefined
  ) {
    return "";
  }

  if (
    typeof unwrapped === "object"
  ) {
    return String(
      unwrapped.name ||
      unwrapped.display_value ||
      unwrapped.value ||
      ""
    ).trim();
  }

  return String(unwrapped).trim();
}

function expenseReportDate(value) {
  if (!value) return "";

  const raw =
    expenseReportString(value);

  if (!raw) return "";

  const parsed =
    new Date(raw);

  if (
    Number.isNaN(
      parsed.getTime()
    )
  ) {
    return raw;
  }

  return parsed.toLocaleDateString(
    "en-US",
    {
      month: "2-digit",
      day: "2-digit",
      year: "numeric"
    }
  );
}

async function buildCandidateExpenseReport(
  email
) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  if (!normalizedEmail) {
    throw new Error(
      "Candidate email is required."
    );
  }

  const [
    savedReport,
    receiptUploads,
    deals
  ] =
    await Promise.all([
      mongoose.connection.db
        .collection(
          "reimbursement_expense_reports"
        )
        .findOne({
          candidate_email:
            normalizedEmail
        }),
      mongoose.connection.db
        .collection(
          "reimbursement_receipt_uploads"
        )
        .find({
          candidate_email:
            normalizedEmail,
          uploaded_via:
            "documents",
          document_library_upload:
            true
        })
        .sort({
          uploaded_at:
            -1
        })
        .toArray(),
      searchDealsByEmail(
        normalizedEmail
      ).catch(
        () => []
      )
    ]);

  const deal =
    deals?.[0] ||
    {};

  const latestByCategory =
    new Map();

  for (
    const receipt of
    receiptUploads || []
  ) {
    const key =
      String(
        receipt.category_id ||
        ""
      )
        .trim()
        .toLowerCase();

    if (
      key &&
      !latestByCategory.has(
        key
      )
    ) {
      latestByCategory.set(
        key,
        receipt
      );
    }
  }

  const rows =
    EXPENSE_REPORT_ROWS.map(
      config => {
        const receipt =
          latestByCategory.get(
            config.id
          );

        const savedAmount =
          Number(
            savedReport
              ?.amounts
              ?.[config.id]
          );

        const receiptAmount =
          Number(
            receipt
              ?.admin_correct_amount_usd ??
            receipt
              ?.admin_correct_amount
          );

        const savedSide =
          String(
            savedReport?.sides?.[config.id] ||
            ""
          )
            .trim()
            .toLowerCase();

        const receiptSide =
          String(
            receipt?.admin_amount_type ||
            ""
          )
            .trim()
            .toLowerCase();

        const selectedSide =
          savedSide === "credit" ||
          savedSide === "deduction"
            ? savedSide
            : receiptSide === "credit" ||
              receiptSide === "deduction"
              ? receiptSide
              : config.side;

        const reviewed =
          (
            receipt?.admin_reviewed === true ||
            Number.isFinite(savedAmount)
          ) &&
          (
            selectedSide === "credit" ||
            selectedSide === "deduction"
          );

        const amount =
          Number.isFinite(
            savedAmount
          )
            ? savedAmount
            : Number.isFinite(
                receiptAmount
              )
              ? receiptAmount
              : null;

        return {
          ...config,
          side:
            selectedSide,
          reviewed,
          amount,
          receipt_id:
            receipt?._id
              ? String(
                  receipt._id
                )
              : null,
          receipt_name:
            receipt
              ?.original_name ||
            receipt
              ?.document_name ||
            null,
          receipt_currency:
            receipt
              ?.currency ||
            null,
          candidate_amount:
            Number.isFinite(
              Number(
                receipt
                  ?.converted_usd ??
                receipt
                  ?.amount
              )
            )
              ? Number(
                  receipt
                    ?.converted_usd ??
                  receipt
                    ?.amount
                )
              : null
        };
      }
    );

  const credits =
    rows.reduce(
      (total, row) =>
        row.side ===
          "credit" &&
        Number.isFinite(
          row.amount
        )
          ? total +
            row.amount
          : total,
      0
    );

  const deductions =
    rows.reduce(
      (total, row) =>
        row.side ===
          "deduction" &&
        Number.isFinite(
          row.amount
        )
          ? total +
            row.amount
          : total,
      0
    );

  const net =
    credits -
    deductions;

  const firstName =
    expenseReportString(
      deal.First_Name
    );

  const lastName =
    expenseReportString(
      deal.Last_Name
    );

  const candidateName =
    [
      firstName,
      lastName
    ]
      .filter(Boolean)
      .join(" ") ||
    expenseReportString(
      deal.Full_Name
    ) ||
    normalizedEmail;

  const facility =
    expenseReportString(
      deal.Facility_Name
    ) ||
    expenseReportString(
      deal.Hospital_Name
    ) ||
    expenseReportString(
      deal.Account_Name
    );

  const arrivalDate =
    expenseReportDate(
      deal.Flight_Arrival_Time ||
      deal.ETA ||
      deal.Final_Destination_Arrival
    );

  return {
    candidate_email:
      normalizedEmail,
    candidate_name:
      candidateName,
    arrival_date:
      arrivalDate,
    facility,
    rows,
    totals: {
      credits,
      deductions,
      net,
      due_to:
        net > 0
          ? "RN"
          : net < 0
            ? "ICP"
            : "Neither",
      amount_due:
        Math.abs(net)
    },
    updated_at:
      savedReport
        ?.updated_at ||
      null
  };
}

async function createExpenseReportPdf(
  report
) {
  const pdf =
    await PDFDocument.create();

  const regular =
    await pdf.embedFont(
      StandardFonts.Helvetica
    );

  const bold =
    await pdf.embedFont(
      StandardFonts.HelveticaBold
    );

  const money =
    value =>
      Number.isFinite(
        Number(value)
      )
        ? `$ ${Number(
            value
          ).toFixed(2)}`
        : "";

  const page1 =
    pdf.addPage([
      612,
      792
    ]);

  page1.drawText(
    "Reimbursement Expense Report",
    {
      x: 175,
      y: 735,
      size: 18,
      font: bold
    }
  );

  page1.drawText(
    `Name: ${report.candidate_name || ""}`,
    {
      x: 54,
      y: 690,
      size: 10,
      font: bold
    }
  );

  page1.drawText(
    `Arrival Date: ${report.arrival_date || ""}`,
    {
      x: 54,
      y: 672,
      size: 10,
      font: bold
    }
  );

  page1.drawText(
    `Facility: ${report.facility || ""}`,
    {
      x: 54,
      y: 654,
      size: 10,
      font: bold
    }
  );

  page1.drawText(
    "Verified amounts below are populated from candidate receipts reviewed by ICP administration.",
    {
      x: 54,
      y: 620,
      size: 9,
      font: regular,
      maxWidth: 500
    }
  );

  const tableX =
    42;

  const widths =
    [
      275,
      120,
      120
    ];

  let y =
    588;

  const headerHeight =
    24;

  page1.drawRectangle({
    x:
      tableX,
    y:
      y -
      headerHeight,
    width:
      widths.reduce(
        (a, b) =>
          a + b,
        0
      ),
    height:
      headerHeight,
    borderWidth:
      1
  });

  page1.drawText(
    "Receipt Details",
    {
      x:
        tableX +
        8,
      y:
        y -
        16,
      size:
        9,
      font:
        bold
    }
  );

  page1.drawText(
    "Credits",
    {
      x:
        tableX +
        widths[0] +
        8,
      y:
        y -
        16,
      size:
        9,
      font:
        bold
    }
  );

  page1.drawText(
    "Deductions",
    {
      x:
        tableX +
        widths[0] +
        widths[1] +
        8,
      y:
        y -
        16,
      size:
        9,
      font:
        bold
    }
  );

  y -=
    headerHeight;

  for (
    const row of
    report.rows
  ) {
    const height =
      24;

    page1.drawRectangle({
      x:
        tableX,
      y:
        y -
        height,
      width:
        widths.reduce(
          (a, b) =>
            a + b,
          0
        ),
      height,
      borderWidth:
        0.6
    });

    page1.drawLine({
      start: {
        x:
          tableX +
          widths[0],
        y:
          y
      },
      end: {
        x:
          tableX +
          widths[0],
        y:
          y -
          height
      },
      thickness:
        0.6
    });

    page1.drawLine({
      start: {
        x:
          tableX +
          widths[0] +
          widths[1],
        y:
          y
      },
      end: {
        x:
          tableX +
          widths[0] +
          widths[1],
        y:
          y -
          height
      },
      thickness:
        0.6
    });

    page1.drawText(
      `${row.label}`,
      {
        x:
          tableX +
          6,
        y:
          y -
          16,
        size:
          8.2,
        font:
          regular,
        maxWidth:
          widths[0] -
          12
      }
    );

    if (
      row.side ===
        "credit"
    ) {
      page1.drawText(
        row.reviewed
          ? `-$ ${Math.abs(Number(row.amount || 0)).toFixed(2)}`
          : "Pending review",
        {
          x:
            tableX +
            widths[0] +
            6,
          y:
            y -
            16,
          size:
            8.2,
          font:
            regular
        }
      );
    } else {
      page1.drawText(
        row.reviewed
          ? `+$ ${Math.abs(Number(row.amount || 0)).toFixed(2)}`
          : "Pending review",
        {
          x:
            tableX +
            widths[0] +
            widths[1] +
            6,
          y:
            y -
            16,
          size:
            8.2,
          font:
            regular
        }
      );
    }

    y -=
      height;
  }

  y -=
    10;

  page1.drawText(
    `Total Credits: -$ ${Math.abs(Number(report.totals.credits || 0)).toFixed(2)}`,
    {
      x: 54,
      y,
      size: 10,
      font: bold
    }
  );

  y -=
    18;

  page1.drawText(
    `Total Debits / Deductions: +$ ${Math.abs(Number(report.totals.deductions || 0)).toFixed(2)}`,
    {
      x: 54,
      y,
      size: 10,
      font: bold
    }
  );

  y -=
    26;

  page1.drawText(
    `Reimbursement Due to ${report.totals.due_to}: ${money(
      report.totals.amount_due
    )}`,
    {
      x: 54,
      y,
      size: 13,
      font: bold
    }
  );

  const page2 =
    pdf.addPage([
      612,
      792
    ]);

  page2.drawText(
    "Advance Payment Agreement",
    {
      x: 190,
      y: 735,
      size: 18,
      font: bold
    }
  );

  page2.drawText(
    `Candidate Name: ${report.candidate_name || ""}`,
    {
      x: 54,
      y: 685,
      size: 10,
      font: bold
    }
  );

  const agreement =
    [
      "This agreement is made between Infinity Care Partners, LLC and the individual who has been offered a permanent nursing or healthcare worker position with a U.S. employer, in collaboration with Infinity Care Partners, LLC.",
      `Based on the verified expense report, the current estimated reimbursement or advance balance is ${money(report.totals.amount_due)}.`,
      "The advanced sum, when applicable, will be deducted or repaid in accordance with the candidate's applicable employment, service, and reimbursement agreements.",
      "The candidate is responsible for promptly notifying Infinity Care Partners of any reasons or changes that may affect the reimbursement or advance payment calculation."
    ];

  let ay =
    645;

  for (
    const paragraph of
    agreement
  ) {
    page2.drawText(
      paragraph,
      {
        x: 54,
        y: ay,
        size: 10,
        font: regular,
        maxWidth: 500,
        lineHeight: 15
      }
    );

    ay -=
      80;
  }

  page2.drawText(
    `Current estimated amount due to ${report.totals.due_to}: ${money(
      report.totals.amount_due
    )}`,
    {
      x: 54,
      y: 290,
      size: 11,
      font: bold
    }
  );

  page2.drawText(
    "Signed: ______________________________     Date: ____________________",
    {
      x: 54,
      y: 220,
      size: 10,
      font: regular
    }
  );

  page2.drawText(
    "Approved By: _________________________     ICP Representative",
    {
      x: 54,
      y: 180,
      size: 10,
      font: regular
    }
  );

  return Buffer.from(
    await pdf.save()
  );
}

