app.patch("/api/admin/receipts/:receiptId", adminAuth, async (req, res) => {
  try {
    if (!mongoConnected || !mongoose.connection?.db) {
      return res.status(503).json({
        success:false,
        error:"Receipt storage is unavailable."
      });
    }

    const receiptId =
      String(req.params.receiptId || "").trim();

    if (!mongoose.Types.ObjectId.isValid(receiptId)) {
      return res.status(400).json({
        success:false,
        error:"Invalid receipt ID."
      });
    }

    const collection =
      mongoose.connection.db
        .collection("reimbursement_receipt_uploads");

    const receipt =
      await collection.findOne({
        _id:new mongoose.Types.ObjectId(receiptId)
      });

    if (!receipt) {
      return res.status(404).json({
        success:false,
        error:"Receipt not found."
      });
    }

    const correctAmount =
      Number(req.body?.correctAmount);

    const correctAmountUsd =
      Number(
        req.body?.correctAmountUsd ??
        req.body?.correctAmount
      );

    const amountType =
      String(
        req.body?.amountType ||
        req.body?.type ||
        ""
      )
        .trim()
        .toLowerCase();

    if (
      !Number.isFinite(correctAmount) ||
      correctAmount < 0
    ) {
      return res.status(400).json({
        success:false,
        error:"Enter a valid amount."
      });
    }

    if (
      amountType !== "credit" &&
      amountType !== "deduction"
    ) {
      return res.status(400).json({
        success:false,
        error:"Select whether this amount is a credit or deduction."
      });
    }

    const now = new Date();

    await collection.updateOne(
      {
        _id:receipt._id
      },
      {
        $set:{
          admin_correct_amount:correctAmount,
          admin_correct_amount_usd:
            Number.isFinite(correctAmountUsd)
              ? correctAmountUsd
              : correctAmount,
          admin_amount_type:
            amountType,
          admin_note:
            String(req.body?.note || "").trim(),
          admin_reviewed:true,
          admin_reviewed_at:now,
          updated_at:now
        }
      }
    );

    const categoryKey =
      String(
        receipt.category_id ||
        "other"
      )
        .trim()
        .replace(
          /[^a-zA-Z0-9_]+/g,
          "_"
        );

    await mongoose.connection.db
      .collection(
        "reimbursement_expense_reports"
      )
      .updateOne(
        {
          candidate_email:
            normalizePipelineEmail(
              receipt.candidate_email
            )
        },
        {
          $set: {
            candidate_email:
              normalizePipelineEmail(
                receipt.candidate_email
              ),
            [`amounts.${categoryKey}`]:
              Number.isFinite(
                correctAmountUsd
              )
                ? correctAmountUsd
                : correctAmount,
            [`sides.${categoryKey}`]:
              amountType,
            [`receipt_ids.${categoryKey}`]:
              String(
                receipt._id
              ),
            updated_at:
              now
          },
          $setOnInsert: {
            created_at:
              now
          }
        },
        {
          upsert:
            true
        }
      );

    const report =
      await buildCandidateExpenseReport(
        receipt.candidate_email
      );

    broadcastToUsers(
      [
        normalizePipelineEmail(
          receipt.candidate_email
        )
      ],
      {
        type:
          "candidate-data-updated",
        event:
          "expense-report-updated",
        timestamp:
          new Date()
            .toISOString()
      }
    );

    return res.json({
      success:true,
      message:"Receipt amount saved successfully.",
      receiptId,
      report
    });
  } catch (error) {
    return res.status(500).json({
      success:false,
      error:error.message
    });
  }
});

