app.put("/api/profile/extended", authenticateToken, async (req, res) => {
  try {
    if (!mongoConnected || !mongoose.connection?.db) {
      return res.status(503).json({ success: false, error: "Profile storage is temporarily unavailable." });
    }
    const email = String(req.userEmail || "").trim().toLowerCase();
    const collection =
      mongoose.connection.db.collection(
        "candidate_extended_profiles"
      );

    const existing =
      await collection.findOne({
        candidate_email: email
      });

    const dependants =
      Array.isArray(req.body?.dependants)
        ? req.body.dependants.map(item => ({
            name:
              String(item?.name || "").trim(),
            age:
              String(item?.age || "").trim(),
            relationship:
              String(item?.relationship || "").trim(),
            passport:
              String(item?.passport || "").trim(),
            passport_uploaded:
              item?.passport_uploaded === true ||
              item?.passportUploaded === true,
            approved_at:
              item?.approved_at || null
          }))
        : (
            Array.isArray(existing?.dependants)
              ? existing.dependants
              : []
          );

    const incomingTravel =
      req.body?.travelSummary &&
      typeof req.body.travelSummary === "object"
        ? req.body.travelSummary
        : null;

    const travelSummary =
      incomingTravel
        ? {
            departureCity:
              String(incomingTravel.departureCity || "").trim(),
            checkedBags:
              String(incomingTravel.checkedBags || "").trim(),
            carryOn:
              String(incomingTravel.carryOn || "").trim(),
            boxes:
              String(incomingTravel.boxes || "").trim(),
            pets:
              String(incomingTravel.pets || "").trim(),
            travelCash:
              String(
                incomingTravel.travelCash ||
                incomingTravel.cashUsd ||
                ""
              ).trim(),
            carSeats:
              String(incomingTravel.carSeats || "").trim(),
            wheelchair:
              String(incomingTravel.wheelchair || "").trim(),
            phoneModelCarrier:
              String(
                incomingTravel.phoneModelCarrier ||
                incomingTravel.phoneMakeType ||
                ""
              ).trim(),
            simUnlocked:
              String(incomingTravel.simUnlocked || "").trim(),
            drivingPlan:
              String(incomingTravel.drivingPlan || "").trim(),
            carPurchasePlan:
              String(incomingTravel.carPurchasePlan || "").trim(),
            foundationsCompleted:
              String(incomingTravel.foundationsCompleted || "").trim(),
            spouseEmployment:
              String(incomingTravel.spouseEmployment || "").trim(),
            updatedAt:
              new Date()
          }
        : (
            existing?.travelSummary ||
            {}
          );

    await collection.updateOne(
      {
        candidate_email: email
      },
      {
        $set: {
          candidate_email: email,
          dependants,
          travelSummary,
          updated_at: new Date()
        },
        $setOnInsert: {
          created_at: new Date()
        }
      },
      {
        upsert: true
      }
    );

    return res.json({
      success: true,
      profile: {
        candidate_email: email,
        dependants,
        travelSummary
      }
    });
  } catch (error) {
    return res.status(500).json({ success: false, error: error.message });
  }
});

