async function getRecruitPipelineStart(email) {
  const normalizedEmail = String(email || "").toLowerCase().trim();
  if (!normalizedEmail) {
    return { dateReceived: null, source: "none", candidateId: null, candidate: null, module: null };
  }

  const records = await searchRecruitCandidatesByEmail(normalizedEmail).catch(error => {
    console.error("[Pipeline] Recruit pipeline lookup failed:", error.message);
    return [];
  });

  if (!Array.isArray(records) || records.length === 0) {
    return { dateReceived: null, source: "none", candidateId: null, candidate: null, module: null };
  }

  const newestRecord = (moduleName) => records
    .filter(record => record?._recruitModule === moduleName)
    .sort((a, b) =>
      new Date(b.Modified_Time || b.Created_Time || 0) -
      new Date(a.Modified_Time || a.Created_Time || 0)
    )[0] || null;

  const candidateRecord = newestRecord("Candidates");
  const applicationRecord = newestRecord("Applications");
  const nclexProgramRecord = newestRecord("CustomModule1");

  // Source priority:
  // 1. Candidates
  // 2. Applications
  // 3. NCLEX PROGRAM (CustomModule1) only when neither of the first two exists.
  //
  // NCLEX PROGRAM must contain Date_Received. Its Created_Time must not start
  // the pipeline because it is only a fallback trigger when the candidate has
  // not yet entered Candidates or Applications.
  let selected = null;
  let dateReceived = null;
  let source = "none";
  let moduleName = null;

  if (candidateRecord) {
    selected = candidateRecord;
    moduleName = "Candidates";
    dateReceived = candidateRecord.Date_Received || candidateRecord.Created_Time || null;
    source = candidateRecord.Date_Received
      ? "Candidates.Date_Received"
      : candidateRecord.Created_Time
        ? "Candidates.Created_Time"
        : "none";
  } else if (applicationRecord) {
    selected = applicationRecord;
    moduleName = "Applications";
    dateReceived = applicationRecord.Date_Received || applicationRecord.Created_Time || null;
    source = applicationRecord.Date_Received
      ? "Applications.Date_Received"
      : applicationRecord.Created_Time
        ? "Applications.Created_Time"
        : "none";
  } else if (nclexProgramRecord?.Date_Received) {
    selected = nclexProgramRecord;
    moduleName = "CustomModule1";
    dateReceived = nclexProgramRecord.Date_Received;
    source = "CustomModule1.Date_Received";
  }

  return {
    dateReceived,
    source,
    candidateId: selected?.id || null,
    candidate: selected,
    module: moduleName
  };
}

function addPipelineOffset(anchorDate, stage) {
  const anchor = new Date(anchorDate);
  if (Number.isNaN(anchor.getTime())) return null;

  const rawDays =
    stage.days_from_start ??
    stage.daysFromStart ??
    stage.day_offset ??
    stage.dayOffset;

  const rawHours =
    stage.hours_from_start ??
    stage.hoursFromStart ??
    stage.hour_offset ??
    stage.hourOffset;

  const days = Number(rawDays || 0);
  const hours = Number(rawHours || 0);

  if (!Number.isFinite(days) || !Number.isFinite(hours)) return null;

  return new Date(
    anchor.getTime() +
    days * 24 * 60 * 60 * 1000 +
    hours * 60 * 60 * 1000
  );
}

