// Stage timers are sequential. Each next stage gets a fresh clock when the
// previous stage completes instead of continuing to count from Date_Received.
function getConfiguredStageOffsetHours(stage = {}) {
  if (stage.hours_from_start !== undefined && stage.hours_from_start !== null) {
    return Number(stage.hours_from_start);
  }
  if (stage.days_from_start !== undefined && stage.days_from_start !== null) {
    return Number(stage.days_from_start) * 24;
  }
  return 0;
}

function getSequentialDurationHours(stages, index) {
  const currentOffset = getConfiguredStageOffsetHours(stages[index]);
  if (index <= 0) return Math.max(0, currentOffset);
  const previousOffset = getConfiguredStageOffsetHours(stages[index - 1]);
  return Math.max(0, currentOffset - previousOffset);
}

function parseZohoDateTime(value) {
  if (!value) return null;

  if (
    value &&
    typeof value === "object" &&
    !(value instanceof Date)
  ) {
    value =
      value.value ??
      value.display_value ??
      value.displayValue ??
      value.name ??
      value.label ??
      value.date ??
      value.datetime ??
      value.Date ??
      value.DateTime ??
      value;
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime())
      ? null
      : value;
  }

  const normalized = String(value).trim();
  if (!normalized || normalized === "—") {
    return null;
  }

  const direct = new Date(normalized);
  if (!Number.isNaN(direct.getTime())) {
    return direct;
  }

  const withoutAt = normalized.replace(
    /\s+at\s+/i,
    " "
  );
  const secondAttempt = new Date(withoutAt);

  return Number.isNaN(secondAttempt.getTime())
    ? null
    : secondAttempt;
}

function isRecruitCheckboxChecked(
  value
) {
  if (
    value === true ||
    value === 1
  ) {
    return true;
  }

  if (
    value === false ||
    value === 0 ||
    value === null ||
    value === undefined
  ) {
    return false;
  }

  if (
    Array.isArray(
      value
    )
  ) {
    return value.some(
      isRecruitCheckboxChecked
    );
  }

  if (
    typeof value ===
    "object"
  ) {
    return isRecruitCheckboxChecked(
      value.checked ??
      value.selected ??
      value.value ??
      value.display_value ??
      value.name ??
      false
    );
  }

  return [
    "true",
    "1",
    "yes",
    "checked",
    "selected",
    "on"
  ].includes(
    String(value)
      .trim()
      .toLowerCase()
  );
}

function getZohoDateKeyForNow(
  rawValue,
  now = new Date()
) {
  const normalized =
    String(rawValue || "")
      .trim();

  // Zoho DateTime normally includes an explicit UTC offset.
  // Calculate "today" in the same offset so a Flight_Arrival_Time later today
  // still unlocks Aftercare, as requested.
  const offsetMatch =
    normalized.match(
      /([+-])(\d{2}):?(\d{2})$/
    );

  if (offsetMatch) {
    const sign =
      offsetMatch[1] === "-"
        ? -1
        : 1;

    const offsetMinutes =
      sign *
      (
        Number(offsetMatch[2]) *
          60 +
        Number(offsetMatch[3])
      );

    return new Date(
      now.getTime() +
      offsetMinutes *
        60 *
        1000
    )
      .toISOString()
      .slice(0, 10);
  }

  // Z means UTC.
  if (/Z$/i.test(normalized)) {
    return now
      .toISOString()
      .slice(0, 10);
  }

  // If Zoho returned a datetime without an offset, use the server's current
  // calendar date rather than comparing the exact clock time.
  const year =
    now.getFullYear();

  const month =
    String(
      now.getMonth() + 1
    ).padStart(2, "0");

  const day =
    String(
      now.getDate()
    ).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

function isZohoDateTodayOrPast(
  value,
  now = new Date()
) {
  if (
    value &&
    typeof value === "object" &&
    !(value instanceof Date)
  ) {
    value =
      value.value ??
      value.display_value ??
      value.displayValue ??
      value.name ??
      value.label ??
      value.date ??
      value.datetime ??
      value.Date ??
      value.DateTime ??
      value;
  }

  if (!value) {
    return false;
  }

  const normalized =
    String(value)
      .trim();

  if (
    !normalized ||
    normalized === "—"
  ) {
    return false;
  }

  // For Zoho DateTime values, the business rule is based on the calendar date:
  // today OR any past date unlocks. The exact hour/minute on today's date does
  // not keep Aftercare locked.
  const datePart =
    normalized.match(
      /^(\d{4}-\d{2}-\d{2})/
    )?.[1];

  if (datePart) {
    return (
      datePart <=
      getZohoDateKeyForNow(
        normalized,
        now
      )
    );
  }

  const parsed =
    parseZohoDateTime(
      value
    );

  return Boolean(
    parsed &&
    !Number.isNaN(
      parsed.getTime()
    ) &&
    parsed.getTime() <=
      now.getTime()
  );
}

function isPipelineStageCompletedRecord(stage) {
  if (!stage) return false;

  const status = String(
    stage.status ||
    stage.stage_status ||
    ""
  ).trim().toLowerCase();

  return (
    status === "completed" ||
    status === "complete" ||
    stage.completed === true ||
    stage.is_completed === true ||
    Boolean(stage.completed_date)
  );
}


function getTimingStanding(stage, now = new Date()) {
  if (stage?.status === "Completed") return "Good Standing";
  const deadline = stage?.target_date ? new Date(stage.target_date) : null;
  if (!deadline || Number.isNaN(deadline.getTime())) return "Good Standing";
  const remaining = deadline.getTime() - now.getTime();
  if (remaining < 0) return "Late";
  const durationMs = Math.max(
    1,
    Number(stage.duration_hours || 0) * 60 * 60 * 1000
  );
  return remaining <= durationMs * 0.25 ? "At Risk" : "Good Standing";
}

