app.get("/api/documents/crm-documents", authenticateToken, async (req, res) => {
  try {
    const email = String(req.userEmail || "").trim().toLowerCase();
    const accessToken = await getValidZohoToken();
    const userDeals = await searchDealsByEmail(email);

    if (!Array.isArray(userDeals) || userDeals.length === 0) {
      return res.json({
        success: true,
        documents: [],
        total: 0
      });
    }

    const documents = [];
    const unavailableDeals = [];

    for (const deal of userDeals) {
      if (!deal?.id) continue;

      let attachments = [];
      let loaded = false;

      for (const apiVersion of ["v3", "v2"]) {
        try {
          const response = await axios.get(
            `${ZOHO_CRM_URL}/crm/${apiVersion}/Deals/${deal.id}/Attachments`,
            {
              headers: {
                Authorization: `Zoho-oauthtoken ${accessToken}`
              },
              params: {
                per_page: 200
              },
              timeout: 30000
            }
          );

          attachments = Array.isArray(response.data?.data)
            ? response.data.data
            : [];

          loaded = true;
          break;
        } catch (error) {
          console.warn(
            `[CRM Docs] ${apiVersion} failed for Deal ${deal.id}:`,
            error.response?.data || error.message
          );
        }
      }

      if (!loaded) {
        unavailableDeals.push(deal.id);
      }

      attachments.forEach(attachment => {
        documents.push({
          id: attachment.id,
          attachment_id: attachment.id,
          document_name:
            attachment.File_Name ||
            attachment.file_name ||
            attachment.name ||
            `Document ${attachment.id}`,
          source: "crm",
          uploaded_at:
            attachment.Created_Time ||
            attachment.created_time ||
            attachment.created_at ||
            new Date().toISOString(),
          file_size: attachment.Size || attachment.size || 0,
          file_type:
            attachment.File_Type ||
            attachment.file_type ||
            "application/octet-stream",
          deal_id: deal.id,
          module: "Deals",
          status: "Available",
          original_name:
            attachment.File_Name ||
            attachment.file_name ||
            attachment.name ||
            `document_${attachment.id}`
        });
      });

      const fieldDocuments = normalizeCRMFileUploadFields(deal).map(document => ({
        ...document,
        source: "crm",
        deal_id: deal.id
      }));

      documents.push(...fieldDocuments);
    }

    const uniqueDocuments = Array.from(
      new Map(
        documents.map(document => [
          [
            document.deal_id || "",
            document.attachment_id || document.id || "",
            document.document_name || "",
            document.uploaded_at || ""
          ].join(":"),
          document
        ])
      ).values()
    ).sort(
      (a, b) =>
        new Date(b.uploaded_at || 0).getTime() -
        new Date(a.uploaded_at || 0).getTime()
    );

    return res.json({
      success: true,
      documents: uniqueDocuments,
      total: uniqueDocuments.length,
      matching_records: userDeals.length,
      partial: unavailableDeals.length > 0
    });
  } catch (error) {
    console.error("[CRM Docs] Error:", error.response?.data || error);

    return res.status(error.response?.status || 500).json({
      success: false,
      error:
        error.response?.data?.data?.[0]?.message ||
        error.response?.data?.message ||
        error.message ||
        "Failed to fetch documents"
    });
  }
});


/**
 * Fetch Recruit candidate attachments independently.
 * The Documents page calls this alongside the CRM endpoint so one source can
 * remain available when the other source is temporarily unavailable.
 */
app.get("/api/documents/recruit-documents", authenticateToken, async (req, res) => {
  res.setHeader("Cache-Control", "no-store, max-age=0");
  res.setHeader("Pragma", "no-cache");

  try {
    const email = String(req.userEmail || "").trim().toLowerCase();
    if (!email) {
      return res.status(400).json({ success: false, error: "User email is required" });
    }

    const accessToken = await getValidZohoToken();
    const candidates = await searchRecruitCandidatesByEmail(email);
    if (!Array.isArray(candidates) || candidates.length === 0) {
      return res.json({ success: true, documents: [], total: 0, connected: true });
    }

    const documents = [];
    const seen = new Set();

    // A candidate can have more than one matching Recruit record. Fetch all of
    // them so the tab does not silently omit documents from older records.
    for (const candidate of candidates) {
      const candidateId = candidate?.id;
      if (!candidateId) continue;

      try {
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments`;
        const responseData =
          await cachedZohoJsonGet(
            recruitUrl,
            {
              headers: {
                Authorization:
                  `Zoho-oauthtoken ${accessToken}`
              },
              ttlMs:
                RECRUIT_STATIC_CACHE_TTL_MS
            }
          );

        const attachments =
          responseData?.data ||
          [];
        for (const att of attachments) {
          const attachmentId = att.id || att.attachment_id;
          const key = `${candidateId}:${attachmentId}`;
          if (!attachmentId || seen.has(key)) continue;
          seen.add(key);

          documents.push({
            id: attachmentId,
            attachment_id: attachmentId,
            document_name: att.File_Name || att.name || `Recruit Document ${attachmentId}`,
            source: "recruit",
            uploaded_at: att.Created_Time || att.created_at || new Date().toISOString(),
            file_size: att.Size || 0,
            file_type: att.File_Type || "application/octet-stream",
            candidate_id: candidateId,
            module: "Candidates",
            status: "Available"
          });
        }
      } catch (candidateError) {
        console.error(`[Documents] Recruit attachments failed for ${candidateId}:`, candidateError.response?.data || candidateError.message);
      }
    }

    // Include locally logged Recruit uploads if Zoho is temporarily missing an
    // attachment. Duplicate IDs are removed above/below.
    if (mongoConnected) {
      try {
        const db = mongoose.connection.db;
        const stored = await db.collection("recruit_documents")
          .find({ candidate_email: email })
          .sort({ uploaded_at: -1 })
          .toArray();

        for (const doc of stored) {
          const attachmentId = doc.attachment_id || String(doc._id || "");
          const key = `mongo:${attachmentId}`;
          if (!attachmentId || seen.has(key) || documents.some((item) => String(item.attachment_id) === String(attachmentId))) continue;
          seen.add(key);
          documents.push({
            ...doc,
            id: attachmentId,
            attachment_id: attachmentId,
            document_name: doc.document_name || `Recruit Document ${attachmentId}`,
            source: "recruit",
            uploaded_at: doc.uploaded_at || new Date().toISOString()
          });
        }
      } catch (mongoError) {
        console.warn("[Documents] Recruit MongoDB fallback failed:", mongoError.message);
      }
    }

    documents.sort((a, b) => new Date(b.uploaded_at || 0) - new Date(a.uploaded_at || 0));
    return res.json({ success: true, documents, total: documents.length, connected: true });
  } catch (error) {
    console.error("[Documents] Recruit endpoint failed:", error.response?.data || error.message);
    return res.status(500).json({
      success: false,
      error: error.response?.data?.message || error.message || "Failed to fetch documents"
    });
  }
});

/**
 * Enhanced ALL documents endpoint with better CRM handling
 */
app.get("/api/documents/all", authenticateToken, async (req, res) => {
  try {
    const email = req.userEmail;
    console.log(`[Documents] Fetching all documents for: ${email}`);
    
    const accessToken = await getValidZohoToken();
    const allDocuments = [];
    let recruitConnected = false;
    let crmConnected = false;
    
    // 1. Fetch from Recruit
    try {
      const candidates = await searchRecruitCandidatesByEmail(email);
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        console.log(`[Documents] Found Recruit candidate: ${candidateId}`);
        
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments`;
        const response = await axios.get(recruitUrl, {
          headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
          timeout: 30000
        });
        
        const attachments = response.data?.data || [];
        console.log(`[Documents] Found ${attachments.length} Recruit attachments`);
        
        for (const att of attachments) {
          allDocuments.push({
            id: att.id,
            attachment_id: att.id,
            document_name: att.File_Name || att.name || `Recruit Document ${att.id}`,
            source: "recruit",
            sourceLabel: "Zoho Recruit",
            sourceIcon: "📊",
            sourceColor: "bg-blue-100 text-blue-700 border-blue-200",
            uploaded_at: att.Created_Time || att.created_at || new Date().toISOString(),
            file_size: att.Size || 0,
            file_type: att.File_Type || "application/pdf",
            candidate_id: candidateId,
            module: "Candidates",
            status: "Available"
          });
        }
        recruitConnected = true;
      }
    } catch (recruitError) {
      console.error("[Documents] Recruit fetch error:", recruitError.message);
      // Try MongoDB fallback for Recruit
      try {
        if (mongoConnected) {
          const db = mongoose.connection.db;
          const collection = db.collection('recruit_documents');
          const docs = await collection
            .find({ candidate_email: email })
            .sort({ uploaded_at: -1 })
            .toArray();
          
          for (const doc of docs) {
            allDocuments.push({
              ...doc,
              id: doc._id,
              attachment_id: doc.attachment_id,
              document_name: doc.document_name || `Recruit Document ${doc._id}`,
              source: "recruit",
              sourceLabel: "Zoho Recruit",
              sourceIcon: "📊",
              sourceColor: "bg-blue-100 text-blue-700 border-blue-200",
              uploaded_at: doc.uploaded_at || new Date().toISOString(),
              status: doc.status || "Available"
            });
          }
          if (docs.length > 0) recruitConnected = true;
        }
      } catch (fallbackError) {
        console.error("[Documents] Recruit fallback error:", fallbackError.message);
      }
    }
    
    // 2. Fetch from CRM - IMPROVED VERSION
    try {
      const userDeals = await searchDealsByEmail(email);
      if (userDeals && userDeals.length > 0) {
        const latestDeal = userDeals.sort((a, b) =>
          new Date(b.Modified_Time || b.Created_Time || 0) - new Date(a.Modified_Time || a.Created_Time || 0)
        )[0];
        const dealId = latestDeal.id;
        console.log(`[Documents] Found CRM deal: ${dealId}`);

        const fieldDocuments = normalizeCRMFileUploadFields(latestDeal);
        allDocuments.push(...fieldDocuments);
        if (fieldDocuments.length > 0) {
          crmConnected = true;
          console.log(`[Documents] Added ${fieldDocuments.length} CRM file-upload field document(s)`);
        }
        
        // Try direct API fetch first
        try {
          const crmUrl = `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments`;
          const response = await axios.get(crmUrl, {
            headers: { 
              Authorization: `Zoho-oauthtoken ${accessToken}`,
              'Content-Type': 'application/json'
            },
            timeout: 30000
          });
          
          const attachments = response.data?.data || [];
          console.log(`[Documents] Found ${attachments.length} CRM attachments via API`);
          
          for (const att of attachments) {
            allDocuments.push({
              id: att.id,
              attachment_id: att.id,
              document_name: att.File_Name || att.name || `CRM Document ${att.id}`,
              source: "crm",
              sourceLabel: "CRM",
              sourceIcon: "📤",
              sourceColor: "bg-green-100 text-green-700 border-green-200",
              uploaded_at: att.Created_Time || att.created_at || new Date().toISOString(),
              file_size: att.Size || 0,
              file_type: att.File_Type || "application/pdf",
              deal_id: dealId,
              module: "Deals",
              status: "Available"
            });
          }
          crmConnected = attachments.length > 0 || true;
        } catch (crmApiError) {
          console.error("[Documents] CRM API error, trying MongoDB fallback:", crmApiError.message);
          
          // Fallback to MongoDB
          if (mongoConnected) {
            const docs = await Documents.find({
              candidate_email: email
            }).sort({ uploaded_at: -1 });
            
            console.log(`[Documents] Found ${docs.length} CRM documents in MongoDB fallback`);
            
            for (const doc of docs) {
              allDocuments.push({
                ...doc.toObject(),
                id: doc._id,
                attachment_id: doc.attachment_id || doc.id,
                document_name: doc.document_name || `CRM Document ${doc._id}`,
                source: "crm",
                sourceLabel: "CRM",
                sourceIcon: "📤",
                sourceColor: "bg-green-100 text-green-700 border-green-200",
                uploaded_at: doc.uploaded_at || new Date().toISOString(),
                deal_id: doc.deal_id || dealId,
                status: doc.status || "Available"
              });
            }
            crmConnected = docs.length > 0 || true;
          }
        }
      } else {
        // No deal found - try MongoDB directly
        if (mongoConnected) {
          const docs = await Documents.find({
            candidate_email: email
          }).sort({ uploaded_at: -1 });
          
          if (docs.length > 0) {
            console.log(`[Documents] Found ${docs.length} CRM documents in MongoDB (no deal)`);
            for (const doc of docs) {
              allDocuments.push({
                ...doc.toObject(),
                id: doc._id,
                attachment_id: doc.attachment_id || doc.id,
                document_name: doc.document_name || `CRM Document ${doc._id}`,
                source: "crm",
                sourceLabel: "CRM",
                sourceIcon: "📤",
                sourceColor: "bg-green-100 text-green-700 border-green-200",
                uploaded_at: doc.uploaded_at || new Date().toISOString(),
                status: doc.status || "Available"
              });
            }
            crmConnected = true;
          }
        }
      }
    } catch (crmError) {
      console.error("[Documents] CRM fetch error:", crmError.message);
      // Final fallback - try MongoDB
      try {
        if (mongoConnected) {
          const docs = await Documents.find({
            candidate_email: email
          }).sort({ uploaded_at: -1 });
          
          if (docs.length > 0) {
            console.log(`[Documents] Found ${docs.length} CRM documents in final MongoDB fallback`);
            for (const doc of docs) {
              allDocuments.push({
                ...doc.toObject(),
                id: doc._id,
                attachment_id: doc.attachment_id || doc.id,
                document_name: doc.document_name || `CRM Document ${doc._id}`,
                source: "crm",
                sourceLabel: "CRM",
                sourceIcon: "📤",
                sourceColor: "bg-green-100 text-green-700 border-green-200",
                uploaded_at: doc.uploaded_at || new Date().toISOString(),
                status: doc.status || "Available"
              });
            }
            crmConnected = true;
          }
        }
      } catch (finalError) {
        console.error("[Documents] Final CRM fallback error:", finalError.message);
      }
    }
    
    console.log(`[Documents] Total documents found: ${allDocuments.length}`);
    console.log(`[Documents] Sources: Recruit=${recruitConnected}, CRM=${crmConnected}`);
    
    // Sort by uploaded date (newest first)
    allDocuments.sort((a, b) => 
      new Date(b.uploaded_at || 0) - new Date(a.uploaded_at || 0)
    );
    
    // Deduplicate by attachment_id
    const seen = new Set();
    const uniqueDocs = allDocuments.filter(doc => {
      const key = doc.attachment_id || doc.id;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
    
    res.json({
      success: true,
      documents: uniqueDocs,
      total: uniqueDocs.length,
      sources: {
        recruit: uniqueDocs.filter(d => d.source === "recruit").length,
        crm: uniqueDocs.filter(d => d.source === "crm").length
      },
      connected: {
        recruit: recruitConnected,
        crm: crmConnected
      }
    });
    
  } catch (error) {
    console.error("[Documents] Error:", error);
    res.status(500).json({
      success: false,
      error: error.message || "Failed to fetch documents"
    });
  }
});

