const normalizePipelineEmail = value =>
  String(value || "").trim().toLowerCase();

const normalizeCandidateIdentityName = value =>
  String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

async function resolveCanonicalPipelineEmail(value) {
  return normalizePipelineEmail(value);
}

const dedupePipelineStageList = (stages = []) => {
  const byName = new Map();
  for (const stage of stages) {
    const key = String(stage.stage_name || "").trim().toLowerCase();
    if (!key || byName.has(key)) continue;
    byName.set(key, stage);
  }
  return Array.from(byName.values())
    .sort((a, b) => Number(a.stage_order || 0) - Number(b.stage_order || 0))
    .slice(0, 56);
};

const HIRING_FORWARD_ORDER = [
  "Applied",
  "Associated with Job",
  "Qualified - Match",
  "Select Prescreen Time",
  "Prescreen Scheduled",
  "Prescreen Completed",
  "Client Documents & Video Provided",
  "Pending Interview Selection",
  "Interview Scheduled",
  "Interview Attended",
  "Offer Made",
  "Offer Accepted",
  "Hired",
  "Employment Contract Sent",
  "Employment Contract Signed",
  "Documents Received"
];

const isStoredStageComplete = stage => {
  if (!stage) return false;

  const status = String(
    stage.status ||
    stage.stage_status ||
    ""
  ).trim().toLowerCase();

  return (
    status === "completed" ||
    status === "complete" ||
    stage.completed === true ||
    stage.is_completed === true ||
    Boolean(stage.completed_date) ||
    Boolean(stage.completed_at)
  );
};

const isStoredTransferReached = stage => {
  if (!stage) {
    return false;
  }

  const status =
    String(
      stage.status ||
      stage.stage_status ||
      ""
    )
      .trim()
      .toLowerCase();

  return (
    isStoredStageComplete(stage) ||
    status === "in progress" ||
    status === "in-progress" ||
    status === "active" ||
    stage.nclex_eligible === true ||
    stage.nclex_branch_visible === true ||
    stage.transfer_status_verified === true ||
    stage.transfer_to_nclex_branch === true ||
    String(
      stage.completion_source ||
      ""
    )
      .toLowerCase()
      .includes("transfer")
  );
};

async function hasDurableNCLEXBranchHistory(
  candidateEmail
) {
  if (!mongoConnected) {
    return false;
  }

  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  const rows =
    await PipelineStage.find({
      candidate_email:
        email,
      is_deleted: {
        $ne: true
      },
      $or: [
        {
          stage_name:
            "Transfer to ICP USRN School"
        },
        {
          stage_category: {
            $in: [
              "NCLEX Roadmap",
              "NCLEX Prescreen"
            ]
          }
        },
        {
          nclex_eligible:
            true
        },
        {
          nclex_branch_visible:
            true
        },
        {
          transfer_status_verified:
            true
        }
      ]
    })
      .sort({
        stage_order: 1,
        updated_at: 1
      })
      .lean();

  return rows.some(stage => {
    if (
      stage.stage_name ===
      "Transfer to ICP USRN School"
    ) {
      return isStoredTransferReached(
        stage
      );
    }

    const status =
      String(
        stage.status ||
        ""
      )
        .trim()
        .toLowerCase();

    return (
      isStoredStageComplete(
        stage
      ) ||
      status ===
        "in progress" ||
      status ===
        "in-progress" ||
      stage.nclex_eligible ===
        true ||
      stage.nclex_branch_visible ===
        true
    );
  });
};


async function restoreForwardOnlyHiringProgress({
  email,
  recruitmentProgress,
  normalizedRecruitStatus
}) {
  const now = new Date();

  const stages =
    await PipelineStage.find({
      candidate_email:
        email,
      stage_name: {
        $in: [
          ...HIRING_FORWARD_ORDER,
          "Transfer to ICP USRN School",
          "Qualified Candidate Pool",
          "Not Qualified - to close",
          "Offer Declined"
        ]
      },
      is_deleted: {
        $ne: true
      }
    }).sort({
      stage_order: 1
    });

  if (!stages.length) return;

  const completedNames = new Set(
    stages
      .filter(isStoredStageComplete)
      .map(stage => stage.stage_name)
  );

  for (
    const name of
    recruitmentProgress?.completed || []
  ) {
    completedNames.add(name);
  }

  const mappedLiveStage =
    LEAD_MANAGEMENT_STATUS_STAGE_MAP.get(
      normalizedRecruitStatus
    );

  if (mappedLiveStage) {
    completedNames.add(
      mappedLiveStage
    );
  }

  const transferSelected =
    [
      "transfer to icp usrn school",
      "transfer to ivp usrn school"
    ].includes(
      normalizedRecruitStatus
    ) ||
    mappedLiveStage ===
      "Transfer to ICP USRN School";

  if (transferSelected) {
    completedNames.add(
      "Transfer to ICP USRN School"
    );

    const transferPayload = {
      candidate_email:
        email,
      stage_name:
        "Transfer to ICP USRN School",
      stage_category:
        "Hiring",
      status:
        "Completed",
      completed:
        true,
      is_completed:
        true,
      completed_date:
        now,
      nclex_eligible:
        true,
      nclex_branch_visible:
        true,
      transfer_status_verified:
        true,
      completion_source:
        "recruit_transfer_status",
      updated_at:
        now,
      is_deleted:
        false
    };

    const transferUpdate =
      await PipelineStage.updateMany(
        {
          candidate_email:
            email,
          stage_name:
            "Transfer to ICP USRN School"
        },
        {
          $set:
            transferPayload
        }
      );

    if (
      transferUpdate.matchedCount ===
      0
    ) {
      await PipelineStage.create({
        ...transferPayload,
        created_at:
          now
      });
    }
  }

  let furthestIndex = -1;

  completedNames.forEach(name => {
    const index =
      HIRING_FORWARD_ORDER.indexOf(name);

    if (index > furthestIndex) {
      furthestIndex = index;
    }
  });

  for (
    let index = 0;
    index <= furthestIndex;
    index += 1
  ) {
    const name =
      HIRING_FORWARD_ORDER[index];

    if (name !== "Documents Received") {
      completedNames.add(name);
    }
  }

  const operations = [];

  for (const stage of stages) {
    if (
      stage.stage_name ===
      "Documents Received"
    ) {
      continue;
    }

    if (
      completedNames.has(stage.stage_name)
    ) {
      operations.push({
        updateOne: {
          filter: { _id: stage._id },
          update: {
            $set: {
              status: "Completed",
              completed: true,
              is_completed: true,
              completed_date:
                stage.completed_date ||
                stage.completed_at ||
                now,
              updated_at: now,
              restored_from_history: true
            }
          }
        }
      });
      continue;
    }

    if (
      recruitmentProgress?.current ===
        stage.stage_name &&
      !isStoredStageComplete(stage)
    ) {
      operations.push({
        updateOne: {
          filter: { _id: stage._id },
          update: {
            $set: {
              status: "In Progress",
              started_at:
                stage.started_at || now,
              updated_at: now
            }
          }
        }
      });
    }
  }

  if (operations.length) {
    await PipelineStage.bulkWrite(
      operations,
      { ordered: false }
    );
  }
}


async function getCandidatePipelineEmails(
  canonicalEmail
) {
  const normalized = normalizePipelineEmail(canonicalEmail);
  return normalized ? [normalized] : [];
}

function chooseStrongestPipelineStage(
  current,
  candidate
) {
  if (!current) return candidate;
  if (!candidate) return current;

  const currentComplete =
    isStoredStageComplete(current);

  const candidateComplete =
    isStoredStageComplete(candidate);

  if (
    candidateComplete &&
    !currentComplete
  ) {
    return candidate;
  }

  if (
    currentComplete &&
    !candidateComplete
  ) {
    return current;
  }

  const currentDate =
    new Date(
      current.completed_date ||
      current.completed_at ||
      current.updated_at ||
      current.created_at ||
      0
    ).getTime();

  const candidateDate =
    new Date(
      candidate.completed_date ||
      candidate.completed_at ||
      candidate.updated_at ||
      candidate.created_at ||
      0
    ).getTime();

  return candidateDate > currentDate
    ? candidate
    : current;
}

