async function migrateVisibleFlowStages(candidateEmail) {
  if (!mongoConnected || !PipelineStage) return;
  const email = normalizePipelineEmail(candidateEmail);
  const rows = await PipelineStage.find({ candidate_email: email, is_deleted: { $ne: true } }).sort({ updated_at: 1 }).lean();
  const byName = new Map();
  for (const row of rows) {
    byName.set(row.stage_name, chooseStrongestPipelineStage(byName.get(row.stage_name), row));
  }
  const now = new Date();
  for (const [newStageName, legacyNames] of Object.entries(VISIBLE_FLOW_STAGE_MIGRATIONS)) {
    const legacyRows = legacyNames.map(name => byName.get(name)).filter(Boolean);
    const strongestLegacy = legacyRows.reduce((strongest, candidate) => chooseStrongestPipelineStage(strongest, candidate), null);
    if (!strongestLegacy) continue;
    const complete = isStoredStageComplete(strongestLegacy);
    const legacyStatus = String(strongestLegacy.status || "").trim().toLowerCase();
    const inProgress = legacyStatus === "in progress" || legacyStatus === "in-progress";
    if (!complete && !inProgress) continue;
    const category = ["I 140 Submitted for Immigration","Immigration Pathway Discovery Call","Foundations: Pillars","Foundations: Endorsement Discovery","I140 Approved","I140 Sent to NVC","I140 NVC Received","Visa Fee Bill","DS-260 / Civil Document Submission","Foundations: Cultural Readiness","Deployment Department Transition Call","Documentarily Qualified"].includes(newStageName) ? "Immigration" : "Deployment";
    await PipelineStage.findOneAndUpdate(
      { candidate_email: email, stage_name: newStageName },
      { $set: {
          candidate_email: email,
          stage_name: newStageName,
          stage_category: category,
          status: complete ? "Completed" : "In Progress",
          completed: complete,
          is_completed: complete,
          completed_date: complete ? (strongestLegacy.completed_date || strongestLegacy.completed_at || now) : null,
          started_at: strongestLegacy.started_at || null,
          target_date: strongestLegacy.target_date || null,
          legacy_source_stage: strongestLegacy.stage_name,
          completion_source: "legacy_flow_migration",
          is_deleted: false,
          updated_at: now
        },
        $setOnInsert: { created_at: strongestLegacy.created_at || now }
      },
      { upsert: true, new: true }
    );
  }
}

function getStrongestPipelineStages(
  stages
) {
  const strongestByName =
    new Map();

  for (const stage of stages || []) {
    if (!stage?.stage_name) {
      continue;
    }

    const plain =
      stage.toObject
        ? stage.toObject()
        : stage;

    strongestByName.set(
      plain.stage_name,
      chooseStrongestPipelineStage(
        strongestByName.get(
          plain.stage_name
        ),
        plain
      )
    );
  }

  return Array.from(
    strongestByName.values()
  ).sort(
    (a, b) =>
      Number(
        a.stage_order || 0
      ) -
      Number(
        b.stage_order || 0
      )
  );
}


