app.post("/api/crm/update-bank-details", authenticateToken, async (req, res) => {
  res.setHeader("Cache-Control", "no-store, max-age=0");
  res.setHeader("Pragma", "no-cache");

  try {
    const email = String(req.userEmail || "").trim().toLowerCase();
    if (!email) return res.status(400).json({ success: false, error: "Email required" });

    let decrypted;
    if (req.body?.encryptedPayload) {
      try {
        decrypted = decryptBankEnvelope(req.body.encryptedPayload);
      } catch (decryptError) {
        console.warn(`[Bank Details] Encrypted envelope could not be decrypted for ${email}: ${decryptError.message}`);
        return res.status(400).json({ success: false, error: "Unable to decrypt bank details securely. Refresh the page and submit again." });
      }
    } else if (req.body?.securePayload && isSecureProxyRequest(req)) {
      // HTTPS/TLS already encrypts this request in transit. This fallback avoids
      // losing submissions when browser Web Crypto or an ephemeral RSA key is unavailable.
      decrypted = req.body.securePayload;
    } else {
      return res.status(400).json({ success: false, error: "Secure bank-details payload is required" });
    }

    const {
      bankDetails,
      paymentDetails,
      totalDueToICPRN,
      payReimbursementTotal,
      advanceAgreement
    } = decrypted || {};

    const isAdvancePaymentAgreement =
      String(paymentDetails?.nursePaymentType || "")
        .trim()
        .toLowerCase() === "advanced payment agreement";

    if (
      isAdvancePaymentAgreement &&
      (
        advanceAgreement?.reviewed !== true ||
        advanceAgreement?.acknowledged !== true
      )
    ) {
      return res.status(400).json({
        success: false,
        error: "Advance Payment Agreement review and acknowledgement are required."
      });
    }
    const cleanBankDetails = {
      accountName: String(bankDetails?.accountName || "").trim(),
      accountNumber: String(bankDetails?.accountNumber || "").replace(/\s+/g, "").trim(),
      routingNumber: String(bankDetails?.routingNumber || "").replace(/\s+/g, "").trim(),
      bankName: String(bankDetails?.bankName || "").trim(),
      accountType: String(bankDetails?.accountType || "Checking").trim()
    };

    if (!cleanBankDetails.accountName || !cleanBankDetails.accountNumber || !cleanBankDetails.routingNumber) {
      return res.status(400).json({ success: false, error: "Account name, account number, and routing number are required" });
    }
    if (cleanBankDetails.accountNumber.length > 40 || cleanBankDetails.routingNumber.length > 30) {
      return res.status(400).json({ success: false, error: "Bank details exceed the allowed length" });
    }

    const userDeals = await searchDealsByEmail(email);
    if (!userDeals?.length) {
      return res.status(404).json({ success: false, error: "No CRM deal found for this user" });
    }

    const latestDeal = [...userDeals].sort((a, b) =>
      new Date(b.Modified_Time || b.Created_Time || 0) - new Date(a.Modified_Time || a.Created_Time || 0)
    )[0];
    const dealId = latestDeal.id;
    if (!dealId) return res.status(404).json({ success: false, error: "CRM deal ID is missing" });

    const reimbursementTotal = Number(
      totalDueToICPRN ?? payReimbursementTotal ?? 0
    );

    const REIMBURSEMENT_PAYMENT_FIELD =
      process.env.ZOHO_REIMBURSEMENT_PAYMENT_FIELD ||
      "Pay_Reimbursement_Total";

    // Keep each reimbursement value separate and human-readable in the CRM
    // multiline field instead of serializing the entire submission as one JSON object.
    const formatPayment = (label, payment = {}) => [
      `${label} Date - ${String(payment?.date || "")}`,
      `${label} Paid - ${payment?.paid === true ? "Yes" : "No"}`,
      `${label} Total - ${Number(payment?.total || 0)}`
    ];

    const protectedPaymentValue = [
      `Account Name - ${cleanBankDetails.accountName}`,
      `Account Number - ${cleanBankDetails.accountNumber}`,
      `Routing Number - ${cleanBankDetails.routingNumber}`,
      `Bank Name - ${cleanBankDetails.bankName}`,
      `Account Type - ${cleanBankDetails.accountType}`,
      `Reimbursement Total - ${Number.isFinite(reimbursementTotal) ? reimbursementTotal : 0}`,
      `Nurse Payment Type - ${String(paymentDetails?.nursePaymentType || "")}`,
      ...(isAdvancePaymentAgreement
        ? [
            `Advance Agreement Reviewed - Yes`,
            `Advance Agreement Acknowledged - Yes`,
            `Advance Agreement Acknowledged At - ${String(advanceAgreement?.acknowledgedAt || new Date().toISOString())}`,
            ...formatPayment("Initial Payment", {
              ...(paymentDetails?.initialPayment || {}),
              total: 1000
            })
          ]
        : []),
      ...formatPayment("Payment 1", paymentDetails?.payment1),
      ...formatPayment("Payment 2", paymentDetails?.payment2),
      ...formatPayment("Payment 3", paymentDetails?.payment3),
      ...formatPayment("Payment 4", paymentDetails?.payment4),
      `Submitted At - ${new Date().toISOString()}`
    ].join("\n");

    const updateRecord = {
      id: dealId,
      [REIMBURSEMENT_PAYMENT_FIELD]: protectedPaymentValue
    };

    const accessToken = await getValidZohoToken();
    const zohoResponse = await axios.put(
      `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}`,
      { data: [updateRecord], trigger: ["workflow"] },
      {
        headers: {
          Authorization: `Zoho-oauthtoken ${accessToken}`,
          "Content-Type": "application/json"
        },
        timeout: 30000
      }
    );

    const result = zohoResponse.data?.data?.[0];
    if (!result || String(result.status || "").toLowerCase() !== "success") {
      const details = result?.details || result?.message || zohoResponse.data;
      console.error("[Bank Details] CRM rejected update:", details);
      return res.status(502).json({
        success: false,
        error: result?.message || "The payment details could not be saved",
        details
      });
    }

    invalidateCandidateDetailsCache(email);

    const verifyResponse = await axios.get(
      `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}`,
      {
        headers: {
          Authorization: `Zoho-oauthtoken ${accessToken}`
        },
        timeout: 30000
      }
    );

    const verifiedRecord = verifyResponse.data?.data?.[0] || {};
    const savedValue = verifiedRecord[REIMBURSEMENT_PAYMENT_FIELD];

    // Zoho may mask protected fields. A successful update plus a non-empty
    // read-back is treated as confirmed.
    const confirmed =
      String(savedValue ?? "").trim().length > 0 ||
      String(result?.status || "").toLowerCase() === "success";

    if (!confirmed) {
      return res.status(502).json({
        success: false,
        error: "The payment details were accepted but could not be confirmed"
      });
    }

    if (mongoConnected) {
      await mongoose.connection.db
        .collection("reimbursement_bank_submissions")
        .updateOne(
          { candidate_email: email },
          {
            $set: {
              candidate_email: email,
              crm_deal_id: dealId,
              submitted: true,
              account_last4: cleanBankDetails.accountNumber.slice(-4),
              routing_last4: cleanBankDetails.routingNumber.slice(-4),
              payment_type: String(paymentDetails?.nursePaymentType || ""),
              advance_agreement_reviewed: isAdvancePaymentAgreement
                ? advanceAgreement?.reviewed === true
                : false,
              advance_agreement_acknowledged: isAdvancePaymentAgreement
                ? advanceAgreement?.acknowledged === true
                : false,
              advance_agreement_acknowledged_at: isAdvancePaymentAgreement
                ? new Date(advanceAgreement?.acknowledgedAt || Date.now())
                : null,
              submitted_at: new Date(),
              updated_at: new Date()
            }
          },
          { upsert: true }
        );
    }

    res.json({
      success: true,
      submitted: true,
      message: "Payment details submitted successfully"
    });
  } catch (error) {
    const zohoMessage = error.response?.data?.data?.[0]?.message || error.response?.data?.message;
    console.error("[Bank Details] Submission failed:", zohoMessage || error.message);
    res.status(error.response?.status || 500).json({
      success: false,
      error: zohoMessage || error.message || "Failed to update bank details"
    });
  }
});

