app.get("/api/crm/reimbursement-data", authenticateToken, async (req, res) => {
  res.setHeader("Cache-Control", "no-store, max-age=0");
  res.setHeader("Pragma", "no-cache");
  try {
    const email = req.userEmail;
    console.log("[Reimbursement] Fetching data for:", email);

    const userDeals = await searchDealsByEmail(email);
    if (!userDeals || userDeals.length === 0) {
      return res.status(404).json({ success: false, error: "No deal found" });
    }

    const latestDeal = userDeals.sort((a, b) =>
      new Date(b.Created_Time || 0) - new Date(a.Created_Time || 0)
    )[0];

    const data = {
      nursePaymentType: latestDeal.Nurse_payment_type || "",
      initialPayment: {
        date: latestDeal.Initial_Payment_Date || "",
        paid: Boolean(latestDeal.Initial_Payment_Date),
        total: Number(latestDeal.Initial_Payment_Total || 1000)
      },
      payment1: {
        date: latestDeal.Payment_1 || "",
        paid: latestDeal.Payment_1_Paid || false,
        total: latestDeal.Payment_1_Total || 0
      },
      payment2: {
        date: latestDeal.Payment_2 || "",
        paid: latestDeal.Payment_2_Paid || false,
        total: latestDeal.Payment_2_Total || 0
      },
      payment3: {
        date: latestDeal.Payment_3 || "",
        paid: latestDeal.Payment_3_Paid || false,
        total: latestDeal.Payment_3_Total || 0
      },
      payment4: {
        date: latestDeal.Payment_4 || "",
        paid: latestDeal.Payment_4_Paid || false,
        total: latestDeal.Payment_4_Total || 0
      },
      totalReimbursement:
        Number(latestDeal.Total_Due_to_ICP_RN || 0),
      amountPaid:
        [1, 2, 3, 4].reduce((sum, number) => {
          const paid = latestDeal[`Payment_${number}_Paid`] === true;
          const amount = Number(
            latestDeal[`Payment_${number}_Total`] || 0
          );
          return paid ? sum + amount : sum;
        }, 0),
      balance:
        Math.max(
          0,
          Number(latestDeal.Total_Due_to_ICP_RN || 0) -
          [1, 2, 3, 4].reduce((sum, number) => {
            const paid = latestDeal[`Payment_${number}_Paid`] === true;
            const amount = Number(
              latestDeal[`Payment_${number}_Total`] || 0
            );
            return paid ? sum + amount : sum;
          }, 0)
        ),
      submitted: false
    };

    if (mongoConnected) {
      const submission = await mongoose.connection.db
        .collection("reimbursement_bank_submissions")
        .findOne({ candidate_email: String(email || "").trim().toLowerCase() });

      data.submitted = submission?.submitted === true;
      data.submittedAt = submission?.submitted_at || null;
    }

    res.json({ success: true, data });
  } catch (error) {
    console.error("[Reimbursement] Error:", error.message);
    res.status(500).json({ success: false, error: error.message });
  }
});


// ─── VERIFIED CRM / RECRUIT ATTACHMENT HELPERS ───────────────────────────────
const extractZohoAttachmentId = (payload) =>
  payload?.data?.[0]?.details?.id || payload?.data?.[0]?.id || payload?.id || null;

const normalizeAttachmentName = (value) =>
  String(value || "").trim().toLowerCase();

const getCrmAttachmentName = (attachment) =>
  attachment?.File_Name ||
  attachment?.file_name ||
  attachment?.name ||
  attachment?.Attachment_Name ||
  attachment?.Original_File_Name ||
  "";

const getCrmAttachmentId = (attachment) =>
  attachment?.id ||
  attachment?.attachment_id ||
  attachment?.details?.id ||
  null;

async function fetchCrmDealAttachments({ token, dealId, apiVersion = "v3" }) {
  const response = await axios.get(
    `${ZOHO_CRM_URL}/crm/${apiVersion}/Deals/${dealId}/Attachments`,
    {
      headers: { Authorization: `Zoho-oauthtoken ${token}` },
      timeout: 45000,
      params: { per_page: 200 }
    }
  );

  return Array.isArray(response.data?.data)
    ? response.data.data
    : Array.isArray(response.data)
      ? response.data
      : [];
}

async function verifyCrmDealAttachment({
  token,
  dealId,
  attachmentId,
  filename,
  attempts = 6
}) {
  const expectedName = normalizeAttachmentName(filename);
  const expectedId = String(attachmentId || "");

  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    for (const apiVersion of ["v3", "v2"]) {
      try {
        const attachments = await fetchCrmDealAttachments({
          token,
          dealId,
          apiVersion
        });

        const match = attachments.find((attachment) => {
          const currentId = String(getCrmAttachmentId(attachment) || "");
          const currentName = normalizeAttachmentName(
            getCrmAttachmentName(attachment)
          );

          return (
            (expectedId && currentId === expectedId) ||
            (expectedName && currentName === expectedName)
          );
        });

        if (match) {
          return {
            verified: true,
            attachment_id: getCrmAttachmentId(match) || attachmentId,
            file_name: getCrmAttachmentName(match) || filename,
            api_version: apiVersion,
            attachment: match
          };
        }
      } catch (error) {
        console.warn(
          `[CRM Attachment Verify] Attempt ${attempt}, ${apiVersion} failed for Deal ${dealId}:`,
          error.response?.data || error.message
        );
      }
    }

    if (attempt < attempts) {
      await new Promise((resolve) => setTimeout(resolve, attempt * 1200));
    }
  }

  return {
    verified: false,
    attachment_id: attachmentId || null,
    file_name: filename
  };
}

async function uploadBufferToCrmDeal({ email, buffer, filename, mimetype }) {
  const normalizedEmail = String(email || "").trim().toLowerCase();
  const deals = await searchDealsByEmail(
    normalizedEmail,
    {
      forceRefresh: true
    }
  );

  if (!deals?.length) {
    throw new Error(`No matching CRM Deal found for ${normalizedEmail}`);
  }

  const sortedDeals = [...deals].sort(
    (a, b) =>
      new Date(b.Modified_Time || b.Created_Time || 0) -
      new Date(a.Modified_Time || a.Created_Time || 0)
  );

  const deal = sortedDeals[0];
  if (!deal?.id) {
    throw new Error("The matching CRM Deal does not contain a record ID");
  }

  const token = await getValidZohoToken();
  let uploadResponse = null;
  let uploadedAttachmentId = null;
  let uploadApiVersion = null;
  let lastUploadError = null;

  // Zoho accounts can differ in which attachment API version is enabled.
  for (const apiVersion of ["v3", "v2"]) {
    try {
      const fd = new FormData();
      fd.append("file", buffer, {
        filename,
        contentType: mimetype,
        knownLength: buffer.length
      });

      uploadResponse = await axios.post(
        `${ZOHO_CRM_URL}/crm/${apiVersion}/Deals/${deal.id}/Attachments`,
        fd,
        {
          headers: {
            Authorization: `Zoho-oauthtoken ${token}`,
            ...fd.getHeaders()
          },
          maxBodyLength: Infinity,
          maxContentLength: Infinity,
          timeout: 90000
        }
      );

      uploadedAttachmentId = extractZohoAttachmentId(uploadResponse.data);
      if (uploadedAttachmentId) {
        uploadApiVersion = apiVersion;
        break;
      }

      lastUploadError = new Error(
        `CRM ${apiVersion} upload did not return an attachment ID`
      );
    } catch (error) {
      lastUploadError = error;
      console.warn(
        `[CRM Attachment Upload] ${apiVersion} failed for Deal ${deal.id}:`,
        error.response?.data || error.message
      );
    }
  }

  if (!uploadedAttachmentId) {
    const zohoMessage =
      lastUploadError?.response?.data?.data?.[0]?.message ||
      lastUploadError?.response?.data?.message ||
      lastUploadError?.message ||
      "CRM did not return an attachment ID";

    throw new Error(zohoMessage);
  }

  // Zoho attachment-list reads can lag behind a successful upload. The upload
  // response attachment ID is authoritative; read-back verification is best-effort.
  let verification = {
    verified: false,
    attachment_id:
      uploadedAttachmentId,
    file_name:
      filename,
    api_version:
      null
  };

  try {
    verification =
      await verifyCrmDealAttachment({
        token,
        dealId: deal.id,
        attachmentId:
          uploadedAttachmentId,
        filename
      });
  } catch (verificationError) {
    console.warn(
      "[CRM Attachment Upload] Upload succeeded; delayed verification will not block submission:",
      verificationError?.message || verificationError
    );
  }

  return {
    success: true,
    verified: true,
    verification_pending:
      verification?.verified !== true,
    attachment_id: verification?.attachment_id || uploadedAttachmentId,
    file_name: verification?.file_name || filename,
    record_id: deal.id,
    record_name:
      deal.Deal_Name ||
      deal.Deal_Name1 ||
      deal.Candidate_Name ||
      deal.Name ||
      null,
    candidate_email: normalizedEmail,
    module: "Deals",
    upload_api_version: uploadApiVersion,
    verify_api_version: verification.api_version,
    matching_deals_count: sortedDeals.length
  };
}

async function uploadBufferToRecruitCandidate({
  email,
  buffer,
  filename,
  mimetype,
  documentType = "Other"
}) {
  const candidate =
    await resolveRecruitCandidateRecordForAttachments(
      email,
      { forceRefresh: true }
    );

  if (!candidate?.id) {
    throw new Error(
      `No actual Candidates-module record was found in Zoho Recruit for ${email}.`
    );
  }

  const token =
    await getValidZohoToken();

  const form =
    new FormData();

  form.append(
    "file",
    Buffer.from(buffer),
    {
      filename:
        filename || "document",
      contentType:
        mimetype ||
        "application/octet-stream",
      knownLength:
        buffer.length
    }
  );

  const category =
    /resume|cv/i.test(documentType)
      ? "Resume"
      : /contract/i.test(documentType)
        ? "Contracts"
        : "Others";

  let response;

  try {
    response =
      await axios({
        method: "POST",
        url:
          `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidate.id}/Attachments`,
        params: {
          attachments_category:
            category
        },
        headers: {
          Authorization:
            `Zoho-oauthtoken ${token}`,
          ...form.getHeaders()
        },
        data: form,
        maxBodyLength: Infinity,
        maxContentLength: Infinity,
        timeout: 90000
      });
  } catch (error) {
    const details =
      error.response?.data
        ? JSON.stringify(
            error.response.data
          )
        : error.message;

    console.error(
      "[Recruit Upload]",
      {
        email,
        candidateId:
          candidate.id,
        filename,
        category,
        status:
          error.response?.status,
        response:
          error.response?.data
      }
    );

    throw new Error(
      `Zoho Recruit attachment upload failed: ${details}`
    );
  }

  const attachmentId =
    extractZohoAttachmentId(
      response.data
    );

  if (!attachmentId) {
    throw new Error(
      "Zoho Recruit accepted the upload but did not return an attachment ID."
    );
  }

  return {
    success: true,
    attachment_id:
      attachmentId,
    record_id:
      candidate.id,
    candidate_id:
      candidate.id,
    module:
      "Candidates",
    category
  };
}

async function logVerifiedDocument({ email, name, type, size, mimetype, crm, recruit }) {
  if(!mongoConnected) return;
  try {
    await Documents.create({
      attachment_id: crm?.attachment_id || recruit?.attachment_id,
      crm_attachment_id: crm?.attachment_id || null,
      recruit_attachment_id: recruit?.attachment_id || null,
      document_name:name, document_type:type, candidate_email:email,
      status:"Uploaded", uploaded_at:new Date(), file_size:size, file_type:mimetype,
      deal_id:crm?.record_id || null, candidate_id:recruit?.record_id || null,
      destination: crm?.success && recruit?.success ? "both" : crm?.success ? "crm" : "recruit"
    });
  } catch(e) { console.error("[Document log]", e.message); }
}

const HIRING_DOCUMENT_TYPES = new Set([
  "passport", "nclex", "birth certificate", "resume", "offer letter",
  "contract", "employment contract", "hiring", "prescreen", "hired"
]);

const resolveDocumentDestination = (
  requestedDestination,
  documentType,
  pipelineSection
) => {
  const requested =
    String(
      requestedDestination ||
      "crm"
    )
      .trim()
      .toLowerCase();

  if (
    [
      "crm",
      "recruit",
      "both"
    ].includes(requested)
  ) {
    return requested;
  }

  const type =
    String(documentType || "")
      .trim()
      .toLowerCase();

  const section =
    String(pipelineSection || "")
      .trim()
      .toLowerCase();

  const isHiring =
    section === "hiring" ||
    HIRING_DOCUMENT_TYPES.has(
      type
    );

  return isHiring
    ? "recruit"
    : "crm";
};


