const DOCUMENT_LIBRARY_SECTION_ORDER = [
  "Profile",
  "Dependants",
  "Recruiting",
  "Immigration",
  "Deployment",
  "Aftercare"
];

const normalizeDocumentLibraryText =
  value =>
    String(value || "")
      .trim()
      .toLowerCase();

const inferDocumentLibraryCategory =
  document => {
    const explicit =
      normalizeDocumentLibraryText(
        document.document_category ||
        document.library_category ||
        document.requirement_key
      );

    if (explicit) {
      const direct =
        DOCUMENT_LIBRARY_CATEGORIES.find(
          category =>
            normalizeDocumentLibraryText(
              category.key
            ) === explicit ||
            normalizeDocumentLibraryText(
              category.label
            ) === explicit ||
            normalizeDocumentLibraryText(
              category.requirementKey
            ) === explicit
        );

      if (direct) {
        return direct;
      }
    }

    const haystack =
      normalizeDocumentLibraryText(
        [
          document.document_name,
          document.document_type,
          document.crm_field_api_name,
          document.original_name
        ]
          .filter(Boolean)
          .join(" ")
      );

    const keywordMap = [
      ["updated_resume_doc", "resume"], ["coe_letter_of_empl", "employment-letter"], ["birth_certificate", "birth-certificate"], ["signed_icp", "commitment-agreement"], ["signed_offer", "signed-offer"], ["emp_contract", "employment-contract"], ["immigration_pathway_acknowledgement", "immigration-pathway"], ["flight_confirmation", "flight-confirmation"], ["welcome_appointments", "welcome-appointments"], ["concierge_biography", "concierge-biography"], ["concierge_debrief", "concierge-debrief"], ["debrief_survey", "concierge-debrief"], ["called_1_yr_results", "one-year-survey"], ["advance_agreement", "expense-report"],
      ["updated resume", "resume"], ["resume", "resume"], ["letter of employment", "employment-letter"], ["certificate of employment", "employment-letter"], ["coe", "employment-letter"], ["passport biometric", "passport-biometric"], ["passport", "passport-id"], ["birth certificate", "birth-certificate"], ["home country rn", "professional-license"], ["professional license", "professional-license"], ["nursing diploma", "degree-diploma"], ["transcript", "degree-diploma"], ["diploma", "degree-diploma"], ["degree", "degree-diploma"], ["service agreement", "commitment-agreement"], ["commitment agreement", "commitment-agreement"], ["nclex pass", "nclex-pass-report"], ["nclex", "nclex-pass-report"], ["ces", "ces-report"], ["us state rn", "us-state-rn-license"], ["signed offer", "signed-offer"], ["offer letter", "signed-offer"], ["employment contract", "employment-contract"],
      ["immigration pathway", "immigration-pathway"], ["i-797", "uscis-approval"], ["i797", "uscis-approval"], ["i140", "i140-petition"], ["i-140", "i140-petition"], ["visa fee", "visa-fee"], ["fee bill", "visa-fee"], ["ds-260", "ds260-civil"], ["ds260", "ds260-civil"], ["civil document", "ds260-civil"], ["visa screen", "visa-screen"], ["visascreen", "visa-screen"], ["english exam", "english-result"], ["ielts", "english-result"], ["oet", "english-result"], ["embassy", "embassy-document"], ["medical exam", "medical-document"],
      ["behavioral", "behavioral-assessment"], ["r&l", "rl-form"], ["relocation logistics", "rl-form"], ["housing & transportation", "housing-transportation"], ["housing and transportation", "housing-transportation"], ["photo release", "photo-release"], ["video release", "photo-release"], ["2x2", "id-photos"], ["id photo", "id-photos"], ["flight confirmation", "flight-confirmation"], ["welcome packet", "welcome-packet"], ["welcome appointment", "welcome-appointments"], ["concierge biography", "concierge-biography"], ["expense report", "expense-report"], ["advance agreement", "expense-report"],
      ["24 hour call", "24-hour-call"], ["relocation survey", "relocation-survey"], ["concierge debrief", "concierge-debrief"], ["debrief survey", "concierge-debrief"], ["7 day call", "7-day-call"], ["2 week call", "2-week-call"], ["30 day survey", "thirty-day-survey"], ["90 day exit", "ninety-day-exit-call"], ["1 year survey", "one-year-survey"], ["1 yr results", "one-year-survey"], ["active license", "active-license"], ["updated license", "active-license"]
    ];

    for (
      const [
        keyword,
        key
      ] of keywordMap
    ) {
      if (
        haystack.includes(
          keyword
        )
      ) {
        return (
          DOCUMENT_LIBRARY_CATEGORIES.find(
            category =>
              category.key ===
              key
          ) ||
          null
        );
      }
    }

    const fallbackKey = String(document.source || document.destination || "").trim().toLowerCase() === "recruit" ? "resume" : "immigration-pathway";
    return DOCUMENT_LIBRARY_CATEGORIES.find(category => category.key === fallbackKey) || DOCUMENT_LIBRARY_CATEGORIES[0] || null;
  };

async function upsertDocumentLibraryUpload({
  email,
  categoryKey,
  documentName,
  documentType,
  destination,
  crm,
  recruit,
  uploadedAt = new Date(),
  approvalExempt = false,
  uploadedVia = "candidate_portal",
  extra = {}
}) {
  if (
    !mongoConnected ||
    !mongoose.connection?.db
  ) {
    return;
  }

  const category =
    DOCUMENT_LIBRARY_CATEGORIES.find(
      item =>
        item.key ===
        categoryKey
    );

  await mongoose.connection.db
    .collection(
      "document_library_uploads"
    )
    .insertOne({
      candidate_email:
        normalizePipelineEmail(email),
      category_key:
        categoryKey ||
        "other",
      category_label:
        category?.label ||
        documentType ||
        "Document",
      section:
        category?.section ||
        "Other",
      section_order:
        DOCUMENT_LIBRARY_SECTION_ORDER.indexOf(
          category?.section ||
          "Other"
        ),
      document_order:
        category?.order ||
        999,
      document_name:
        documentName,
      document_type:
        documentType,
      destination,
      crm_attachment_id:
        crm?.attachment_id ||
        null,
      recruit_attachment_id:
        recruit?.attachment_id ||
        null,
      crm_record_id:
        crm?.record_id ||
        null,
      recruit_record_id:
        recruit?.record_id ||
        null,
      approval_status:
        approvalExempt
          ? "approved"
          : "pending",
      approval_exempt:
        approvalExempt === true,
      already_approved:
        approvalExempt === true,
      uploaded_by_candidate:
        true,
      uploaded_via:
        uploadedVia,
      uploaded_at:
        uploadedAt,
      created_at:
        new Date(),
      ...extra
    });
}

async function synchronizePipelineFromDocumentLibrary(candidateEmail) {
  if (!mongoConnected || !mongoose.connection?.db || !PipelineStage) return;

  const email = normalizePipelineEmail(candidateEmail);
  const uploads = await mongoose.connection.db.collection("document_library_uploads")
    .find({ candidate_email: email }).toArray();
  const available = new Set(uploads.map(item => item.category_key));
  const now = new Date();

  const completeStage = async (stageName, categories, mode = "any") => {
    const keys = Array.isArray(categories) ? categories : [categories];
    const complete = mode === "all" ? keys.every(key => available.has(key)) : keys.some(key => available.has(key));
    if (!complete) return;
    await PipelineStage.updateMany(
      { candidate_email: email, stage_name: stageName, is_deleted: { $ne: true } },
      { $set: {
        status: "Completed", completed: true, is_completed: true,
        completed_date: now, updated_at: now,
        completion_source: "document_library",
        document_library_categories: keys,
        document_library_synced_at: now
      }}
    );
  };

  // Direct one-document pipeline links. If the stage explicitly requires the
  // document, upload in the library is enough to satisfy that document step.
  const direct = [
    ["Offer Accepted", ["signed-offer"]],
    ["Employment Contract Signed", ["employment-contract"]],
    ["Receipt Submission", ["expense-report"]],
    ["Document Review", ["nclex-pass-report", "passport-biometric", "birth-certificate"]]
  ];
  for (const [stageName, keys] of direct) await completeStage(stageName, keys, "any");

  // Preserve legacy required-document stages if they still exist for older candidates.
  const recruitmentRequired = ["resume","employment-letter","passport-id","birth-certificate","professional-license","degree-diploma","commitment-agreement"];
  for (const stageName of ["Required Documents","Document Upload","Upload Required Documents"]) {
    await completeStage(stageName, recruitmentRequired, "all");
  }
}


async function forceCompleteReceiptSubmissionFromDocumentLibrary(
  candidateEmail
) {
  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  if (
    !email ||
    !mongoConnected ||
    !PipelineStage
  ) {
    return null;
  }

  const now =
    new Date();

  const stage =
    await PipelineStage
      .findOneAndUpdate(
        {
          candidate_email:
            email,
          stage_name:
            "Receipt Submission",
          is_deleted: {
            $ne: true
          }
        },
        {
          $set: {
            status:
              "Completed",
            completed:
              true,
            is_completed:
              true,
            completed_date:
              now,
            completion_source:
              "document_library_expense_report",
            document_library_categories: [
              "expense-report"
            ],
            source_trigger_unlocked:
              true,
            trigger_unlocked:
              true,
            updated_at:
              now
          },
          $setOnInsert: {
            candidate_email:
              email,
            stage_name:
              "Receipt Submission",
            stage_category:
              "Deployment",
            stage_order:
              39,
            is_deleted:
              false,
            created_at:
              now
          }
        },
        {
          upsert:
            true,
          new:
            true,
          setDefaultsOnInsert:
            true
        }
      );

  invalidateCandidateDetailsCache?.(
    email
  );

  pipelineFieldStatusResponseCache
    ?.delete?.(
      email
    );

  pipelineLiveCrmStateCache
    ?.delete?.(
      email
    );

  broadcastToUsers(
    [email],
    {
      type:
        "pipeline-updated",
      event:
        "receipt-document-uploaded",
      source:
        "candidate_action",
      candidateEmail:
        email,
      stageStatus: {
        "Receipt Submission": {
          stage_name:
            "Receipt Submission",
          completed:
            true,
          is_completed:
            true,
          status:
            "Completed",
          unlocked:
            true,
          completed_date:
            now.toISOString()
        }
      },
      completionMap: {
        "Receipt Submission":
          true
      },
      changedFields: {},
      timestamp:
        now.toISOString()
    }
  );

  return stage;
}


const REQUIRED_DOCUMENT_DEFINITIONS = {
  resume: { label: "Resume", slug: "Resume" },
  employmentLetter: { label: "Letter of Employment", slug: "Letter_of_Employment" },
  passportId: { label: "Passport or Government ID", slug: "Passport_or_ID" },
  birthCertificate: { label: "Birth Certificate", slug: "Birth_Certificate" },
  license: { label: "Professional License", slug: "Professional_License" },
  education: { label: "Diploma or Degree", slug: "Diploma_or_Degree" },
  commitmentAgreement: { label: "Commitment Agreement", slug: "Commitment_Agreement" }
};

const sanitizeDocumentFilenamePart = value =>
  String(value || "")
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 80);

const getCanonicalFileExtension = filename => {
  const match = String(filename || "").match(/(\.[a-zA-Z0-9]{1,10})$/);
  return match ? match[1].toLowerCase() : "";
};

const buildCanonicalDocumentFilename = ({
  requirementKey,
  documentType,
  candidateEmail,
  originalName
}) => {
  const definition = REQUIRED_DOCUMENT_DEFINITIONS[requirementKey];
  const requestedType =
    definition?.slug ||
    sanitizeDocumentFilenamePart(documentType) ||
    "Document";

  const candidatePart =
    sanitizeDocumentFilenamePart(
      String(candidateEmail || "").split("@")[0]
    ) || "Candidate";

  const extension = getCanonicalFileExtension(originalName);
  return `${requestedType}_${candidatePart}${extension}`;
};

const REQUIRED_HIRING_DOCUMENT_KEYS =
  Object.keys(REQUIRED_DOCUMENT_DEFINITIONS);

const getHiringDocumentApprovalSummary = async candidateEmail => {
  if (!mongoConnected) {
    return {
      submitted: 0,
      approved: 0,
      rejected: 0,
      complete: false,
      documents: {}
    };
  }

  const record = await mongoose.connection.db
    .collection("hiring_required_documents")
    .findOne({ candidate_email: normalizePipelineEmail(candidateEmail) });

  const documents = record?.documents || {};
  const values = REQUIRED_HIRING_DOCUMENT_KEYS
    .map(key => documents[key])
    .filter(Boolean);

  const approved = values.filter(item => item.approval_status === "approved").length;
  const rejected = values.filter(item => item.approval_status === "rejected").length;

  return {
    submitted: values.length,
    approved,
    rejected,
    complete:
      REQUIRED_HIRING_DOCUMENT_KEYS.every(
        key => documents[key]?.approval_status === "approved"
      ),
    documents
  };
};

async function stageRecruitingDocumentForApproval({
  email,
  file,
  name,
  type,
  requirementKey,
  libraryCategoryKey,
  libraryDepartment,
  pipelineSection
}) {
  if (
    !mongoConnected ||
    !mongoose.connection?.db
  ) {
    throw new Error(
      "Database is required to hold Recruiting documents for approval."
    );
  }

  const now =
    new Date();

  const result =
    await mongoose.connection.db
      .collection(
        "pending_recruit_document_uploads"
      )
      .insertOne({
        candidate_email:
          normalizePipelineEmail(
            email
          ),
        document_name:
          name,
        original_name:
          file.originalname ||
          name,
        document_type:
          type,
        requirement_key:
          requirementKey ||
          null,
        document_category:
          libraryCategoryKey ||
          null,
        document_department:
          libraryDepartment ||
          "Recruiting",
        pipeline_section:
          pipelineSection ||
          "hiring",
        destination:
          "recruit",
        file_type:
          file.mimetype ||
          "application/octet-stream",
        file_size:
          file.size ||
          file.buffer?.length ||
          0,
        file_base64:
          Buffer.from(
            file.buffer
          ).toString(
            "base64"
          ),
        approval_status:
          "pending",
        status:
          "Awaiting Approval",
        created_at:
          now,
        uploaded_at:
          now,
        updated_at:
          now
      });

  const pendingId =
    String(
      result.insertedId
    );

  await upsertDocumentLibraryUpload({
    email,
    categoryKey:
      libraryCategoryKey ||
      "other",
    documentName:
      name,
    documentType:
      type,
    destination:
      "recruit",
    crm:
      null,
    recruit:
      null,
    uploadedAt:
      now,
    approvalExempt:
      false,
    uploadedVia:
      "documents",
    extra: {
      pending_upload_id:
        pendingId,
      pending_storage:
        true,
      approval_status:
        "pending",
      source:
        "pending",
      requirement_key:
        requirementKey ||
        null,
      pipeline_section:
        pipelineSection ||
        "hiring"
    }
  });

  if (
    requirementKey
  ) {
    const collection =
      mongoose.connection.db
        .collection(
          "hiring_required_documents"
        );

    await collection.updateOne(
      {
        candidate_email:
          normalizePipelineEmail(
            email
          )
      },
      {
        $set: {
          candidate_email:
            normalizePipelineEmail(
              email
            ),
          [`documents.${requirementKey}`]: {
            document_name:
              name,
            document_label:
              REQUIRED_DOCUMENT_DEFINITIONS[
                requirementKey
              ]?.label ||
              type,
            original_name:
              file.originalname ||
              name,
            pending_upload_id:
              pendingId,
            recruit_attachment_id:
              null,
            verified:
              false,
            approval_status:
              "pending",
            approved_at:
              null,
            approved_by:
              null,
            rejected_at:
              null,
            rejection_reason:
              null,
            uploaded_at:
              now
          },
          all_submitted:
            false,
          all_approved:
            false,
          updated_at:
            now,
          approval_updated_at:
            now
        }
      },
      {
        upsert:
          true
      }
    );
  }

  return {
    pendingId,
    uploadedAt:
      now
  };
}


app.post(["/api/documents/upload", "/api/documents/upload-to-crm-and-recruit"], authenticateToken, upload.single("file"), async (req,res)=>{
  const file=req.file;
  const email=String(req.userEmail || "").trim().toLowerCase();
  const type=req.body.document_type || "Document";
  const requirementKey=String(req.body.requirement_key || "").trim();
  const requestedName=req.body.document_name || file?.originalname;
  const name=buildCanonicalDocumentFilename({
    requirementKey,
    documentType:type,
    candidateEmail:email,
    originalName:file?.originalname || requestedName
  });
  const pipelineSection=
    String(
      req.body.pipeline_section ||
      ""
    ).trim();
  const crmFieldApiName=
    String(
      req.body.crm_field_api_name ||
      ""
    ).trim();
  const isDocumentLibraryUpload =
    String(
      req.body.document_library_upload ||
      ""
    )
      .trim()
      .toLowerCase() ===
      "true";

  const libraryDepartment =
    String(
      req.body.document_department ||
      ""
    )
      .trim();

  const requestedLibraryCategory =
    String(
      req.body.document_category ||
      req.body.library_category ||
      ""
    )
      .trim()
      .toLowerCase();

  const configuredLibraryCategory =
    DOCUMENT_LIBRARY_CATEGORIES.find(
      category =>
        String(
          category.key ||
          ""
        )
          .trim()
          .toLowerCase() ===
        requestedLibraryCategory
    );

  const configuredDestination =
    String(
      configuredLibraryCategory
        ?.defaultDestination ||
      ""
    )
      .trim()
      .toLowerCase();

  const destination =
    isDocumentLibraryUpload
      ? (
          configuredDestination ===
            "recruit"
            ? "recruit"
            : configuredDestination ===
                "crm"
              ? "crm"
              : [
                  "recruiting",
                  "recruitment"
                ].includes(
                  libraryDepartment
                    .toLowerCase()
                )
                ? "recruit"
                : "crm"
        )
      : resolveDocumentDestination(
          req.body.destination,
          type,
          pipelineSection
        );
  if(!file) return res.status(400).json({success:false,error:"No file uploaded"});
  if(!email) return res.status(400).json({success:false,error:"Candidate email is required"});
  if(file.size>15*1024*1024) return res.status(400).json({success:false,error:"File size must be under 15MB"});

  const libraryCategoryKey =
    String(
      req.body.document_category ||
      req.body.library_category ||
      ""
    )
      .trim()
      .toLowerCase();

  const isRecruitingLibraryUpload =
    isDocumentLibraryUpload &&
    destination === "recruit" &&
    (
      libraryDepartment
        .trim()
        .toLowerCase() ===
        "recruiting" ||
      configuredLibraryCategory
        ?.section ===
        "Recruiting"
    );

  if (
    isRecruitingLibraryUpload
  ) {
    try {
      const staged =
        await stageRecruitingDocumentForApproval({
          email,
          file,
          name,
          type,
          requirementKey:
            requirementKey ||
            configuredLibraryCategory
              ?.requirementKey ||
            "",
          libraryCategoryKey:
            libraryCategoryKey ||
            configuredLibraryCategory
              ?.key ||
            "other",
          libraryDepartment:
            libraryDepartment ||
            "Recruiting",
          pipelineSection:
            pipelineSection ||
            "hiring"
        });

      return res.status(201).json({
        success:
          true,
        pending_approval:
          true,
        approval_status:
          "pending",
        destination:
          "recruit",
        pending_upload_id:
          staged.pendingId,
        document_name:
          name,
        document_type:
          type,
        document_category:
          libraryCategoryKey ||
          configuredLibraryCategory
            ?.key ||
          "other",
        message:
          "Document submitted for administrator approval. It will be attached to Zoho Recruit after approval."
      });
    } catch (stagingError) {
      console.error(
        "[Documents] Recruiting document could not be staged:",
        stagingError
      );

      return res.status(500).json({
        success:
          false,
        error:
          stagingError.message ||
          "Unable to submit Recruiting document for approval."
      });
    }
  }

  let crm = {
    success: false,
    skipped:
      ![
        "crm",
        "both"
      ].includes(destination)
  };

  let recruit = {
    success: false,
    skipped:
      ![
        "recruit",
        "both"
      ].includes(destination)
  };

  if (
    [
      "crm",
      "both"
    ].includes(destination)
  ) {
    try {
      crm =
        await uploadBufferToCrmDeal({
          email,
          buffer:
            file.buffer,
          filename:
            name,
          mimetype:
            file.mimetype
        });
    } catch (error) {
      crm = {
        success: false,
        error:
          error.response?.data
            ?.message ||
          error.message
      };
    }
  }

  if (
    [
      "recruit",
      "both"
    ].includes(destination)
  ) {
    try {
      recruit =
        await uploadBufferToRecruitCandidate({
          email,
          buffer:
            file.buffer,
          filename:
            name,
          mimetype:
            file.mimetype,
          documentType:
            type
        });
    } catch (error) {
      recruit = {
        success: false,
        error:
          error.response?.data
            ?.message ||
          error.message
      };
    }
  }

  const requiredOk =
    destination === "both"
      ? (
          crm.success === true &&
          recruit.success === true
        )
      : destination === "crm"
        ? crm.success === true
        : recruit.success === true;
  if(requiredOk) {
    if (
      [
        "crm",
        "both"
      ].includes(destination) &&
      crm?.success &&
      crmFieldApiName &&
      crm?.record_id
    ) {
      try {
        const token =
          await getValidZohoToken();

        await axios.put(
          `${ZOHO_CRM_URL}/crm/v3/Deals`,
          {
            data: [
              {
                id: crm.record_id,
                [crmFieldApiName]: [
                  {
                    file_id:
                      crm.attachment_id
                  }
                ]
              }
            ]
          },
          {
            headers: {
              Authorization:
                `Zoho-oauthtoken ${token}`,
              "Content-Type":
                "application/json"
            },
            timeout: 30000
          }
        );

        crm.crm_field_api_name =
          crmFieldApiName;
        crm.crm_field_linked = true;
      } catch (fieldError) {
        crm.crm_field_api_name =
          crmFieldApiName;
        crm.crm_field_linked = false;
        crm.crm_field_error =
          fieldError.response?.data?.message ||
          fieldError.message;
        console.warn(
          `[Documents] CRM field ${crmFieldApiName} could not be linked; attachment remains available:`,
          crm.crm_field_error
        );
      }
    }

    await logVerifiedDocument({email,name,type,size:file.size,mimetype:file.mimetype,crm,recruit});

    await upsertDocumentLibraryUpload({
      email,
      categoryKey:
        libraryCategoryKey ||
        inferDocumentLibraryCategory({
          document_name:
            name,
          document_type:
            type,
          crm_field_api_name:
            crmFieldApiName,
          requirement_key:
            requirementKey
        })?.key ||
        "other",
      documentName:
        name,
      documentType:
        type,
      destination,
      crm,
      recruit
    });

    await synchronizePipelineFromDocumentLibrary(
      email
    );

    if (
      libraryCategoryKey ===
        "expense-report"
    ) {
      await forceCompleteReceiptSubmissionFromDocumentLibrary(
        email
      );
    }

    if (
      mongoConnected &&
      [
        "recruit",
        "both"
      ].includes(destination) &&
      pipelineSection.toLowerCase() ===
        "hiring" &&
      requirementKey
    ) {
      const collection = mongoose.connection.db.collection("hiring_required_documents");
      await collection.updateOne(
        { candidate_email: email },
        {
          $set: {
            candidate_email: email,
            [`documents.${requirementKey}`]: {
              document_name: name,
              document_label:
                REQUIRED_DOCUMENT_DEFINITIONS[requirementKey]?.label ||
                type,
              original_name: file.originalname,
              recruit_attachment_id: recruit.attachment_id || null,
              verified: recruit.success === true,
              approval_status: "pending",
              approved_at: null,
              approved_by: null,
              rejected_at: null,
              rejection_reason: null,
              uploaded_at: new Date()
            },
            updated_at: new Date()
          }
        },
        { upsert: true }
      );

      await collection.updateOne(
        { candidate_email: email },
        {
          $set: {
            all_submitted: false,
            all_approved: false,
            approval_updated_at: new Date()
          }
        }
      );
    }

    if (
      mongoConnected &&
      (
        libraryCategoryKey === "expense-report" ||
        String(req.body?.receipt_category || "").trim()
      )
    ) {
      await mongoose.connection.db
        .collection(
          "reimbursement_receipt_uploads"
        )
        .insertOne({
          candidate_email:
            email,
          category_id:
            String(
              req.body
                .receipt_category ||
              ""
            ),
          category_label:
            String(
              req.body
                .receipt_category_label ||
              ""
            ),
          amount:
            Number(
              req.body
                .receipt_amount ||
              0
            ),
          currency:
            String(
              req.body
                .receipt_currency ||
              "USD"
            ),
          converted_usd:
            Number(
              req.body
                .receipt_amount_usd ||
              0
            ),
          original_name:
            file.originalname,
          uploaded_via:
            "documents",
          document_library_upload:
            true,
          crm_attachment_id:
            crm?.attachment_id ||
            null,
          recruit_attachment_id:
            recruit?.attachment_id ||
            null,
          crm_deal_id:
            crm?.record_id ||
            null,
          recruit_candidate_id:
            recruit?.record_id ||
            null,
          source:
            crm?.success
              ? "crm"
              : recruit?.success
                ? "recruit"
                : null,
          uploaded_at:
            new Date()
        });
    }

    invalidateCandidateDetailsCache(email);
  }
  return res.status(requiredOk?200:502).json({
    success:requiredOk,document_name:name,destination,crm,recruit,
    policy:
      "Document Library uploads may be sent to CRM, Recruit, or both. Pipeline-triggered uploads are synchronized from the library category.",
    error:requiredOk?undefined:`${destination.toUpperCase()} rejected the document`
  });
});

// Complete R&L form: generates a PDF and uploads the PDF plus every supporting
// document to CRM Deal attachments. R&L is a Deployment form, not Hiring.
const rlUpload = upload.fields([
  {name:"documents_vaccineCards",maxCount:20},{name:"documents_policeClearance",maxCount:20},
  {name:"documents_passports",maxCount:20},{name:"documents_nclexFee",maxCount:20},{name:"documents_nclexSchedule",maxCount:20},
  {name:"documents_englishExam",maxCount:20},{name:"documents_cesReport",maxCount:20},{name:"documents_visaScreenFee",maxCount:20}
]);
app.post("/api/relocation-logistics/submit", authenticateToken, rlUpload, async(req,res)=>{
  try {
    const email=String(req.userEmail || "").trim().toLowerCase();
    const form=JSON.parse(req.body.form_data || "{}");
    if(!email) return res.status(400).json({success:false,error:"Candidate email is required"});
    const pdf=await PDFDocument.create(); const font=await pdf.embedFont(StandardFonts.Helvetica); const bold=await pdf.embedFont(StandardFonts.HelveticaBold);
    const pageSize=[612,792]; let page=pdf.addPage(pageSize); let y=750;
    const addLine=(label,value="")=>{ const text=`${label}${value!==""?": "+String(value):""}`; const wrapped=[]; let line=""; text.split(/\s+/).forEach(w=>{if((line+" "+w).length>88){wrapped.push(line);line=w}else line+=(line?" ":"")+w});if(line)wrapped.push(line); wrapped.forEach(t=>{if(y<55){page=pdf.addPage(pageSize);y=750}page.drawText(t,{x:45,y,size:10,font});y-=14}); };
    page.drawText("Relocation + Logistics Checklist",{x:45,y,size:18,font:bold}); y-=28;
    const fields=[
      ["Name",form.name],["Birth Date",form.birthDate],["Gender",form.gender],["Email",form.email],["Phone",form.phone],
      ["Case Manager",form.caseManager],["Preferred Contact",form.preferredContactText],["Height",form.height],["Weight",form.weight],["Clothing Size",form.clothingSize],
      ["About Candidate",form.aboutYou],["Resignation Period",form.resignationPeriod],["Anticipated Last Day",form.anticipatedLastDay],
      ["Departure City / Airport",form.departureCity],["Wheelchair",form.wheelchair],["Checked Bags",form.checkedBags],["Carry On",form.carryOn],["Boxes",form.boxes],
      ["Pets",form.pets],["Travel Cash",form.travelCash],["Car Seats",form.carSeats],["Phone + Carrier",form.phoneModelCarrier],["SIM Unlocked",form.simUnlocked],
      ["Driving Plan",form.drivingPlan],["Car Purchase Plan",form.carPurchasePlan],["Foundation Relias Complete",form.foundationsCompleted],["Family Employment Plans",form.spouseEmployment]
    ]; fields.forEach(([l,v])=>addLine(l,v||"—"));
    addLine("Dependents"); (form.dependents||[]).filter(d=>Object.values(d).some(Boolean)).forEach((d,i)=>addLine(`Dependent ${i+1}`,`${d.name||"—"}; DOB ${d.birthDate||"—"}; ${d.gender||"—"}; ${d.relationship||"—"}; Height ${d.height||"—"}; Weight ${d.weight||"—"}`));
    addLine("Relocation Travel Policy Accepted",form.relocationPolicyAccepted?"Yes":"No");
    addLine("Relocation Signature",form.relocationSignature||"—");
    const pdfBuffer=Buffer.from(await pdf.save()); const filename=`Relocation_Logistics_${email.replace(/[^a-z0-9]/gi,"_")}_${Date.now()}.pdf`;
    const crm=await uploadBufferToCrmDeal({email,buffer:pdfBuffer,filename,mimetype:"application/pdf"});
    const recruit={success:false,skipped:true,reason:"R&L is a Deployment form and is stored in CRM only"};
    const supporting=[]; for(const [field,files] of Object.entries(req.files||{})){ for(const file of files){
      let c={success:false}; try{c=await uploadBufferToCrmDeal({email,buffer:file.buffer,filename:file.originalname,mimetype:file.mimetype})}catch(e){c={success:false,error:e.message}}
      supporting.push({field,name:file.originalname,crm:c,recruit:{success:false,skipped:true}});
    }}
    const failed=supporting.filter(x=>!x.crm.success || x.crm.verified !== true);
    if(!crm.success || crm.verified !== true || failed.length) {
      return res.status(502).json({
        success:false,
        error:`${failed.length + (!crm.success || crm.verified !== true ? 1 : 0)} R&L file(s) were not verified in CRM attachments`,
        crm,
        recruit,
        supporting
      });
    }
    await logVerifiedDocument({
      email,
      name:filename,
      type:"Relocation & Logistics Checklist",
      size:pdfBuffer.length,
      mimetype:"application/pdf",
      crm,
      recruit
    });

    let completedStage = null;
    if(mongoConnected){
      const travelSummary = {
        departureCity: String(form.departureCity || "").trim(),
        wheelchair: String(form.wheelchair || "").trim(),
        checkedBags: String(form.checkedBags || "").trim(),
        carryOn: String(form.carryOn || "").trim(),
        boxes: String(form.boxes || "").trim(),
        pets: String(form.pets || "").trim(),
        travelCash: String(form.travelCash || "").trim(),
        carSeats: String(form.carSeats || "").trim(),
        phoneModelCarrier: String(form.phoneModelCarrier || "").trim(),
        simUnlocked: String(form.simUnlocked || "").trim(),
        drivingPlan: String(form.drivingPlan || "").trim(),
        carPurchasePlan: String(form.carPurchasePlan || "").trim(),
        submittedAt: new Date()
      };

      await mongoose.connection.db
        .collection("candidate_extended_profiles")
        .updateOne(
          { candidate_email:email },
          {
            $set:{ candidate_email:email, travelSummary, updated_at:new Date() },
            $setOnInsert:{ created_at:new Date() }
          },
          { upsert:true }
        );

      await mongoose.connection.db.collection("relocation_logistics_forms").updateOne(
        {candidate_email:email},
        {$set:{
          candidate_email:email,
          form_data:form,
          pdf_filename:filename,
          crm_attachment_id:crm.attachment_id,
          crm_deal_id:crm.record_id || null,
          crm_verified:crm.verified === true,
          recruit_attachment_id:null,
          supporting_documents:supporting.map(x=>({
            field:x.field,
            name:x.name,
            crm_attachment_id:x.crm.attachment_id,
            crm_verified:x.crm.verified === true,
            recruit_attachment_id:null
          })),
          submitted_at:new Date()
        }},
        {upsert:true}
      );

      // Complete the R&L stage only after the generated PDF and all selected
      // supporting files have been verified in CRM.
      const now = new Date();
      completedStage = await PipelineStage.findOneAndUpdate(
        {
          candidate_email: email,
          stage_name: "Submit R&L Checklist"
        },
        {
          $set: {
            status: "Completed",
            completed_date: now,
            timing_status: "Good Standing",
            updated_at: now,
            submission_reference: {
              crm_deal_id: crm.record_id || null,
              crm_attachment_id: crm.attachment_id,
              pdf_filename: filename,
              supporting_attachment_ids: supporting.map(item => item.crm.attachment_id)
            }
          }
        },
        { new: true }
      );

      if (completedStage) {
        const nextStage = await PipelineStage.findOne({
          candidate_email: email,
          is_deleted: { $ne: true },
          stage_order: { $gt: completedStage.stage_order }
        }).sort({ stage_order: 1 });

        if (nextStage && nextStage.status !== "Completed") {
          const durationHours = Math.max(0, Number(nextStage.duration_hours || 0));
          const nextTarget = new Date(now.getTime() + durationHours * 60 * 60 * 1000);

          await PipelineStage.findByIdAndUpdate(nextStage._id, {
            $set: {
              started_at: now,
              target_date:
                nextStage.stage_category === "Aftercare" && nextStage.target_date
                  ? nextStage.target_date
                  : nextTarget,
              status: nextStage.status === "Not Started"
                ? "In Progress"
                : nextStage.status,
              timing_status: "Good Standing",
              updated_at: now
            }
          });
        }
      }
    }

    invalidateCandidateDetailsCache(email);
    res.json({
      success:true,
      crm,
      recruit,
      supporting,
      pdf_filename:filename,
      destination:"crm",
      stage:completedStage,
      stage_completed:completedStage?.status === "Completed"
    });
  } catch(e){ console.error("[R&L]",e.response?.data||e); res.status(500).json({success:false,error:e.response?.data?.message||e.message}); }
});


// ─── HOUSING FORM SUBMISSION ─────────────────────────────────────────────────
// Registered before the catch-all 404 middleware. The completed housing form is
// rendered as a PDF, attached to CRM, and persisted in MongoDB before the
// pipeline stage is completed. Housing is not a Hiring document.
app.post(["/api/housing/submit", "/api/forms/housing/submit"], authenticateToken, express.json({ limit: "5mb" }), async (req, res) => {
  try {
    const email = String(req.userEmail || "")
      .trim()
      .toLowerCase();

    if (!email) {
      return res.status(400).json({ success: false, error: "Candidate email is required" });
    }

    const requiredFields = [
      "firstName", "lastName", "currentPhone", "currentAddress",
      "city", "state", "zipCode", "country"
    ];
    const missingFields = requiredFields.filter((field) => !String(req.body[field] || "").trim());
    if (missingFields.length) {
      return res.status(400).json({
        success: false,
        error: `Missing required housing fields: ${missingFields.join(", ")}`,
        missingFields
      });
    }

    const submittedAt = new Date();
    const form = { ...req.body, candidateEmail: email, submittedAt: submittedAt.toISOString() };

    const pdfDoc = await PDFDocument.create();
    const regularFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
    const pageWidth = 612;
    const pageHeight = 792;
    const margin = 45;
    const lineHeight = 14;
    let page = pdfDoc.addPage([pageWidth, pageHeight]);
    let y = pageHeight - margin;

    const safeText = (value) => {
      if (value === undefined || value === null || value === "") return "Not provided";
      if (typeof value === "boolean") return value ? "Yes" : "No";
      if (Array.isArray(value)) return value.length ? value.map(safeText).join("; ") : "None";
      if (typeof value === "object") return Object.entries(value).map(([k,v]) => `${k}: ${safeText(v)}`).join("; ");
      return String(value);
    };

    const wrap = (text, max = 92) => {
      const words = String(text || "").split(/\s+/);
      const lines = [];
      let line = "";
      for (const word of words) {
        const next = line ? `${line} ${word}` : word;
        if (next.length > max && line) { lines.push(line); line = word; }
        else line = next;
      }
      if (line) lines.push(line);
      return lines.length ? lines : [""];
    };

    const ensureSpace = (needed = lineHeight) => {
      if (y - needed < margin) {
        page = pdfDoc.addPage([pageWidth, pageHeight]);
        y = pageHeight - margin;
      }
    };

    const drawLine = (text, { bold = false, size = 10, gap = lineHeight } = {}) => {
      for (const line of wrap(text)) {
        ensureSpace(gap);
        page.drawText(line, { x: margin, y, size, font: bold ? boldFont : regularFont });
        y -= gap;
      }
    };

    const drawField = (label, value) => {
      ensureSpace(lineHeight * 2);
      drawLine(label, { bold: true, size: 10 });
      drawLine(safeText(value), { size: 10 });
      y -= 3;
    };

    drawLine("HOUSING DETAILS FORM", { bold: true, size: 18, gap: 24 });
    drawLine(`Candidate: ${[form.firstName, form.middleName, form.lastName].filter(Boolean).join(" ")}`, { bold: true });
    drawLine(`Email: ${email}`);
    drawLine(`Submitted: ${submittedAt.toISOString()}`);
    y -= 10;

    const sections = [
      ["Candidate Information", ["dateCompleted","firstName","middleName","lastName","dateOfBirth","email","currentPhone"]],
      ["Current Address", ["currentAddress","city","state","zipCode","country","ownOrRent","monthlyMortgageRent","lengthAtAddress","numBedrooms","numBathrooms"]],
      ["Housing Preferences", ["housingPreference","hasPets","petType","petWeight","petAge","petColor","petBreed","petName","petGender","petSpayedNeutered","smokes"]],
      ["Driving and Vehicle Information", ["hasDriversLicense","licenseIssued","licenseExpiry","whoWillDrive","usingIAS","vehiclePurchaseDate"]],
      ["Employment", ["employerName","employerCity","employerState","annualSalary"]],
      ["Emergency Contact", ["emergencyName","emergencyRelationship","emergencyStreet","emergencyCity","emergencyState","emergencyCountry","emergencyZip","emergencyEmail","emergencyPhone"]],
      ["Co-signer", ["cosignerName","cosignerRelationship","cosignerStreet","cosignerCity","cosignerState","cosignerCountry","cosignerZip","cosignerEmail","cosignerPhone"]],
      ["Consent and Waivers", ["consentFullName","consentDate","consentSignature","waiverHousing","waiverConcierge"]]
    ];

    for (const [heading, fields] of sections) {
      ensureSpace(30);
      drawLine(heading, { bold: true, size: 13, gap: 19 });
      for (const field of fields) drawField(field.replace(/([a-z])([A-Z])/g, "$1 $2"), form[field]);
    }

    drawLine("Dependents", { bold: true, size: 13, gap: 19 });
    const dependents = Array.isArray(form.dependents) ? form.dependents : [];
    if (!dependents.length) drawLine("None listed");
    dependents.forEach((dependent, index) => drawField(`Dependent ${index + 1}`, dependent));

    const pdfBuffer = Buffer.from(await pdfDoc.save());
    const safeEmail = email.replace(/[^a-z0-9]+/gi, "_");
    const filename = `Housing_Form_${safeEmail}_${Date.now()}.pdf`;

    let crm = { success: false, skipped: false };
    const recruit = { success: false, skipped: true, reason: "Housing is stored in CRM only" };

    try {
      crm = await uploadBufferToCrmDeal({
        email,
        buffer: pdfBuffer,
        filename,
        mimetype: "application/pdf"
      });
    } catch (error) {
      crm = { success: false, error: error.message };
    }

    if (!crm.success || crm.verified !== true || !crm.attachment_id) {
      return res.status(502).json({
        success: false,
        error: "The housing form upload could not be verified in CRM Deal attachments.",
        crm,
        recruit
      });
    }

    await logVerifiedDocument({
      email,
      name: filename,
      type: "Housing Form",
      size: pdfBuffer.length,
      mimetype: "application/pdf",
      crm,
      recruit
    });

    if (mongoConnected) {
      await mongoose.connection.db.collection("housing_forms").updateOne(
        { candidate_email: email },
        {
          $set: {
            candidate_email: email,
            form_data: form,
            pdf_filename: filename,
            crm_attachment_id: crm.attachment_id || null,
            crm_deal_id: crm.record_id || null,
            crm_deal_name: crm.record_name || null,
            crm_file_name: crm.file_name || filename,
            crm_verified: crm.verified === true,
            crm_upload_api_version: crm.upload_api_version || null,
            crm_verify_api_version: crm.verify_api_version || null,
            recruit_attachment_id: null,
            destinations: {
              crm: crm.success === true && crm.verified === true,
              recruit: false
            },
            submitted_at: submittedAt,
            updated_at: submittedAt
          },
          $setOnInsert: { created_at: submittedAt }
        },
        { upsert: true }
      );
    }

    const stageName = "Submit Housing Form";
    const stage = await PipelineStage.findOneAndUpdate(
      { candidate_email: email, stage_name: stageName, is_deleted: { $ne: true } },
      {
        $set: {
          status: "Completed",
          completed_date: submittedAt,
          completed_at: submittedAt,
          timing_status: "Good Standing",
          updated_at: submittedAt,
          completion_source: "candidate_housing_form"
        },
        $setOnInsert: {
          candidate_email: email,
          stage_name: stageName,
          stage_category: "Deployment",
          stage_order: 30,
          created_at: submittedAt,
          is_deleted: false
        }
      },
      { new: true, upsert: true, setDefaultsOnInsert: true }
    );

    const nextStage = await PipelineStage.findOne({
      candidate_email: email,
      is_deleted: { $ne: true },
      stage_order: { $gt: Number(stage.stage_order || 30) }
    }).sort({ stage_order: 1 });

    if (nextStage && nextStage.status !== "Completed") {
      const durationHours = Math.max(0, Number(nextStage.duration_hours || 0));
      await PipelineStage.updateOne(
        { _id: nextStage._id },
        {
          $set: {
            started_at: submittedAt,
            target_date: durationHours > 0
              ? new Date(submittedAt.getTime() + durationHours * 60 * 60 * 1000)
              : null,
            timing_status: "Good Standing",
            updated_at: submittedAt
          }
        }
      );
    }

    invalidateCandidateDetailsCache(email);

    return res.json({
      success: true,
      message: "Housing form submitted and verified in CRM Deal attachments",
      filename,
      crmDealId: crm.record_id,
      crmDealName: crm.record_name || null,
      crmAttachmentId: crm.attachment_id,
      crmAttachmentName: crm.file_name || filename,
      attachments: { crm, recruit },
      stage
    });
  } catch (error) {
    console.error("[Housing] Submission failed:", error.response?.data || error);
    return res.status(500).json({
      success: false,
      error: error.response?.data?.message || error.message || "Failed to submit housing form"
    });
  }
});


// Returns the live CRM Deal attachment list for the signed-in candidate.
// This is useful for confirming exactly which Deal contains generated forms.
app.get("/api/crm/my-deal-attachments", authenticateToken, async (req, res) => {
  try {
    const email = String(
      req.userEmail || ""
    ).trim().toLowerCase();

    if (!email) {
      return res.status(400).json({
        success: false,
        error: "Candidate email is required"
      });
    }

    const deals = await searchDealsByEmail(email);
    if (!deals?.length) {
      return res.status(404).json({
        success: false,
        error: `No matching CRM Deal found for ${email}`
      });
    }

    const token = await getValidZohoToken();
    const results = [];

    for (const deal of deals) {
      if (!deal?.id) continue;

      let attachments = [];
      let apiVersion = null;

      for (const version of ["v3", "v2"]) {
        try {
          attachments = await fetchCrmDealAttachments({
            token,
            dealId: deal.id,
            apiVersion: version
          });
          apiVersion = version;
          break;
        } catch (error) {
          console.warn(
            `[CRM Attachment Diagnostic] ${version} failed for Deal ${deal.id}:`,
            error.response?.data || error.message
          );
        }
      }

      results.push({
        deal_id: deal.id,
        deal_name:
          deal.Deal_Name ||
          deal.Deal_Name1 ||
          deal.Candidate_Name ||
          deal.Name ||
          null,
        modified_time: deal.Modified_Time || null,
        api_version: apiVersion,
        attachments: attachments.map((attachment) => ({
          id: getCrmAttachmentId(attachment),
          file_name: getCrmAttachmentName(attachment),
          created_time:
            attachment.Created_Time ||
            attachment.created_time ||
            null,
          raw: attachment
        }))
      });
    }

    return res.json({
      success: true,
      email,
      deals: results
    });
  } catch (error) {
    console.error(
      "[CRM Attachment Diagnostic] Failed:",
      error.response?.data || error
    );

    return res.status(error.response?.status || 500).json({
      success: false,
      error:
        error.response?.data?.data?.[0]?.message ||
        error.response?.data?.message ||
        error.message ||
        "Unable to load CRM Deal attachments"
    });
  }
});

