app.post("/api/recruit/upload-document", authenticateToken, upload.single('file'), async (req, res) => {
  try {
    console.log("[Recruit Upload] === START ===");
    console.log("[Recruit Upload] User:", req.userEmail);

    const file = req.file;
    const { document_name, document_type } = req.body;

    if (!file) {
      return res.status(400).json({ success: false, error: "No file uploaded" });
    }
    if (!document_name) {
      return res.status(400).json({ success: false, error: "Document name required" });
    }
    if (file.size > 10 * 1024 * 1024) {
      return res.status(400).json({ success: false, error: "File size must be under 10MB" });
    }

    const candidates = await searchRecruitCandidatesByEmail(req.userEmail);
    if (!candidates || candidates.length === 0) {
      return res.status(404).json({ success: false, error: "No candidate found in Recruit" });
    }

    const latestCandidate = candidates.sort((a, b) => new Date(b.Created_Time || 0) - new Date(a.Created_Time || 0))[0];
    const candidateId = latestCandidate.id;

    const accessToken = await getValidZohoToken();
    
    const categoryMap = {
      "Resume": "Resume",
      "Formatted Resume": "Formatted Resume",
      "Cover Letter": "Cover Letter",
      "Offer Letter": "Offer",
      "Contract": "Contracts",
      "Passport": "Others",
      "NCLEX": "Others",
      "Birth Certificate": "Others",
      "Government ID": "Others",
      "License": "Others",
      "Certificate": "Others",
      "Transcript": "Others",
      "Diploma": "Others",
      "Visa": "Others",
      "Housing": "Others",
      "Reimbursement": "Others",
      "Other": "Others"
    };
    
    const category = categoryMap[document_type] || "Others";

    const formData = new FormData();
    formData.append("file", file.buffer, {
      filename: file.originalname,
      contentType: file.mimetype,
      knownLength: file.size
    });

    const uploadUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments?attachments_category=${encodeURIComponent(category)}`;

    const uploadResponse = await axios.post(
      uploadUrl,
      formData,
      {
        headers: {
          Authorization: `Zoho-oauthtoken ${accessToken}`,
          ...formData.getHeaders()
        },
        maxBodyLength: Infinity,
        maxContentLength: Infinity,
        timeout: 60000
      }
    );

    let attachmentId = null;
    const data = uploadResponse.data;

    if (data?.data && Array.isArray(data.data)) {
      for (const item of data.data) {
        if (item?.id) { attachmentId = item.id; break; }
      }
    }

    if (!attachmentId && data?.id) {
      attachmentId = data.id;
    }

    if (attachmentId) {
      invalidateCandidateDetailsCache(req.userEmail);

      if (mongoConnected) {
        try {
          const db = mongoose.connection.db;
          const collection = db.collection('recruit_documents');
          await collection.insertOne({
            attachment_id: attachmentId,
            document_name: document_name,
            document_type: document_type || "Document",
            document_category: category,
            candidate_email: req.userEmail,
            candidate_id: candidateId,
            status: "Uploaded",
            uploaded_at: new Date(),
            file_size: file.size,
            file_type: file.mimetype,
            original_name: file.originalname,
            destination: "recruit"
          });
        } catch (e) {
          console.error("[Recruit Upload] MongoDB log failed (non-critical):", e.message);
        }
      }

      return res.json({
        success: true,
        message: "Document uploaded to Recruit successfully",
        attachment_id: attachmentId,
        candidate_id: candidateId,
        destination: "recruit",
        category: category,
        document_name: document_name
      });
    }

    return res.json({
      success: true,
      message: "File uploaded to Recruit",
      candidate_id: candidateId,
      warning: "Attachment ID not found - check Recruit manually"
    });

  } catch (error) {
    console.error("[Recruit Upload] Error:", error.message);
    res.status(500).json({
      success: false,
      error: "Failed to upload to Recruit",
      details: error.response?.data || error.message
    });
  }
});

app.post("/api/documents/upload-to-concierge", authenticateToken, upload.single('file'), async (req, res) => {
  try {
    const file = req.file;
    const { document_name } = req.body;

    if (!file) {
      return res.status(400).json({ success: false, error: "No file uploaded" });
    }
    if (!document_name) {
      return res.status(400).json({ success: false, error: "Document name required" });
    }
    if (file.mimetype !== "application/pdf") {
      return res.status(400).json({ success: false, error: "Only PDF files are accepted" });
    }
    if (file.size > 10 * 1024 * 1024) {
      return res.status(400).json({ success: false, error: "File size must be under 10MB" });
    }

    const userDeals = await searchDealsByEmail(req.userEmail);
    if (!userDeals || userDeals.length === 0) {
      return res.status(404).json({ success: false, error: "No deal found for this user" });
    }

    const latestDeal = userDeals.sort((a, b) => new Date(b.Created_Time || 0) - new Date(a.Created_Time || 0))[0];
    const dealId = latestDeal.id;

    const accessToken = await getValidZohoToken();

    const formData = new FormData();
    formData.append("file", file.buffer, {
      filename: file.originalname,
      contentType: file.mimetype,
      knownLength: file.size
    });

    const uploadResponse = await axios.post(
      `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments`,
      formData,
      {
        headers: {
          Authorization: `Zoho-oauthtoken ${accessToken}`,
          ...formData.getHeaders()
        },
        maxBodyLength: Infinity,
        maxContentLength: Infinity,
        timeout: 60000
      }
    );

    const attachmentId =
      uploadResponse.data?.data?.[0]?.details?.id ||
      uploadResponse.data?.data?.[0]?.id ||
      uploadResponse.data?.id;

    if (!attachmentId) {
      throw new Error("Zoho did not return an attachment ID");
    }

    await axios.put(
      `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}`,
      { data: [{ id: dealId, Concierge_biography: attachmentId }] },
      {
        headers: {
          Authorization: `Zoho-oauthtoken ${accessToken}`,
          "Content-Type": "application/json"
        },
        timeout: 30000
      }
    );

    invalidateCandidateDetailsCache(req.userEmail);

    if (mongoConnected) {
      try {
        await Documents.create({
          attachment_id: attachmentId,
          document_name: document_name,
          document_type: "Concierge Biography",
          candidate_email: req.userEmail,
          status: "Uploaded",
          uploaded_at: new Date(),
          file_size: file.size,
          file_type: file.mimetype,
          deal_id: dealId,
          destination: "crm"
        });
      } catch (e) {
        console.error("[CRM Upload] MongoDB log failed (non-critical):", e.message);
      }
    }

    res.json({
      success: true,
      message: "Document uploaded to Zoho CRM successfully",
      attachment_id: attachmentId,
      deal_id: dealId,
      destination: "crm",
      document_name: document_name
    });

  } catch (error) {
    console.error("[CRM Upload] Error:", error.response?.data || error.message);
    res.status(500).json({
      success: false,
      error: error.response?.data?.message || error.message || "Upload failed"
    });
  }
});
