app.get("/api/documents/all", authenticateToken, async (req, res) => {
  try {
    const email = req.userEmail;
    console.log(`[Documents] Fetching all documents for: ${email}`);
    
    const allDocuments = [];
    let recruitConnected = false;
    let crmConnected = false;
    let crmMethods = [];
    
    // 1. Fetch Recruit Documents
    try {
      console.log('[Documents] Fetching Recruit documents...');
      const candidates = await searchRecruitCandidatesByEmail(email);
      
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        const accessToken = await getValidZohoToken();
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments`;
        
        const response = await axios.get(recruitUrl, {
          headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
          timeout: 30000
        });
        
        const attachments = response.data?.data || [];
        console.log(`[Documents] Found ${attachments.length} Recruit attachments`);
        
        for (const att of attachments) {
          allDocuments.push({
            id: att.id,
            attachment_id: att.id,
            document_name: att.File_Name || att.name || `Recruit Document ${att.id}`,
            source: "recruit",
            sourceLabel: "Zoho Recruit",
            sourceIcon: "📊",
            sourceColor: "bg-blue-100 text-blue-700 border-blue-200",
            uploaded_at: att.Created_Time || att.created_at || new Date().toISOString(),
            file_size: att.Size || 0,
            file_type: att.File_Type || "application/pdf",
            candidate_id: candidateId,
            module: "Candidates",
            status: "Available"
          });
        }
        recruitConnected = attachments.length > 0 || true;
      }
    } catch (recruitError) {
      console.error('[Documents] Recruit error:', recruitError.message);
    }
    
    // 2. Fetch CRM Documents using enhanced method
    try {
      console.log('[Documents] Fetching CRM documents...');
      
      // Use the enhanced CRM fetch
      const crmResponse = await fetch(`${req.protocol}://${req.get('host')}/api/documents/crm-documents`, {
        headers: {
          Authorization: req.headers.authorization
        }
      });
      
      if (crmResponse.ok) {
        const crmData = await crmResponse.json();
        if (crmData.success && crmData.documents) {
          allDocuments.push(...crmData.documents);
          crmConnected = crmData.documents.length > 0 || true;
          crmMethods = crmData.methods_used || [];
          console.log(`[Documents] Added ${crmData.documents.length} CRM documents`);
        }
      } else {
        // If the enhanced endpoint fails, try the simplified version
        console.log('[Documents] Enhanced CRM failed, trying simplified...');
        
        const simpleResponse = await fetch(`${req.protocol}://${req.get('host')}/api/documents/crm-documents`, {
          headers: {
            Authorization: req.headers.authorization
          }
        });
        
        if (simpleResponse.ok) {
          const simpleData = await simpleResponse.json();
          if (simpleData.success && simpleData.documents) {
            allDocuments.push(...simpleData.documents);
            crmConnected = simpleData.documents.length > 0 || true;
            console.log(`[Documents] Added ${simpleData.documents.length} CRM documents (simplified)`);
          }
        }
      }
    } catch (crmError) {
      console.error('[Documents] CRM error:', crmError.message);
      
      // Final fallback: check MongoDB directly
      if (mongoConnected) {
        try {
          const docs = await Documents.find({
            candidate_email: email
          }).sort({ uploaded_at: -1 });
          
          if (docs.length > 0) {
            console.log(`[Documents] Found ${docs.length} CRM documents in MongoDB`);
            for (const doc of docs) {
              allDocuments.push({
                ...doc.toObject(),
                id: doc._id,
                attachment_id: doc.attachment_id || doc.id,
                document_name: doc.document_name || `CRM Document ${doc._id}`,
                source: "crm",
                sourceLabel: "CRM - MongoDB",
                sourceIcon: "📤",
                sourceColor: "bg-green-100 text-green-700 border-green-200",
                uploaded_at: doc.uploaded_at || new Date().toISOString(),
                status: doc.status || "Available",
                from_mongodb: true
              });
            }
            crmConnected = true;
          }
        } catch (mongoError) {
          console.error('[Documents] MongoDB fallback error:', mongoError.message);
        }
      }
    }
    
    // Deduplicate by attachment_id
    const seen = new Set();
    const uniqueDocs = allDocuments.filter(doc => {
      const key = doc.attachment_id || doc.id;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
    
    console.log(`[Documents] Total: ${uniqueDocs.length} (Recruit: ${uniqueDocs.filter(d => d.source === 'recruit').length}, CRM: ${uniqueDocs.filter(d => d.source === 'crm').length})`);
    
    res.json({
      success: true,
      documents: uniqueDocs,
      total: uniqueDocs.length,
      sources: {
        recruit: uniqueDocs.filter(d => d.source === "recruit").length,
        crm: uniqueDocs.filter(d => d.source === "crm").length
      },
      connected: {
        recruit: recruitConnected,
        crm: crmConnected
      },
      crm_methods: crmMethods
    });
    
  } catch (error) {
    console.error('[Documents] Error:', error);
    res.status(500).json({
      success: false,
      error: error.message || "Failed to fetch documents"
    });
  }
});
/**
 * Enhanced document download that works for both Recruit and CRM
 
 */

app.get(
  "/api/documents/download/:documentId",
  optionalAdminOrUserAuth,
  async (req, res) => {
  const { documentId } = req.params;
  const { source } = req.query; // 'recruit' or 'crm'
  
  try {
    console.log(`[Download] Fetching document ${documentId} from ${source || 'auto'} for ${req.userEmail}`);
    
    const accessToken = await getValidZohoToken();
    const email =
      req.isAdmin
        ? await resolveCanonicalPipelineEmail(
            req.query.email
          )
        : await resolveCanonicalPipelineEmail(
            req.userEmail
          );
    
    // If source is specified, try that first
    if (source === 'recruit') {
      // Try Recruit
      const candidates = await searchRecruitCandidatesByEmail(email);
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments/${documentId}`;
        
        const response = await axios({
          method: "GET",
          url: recruitUrl,
          headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
          responseType: "arraybuffer",
          timeout: 30000
        });
        
        if (response.status === 200 && response.data && response.data.length > 0) {
          const buffer = Buffer.from(response.data);
          const contentType = response.headers["content-type"] || "application/octet-stream";
          const fileName = documentId;
          return sendDocumentResponse(res, req, buffer, contentType, fileName, true);
        }
      }
    } else if (source === 'crm') {
      // streamDocumentFromZoho tries CRM file-upload fields first and ordinary
      // record attachments next, so both document types work through one URL.
      const userDeals = await searchDealsByEmail(email);
      if (userDeals && userDeals.length > 0) {
        const latestDeal = userDeals.sort((a, b) =>
          new Date(b.Modified_Time || b.Created_Time || 0) - new Date(a.Modified_Time || a.Created_Time || 0)
        )[0];
        const file = await streamDocumentFromZoho("Deals", latestDeal.id, documentId);
        if (file) {
          return sendDocumentResponse(res, req, file.buffer, file.contentType, file.fileName, true);
        }
      }
    }
    
    // Auto-detect: Try both
    // Try Recruit first
    try {
      const candidates = await searchRecruitCandidatesByEmail(email);
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments/${documentId}`;
        const response = await axios({
          method: "GET",
          url: recruitUrl,
          headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
          responseType: "arraybuffer",
          timeout: 30000
        });
        
        if (response.status === 200 && response.data && response.data.length > 0) {
          const buffer = Buffer.from(response.data);
          const contentType = response.headers["content-type"] || "application/octet-stream";
          const fileName = documentId;
          return sendDocumentResponse(res, req, buffer, contentType, fileName, true);
        }
      }
    } catch (e) {
      console.log("[Download] Recruit not found, trying CRM");
    }
    
    // Try CRM
    try {
      const userDeals = await searchDealsByEmail(email);
      if (userDeals && userDeals.length > 0) {
        const dealId = userDeals[0].id;
        const crmUrl = `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments/${documentId}`;
        const response = await axios({
          method: "GET",
          url: crmUrl,
          headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
          responseType: "arraybuffer",
          timeout: 30000
        });
        
        if (response.status === 200 && response.data && response.data.length > 0) {
          const buffer = Buffer.from(response.data);
          const contentType = response.headers["content-type"] || "application/octet-stream";
          const fileName = documentId;
          return sendDocumentResponse(res, req, buffer, contentType, fileName, true);
        }
      }
    } catch (e) {
      console.log("[Download] CRM not found");
    }
    
    return res.status(404).json({ 
      success: false, 
      error: "Document not found in Recruit or CRM" 
    });
    
  } catch (error) {
    console.error("[Download] Error:", error);
    if (!res.headersSent) {
      res.status(500).json({ 
        success: false, 
        error: error.message || "Failed to download document" 
      });
    }
  }
});

app.get("/api/documents/preview", authenticateToken, async (req, res) => {
  try {
    const key =
      String(
        req.query.key ||
        ""
      ).trim();

    if (!key) {
      return res.status(400).json({
        success: false,
        error:
          "Document key is required."
      });
    }

    const documents =
      await collectCandidateDocuments(
        req.userEmail
      );

    const document =
      documents.find(item =>
        buildDocumentApprovalKey(item) === key ||
        String(item.approval_key || "") === key
      );

    if (!document) {
      return res.status(404).json({
        success: false,
        error:
          "Document was not found."
      });
    }

    if (
      String(
        document.source
      )
        .toLowerCase() ===
      "pending"
    ) {
      if (
        !mongoConnected ||
        !mongoose.connection?.db ||
        !mongoose.Types.ObjectId.isValid(
          String(
            document.pending_upload_id ||
            document.attachment_id ||
            ""
          )
        )
      ) {
        return res.status(404).json({
          success:
            false,
          error:
            "Pending document content is unavailable."
        });
      }

      const pending =
        await mongoose.connection.db
          .collection(
            "pending_recruit_document_uploads"
          )
          .findOne({
            _id:
              new mongoose.Types.ObjectId(
                String(
                  document.pending_upload_id ||
                  document.attachment_id
                )
              ),
            candidate_email:
              normalizePipelineEmail(
                req.userEmail
              )
          });

      if (
        !pending?.file_base64
      ) {
        return res.status(404).json({
          success:
            false,
          error:
            "Pending document content is no longer available."
        });
      }

      return sendDocumentResponse(
        res,
        req,
        Buffer.from(
          pending.file_base64,
          "base64"
        ),
        pending.file_type ||
          "application/octet-stream",
        pending.document_name ||
          pending.original_name ||
          "Recruiting Document",
        true
      );
    }

    const token =
      await getValidZohoToken();

    if (
      String(document.source).toLowerCase() ===
      "recruit"
    ) {
      const candidate =
        await resolveRecruitCandidateRecordForAttachments(
          req.userEmail,
          {
            preferredCandidateId:
              document.candidate_id ||
              document.recruit_record_id ||
              null,
            forceRefresh: false
          }
        );

      const candidateId =
        candidate?.id ||
        null;

      if (
        !candidateId ||
        !document.attachment_id
      ) {
        return res.status(404).json({
          success: false,
          error:
            "Recruit attachment identifiers are unavailable."
        });
      }

      const response =
        await axios({
          method: "GET",
          url:
            `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments/${document.attachment_id}`,
          headers: {
            Authorization:
              `Zoho-oauthtoken ${token}`
          },
          responseType:
            "arraybuffer",
          timeout:
            30000
        });

      return sendDocumentResponse(
        res,
        req,
        Buffer.from(response.data),
        response.headers["content-type"] ||
          document.file_type ||
          "application/octet-stream",
        document.document_name,
        true
      );
    }

    if (
      String(document.source).toLowerCase() ===
      "crm"
    ) {
      const dealId =
        document.deal_id ||
        document.crm_record_id ||
        document.crm_deal_id;

      const attachmentId =
        document.attachment_id ||
        document.crm_attachment_id ||
        document.id;

      if (
        !dealId ||
        !attachmentId
      ) {
        const legacyAttachmentId =
          document.recruit_attachment_id ||
          document.attachment_id ||
          document.id ||
          null;

        if (legacyAttachmentId) {
          const candidate =
            await resolveRecruitCandidateRecordForAttachments(
              req.userEmail,
              {
                preferredCandidateId:
                  document.recruit_record_id ||
                  document.candidate_id ||
                  null,
                forceRefresh: false
              }
            );

          if (candidate?.id) {
            try {
              const recruitResponse =
                await axios({
                  method: "GET",
                  url:
                    `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidate.id}/Attachments/${legacyAttachmentId}`,
                  headers: {
                    Authorization:
                      `Zoho-oauthtoken ${token}`
                  },
                  responseType:
                    "arraybuffer",
                  timeout:
                    30000
                });

              return sendDocumentResponse(
                res,
                req,
                Buffer.from(
                  recruitResponse.data
                ),
                recruitResponse.headers[
                  "content-type"
                ] ||
                  document.file_type ||
                  "application/octet-stream",
                document.document_name ||
                  "Recruit Document",
                true
              );
            } catch {
              // Not a Recruit attachment either.
            }
          }
        }

        return res.status(404).json({
          success: false,
          error:
            "This older document no longer has a valid Zoho attachment reference."
        });
      }

      if (
        document.crm_file_upload_field === true ||
        document.crm_field_api_name
      ) {
        const response =
          await axios({
            method: "GET",
            url:
              `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/actions/download_fields_attachment`,
            params: {
              fields_attachment_id:
                attachmentId
            },
            headers: {
              Authorization:
                `Zoho-oauthtoken ${token}`
            },
            responseType:
              "arraybuffer",
            timeout:
              30000
          });

        return sendDocumentResponse(
          res,
          req,
          Buffer.from(response.data),
          response.headers["content-type"] ||
            document.file_type ||
            "application/octet-stream",
          document.document_name ||
            "CRM Document",
          true
        );
      }

      const file =
        await streamDocumentFromZoho(
          "Deals",
          dealId,
          attachmentId
        );

      if (!file) {
        return res.status(404).json({
          success: false,
          error:
            "CRM document content could not be loaded."
        });
      }

      return sendDocumentResponse(
        res,
        req,
        file.buffer,
        file.contentType,
        file.fileName ||
          document.document_name,
        true
      );
    }

    return res.status(404).json({
      success: false,
      error:
        "Unsupported document source."
    });
  } catch (error) {
    console.error(
      "[Documents Preview]",
      error
    );

    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});

/**
 * Get document stats from both sources
 */
app.get("/api/documents/stats", authenticateToken, async (req, res) => {
  try {
    const email = req.userEmail;
    console.log(`[Stats] Fetching document stats for: ${email}`);
    
    let recruitCount = 0;
    let crmCount = 0;
    const accessToken = await getValidZohoToken();
    
    // Recruit count
    try {
      const candidates = await searchRecruitCandidatesByEmail(email);
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments`;
        const responseData =
          await cachedZohoJsonGet(
            recruitUrl,
            {
              headers: {
                Authorization:
                  `Zoho-oauthtoken ${accessToken}`
              },
              ttlMs:
                RECRUIT_STATIC_CACHE_TTL_MS
            }
          );

        recruitCount =
          responseData?.data
            ?.length ||
          0;
      }
    } catch (e) {
      console.log("[Stats] Recruit count error:", e.message);
    }
    
    // CRM count
    try {
      const userDeals = await searchDealsByEmail(email);
      if (userDeals && userDeals.length > 0) {
        const dealId = userDeals[0].id;
        const crmUrl = `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments`;
        const responseData =
          await cachedZohoJsonGet(
            crmUrl,
            {
              headers: {
                Authorization:
                  `Zoho-oauthtoken ${accessToken}`
              },
              ttlMs:
                ZOHO_STATIC_CACHE_TTL_MS
            }
          );

        crmCount =
          responseData?.data
            ?.length ||
          0;
      }
    } catch (e) {
      console.log("[Stats] CRM count error:", e.message);
    }
    
    res.json({
      success: true,
      stats: {
        total: recruitCount + crmCount,
        recruit: recruitCount,
        crm: crmCount,
        byStatus: { "Available": recruitCount + crmCount },
        byCategory: { "General": recruitCount + crmCount }
      }
    });
    
  } catch (error) {
    console.error("[Stats] Error:", error);
    res.status(500).json({ success: false, error: error.message });
  }
});
app.get("/api/recruit/documents", authenticateToken, async (req, res) => {
  try {
    if (!mongoConnected) {
      return res.json({ success: true, documents: [] });
    }

    const db = mongoose.connection.db;
    const collection = db.collection('recruit_documents');
    
    const documents = await collection
      .find({ candidate_email: req.userEmail })
      .sort({ uploaded_at: -1 })
      .toArray();

    res.json({
      success: true,
      documents: documents.map(doc => ({
        id: doc._id,
        attachment_id: doc.attachment_id,
        document_name: doc.document_name,
        document_type: doc.document_type,
        document_category: doc.document_category,
        status: doc.status,
        uploaded_at: doc.uploaded_at,
        file_size: doc.file_size,
        file_type: doc.file_type,
        original_name: doc.original_name
      }))
    });
  } catch (error) {
    console.error("[Recruit Docs] Error:", error.message);
    res.status(500).json({ success: false, error: error.message });
  }
});

app.get(
  "/api/documents/library",
  authenticateToken,
  async (req, res) => {
    try {
      const email =
        normalizePipelineEmail(
          req.userEmail
        );

      const documents =
        await collectCandidateDocuments(
          email
        );

      const libraryUploads =
        mongoConnected &&
        mongoose.connection?.db
          ? await mongoose.connection.db
              .collection(
                "document_library_uploads"
              )
              .find({
                candidate_email:
                  email
              })
              .sort({
                uploaded_at: -1
              })
              .toArray()
          : [];

      const uploadByAttachment =
        new Map();

      const uploadByName =
        new Map();

      for (
        const upload of
        libraryUploads
      ) {
        for (
          const attachmentId of
          [
            upload.crm_attachment_id,
            upload.recruit_attachment_id
          ].filter(Boolean)
        ) {
          uploadByAttachment.set(
            String(attachmentId),
            upload
          );
        }

        const normalizedName =
          String(
            upload.document_name ||
            ""
          )
            .trim()
            .toLowerCase();

        if (normalizedName) {
          uploadByName.set(
            normalizedName,
            upload
          );
        }
      }

      const normalized =
        documents.map(
          document => {
            const upload =
              uploadByAttachment.get(
                String(
                  document.attachment_id ||
                  document.id ||
                  ""
                )
              ) ||
              uploadByName.get(
                String(
                  document.document_name ||
                  document.name ||
                  ""
                )
                  .trim()
                  .toLowerCase()
              );

            const category =
              upload
                ? DOCUMENT_LIBRARY_CATEGORIES.find(
                    item =>
                      item.key ===
                      upload.category_key
                  )
                : inferDocumentLibraryCategory(
                    document
                  );

            return {
              ...document,
              document_category:
                category?.key ||
                "other",
              category_label:
                category?.label ||
                "Other Document",
              library_section:
                category?.section ||
                "Other",
              library_section_order:
                DOCUMENT_LIBRARY_SECTION_ORDER.indexOf(
                  category?.section ||
                  "Other"
                ),
              document_order:
                category?.order ||
                999,
              default_destination:
                category?.defaultDestination ||
                "crm",
              requirement_key:
                category?.requirementKey ||
                null,
              pipeline_stage:
                category?.pipelineStage ||
                null,
              crm_field_api_name:
                document.crm_field_api_name ||
                category?.crmFieldApiName ||
                null,
              candidate_uploaded:
                upload
                  ?.uploaded_by_candidate ===
                true,
              uploaded_via:
                upload?.uploaded_via ||
                null,
              source:
                document.source ||
                (
                  upload?.destination ===
                    "recruit"
                    ? "recruit"
                    : upload?.destination ===
                        "crm"
                      ? "crm"
                      : document.source
                ),
              attachment_id:
                document.attachment_id ||
                (
                  document.source ===
                    "recruit"
                    ? upload?.recruit_attachment_id
                    : upload?.crm_attachment_id
                ) ||
                upload?.recruit_attachment_id ||
                upload?.crm_attachment_id ||
                document.id,
              candidate_id:
                document.candidate_id ||
                upload?.recruit_record_id ||
                null,
              deal_id:
                document.deal_id ||
                upload?.crm_record_id ||
                null,
              crm_record_id:
                document.crm_record_id ||
                upload?.crm_record_id ||
                null,
              recruit_record_id:
                document.recruit_record_id ||
                upload?.recruit_record_id ||
                null,
              pending_upload_id:
                document.pending_upload_id ||
                upload?.pending_upload_id ||
                null,
              approval_status:
                upload?.approval_status ||
                document.approval_status ||
                "pending",
              already_approved:
                upload?.approval_status ===
                  "approved" ||
                document.already_approved ===
                  true,
              approval_exempt:
                upload?.approval_exempt ===
                  true ||
                document.approval_exempt ===
                  true,
              rejection_reason:
                upload?.rejection_reason ||
                document.rejection_reason ||
                null
            };
          }
        )
        .sort(
          (a, b) =>
            Number(
              a.library_section_order ??
              999
            ) -
              Number(
                b.library_section_order ??
                999
              ) ||
            Number(
              a.document_order ??
              999
            ) -
              Number(
                b.document_order ??
                999
              ) ||
            new Date(
              b.uploaded_at ||
              0
            ) -
              new Date(
                a.uploaded_at ||
                0
              )
        );

      const normalizedAttachmentIds =
        new Set(
          normalized
            .map(document =>
              String(
                document.attachment_id ||
                document.id ||
                ""
              )
            )
            .filter(Boolean)
        );

      const normalizedNames =
        new Set(
          normalized
            .map(document =>
              String(
                document.document_name ||
                ""
              )
                .trim()
                .toLowerCase()
            )
            .filter(Boolean)
        );

      for (
        const upload of
        libraryUploads
      ) {
        const category =
          DOCUMENT_LIBRARY_CATEGORIES.find(
            item =>
              item.key ===
              upload.category_key
          ) ||
          inferDocumentLibraryCategory(
            upload
          );

        const attachmentId =
          upload.recruit_attachment_id ||
          upload.crm_attachment_id ||
          upload.pending_upload_id ||
          "";

        const normalizedName =
          String(
            upload.document_name ||
            ""
          )
            .trim()
            .toLowerCase();

        if (
          (
            attachmentId &&
            normalizedAttachmentIds.has(
              String(attachmentId)
            )
          ) ||
          (
            normalizedName &&
            normalizedNames.has(
              normalizedName
            )
          )
        ) {
          continue;
        }

        if (
          !attachmentId &&
          upload.pending_storage !== true
        ) {
          continue;
        }

        normalized.push({
          id:
            String(
              attachmentId ||
              upload._id
            ),
          attachment_id:
            String(
              attachmentId ||
              upload._id
            ),
          document_name:
            upload.document_name ||
            "Document",
          document_type:
            upload.document_type ||
            category?.label ||
            "Document",
          document_category:
            category?.key ||
            upload.category_key ||
            "other",
          category_label:
            category?.label ||
            "Other Document",
          library_section:
            category?.section ||
            "Other",
          library_section_order:
            DOCUMENT_LIBRARY_SECTION_ORDER.indexOf(
              category?.section ||
              "Other"
            ),
          document_order:
            category?.order ||
            999,
          default_destination:
            category?.defaultDestination ||
            upload.destination ||
            "crm",
          requirement_key:
            category?.requirementKey ||
            upload.requirement_key ||
            null,
          pipeline_stage:
            category?.pipelineStage ||
            upload.pipeline_stage ||
            null,
          crm_field_api_name:
            category?.crmFieldApiName ||
            upload.crm_field_api_name ||
            null,
          source:
            upload.pending_storage === true
              ? "pending"
              : (
                  upload.recruit_attachment_id ||
                  upload.recruit_record_id
                )
                ? "recruit"
                : "crm",
          candidate_uploaded:
            upload.uploaded_by_candidate ===
              true,
          uploaded_via:
            upload.uploaded_via ||
            null,
          uploaded_at:
            upload.uploaded_at ||
            upload.created_at ||
            null,
          file_type:
            upload.file_type ||
            "application/pdf",
          file_size:
            upload.file_size ||
            0,
          candidate_id:
            upload.recruit_record_id ||
            null,
          recruit_record_id:
            upload.recruit_record_id ||
            null,
          deal_id:
            upload.crm_record_id ||
            upload.crm_deal_id ||
            null,
          crm_record_id:
            upload.crm_record_id ||
            upload.crm_deal_id ||
            null,
          crm_deal_id:
            upload.crm_record_id ||
            upload.crm_deal_id ||
            null,
          pending_upload_id:
            upload.pending_upload_id ||
            null,
          approval_status:
            upload.approval_exempt === true
              ? "approved"
              : (
                  upload.approval_status ||
                  "pending"
                ),
          already_approved:
            upload.approval_exempt === true ||
            upload.approval_status ===
              "approved",
          approval_exempt:
            upload.approval_exempt ===
              true,
          rejection_reason:
            upload.rejection_reason ||
            null,
          survey_submission:
            upload.survey_submission ===
              true,
          survey_stage_name:
            upload.survey_stage_name ||
            null,
          visible_in_library:
            upload.visible_in_library ===
              true
        });

        if (attachmentId) {
          normalizedAttachmentIds.add(
            String(attachmentId)
          );
        }

        if (normalizedName) {
          normalizedNames.add(
            normalizedName
          );
        }
      }

      normalized.sort(
        (a, b) =>
          Number(
            a.library_section_order ??
            999
          ) -
            Number(
              b.library_section_order ??
              999
            ) ||
          Number(
            a.document_order ??
            999
          ) -
            Number(
              b.document_order ??
              999
            ) ||
          new Date(
            b.uploaded_at ||
            0
          ) -
            new Date(
              a.uploaded_at ||
              0
            )
      );

      const approvedDocuments =
        normalized.filter(
          document =>
            document.already_approved ===
              true ||
            document.approval_status ===
              "approved" ||
            document.approval_status ===
              "rejected" ||
            document.approval_exempt ===
              true ||
            document.candidate_uploaded ===
              true ||
            document.visible_in_library ===
              true ||
            document.survey_submission ===
              true
        );

      const sections =
        DOCUMENT_LIBRARY_SECTION_ORDER.map((section, sectionIndex) => ({
          section,
          section_order: sectionIndex,
          required_document_types: DOCUMENT_LIBRARY_CATEGORIES
            .filter(category => category.section === section)
            .sort((a, b) => Number(a.order || 999) - Number(b.order || 999)),
          documents: approvedDocuments
            .filter(document => document.library_section === section)
            .sort((a, b) => Number(a.document_order || 999) - Number(b.document_order || 999) || new Date(b.uploaded_at || 0) - new Date(a.uploaded_at || 0))
        }));

      return res.json({
        success: true,
        documents:
          approvedDocuments,
        total:
          approvedDocuments.length,
        sections,
        categories:
          DOCUMENT_LIBRARY_CATEGORIES,
        pending_count:
          normalized.filter(
            document =>
              document.approval_status ===
              "pending"
          ).length,
        rejected_count:
          normalized.filter(
            document =>
              document.approval_status ===
              "rejected"
          ).length
      });
    } catch (error) {
      console.error(
        "[Document Library]",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message ||
          "Unable to load document library"
      });
    }
  }
);

