app.get("/api/documents/view/:documentId", authenticateToken, async (req, res) => {
  try {
    const documentId =
      String(
        req.params.documentId ||
        ""
      ).trim();

    const email =
      await resolveCanonicalPipelineEmail(
        req.userEmail
      );

    const requestedSource =
      String(
        req.query?.source ||
        ""
      )
        .trim()
        .toLowerCase();

    const candidateId =
      String(
        req.query?.candidateId ||
        req.query?.recruitRecordId ||
        ""
      ).trim();

    const dealId =
      String(
        req.query?.dealId ||
        req.query?.crmRecordId ||
        ""
      ).trim();

    const crmField =
      String(
        req.query?.field ||
        ""
      ).trim();

    const fieldUpload =
      String(
        req.query?.fieldUpload ||
        ""
      )
        .trim()
        .toLowerCase() ===
      "true";

    if (!documentId) {
      return res.status(400).json({
        success: false,
        error:
          "Document ID is required."
      });
    }

    const token =
      await getValidZohoToken();

    const readRecruit =
      async () => {
        let resolvedCandidateId =
          candidateId;

        if (!resolvedCandidateId) {
          const candidates =
            await searchRecruitCandidatesByEmail(
              email
            );

          resolvedCandidateId =
            candidates?.[0]?.id ||
            "";
        }

        if (!resolvedCandidateId) {
          throw new Error(
            "Recruit candidate identifier is unavailable."
          );
        }

        return axios({
          method: "GET",
          url:
            `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${resolvedCandidateId}/Attachments/${documentId}`,
          headers: {
            Authorization:
              `Zoho-oauthtoken ${token}`
          },
          responseType:
            "arraybuffer",
          timeout:
            30000
        });
      };

    const readCrm =
      async () => {
        let resolvedDealId =
          dealId;

        if (!resolvedDealId) {
          const deals =
            await searchDealsByEmail(
              email
            );

          resolvedDealId =
            deals?.[0]?.id ||
            "";
        }

        if (!resolvedDealId) {
          throw new Error(
            "CRM Deal identifier is unavailable."
          );
        }

        if (
          fieldUpload ||
          crmField
        ) {
          return axios({
            method: "GET",
            url:
              `${ZOHO_CRM_URL}/crm/v3/Deals/${resolvedDealId}/actions/download_fields_attachment`,
            params: {
              fields_attachment_id:
                documentId
            },
            headers: {
              Authorization:
                `Zoho-oauthtoken ${token}`
            },
            responseType:
              "arraybuffer",
            timeout:
              30000
          });
        }

        return axios({
          method: "GET",
          url:
            `${ZOHO_CRM_URL}/crm/v3/Deals/${resolvedDealId}/Attachments/${documentId}`,
          headers: {
            Authorization:
              `Zoho-oauthtoken ${token}`
          },
          responseType:
            "arraybuffer",
          timeout:
            30000
        });
      };

    let response = null;

    if (requestedSource === "recruit") {
      response =
        await readRecruit();
    } else if (requestedSource === "crm") {
      response =
        await readCrm();
    } else {
      try {
        response =
          await readRecruit();
      } catch {
        response =
          await readCrm();
      }
    }

    return sendDocumentResponse(
      res,
      req,
      Buffer.from(
        response.data
      ),
      response.headers[
        "content-type"
      ] ||
        "application/octet-stream",
      String(
        req.query?.name ||
        `document-${documentId}`
      ),
      true
    );
  } catch (error) {
    console.error(
      "[Candidate Document View]",
      error
    );

    return res.status(
      error.response?.status === 404
        ? 404
        : 500
    ).json({
      success: false,
      error:
        error.response?.data?.message ||
        error.message ||
        "Unable to load document."
    });
  }
});

app.get("/api/admin/documents/download/:documentId", adminAuth, async (req, res) => {
  try {
    const documentId =
      String(req.params.documentId || "").trim();

    const email =
      normalizePipelineEmail(
        req.query?.email || ""
      );

    const requestedSource =
      String(
        req.query?.source || ""
      )
        .trim()
        .toLowerCase();

    const crmRecordId =
      String(
        req.query?.crmRecordId ||
        req.query?.dealId ||
        ""
      ).trim();

    const recruitRecordId =
      String(
        req.query?.recruitRecordId ||
        req.query?.candidateId ||
        ""
      ).trim();

    const crmField =
      String(
        req.query?.field || ""
      ).trim();

    const fieldUpload =
      String(
        req.query?.fieldUpload || ""
      )
        .trim()
        .toLowerCase() ===
      "true";

    if (!documentId || !email) {
      return res.status(400).json({
        success: false,
        error:
          "Document ID and candidate email are required."
      });
    }

    if (
      requestedSource ===
      "pending"
    ) {
      if (
        !mongoConnected ||
        !mongoose.connection?.db ||
        !mongoose.Types.ObjectId.isValid(
          documentId
        )
      ) {
        return res.status(404).json({
          success:
            false,
          error:
            "Pending document content is unavailable."
        });
      }

      const pending =
        await mongoose.connection.db
          .collection(
            "pending_recruit_document_uploads"
          )
          .findOne({
            _id:
              new mongoose.Types.ObjectId(
                documentId
              ),
            candidate_email:
              email
          });

      if (
        !pending?.file_base64
      ) {
        return res.status(404).json({
          success:
            false,
          error:
            "Pending document content is no longer available."
        });
      }

      return sendDocumentResponse(
        res,
        req,
        Buffer.from(
          pending.file_base64,
          "base64"
        ),
        pending.file_type ||
          "application/octet-stream",
        pending.document_name ||
          pending.original_name ||
          "Recruiting Document",
        true
      );
    }

    const token =
      await getValidZohoToken();

    const tryRecruit = async () => {
      const candidate =
        await resolveRecruitCandidateRecordForAttachments(
          email,
          {
            preferredCandidateId:
              recruitRecordId ||
              null,
            forceRefresh: false
          }
        );

      const candidateId =
        candidate?.id ||
        "";

      if (!candidateId) {
        throw new Error(
          "Recruit candidate identifier is unavailable."
        );
      }

      return axios({
        method: "GET",
        url:
          `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments/${documentId}`,
        headers: {
          Authorization:
            `Zoho-oauthtoken ${token}`
        },
        responseType:
          "arraybuffer",
        timeout:
          30000
      });
    };

    const tryCrm = async () => {
      let dealId =
        crmRecordId;

      if (!dealId) {
        const deals =
          await searchDealsByEmail(
            email
          );
        dealId =
          deals?.[0]?.id ||
          "";
      }

      if (!dealId) {
        throw new Error(
          "CRM Deal identifier is unavailable."
        );
      }

      if (
        fieldUpload ||
        crmField
      ) {
        return axios({
          method: "GET",
          url:
            `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/actions/download_fields_attachment`,
          params: {
            fields_attachment_id:
              documentId
          },
          headers: {
            Authorization:
              `Zoho-oauthtoken ${token}`
          },
          responseType:
            "arraybuffer",
          timeout:
            30000
        });
      }

      return axios({
        method: "GET",
        url:
          `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments/${documentId}`,
        headers: {
          Authorization:
            `Zoho-oauthtoken ${token}`
        },
        responseType:
          "arraybuffer",
        timeout:
          30000
      });
    };

    let response = null;
    let source = requestedSource;

    if (requestedSource === "recruit") {
      response = await tryRecruit();
    } else if (requestedSource === "crm") {
      response = await tryCrm();
    } else {
      try {
        response = await tryRecruit();
        source = "recruit";
      } catch {
        response = await tryCrm();
        source = "crm";
      }
    }

    return sendDocumentResponse(
      res,
      req,
      Buffer.from(response.data),
      response.headers["content-type"] ||
        "application/octet-stream",
      String(
        req.query?.name ||
        `document-${documentId}`
      ),
      true
    );
  } catch (error) {
    console.error(
      "[Admin Document Download]",
      error
    );

    return res.status(
      error.response?.status === 404
        ? 404
        : 500
    ).json({
      success: false,
      error:
        error.response?.data?.message ||
        error.message ||
        "Unable to load document."
    });
  }
});

app.get("/api/documents/download/:documentId", authenticateToken, async (req, res) => {
  const { documentId } = req.params;
  
  try {
    console.log("[Download] Fetching document:", documentId, "for user:", req.userEmail);
    
    const accessToken = await getValidZohoToken();

    // Try Recruit first
    try {
      const candidates = await searchRecruitCandidatesByEmail(req.userEmail);
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        const recruitUrl = `${ZOHO_RECRUIT_URL}/recruit/v2/Candidates/${candidateId}/Attachments/${documentId}`;
        
        const response = await axios({
          method: "GET",
          url: recruitUrl,
          headers: {
            Authorization: `Zoho-oauthtoken ${accessToken}`
          },
          responseType: "arraybuffer",
          timeout: 30000
        });

        if (response.status === 200 && response.data && response.data.length > 0) {
          const buffer = Buffer.from(response.data);
          const contentType = response.headers["content-type"] || "application/octet-stream";
          const fileName = documentId;
          return sendDocumentResponse(res, req, buffer, contentType, fileName, true);
        }
      }
    } catch (recruitError) {
      console.log("[Download] Recruit download failed, trying CRM:", recruitError.message);
    }

    // Try CRM
    try {
      const userDeals = await searchDealsByEmail(req.userEmail);
      if (userDeals && userDeals.length > 0) {
        const dealId = userDeals[0].id;
        const crmUrl = `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments/${documentId}`;
        
        const response = await axios({
          method: "GET",
          url: crmUrl,
          headers: {
            Authorization: `Zoho-oauthtoken ${accessToken}`
          },
          responseType: "arraybuffer",
          timeout: 30000
        });

        if (response.status === 200 && response.data && response.data.length > 0) {
          const buffer = Buffer.from(response.data);
          const contentType = response.headers["content-type"] || "application/octet-stream";
          const fileName = documentId;
          return sendDocumentResponse(res, req, buffer, contentType, fileName, true);
        }
      }
    } catch (crmError) {
      console.log("[Download] CRM download failed:", crmError.message);
    }

    return res.status(404).json({ success: false, error: "Document not found in Recruit or CRM" });

  } catch (error) {
    console.error("[Download] Error:", error.message);
    if (!res.headersSent) {
      res.status(500).json({ 
        success: false, 
        error: error.response?.data?.message || error.message || "Failed to download document" 
      });
    }
  }
});

app.get("/api/documents/stats", authenticateToken, async (req, res) => {
  try {
    console.log("[Stats] Fetching document stats for:", req.userEmail);
    
    let recruitCount = 0;
    let crmCount = 0;

    try {
      const candidates = await searchRecruitCandidatesByEmail(req.userEmail);
      if (candidates && candidates.length > 0) {
        const candidateId = candidates[0].id;
        const responseData =
          await makeZohoRecruitApiRequest(
            `/recruit/v2/Candidates/${candidateId}/Attachments`,
            {
              cacheTtlMs:
                RECRUIT_STATIC_CACHE_TTL_MS
            }
          );
        recruitCount =
          responseData?.data?.length ||
          0;
      }
    } catch (e) {
      console.log("[Stats] Recruit count error:", e.message);
    }

    try {
      const userDeals = await searchDealsByEmail(req.userEmail);
      if (userDeals && userDeals.length > 0) {
        const dealId = userDeals[0].id;
        const accessToken = await getValidZohoToken();
        const listUrl = `${ZOHO_CRM_URL}/crm/v3/Deals/${dealId}/Attachments`;
        const response = await axios.get(listUrl, {
          headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
          timeout: 30000
        });
        crmCount = response.data?.data?.length || 0;
      }
    } catch (e) {
      console.log("[Stats] CRM count error:", e.message);
    }

    res.json({
      success: true,
      stats: {
        total: recruitCount + crmCount,
        recruit: recruitCount,
        crm: crmCount,
        byStatus: { "Available": recruitCount + crmCount },
        byCategory: { "General": recruitCount + crmCount }
      }
    });
  } catch (error) {
    console.error("[Stats] Error:", error.message);
    res.status(500).json({ success: false, error: error.message });
  }
});

app.get("/api/recruit/valid-categories", authenticateToken, async (req, res) => {
  try {
    const accessToken = await getValidZohoToken();
    
    try {
      const responseData =
        await makeZohoRecruitApiRequest(
          "/recruit/v2/settings/fields",
          {
            params: {
              module:
                "Candidates",
              field:
                "Attachments"
            },
            cacheTtlMs:
              RECRUIT_STATIC_CACHE_TTL_MS
          }
        );

      let categories = [];
      if (responseData?.fields) {
        for (const field of responseData.fields) {
          if (field.api_name === "Attachments" && field.pick_list_values) {
            categories = field.pick_list_values.map(v => v.display_value || v.value);
            break;
          }
        }
      }
      
      if (categories.length > 0) {
        return res.json({ success: true, categories });
      }
    } catch (error) {
      console.warn("[Categories] Could not fetch from API, using defaults:", error.message);
    }
    
    const fallbackCategories = ["Resume", "Cover Letter", "Other", "Reference", "Offer Letter", "Contract"];
    return res.json({ success: true, categories: fallbackCategories });
    
  } catch (error) {
    console.error("[Categories] Error:", error.message);
    res.status(500).json({ 
      success: false, 
      error: error.message,
      categories: ["Resume", "Cover Letter", "Other", "Reference", "Offer Letter", "Contract"]
    });
  }
});

