app.post("/api/chat/local", authenticateToken, (req, res) => {
  try {
    const { message, userName, candidateData } = req.body;
    if (!message || typeof message!=="string") return res.status(400).json({ success:false, error:"Invalid message" });
    res.json({ success:true, reply:generateChatResponse(message.trim(), userName, candidateData) });
  } catch (e) { res.status(500).json({ success:false, error:"Failed to generate response" }); }
});

app.post("/api/chat/message", authenticateToken, async (req, res) => {
  const { message } = req.body;
  if (!message) return res.status(400).json({ success:false, error:"Message required" });
  try {
    const token = req.authToken;
    if (!chatHistory.has(token)) chatHistory.set(token, []);
    const h = chatHistory.get(token);
    h.push({ id:Date.now().toString(), role:"user", content:message, timestamp:new Date().toISOString() });
    const botResponse = generateChatResponse(message, req.userEmail.split("@")[0]);
    h.push({ id:(Date.now()+1).toString(), role:"bot", content:botResponse, timestamp:new Date().toISOString() });
    if (h.length > 50) chatHistory.set(token, h.slice(-50));
    res.json({ success:true, response:botResponse, timestamp:new Date().toISOString() });
  } catch (e) { res.status(500).json({ success:false, error:"Failed to process message" }); }
});

