// ─── MESSAGING USER DISPLAY NAMES ────────────────────────────────────────────
// Messaging may call this for every recipient in a broadcast. Do not perform
// one Zoho CRM/Recruit request per recipient; resolve from Mongo/local data
// first and fall back to the email prefix.
async function getUserName(identifier) {
  try {
    const raw =
      String(
        identifier ||
        ""
      ).trim();

    if (!raw) {
      return "User";
    }

    if (
      raw.toLowerCase() ===
        "admin" ||
      raw.toLowerCase() ===
        "system" ||
      raw.toLowerCase() ===
        "admin@infinitycarepartners.com"
    ) {
      return raw
        .toLowerCase()
        .startsWith("system")
          ? "System"
          : "Admin";
    }

    const email =
      normalizePipelineEmail(
        raw
      );

    if (
      mongoConnected &&
      UserAuth &&
      email
    ) {
      const user =
        await UserAuth.findOne(
          {
            email
          },
          {
            candidateName: 1,
            name: 1,
            firstName: 1,
            lastName: 1,
            email: 1
          }
        )
          .lean()
          .catch(
            () => null
          );

      const storedName =
        String(
          user?.candidateName ||
          user?.name ||
          [
            user?.firstName,
            user?.lastName
          ]
            .filter(Boolean)
            .join(" ") ||
          ""
        ).trim();

      if (storedName) {
        return storedName.split(/\s+/)[0];
      }
    }

    const cachedDetails = candidateDetailsCache.get(email)?.data || candidateDetailsCache.get(email) || null;
    const cachedUser = cachedDetails?.user || cachedDetails || {};
    const sourceFirstName = String(
      cachedUser.firstName || cachedUser.First_Name || cachedUser.Candidate_First_Name || ""
    ).trim();
    if (sourceFirstName) return sourceFirstName.split(/\s+/)[0];

    const sourceFullName = String(
      cachedUser.candidateName || cachedUser.Full_Name || ""
    ).trim();
    if (sourceFullName) return sourceFullName.split(/\s+/)[0];

    return email
      ? email.split("@")[0]
      : raw;
  } catch (error) {
    console.warn(
      "[Messaging] getUserName fallback:",
      error.message
    );

    const raw =
      String(
        identifier ||
        "User"
      ).trim();

    return raw.includes("@")
      ? raw.split("@")[0]
      : raw || "User";
  }
}

