app.post("/api/admin/messaging/send", adminAuth, async (req, res) => {
  try {
    const recipientEmail = normalizePipelineEmail(req.body.recipientEmail);
    const content = String(req.body.content || "").trim();
    if (!recipientEmail || !content) return res.status(400).json({ success:false, error:"Recipient email and message are required" });

    let conversation = await Conversation.findOne({ type:"direct", participants:{ $all:["admin",recipientEmail] }, isActive:{ $ne:false } });
    if (!conversation) {
      conversation = await Conversation.create({
        participants:["admin",recipientEmail],
        // Mongoose Maps become MongoDB object keys. Email addresses can contain
        // dots, which MongoDB does not permit in field names, so do not use the
        // recipient email as a participantNames map key.
        participantNames: new Map([["admin", "Admin"]]),
        type:"direct", createdBy:"admin", lastMessageAt:new Date()
      });
      await ConversationParticipant.updateOne({ conversationId:conversation._id, email:"admin" }, { $set:{ isAdmin:true, joinedAt:new Date() } }, { upsert:true });
      await ConversationParticipant.updateOne({ conversationId:conversation._id, email:recipientEmail }, { $set:{ joinedAt:new Date() } }, { upsert:true });
    }

    const message = await Message.create({
      conversationId:conversation._id, senderEmail:"admin", senderName:"Admin",
      content, messageType:"text", isRead:false, createdAt:new Date()
    });
    conversation.lastMessage=message._id; conversation.lastMessageAt=message.createdAt; await conversation.save();
    broadcastToUsers([recipientEmail], { type:"new_message", conversationId:String(conversation._id), message:message.toObject ? message.toObject() : message });
    return res.json({ success:true, conversation, message });
  } catch (error) { return res.status(500).json({ success:false, error:error.message }); }
});

app.post("/api/admin/messaging/broadcast", adminAuth, async (req, res) => {
  const content =
    String(
      req.body.content ||
      ""
    ).trim();

  if (!content) {
    return res.status(400).json({
      success:false,
      error:"Message is required"
    });
  }

  try {
    const conversation =
      await getOrCreateCommunityConversation();

    const message =
      await Message.create({
        conversationId:
          conversation._id,
        senderEmail:
          "admin",
        senderName:
          "Admin",
        content,
        messageType:
          "text",
        broadcast:
          true,
        isRead:
          false,
        createdAt:
          new Date()
      });

    conversation.lastMessage =
      message._id;
    conversation.lastMessageAt =
      message.createdAt;
    conversation.updatedAt =
      new Date();

    await conversation.save();

    const recipients =
      (conversation.participants || [])
        .filter(
          participant =>
            participant !==
              "admin" &&
            Boolean(
              normalizePipelineEmail(
                participant
              )
            )
        );

    broadcastToUsers(
      recipients,
      {
        type:
          "new_message",
        conversationId:
          CANDIDATE_COMMUNITY_CONVERSATION_ID,
        message: {
          ...(
            message.toObject
              ? message.toObject()
              : message
          ),
          conversationId:
            CANDIDATE_COMMUNITY_CONVERSATION_ID,
          broadcast:
            true
        }
      }
    );

    return res.json({
      success:true,
      conversation:{
        _id:
          CANDIDATE_COMMUNITY_CONVERSATION_ID,
        type:
          "community",
        groupName:
          "Community Messages"
      },
      message,
      recipientCount:
        recipients.length
    });
  } catch (error) {
    return res.status(500).json({
      success:false,
      error:error.message
    });
  }
});


