// Browser admin login.
// The HTML admin form at "/" posts to /admin/login, while the React/API
// clients use /api/admin/login or /api/admin/login-token. Keep all three.
app.post("/admin/login", async (req, res) => {
  const {
    username,
    password
  } = req.body || {};

  let isValid = false;

  if (db) {
    try {
      let snapshot =
        await db
          .collection("Users")
          .where(
            "user",
            "==",
            username
          )
          .where(
            "password",
            "==",
            password
          )
          .get();

      if (!snapshot.empty) {
        isValid = true;
      } else {
        const subSnap =
          await db
            .collectionGroup(
              "Users"
            )
            .where(
              "user",
              "==",
              username
            )
            .where(
              "password",
              "==",
              password
            )
            .get();

        if (
          !subSnap.empty
        ) {
          isValid = true;
        }
      }
    } catch (error) {
      console.error(
        "[Admin] Firestore browser login check failed:",
        error.message
      );
    }
  }

  // Preserve the existing local fallback exactly as the other admin routes do.
  if (
    !isValid &&
    username === "admin" &&
    password === "admin"
  ) {
    isValid = true;
  }

  if (!isValid) {
    return res.redirect(
      "/?error=1"
    );
  }

  setAdminCookie(req, res);

  return res.redirect(
    "/admin/dashboard"
  );
});

