function webhookNormalizeValue(value) {
  if (
    value === undefined ||
    value === null
  ) {
    return value;
  }

  if (Array.isArray(value)) {
    if (value.length === 1) {
      return webhookNormalizeValue(
        value[0]
      );
    }

    return value.map(
      webhookNormalizeValue
    );
  }

  if (
    typeof value === "object"
  ) {
    const preferred =
      value.value ??
      value.display_value ??
      value.displayValue ??
      value.name ??
      value.label ??
      value.selected ??
      value.checked ??
      value.date ??
      value.datetime ??
      value.Date ??
      value.DateTime;

    if (
      preferred !== undefined
    ) {
      return webhookNormalizeValue(
        preferred
      );
    }
  }

  return value;
}

function webhookHasValue(value) {
  const normalized =
    webhookNormalizeValue(
      value
    );

  if (
    normalized === undefined ||
    normalized === null
  ) {
    return false;
  }

  if (
    typeof normalized ===
    "boolean"
  ) {
    return true;
  }

  return (
    String(normalized)
      .trim() !== ""
  );
}

function webhookNormalizedText(value) {
  return String(
    webhookNormalizeValue(value) ??
    ""
  )
    .trim()
    .toLowerCase();
}

function webhookCheckboxComplete(value) {
  const normalized =
    webhookNormalizeValue(
      value
    );

  if (
    normalized === true ||
    normalized === 1
  ) {
    return true;
  }

  return [
    "true",
    "yes",
    "checked",
    "complete",
    "completed",
    "passed",
    "done",
    "1"
  ].includes(
    String(normalized ?? "")
      .trim()
      .toLowerCase()
  );
}

function webhookDateTodayOrPast(value) {
  const normalized =
    webhookNormalizeValue(
      value
    );

  if (!webhookHasValue(normalized)) {
    return false;
  }

  const parsed =
    new Date(normalized);

  if (
    Number.isNaN(
      parsed.getTime()
    )
  ) {
    return false;
  }

  const today =
    new Date();

  const targetDay =
    new Date(
      parsed.getFullYear(),
      parsed.getMonth(),
      parsed.getDate()
    );

  const currentDay =
    new Date(
      today.getFullYear(),
      today.getMonth(),
      today.getDate()
    );

  return (
    targetDay.getTime() <=
    currentDay.getTime()
  );
}

function webhookParseCount(value) {
  const normalized =
    String(
      webhookNormalizeValue(value) ??
      ""
    ).trim();

  if (!normalized) {
    return 0;
  }

  const parsed =
    Number.parseInt(
      normalized.replace(
        /[^0-9]/g,
        ""
      ),
      10
    );

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}

function webhookPicklistEquals(
  value,
  accepted = []
) {
  const normalized =
    webhookNormalizedText(value);

  return accepted
    .map(item =>
      String(item)
        .trim()
        .toLowerCase()
    )
    .includes(normalized);
}

function webhookPickFields(
  source,
  fields
) {
  const result = {};

  for (const field of fields) {
    if (
      source &&
      Object.prototype
        .hasOwnProperty.call(
          source,
          field
        )
    ) {
      result[field] =
        source[field];
    }
  }

  return result;
}

function flattenWebhookObject(
  value,
  target = {},
  depth = 0
) {
  if (
    depth > 5 ||
    value === null ||
    value === undefined
  ) {
    return target;
  }

  if (Array.isArray(value)) {
    value.forEach(item =>
      flattenWebhookObject(
        item,
        target,
        depth + 1
      )
    );

    return target;
  }

  if (
    typeof value !==
    "object"
  ) {
    return target;
  }

  for (
    const [key, item]
    of Object.entries(value)
  ) {
    if (
      item === null ||
      item === undefined ||
      typeof item !==
      "object"
    ) {
      target[key] = item;
      continue;
    }

    if (
      Array.isArray(item) &&
      item.every(entry =>
        entry === null ||
        entry === undefined ||
        typeof entry !==
        "object"
      )
    ) {
      target[key] = item;
      continue;
    }

    const preferred =
      webhookNormalizeValue(
        item
      );

    if (
      preferred !== item &&
      (
        preferred === null ||
        typeof preferred !==
        "object"
      )
    ) {
      target[key] =
        preferred;
    }

    flattenWebhookObject(
      item,
      target,
      depth + 1
    );
  }

  return target;
}

function readWebhookEmail(
  ...sources
) {
  const emailKeys = [
    "candidate_email",
    "Candidate_Email",
    "Candidate_Email_Address",
    "CandidateEmail",
    "Candidate email",
    "Email",
    "email"
  ];

  for (const source of sources) {
    if (!source) continue;

    const flattened =
      flattenWebhookObject(
        source,
        {}
      );

    for (const key of emailKeys) {
      const value =
        flattened[key];

      if (
        value &&
        String(value)
          .includes("@")
      ) {
        return normalizePipelineEmail(
          value
        );
      }
    }

    for (
      const [key, value]
      of Object.entries(
        flattened
      )
    ) {
      if (
        /email/i.test(key) &&
        value &&
        String(value)
          .includes("@")
      ) {
        return normalizePipelineEmail(
          value
        );
      }
    }
  }

  return "";
}

function webhookSecretsMatch(
  provided,
  expected
) {
  const a =
    Buffer.from(
      String(provided || "")
    );

  const b =
    Buffer.from(
      String(expected || "")
    );

  return (
    a.length > 0 &&
    a.length === b.length &&
    crypto.timingSafeEqual(
      a,
      b
    )
  );
}

function requireRecruitWebhookSecret(
  req
) {
  if (!ZOHO_WEBHOOK_SECRET) {
    return false;
  }

  const provided =
    req.get(
      "x-zoho-webhook-secret"
    ) ||
    req.query?.secret ||
    req.body?.secret ||
    "";

  return webhookSecretsMatch(
    provided,
    ZOHO_WEBHOOK_SECRET
  );
}

function requireCrmNotificationToken(
  body
) {
  if (
    !ZOHO_CRM_NOTIFICATION_TOKEN
  ) {
    return false;
  }

  return webhookSecretsMatch(
    body?.token,
    ZOHO_CRM_NOTIFICATION_TOKEN
  );
}

function getWebhookCollections() {
  if (
    !mongoConnected ||
    !mongoose.connection?.db
  ) {
    return null;
  }

  return {
    identities:
      mongoose.connection.db
        .collection(
          "zoho_record_candidate_map"
        ),
    snapshots:
      mongoose.connection.db
        .collection(
          "zoho_pipeline_webhook_snapshots"
        ),
    events:
      mongoose.connection.db
        .collection(
          "zoho_webhook_events"
        )
  };
}

async function rememberZohoWebhookIdentity({
  source,
  module,
  recordId,
  email
}) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  const normalizedRecordId =
    String(
      recordId || ""
    ).trim();

  if (
    !normalizedEmail ||
    !normalizedRecordId
  ) {
    return;
  }

  const collections =
    getWebhookCollections();

  if (!collections) return;

  await collections.identities
    .updateOne(
      {
        source:
          String(source || "")
            .toLowerCase(),
        module:
          String(module || ""),
        record_id:
          normalizedRecordId
      },
      {
        $set: {
          candidate_email:
            normalizedEmail,
          updated_at:
            new Date()
        },
        $setOnInsert: {
          created_at:
            new Date()
        }
      },
      {
        upsert: true
      }
    )
    .catch(error =>
      console.warn(
        "[Zoho Webhook] Could not persist record/email mapping:",
        error.message
      )
    );
}

async function lookupZohoWebhookEmail({
  source,
  module,
  recordId
}) {
  const collections =
    getWebhookCollections();

  if (!collections) return "";

  const row =
    await collections.identities
      .findOne({
        source:
          String(source || "")
            .toLowerCase(),
        module:
          String(module || ""),
        record_id:
          String(
            recordId || ""
          )
      })
      .catch(() => null);

  return normalizePipelineEmail(
    row?.candidate_email
  );
}

async function rememberWebhookSnapshot({
  email,
  source,
  module,
  recordId,
  fields
}) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  if (!normalizedEmail) {
    return;
  }

  const collections =
    getWebhookCollections();

  if (!collections) return;

  const safeSource =
    String(source || "")
      .toLowerCase();

  const safeModule =
    String(module || "")
      .replace(
        /[^a-zA-Z0-9_]/g,
        "_"
      );

  await collections.snapshots
    .updateOne(
      {
        candidate_email:
          normalizedEmail
      },
      {
        $set: {
          [
            `sources.${safeSource}.${safeModule}`
          ]:
            fields || {},
          updated_at:
            new Date()
        },
        $setOnInsert: {
          candidate_email:
            normalizedEmail,
          created_at:
            new Date()
        }
      },
      {
        upsert: true
      }
    )
    .catch(error =>
      console.warn(
        "[Zoho Webhook] Could not persist field snapshot:",
        error.message
      )
    );

  await rememberZohoWebhookIdentity({
    source:
      safeSource,
    module:
      module,
    recordId,
    email:
      normalizedEmail
  });
}

async function mergeWebhookSnapshot({
  email,
  source,
  module,
  recordId,
  changedFields
}) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  const collections =
    getWebhookCollections();

  if (
    !normalizedEmail ||
    !collections
  ) {
    return {
      ...(changedFields || {})
    };
  }

  const safeSource =
    String(source || "")
      .toLowerCase();

  const safeModule =
    String(module || "")
      .replace(
        /[^a-zA-Z0-9_]/g,
        "_"
      );

  const existing =
    await collections.snapshots
      .findOne({
        candidate_email:
          normalizedEmail
      })
      .catch(() => null);

  const previous =
    existing
      ?.sources
      ?.[safeSource]
      ?.[safeModule] ||
    {};

  const merged = {
    ...previous,
    ...(changedFields || {})
  };

  await rememberWebhookSnapshot({
    email:
      normalizedEmail,
    source:
      safeSource,
    module,
    recordId,
    fields:
      merged
  });

  return merged;
}

async function webhookEventIsNew(
  eventKey,
  metadata = {}
) {
  const collections =
    getWebhookCollections();

  if (!collections) {
    return true;
  }

  try {
    const result =
      await collections.events
        .updateOne(
          {
            event_key:
              eventKey
          },
          {
            $setOnInsert: {
              event_key:
                eventKey,
              ...metadata,
              created_at:
                new Date()
            }
          },
          {
            upsert: true
          }
        );

    return (
      result.upsertedCount ===
      1
    );
  } catch {
    return true;
  }
}

function removeZohoCacheEntriesForWebhook({
  email,
  recordIds = []
}) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  const fragments = [
    normalizedEmail,
    ...recordIds
      .filter(Boolean)
      .map(String)
  ]
    .filter(Boolean)
    .map(item =>
      item.toLowerCase()
    );

  const clearMatching = cache => {
    if (!cache?.entries) return;

    for (
      const [key]
      of cache.entries()
    ) {
      const normalizedKey =
        String(key)
          .toLowerCase();

      if (
        fragments.some(fragment =>
          normalizedKey.includes(
            fragment
          )
        )
      ) {
        cache.delete(key);
      }
    }
  };

  clearMatching(
    zohoReadCache
  );

  clearMatching(
    zohoSearchCache
  );

  if (normalizedEmail) {
    invalidateCandidateDetailsCache(
      normalizedEmail
    );

    userDetailsCache?.delete?.(
      normalizedEmail
    );

    recruitLiveRefreshAt.delete(
      normalizedEmail
    );

    pipelineLiveRefreshAt.delete(
      normalizedEmail
    );
  }
}

async function applyWebhookPipelineStage({
  email,
  stageName,
  completed,
  unlocked,
  sourceFields = [],
  sourceType = "crm",
  status = null
}) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  if (
    !normalizedEmail ||
    !stageName
  ) {
    return null;
  }

  let isCompleted =
    completed === true;

  if (
    stageName === "deployMate Ready" &&
    mongoConnected &&
    PipelineStage
  ) {
    const savedDeployMate = await PipelineStage.findOne({
      candidate_email: normalizedEmail,
      stage_name: "deployMate Ready",
      is_deleted: { $ne: true },
      $or: [
        { completed: true },
        { is_completed: true },
        { status: "Completed" },
        { completed_date: { $ne: null } }
      ]
    })
      .select({ _id: 1 })
      .lean()
      .catch(() => null);

    if (savedDeployMate) {
      isCompleted = true;
    }
  }

  // A refresh or temporarily missing Zoho value must never erase an already
  // completed candidate milestone. Explicit reset tools can be added separately.
  if (
    !isCompleted &&
    mongoConnected &&
    PipelineStage
  ) {
    const existingCompleted =
      await PipelineStage.findOne({
        candidate_email:
          normalizedEmail,
        stage_name:
          stageName,
        is_deleted: {
          $ne: true
        },
        $or: [
          { completed: true },
          { is_completed: true },
          { status: "Completed" },
          {
            completed_date: {
              $ne: null
            }
          }
        ]
      })
        .select({
          _id: 1
        })
        .lean()
        .catch(() => null);

    if (existingCompleted) {
      isCompleted = true;
    }
  }

  const isUnlocked =
    unlocked === undefined
      ? isCompleted
      : unlocked === true;

  const now =
    new Date();

  const finalStatus =
    status ||
    (
      isCompleted
        ? "Completed"
        : isUnlocked
          ? "In Progress"
          : "Not Started"
    );

  if (
    mongoConnected &&
    PipelineStage
  ) {
    await PipelineStage
      .updateMany(
        {
          candidate_email:
            normalizedEmail,
          stage_name:
            stageName,
          is_deleted: {
            $ne: true
          }
        },
        {
          $set: {
            status:
              finalStatus,
            completed:
              isCompleted,
            is_completed:
              isCompleted,
            completed_date:
              isCompleted
                ? now
                : null,
            source_trigger_fields:
              sourceFields,
            source_trigger_unlocked:
              isUnlocked,
            trigger_unlocked:
              isUnlocked,
            crm_unlocked:
              sourceType === "crm"
                ? isUnlocked
                : false,
            recruit_unlocked:
              sourceType === "recruit"
                ? isUnlocked
                : false,
            source_trigger_synced_at:
              now,
            updated_at:
              now
          }
        }
      )
      .catch(error =>
        console.warn(
          "[Zoho Webhook] Could not persist pipeline stage:",
          stageName,
          error.message
        )
      );
  }

  return {
    stage_name:
      stageName,
    completed:
      isCompleted,
    status:
      finalStatus,
    unlocked:
      isUnlocked,
    source_fields:
      sourceFields,
    completed_date:
      isCompleted
        ? now.toISOString()
        : null
  };
}

function patchWebhookFieldStatusCache({
  email,
  source,
  module,
  changedFields,
  stageStates
}) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  const entry =
    pipelineFieldStatusResponseCache
      .get(normalizedEmail);

  if (
    !entry?.payload
  ) {
    return;
  }

  const payload =
    entry.payload;

  payload.stageStatus =
    payload.stageStatus || {};

  payload.completionMap =
    payload.completionMap || {};

  payload.sectionGates =
    payload.sectionGates || {};

  if (
    source === "crm"
  ) {
    payload.deployment =
      payload.deployment || {};

    payload.immigration =
      payload.immigration || {};

    for (
      const [field, value]
      of Object.entries(
        changedFields || {}
      )
    ) {
      payload.deployment[field] =
        value;

      payload.immigration[field] =
        value;
    }
  } else {
    payload.recruit =
      payload.recruit || {};

    payload.nclex =
      payload.nclex || {};

    for (
      const [field, value]
      of Object.entries(
        changedFields || {}
      )
    ) {
      if (
        String(module)
          .toLowerCase() ===
        "custommodule1"
      ) {
        payload.nclex[field] =
          value;
      } else {
        payload.recruit[field] =
          value;
      }
    }
  }

  for (const state of stageStates) {
    if (!state) continue;

    payload.stageStatus[
      state.stage_name
    ] = {
      ...(
        payload.stageStatus[
          state.stage_name
        ] || {}
      ),
      evaluated:
        true,
      completed:
        state.completed,
      status:
        state.status,
      completed_date:
        state.completed_date,
      unlocked:
        state.unlocked,
      source_fields:
        state.source_fields
    };

    payload.completionMap[
      state.stage_name
    ] =
      state.completed;

    if (
      state.stage_name ===
      "Immigration forms submitted"
    ) {
      payload.sectionGates
        .immigration = {
          ...(
            payload.sectionGates
              .immigration ||
            {}
          ),
          unlocked:
            state.completed
        };
    }

    if (
      state.stage_name ===
      "Speciality Classes"
    ) {
      payload.sectionGates
        .deployment = {
          ...(
            payload.sectionGates
              .deployment ||
            {}
          ),
          unlocked:
            state.completed
        };
    }

    if (
      state.stage_name ===
      "Arrived"
    ) {
      payload.sectionGates
        .aftercare = {
          ...(
            payload.sectionGates
              .aftercare ||
            {}
          ),
          unlocked:
            state.completed
        };
    }
  }

  entry.fetchedAt =
    Date.now();

  entry.payload =
    payload;

  pipelineFieldStatusResponseCache
    .set(
      normalizedEmail,
      entry
    );
}

function webhookFoundationStates(
  fields,
  changedSet
) {
  const states = [];

  for (
    const [stageName, group]
    of Object.entries(
      WEBHOOK_FOUNDATION_GROUPS
    )
  ) {
    if (
      !group.some(field =>
        changedSet.has(field)
      )
    ) {
      continue;
    }

    const allKnown =
      group.every(field =>
        Object.prototype
          .hasOwnProperty.call(
            fields,
            field
          )
      );

    if (!allKnown) {
      continue;
    }

    states.push({
      stageName,
      completed:
        group.every(field =>
          webhookCheckboxComplete(
            fields[field]
          )
        ),
      sourceFields:
        group
    });
  }

  return states;
}


const AFTERCARE_SURVEY_STAGE_FIELDS = {
  "Relocation Survey": "Date_Relocation_Submitted",
  "U.S. Integration Call (30 Day Call / Survey)": "FY25_30_Day_Survey",
  "1 Year Survey": "Employment_Status_Date"
};

async function getAftercareSurveySubmissionMap(candidateEmail) {
  const email = normalizePipelineEmail(candidateEmail);

  if (!email || !mongoConnected || !mongoose.connection?.db) {
    return {};
  }

  const rows = await mongoose.connection.db
    .collection("aftercare_survey_submissions")
    .find({ candidate_email: email })
    .toArray();

  return Object.fromEntries(
    rows.map(row => [
      row.stage_name,
      row.submitted === true
    ])
  );
}

async function saveAftercareSurveySubmission(candidateEmail, stageName) {
  const email = normalizePipelineEmail(candidateEmail);
  const allowed = new Set(Object.keys(AFTERCARE_SURVEY_STAGE_FIELDS));

  if (!email || !mongoConnected || !mongoose.connection?.db) {
    throw new Error("Survey submission storage is unavailable.");
  }

  if (!allowed.has(stageName)) {
    throw new Error("Unsupported Aftercare survey stage.");
  }

  const now = new Date();

  await mongoose.connection.db
    .collection("aftercare_survey_submissions")
    .updateOne(
      {
        candidate_email: email,
        stage_name: stageName
      },
      {
        $set: {
          candidate_email: email,
          stage_name: stageName,
          submitted: true,
          submitted_at: now,
          updated_at: now
        },
        $setOnInsert: { created_at: now }
      },
      { upsert: true }
    );

  return now;
}

function computeWebhookCrmStages(
  fields,
  changedFields
) {
  const changedSet =
    new Set(
      Object.keys(
        changedFields || {}
      )
    );

  const states = [];

  const pushIfChanged = (
    stageName,
    sourceFields,
    completed,
    unlocked = undefined
  ) => {
    if (
      !sourceFields.some(field =>
        changedSet.has(field)
      )
    ) {
      return;
    }

    states.push({
      stageName,
      completed:
        completed === true,
      unlocked,
      sourceFields
    });
  };

  pushIfChanged(
    "Immigration forms submitted",
    [
      "Added_to_Weekly_I140_Candidates"
    ],
    webhookDateTodayOrPast(
      fields
        .Added_to_Weekly_I140_Candidates
    )
  );

  for (
    const foundation
    of webhookFoundationStates(
      fields,
      changedSet
    )
  ) {
    states.push(
      foundation
    );
  }

  pushIfChanged(
    "Immigration approved",
    ["Approval_datetime"],
    webhookDateTodayOrPast(
      fields.Approval_datetime
    )
  );

  pushIfChanged(
    "Visa bill issued",
    ["Visa_Fee_Bill"],
    [
      "received - ready to be paid",
      "paid"
    ].includes(
      webhookNormalizedText(
        fields.Visa_Fee_Bill
      )
    )
  );

  pushIfChanged(
    "Visa bill paid",
    ["Visa_Fee_Bill"],
    webhookNormalizedText(
      fields.Visa_Fee_Bill
    ) === "paid"
  );

  pushIfChanged(
    "DS-260 / Civil Document Submission",
    ["DS260_STATUS"],
    webhookNormalizedText(
      fields.DS260_STATUS
    ) ===
      "submitted to nvc"
  );

  pushIfChanged(
    "Documentarily Qualified",
    [
      "All_Clear_Documentary_Complete"
    ],
    webhookNormalizedText(
      fields
        .All_Clear_Documentary_Complete
    ) === "yes"
  );

  pushIfChanged(
    "Introduction to Deployment Call",
    [
      "Stage_3_Intro_Call"
    ],
    (() => {
      const raw =
        webhookNormalizeValue(
          fields.Stage_3_Intro_Call
        );

      if (
        raw === true ||
        [
          "yes",
          "complete",
          "completed",
          "done",
          "attended",
          "pass"
        ].includes(
          String(raw || "")
            .trim()
            .toLowerCase()
        )
      ) {
        return true;
      }

      return webhookDateTodayOrPast(raw);
    })()
  );

  pushIfChanged(
    "Speciality Classes",
    [
      "Hours_Recent_Bedside_Experience"
    ],
    webhookNormalizedText(
      fields
        .Hours_Recent_Bedside_Experience
    ) === "pass"
  );

  pushIfChanged(
    "Final Self Assessment",
    [
      "Self_Assessment_2_Complete"
    ],
    webhookDateTodayOrPast(
      fields
        .Self_Assessment_2_Complete
    )
  );

  pushIfChanged(
    "Speciality with Trainer Skills Check",
    [
      "Speciality_with_Trainer_Skills_Check"
    ],
    webhookCheckboxComplete(
      fields
        .Speciality_with_Trainer_Skills_Check
    )
  );

  pushIfChanged(
    "Housing / Transportation Call",
    [
      "Final_Housing_Confirmation_Call"
    ],
    webhookDateTodayOrPast(
      fields
        .Final_Housing_Confirmation_Call
    )
  );

  pushIfChanged(
    "Deployment Pre-Arrival Call",
    ["Deployment_Call"],
    webhookDateTodayOrPast(
      fields.Deployment_Call
    )
  );

  pushIfChanged(
    "Pre-Arrival Banking Call",
    [
      "Pre_Arrival_Banking_Call"
    ],
    webhookDateTodayOrPast(
      fields
        .Pre_Arrival_Banking_Call
    )
  );

  pushIfChanged(
    "Employer Pre-Arrival Call",
    ["Client_Arrival_Call"],
    webhookDateTodayOrPast(
      fields.Client_Arrival_Call
    )
  );

  pushIfChanged(
    "Receipt Submission",
    ["Advance_Agreement"],
    webhookHasValue(
      fields.Advance_Agreement
    )
  );

  pushIfChanged(
    "Arrived",
    ["Flight_Arrival_Time"],
    webhookDateTodayOrPast(
      fields.Flight_Arrival_Time
    )
  );

  pushIfChanged(
    "Welcome Call/24 Hour Call",
    ["Candidate_U_S_Welcome_Text_Call"],
    webhookHasValue(
      fields.Candidate_U_S_Welcome_Text_Call
    )
  );

  // Survey stages require BOTH the survey submission marker and CRM field.
  pushIfChanged(
    "Relocation Survey",
    ["Date_Relocation_Submitted"],
    false
  );

  pushIfChanged(
    "Concierge Debrief",
    ["Concierge_Debrief"],
    webhookDateTodayOrPast(
      fields.Concierge_Debrief
    )
  );

  pushIfChanged(
    "7 Day Call",
    ["Day_Call"],
    webhookDateTodayOrPast(
      fields.Day_Call
    )
  );

  pushIfChanged(
    "2 Week Call",
    ["Client_Post_Arrival_Survey_Due_90_Days"],
    webhookDateTodayOrPast(
      fields.Client_Post_Arrival_Survey_Due_90_Days
    )
  );

  pushIfChanged(
    "U.S. Integration Call (30 Day Call / Survey)",
    ["FY25_30_Day_Survey"],
    false
  );

  pushIfChanged(
    "Placement Stability Check-in (90 Day Call)",
    ["FY25_90_Day_Exit_Call"],
    webhookHasValue(
      fields.FY25_90_Day_Exit_Call
    )
  );

  pushIfChanged(
    "1 Year Survey",
    ["Employment_Status_Date"],
    false
  );

  return states;
}

function computeWebhookNclexStages(
  fields,
  changedFields
) {
  const changedSet =
    new Set(
      Object.keys(
        changedFields || {}
      )
    );

  const states = [];

  const assessments =
    webhookParseCount(
      fields.Assessments_Completed
    );

  const assignments =
    webhookParseCount(
      fields.Assignments_Completed
    );

  const ratingPass =
    [
      "high",
      "very high"
    ].includes(
      webhookNormalizedText(
        fields.Performance_Rating
      )
    );

  const gate = (
    assessmentsRequired,
    assignmentsRequired
  ) =>
    assessments >=
      assessmentsRequired &&
    assignments >=
      assignmentsRequired &&
    ratingPass;

  const pushIfAffected = (
    stageName,
    sourceFields,
    completed,
    unlocked = undefined
  ) => {
    if (
      !sourceFields.some(field =>
        changedSet.has(field)
      )
    ) {
      return;
    }

    states.push({
      stageName,
      completed:
        completed === true,
      unlocked,
      sourceFields
    });
  };

  pushIfAffected(
    "Pipeline Start",
    ["Date_Received"],
    webhookHasValue(
      fields.Date_Received
    )
  );

  pushIfAffected(
    "Complete Pre-assessment",
    ["NCLEX_Pre_Exam"],
    webhookPicklistEquals(
      fields.NCLEX_Pre_Exam,
      [
        "1st Attempt Pass",
        "2nd Attempt Pass"
      ]
    )
  );

  pushIfAffected(
    "Program Prescreen",
    ["Prescreen_Status"],
    webhookPicklistEquals(
      fields.Prescreen_Status,
      ["Attended"]
    )
  );

  pushIfAffected(
    "Document Review",
    ["Documents_Submitted"],
    webhookHasValue(
      fields.Documents_Submitted
    )
  );

  pushIfAffected(
    "Educational Program Agreement",
    ["Sponsorship_Agreement"],
    webhookCheckboxComplete(
      fields.Sponsorship_Agreement
    )
  );

  pushIfAffected(
    "Program Approval",
    ["Program_Status"],
    webhookPicklistEquals(
      fields.Program_Status,
      ["Approved"]
    )
  );

  pushIfAffected(
    "Credential Evaluation Set-up",
    ["Credential_Service"],
    webhookPicklistEquals(
      fields.Credential_Service,
      [
        "Paid by ICP",
        "Sponsored by ICP",
        "To be Sponsored by Infinity",
        "Paid by Infinity"
      ]
    )
  );

  pushIfAffected(
    "Credential Evaluation Completed",
    [
      "Credential_Registration_Date"
    ],
    webhookHasValue(
      fields
        .Credential_Registration_Date
    )
  );

  pushIfAffected(
    "CES Report Issued",
    ["Date_Report_Issued"],
    webhookHasValue(
      fields.Date_Report_Issued
    )
  );

  const boardRegistrationSources = [
    "State_License_Board_of_Registration",
    "Assessments_Completed",
    "Assignments_Completed",
    "Performance_Rating"
  ];

  pushIfAffected(
    "Board Registration",
    boardRegistrationSources,
    webhookPicklistEquals(
      fields
        .State_License_Board_of_Registration,
      [
        "Paid by ICP",
        "Sponsored by ICP",
        "To be Sponsored by Infinity",
        "Paid by Infinity"
      ]
    ),
    gate(2, 6)
  );

  const boardApprovalSources = [
    "Board_Username",
    "Assessments_Completed",
    "Assignments_Completed",
    "Performance_Rating"
  ];

  pushIfAffected(
    "Board Approval",
    boardApprovalSources,
    webhookHasValue(
      fields.Board_Username
    ),
    gate(4, 15)
  );

  pushIfAffected(
    "Pearson Vue Registration",
    ["Pearson_Vue_Status"],
    webhookNormalizedText(
      fields.Pearson_Vue_Status
    ) === "complete"
  );

  const attSources = [
    "ATT_Received_Date",
    "Assessments_Completed",
    "Assignments_Completed",
    "Performance_Rating"
  ];

  pushIfAffected(
    "ATT Received",
    attSources,
    webhookHasValue(
      fields.ATT_Received_Date
    ),
    gate(5, 0)
  );

  const examSources = [
    "NCLEX_Exam_Date",
    "Assessments_Completed",
    "Assignments_Completed",
    "Performance_Rating"
  ];

  pushIfAffected(
    "Exam Scheduled",
    examSources,
    webhookHasValue(
      fields.NCLEX_Exam_Date
    ),
    gate(6, 0)
  );

  pushIfAffected(
    "Exam Results",
    ["NCLEX_Status"],
    webhookPicklistEquals(
      fields.NCLEX_Status,
      ["Passed"]
    )
  );

  // Visible performance mini-boxes.
  if (
    [
      "Assessments_Completed",
      "Assignments_Completed",
      "Performance_Rating"
    ].some(field =>
      changedSet.has(field)
    )
  ) {
    states.push(
      {
        stageName:
          "Performance Check 1",
        completed:
          gate(2, 6),
        unlocked:
          gate(2, 6),
        sourceFields: [
          "Assessments_Completed",
          "Assignments_Completed",
          "Performance_Rating"
        ]
      },
      {
        stageName:
          "Performance Check 2",
        completed:
          gate(4, 15),
        unlocked:
          gate(4, 15),
        sourceFields: [
          "Assessments_Completed",
          "Assignments_Completed",
          "Performance_Rating"
        ]
      },
      {
        stageName:
          "Performance Check 3",
        completed:
          gate(5, 0),
        unlocked:
          gate(5, 0),
        sourceFields: [
          "Assessments_Completed",
          "Performance_Rating"
        ]
      },
      {
        stageName:
          "Performance Check 4",
        completed:
          gate(6, 0),
        unlocked:
          gate(6, 0),
        sourceFields: [
          "Assessments_Completed",
          "Performance_Rating"
        ]
      }
    );
  }

  return states;
}

async function applyRecruitApplicationStatusWebhook({
  email,
  applicationStatus
}) {
  const normalizedStatus =
    String(
      webhookNormalizeValue(
        applicationStatus
      ) ??
      ""
    )
      .trim()
      .toLowerCase();

  const progress =
    HIRING_STATUS_PROGRESS_MAP[
      normalizedStatus
    ] || {
      completed: [],
      current: null
    };

  const completedSet =
    new Set(
      progress.completed || []
    );

  const states = [];

  for (
    const stageName
    of WEBHOOK_STATUS_HIRING_STAGES
  ) {
    const completed =
      completedSet.has(
        stageName
      );

    const current =
      progress.current ===
      stageName;

    const state =
      await applyWebhookPipelineStage({
        email,
        stageName,
        completed,
        unlocked:
          completed ||
          current,
        sourceFields: [
          "Application_Status"
        ],
        sourceType:
          "recruit",
        status:
          completed
            ? "Completed"
            : current
              ? "In Progress"
              : "Not Started"
      });

    states.push(state);
  }

  return states.filter(Boolean);
}

async function fetchWebhookFallbackRecord({
  source,
  module,
  recordId
}) {
  if (!recordId) {
    return {};
  }

  try {
    if (
      source === "crm" &&
      String(module)
        .toLowerCase() ===
      "deals"
    ) {
      const response =
        await makeZohoApiRequest(
          `/crm/v3/Deals/${recordId}`,
          {
            cacheTtlMs:
              ZOHO_READ_CACHE_TTL_MS,
            forceRefresh:
              true
          }
        );

      return (
        response?.data?.[0] ||
        {}
      );
    }

    if (
      source === "recruit"
    ) {
      const response =
        await makeZohoRecruitApiRequest(
          `/recruit/v2/${module}/${recordId}`,
          {
            cacheTtlMs:
              RECRUIT_READ_CACHE_TTL_MS,
            forceRefresh:
              true,
            allowRecruitLiveRefresh:
              true
          }
        );

      return (
        response?.data?.[0] ||
        {}
      );
    }
  } catch (error) {
    console.warn(
      "[Zoho Webhook] Rare fallback record fetch failed:",
      source,
      module,
      recordId,
      error.message
    );
  }

  return {};
}

async function ensureWebhookEmailAndFields({
  source,
  module,
  recordId,
  changedFields,
  trackedFields
}) {
  let fields = {
    ...(changedFields || {})
  };

  let email =
    readWebhookEmail(
      fields
    );

  if (!email) {
    email =
      await lookupZohoWebhookEmail({
        source,
        module,
        recordId
      });
  }

  let persistedSnapshot = {};

  if (email) {
    persistedSnapshot =
      await mergeWebhookSnapshot({
        email,
        source,
        module,
        recordId,
        changedFields:
          fields
      });

    fields = {
      ...persistedSnapshot,
      ...fields
    };
  }

  if (!email) {
    const fallback =
      await fetchWebhookFallbackRecord({
        source,
        module,
        recordId
      });

    email =
      readWebhookEmail(
        fallback
      );

    fields = {
      ...webhookPickFields(
        fallback,
        trackedFields
      ),
      ...fields
    };
  }

  if (email) {
    const merged =
      await mergeWebhookSnapshot({
        email,
        source,
        module,
        recordId,
        changedFields:
          fields
      });

    fields = {
      ...merged,
      ...fields
    };

    await rememberZohoWebhookIdentity({
      source,
      module,
      recordId,
      email
    });
  }

  return {
    email,
    fields
  };
}

async function ensureFoundationWebhookContext({
  email,
  recordId,
  fields,
  changedFields
}) {
  const changedSet =
    new Set(
      Object.keys(
        changedFields || {}
      )
    );

  const affectedGroups =
    Object.values(
      WEBHOOK_FOUNDATION_GROUPS
    ).filter(group =>
      group.some(field =>
        changedSet.has(field)
      )
    );

  const missingNeeded =
    affectedGroups.some(group =>
      group.some(field =>
        !Object.prototype
          .hasOwnProperty.call(
            fields,
            field
          )
      )
    );

  if (!missingNeeded) {
    return fields;
  }

  // This is the only CRM fallback for a Foundation checkbox change when the
  // server has no previous snapshot. It is one GET for the actual change,
  // not recurring polling.
  const fallback =
    await fetchWebhookFallbackRecord({
      source: "crm",
      module: "Deals",
      recordId
    });

  const merged = {
    ...webhookPickFields(
      fallback,
      WEBHOOK_CRM_TRACKED_FIELDS
    ),
    ...fields
  };

  await mergeWebhookSnapshot({
    email,
    source: "crm",
    module: "Deals",
    recordId,
    changedFields:
      merged
  });

  return merged;
}

async function ensureNclexWebhookContext({
  email,
  recordId,
  fields,
  changedFields
}) {
  const changedSet =
    new Set(
      Object.keys(
        changedFields || {}
      )
    );

  const performanceChanged =
    [
      "Assessments_Completed",
      "Assignments_Completed",
      "Performance_Rating"
    ].some(field =>
      changedSet.has(field)
    );

  if (!performanceChanged) {
    return fields;
  }

  const required = [
    "Assessments_Completed",
    "Assignments_Completed",
    "Performance_Rating"
  ];

  const missing =
    required.some(field =>
      !Object.prototype
        .hasOwnProperty.call(
          fields,
          field
        )
    );

  if (!missing) {
    return fields;
  }

  // Recruit workflow webhooks should include all three gate fields. If one is
  // omitted and there is no cached snapshot, this performs one Recruit GET for
  // the actual change so the gate is never guessed.
  const fallback =
    await fetchWebhookFallbackRecord({
      source: "recruit",
      module: "CustomModule1",
      recordId
    });

  const merged = {
    ...webhookPickFields(
      fallback,
      WEBHOOK_NCLEX_TRACKED_FIELDS
    ),
    ...fields
  };

  await mergeWebhookSnapshot({
    email,
    source: "recruit",
    module: "CustomModule1",
    recordId,
    changedFields:
      merged
  });

  return merged;
}

async function processCrmWebhookPayload(
  body
) {
  const entries =
    Array.isArray(
      body?.affected_values
    )
      ? body.affected_values
      : [];

  const ids =
    Array.isArray(body?.ids)
      ? body.ids.map(String)
      : [];

  const records =
    entries.length > 0
      ? entries.map(entry => {
          const nestedValues =
            entry?.values &&
            typeof entry.values ===
              "object" &&
            !Array.isArray(
              entry.values
            )
              ? entry.values
              : null;

          // Zoho CRM Notifications can return affected_values with changed
          // fields directly on each record object. Preserve those fields
          // instead of discarding them when entry.values is absent.
          const directValues = {};

          if (
            entry &&
            typeof entry ===
              "object"
          ) {
            for (
              const [key, value]
              of Object.entries(
                entry
              )
            ) {
              if (
                [
                  "record_id",
                  "id",
                  "values"
                ].includes(key)
              ) {
                continue;
              }

              directValues[key] =
                value;
            }
          }

          return {
            recordId:
              String(
                entry?.record_id ||
                entry?.id ||
                ""
              ),
            values:
              nestedValues
                ? {
                    ...directValues,
                    ...nestedValues
                  }
                : directValues
          };
        })
      : ids.map(recordId => ({
          recordId,
          values: {}
        }));

  const processed = [];

  zohoWebhookRuntimeState
    .lastCrmRecordIds =
    records
      .map(record =>
        record.recordId
      )
      .filter(Boolean);

  zohoWebhookRuntimeState
    .lastCrmChangedFields =
    Array.from(
      new Set(
        records.flatMap(
          record =>
            Object.keys(
              record.values || {}
            )
        )
      )
    );

  zohoWebhookRuntimeState
    .lastCrmRealtimeDeliveries =
    0;

  for (const record of records) {
    const eventKey =
      [
        "crm",
        body?.channel_id || "",
        body?.server_time || "",
        body?.operation || "",
        record.recordId,
        Object.keys(
          record.values || {}
        )
          .sort()
          .join(",")
      ].join(":");

    const isNew =
      await webhookEventIsNew(
        eventKey,
        {
          source: "crm",
          module:
            body?.module ||
            "Deals",
          record_id:
            record.recordId
        }
      );

    if (!isNew) {
      continue;
    }

    let {
      email,
      fields
    } =
      await ensureWebhookEmailAndFields({
        source: "crm",
        module:
          body?.module ||
          "Deals",
        recordId:
          record.recordId,
        changedFields:
          record.values,
        trackedFields:
          WEBHOOK_CRM_TRACKED_FIELDS
      });

    if (!email) {
      console.warn(
        "[Zoho CRM Webhook] Could not resolve candidate email for record:",
        record.recordId
      );
      continue;
    }

    fields =
      await ensureFoundationWebhookContext({
        email,
        recordId:
          record.recordId,
        fields,
        changedFields:
          record.values
      });

    const stageDefinitions =
      computeWebhookCrmStages(
        fields,
        record.values
      );

    const stageStates = [];

    for (
      const definition
      of stageDefinitions
    ) {
      stageStates.push(
        await applyWebhookPipelineStage({
          email,
          stageName:
            definition.stageName,
          completed:
            definition.completed,
          unlocked:
            definition.unlocked,
          sourceFields:
            definition.sourceFields,
          sourceType:
            "crm"
        })
      );
    }

    const validStates =
      stageStates.filter(Boolean);

    patchWebhookFieldStatusCache({
      email,
      source: "crm",
      module: "Deals",
      changedFields:
        record.values,
      stageStates:
        validStates
    });

    removeZohoCacheEntriesForWebhook({
      email,
      recordIds: [
        record.recordId
      ]
    });

    // Restore the just-patched field-status cache after generic cache
    // invalidation. The snapshot contains the webhook values, so the next
    // portal read does not need a Zoho GET.
    patchWebhookFieldStatusCache({
      email,
      source: "crm",
      module: "Deals",
      changedFields:
        record.values,
      stageStates:
        validStates
    });

    if (
      Object.prototype
        .hasOwnProperty.call(
          record.values,
          "i140"
        ) &&
      [
        "rfe",
        "rfe (request for evidence)",
        "request for evidence",
        "request for further evidence"
      ].includes(
        webhookNormalizedText(
          record.values.i140
        )
      )
    ) {
      broadcastToUsers(
        [email],
        {
          type:
            "candidate-data-updated",
          event: "rfe",
          title:
            "Request for Evidence (RFE)",
          message:
            "Your immigration stage is now RFE (Request for Evidence).",
          timestamp:
            new Date()
              .toISOString()
        }
      );
    }

    const realtimePayload = {
      type:
        "pipeline-updated",
      event:
        "zoho-webhook",
      source:
        "crm",
      candidateEmail:
        email,
      changedFields:
        record.values,
      stageStatus:
        Object.fromEntries(
          validStates.map(state => [
            state.stage_name,
            state
          ])
        ),
      timestamp:
        new Date()
          .toISOString()
    };

    const realtimeDeliveries =
      broadcastToUsers(
        [email],
        realtimePayload
      );

    zohoWebhookRuntimeState
      .lastCrmRealtimeDeliveries +=
      realtimeDeliveries;

    console.log(
      "[Zoho CRM Webhook] Realtime pipeline push:",
      {
        email,
        realtimeDeliveries,
        changedFields:
          Object.keys(
            record.values || {}
          ),
        stages:
          validStates.map(
            item =>
              item.stage_name
          )
      }
    );

    broadcastToUsers(
      [email],
      {
        ...realtimePayload,
        type:
          "candidate-data-updated"
      }
    );

    broadcastToUsers(
      [email],
      {
        ...realtimePayload,
        type:
          "crm-recruit-updated"
      }
    );

    processed.push({
      email,
      recordId:
        record.recordId,
      changedFields:
        Object.keys(
          record.values || {}
        ),
      stages:
        validStates.map(
          item =>
            item.stage_name
        )
    });
  }

  zohoWebhookRuntimeState
    .lastCrmEventAt =
    new Date()
      .toISOString();

  zohoWebhookRuntimeState
    .lastCrmProcessedCandidates =
    Array.from(
      new Set(
        processed
          .map(item =>
            item.email
          )
          .filter(Boolean)
      )
    );

  return processed;
}

function inferRecruitWebhookModule(
  req,
  flatFields
) {
  const explicit =
    req.query?.module ||
    req.body?.module ||
    req.body?.Module ||
    req.body?.module_api_name ||
    "";

  if (explicit) {
    return String(explicit)
      .trim();
  }

  if (
    WEBHOOK_NCLEX_TRACKED_FIELDS
      .some(field =>
        Object.prototype
          .hasOwnProperty.call(
            flatFields,
            field
          )
      )
  ) {
    return "CustomModule1";
  }

  if (
    Object.prototype
      .hasOwnProperty.call(
        flatFields,
        "Application_Status"
      )
  ) {
    return "Applications";
  }

  if (
    [
      "All_docs_on_file",
      "All_Docs_on_File",
      "Attended_Pre_Interview_Call"
    ].some(field =>
      Object.prototype
        .hasOwnProperty.call(
          flatFields,
          field
        )
    )
  ) {
    return "Candidates";
  }

  return "";
}

function recruitWebhookRecordId(
  flatFields
) {
  const candidates = [
    "record_id",
    "Record_Id",
    "Record_ID",
    "id",
    "Id",
    "ID",
    "Candidate_Id",
    "Candidate_ID",
    "Application_Id",
    "Application_ID",
    "CustomModule1_Id",
    "CustomModule1_ID"
  ];

  for (const key of candidates) {
    if (
      flatFields[key] !==
        undefined &&
      flatFields[key] !==
        null &&
      String(flatFields[key])
        .trim() !== ""
    ) {
      return String(
        flatFields[key]
      ).trim();
    }
  }

  return "";
}

async function processRecruitWebhookPayload(
  req
) {
  const flat =
    flattenWebhookObject(
      req.body || {},
      {}
    );

  const module =
    inferRecruitWebhookModule(
      req,
      flat
    );

  if (!module) {
    throw new Error(
      "Recruit webhook module could not be determined. Add ?module=Applications, ?module=Candidates, or ?module=CustomModule1."
    );
  }

  const recordId =
    recruitWebhookRecordId(
      flat
    );

  const moduleLower =
    module.toLowerCase();

  const trackedFields =
    moduleLower ===
      "custommodule1"
      ? WEBHOOK_NCLEX_TRACKED_FIELDS
      : moduleLower ===
          "applications"
        ? WEBHOOK_APPLICATION_TRACKED_FIELDS
        : WEBHOOK_CANDIDATE_TRACKED_FIELDS;

  const changedFields =
    webhookPickFields(
      flat,
      trackedFields
    );

  const eventKey =
    [
      "recruit",
      module,
      recordId,
      flat.Modified_Time ||
        flat.modified_time ||
        Date.now(),
      Object.entries(
        changedFields
      )
        .map(
          ([key, value]) =>
            `${key}=${String(
              webhookNormalizeValue(
                value
              )
            )}`
        )
        .sort()
        .join("&")
    ].join(":");

  const isNew =
    await webhookEventIsNew(
      eventKey,
      {
        source:
          "recruit",
        module,
        record_id:
          recordId
      }
    );

  if (!isNew) {
    return {
      duplicate: true
    };
  }

  let {
    email,
    fields
  } =
    await ensureWebhookEmailAndFields({
      source:
        "recruit",
      module,
      recordId,
      changedFields,
      trackedFields
    });

  if (!email) {
    throw new Error(
      "Recruit webhook did not include a candidate email and the record could not be resolved."
    );
  }

  const stageStates = [];

  if (
    moduleLower ===
    "applications"
  ) {
    if (
      Object.prototype
        .hasOwnProperty.call(
          fields,
          "Application_Status"
        )
    ) {
      stageStates.push(
        ...(
          await applyRecruitApplicationStatusWebhook({
            email,
            applicationStatus:
              fields.Application_Status
          })
        )
      );
    }
  } else if (
    moduleLower ===
    "candidates"
  ) {
    if (
      Object.prototype
        .hasOwnProperty.call(
          changedFields,
          "Attended_Pre_Interview_Call"
        )
    ) {
      stageStates.push(
        await applyWebhookPipelineStage({
          email,
          stageName:
            "Mandatory Pre-Interview Coaching Call",
          completed:
            webhookCheckboxComplete(
              fields
                .Attended_Pre_Interview_Call
            ),
          sourceFields: [
            "Attended_Pre_Interview_Call"
          ],
          sourceType:
            "recruit"
        })
      );
    }

    if (
      [
        "All_docs_on_file",
        "All_Docs_on_File"
      ].some(field =>
        Object.prototype
          .hasOwnProperty.call(
            changedFields,
            field
          )
      )
    ) {
      stageStates.push(
        await applyWebhookPipelineStage({
          email,
          stageName:
            "Documents Received",
          completed:
            webhookCheckboxComplete(
              fields
                .All_docs_on_file ??
              fields
                .All_Docs_on_File
            ),
          sourceFields: [
            "All_docs_on_file"
          ],
          sourceType:
            "recruit"
        })
      );
    }
  } else if (
    moduleLower ===
    "custommodule1"
  ) {
    fields =
      await ensureNclexWebhookContext({
        email,
        recordId,
        fields,
        changedFields
      });

    const definitions =
      computeWebhookNclexStages(
        fields,
        changedFields
      );

    for (
      const definition
      of definitions
    ) {
      stageStates.push(
        await applyWebhookPipelineStage({
          email,
          stageName:
            definition.stageName,
          completed:
            definition.completed,
          unlocked:
            definition.unlocked,
          sourceFields:
            definition.sourceFields,
          sourceType:
            "recruit"
        })
      );
    }
  }

  const validStates =
    stageStates.filter(Boolean);

  removeZohoCacheEntriesForWebhook({
    email,
    recordIds: [
      recordId
    ]
  });

  patchWebhookFieldStatusCache({
    email,
    source:
      "recruit",
    module,
    changedFields,
    stageStates:
      validStates
  });

  const realtimePayload = {
    type:
      "pipeline-updated",
    event:
      "zoho-webhook",
    source:
      "recruit",
    module,
    candidateEmail:
      email,
    changedFields,
    stageStatus:
      Object.fromEntries(
        validStates.map(state => [
          state.stage_name,
          state
        ])
      ),
    timestamp:
      new Date()
        .toISOString()
  };

  broadcastToUsers(
    [email],
    realtimePayload
  );

  broadcastToUsers(
    [email],
    {
      ...realtimePayload,
      type:
        "candidate-data-updated"
    }
  );

  broadcastToUsers(
    [email],
    {
      ...realtimePayload,
      type:
        "crm-recruit-updated"
    }
  );

  zohoWebhookRuntimeState
    .lastRecruitEventAt =
    new Date()
      .toISOString();

  return {
    email,
    module,
    recordId,
    changedFields:
      Object.keys(
        changedFields
      ),
    stages:
      validStates.map(
        item =>
          item.stage_name
      )
  };
}

app.post(
  "/api/webhooks/zoho/crm",
  async (req, res) => {
    const body =
      req.body || {};

    zohoWebhookRuntimeState
      .lastCrmCallbackAt =
      new Date().toISOString();
    zohoWebhookRuntimeState
      .crmCallbackCount += 1;
    zohoWebhookRuntimeState
      .lastCrmCallbackModule =
      body?.module || null;
    zohoWebhookRuntimeState
      .lastCrmCallbackOperation =
      body?.operation || null;

    if (
      !requireCrmNotificationToken(
        body
      )
    ) {
      zohoWebhookRuntimeState
        .lastCrmRejectedCallbackAt =
        new Date().toISOString();
      zohoWebhookRuntimeState
        .lastCrmRejectedReason =
        "Notification token mismatch";
      return res
        .status(
          ZOHO_CRM_NOTIFICATION_TOKEN
            ? 401
            : 503
        )
        .json({
          success:
            false,
          error:
            ZOHO_CRM_NOTIFICATION_TOKEN
              ? "Invalid Zoho CRM notification token."
              : "ZOHO_WEBHOOK_SECRET or ZOHO_CRM_NOTIFICATION_TOKEN is not configured."
        });
    }

    zohoWebhookRuntimeState
      .lastCrmRejectedReason =
      null;

    // Acknowledge immediately. Actual processing continues asynchronously so
    // Zoho never waits on Mongo or a rare fallback GET.
    res.status(202).json({
      success: true,
      accepted: true
    });

    setImmediate(() => {
      processCrmWebhookPayload(
        body
      ).catch(error =>
        console.error(
          "[Zoho CRM Webhook] Processing failed:",
          error
        )
      );
    });
  }
);

