// ─── ADMIN / USER MESSAGING ──────────────────────────────────────────────────
const authenticateAdminOrUser = async (req,res,next)=>{
  const adminHeader=req.headers["x-admin-token"] || "";
  const auth=req.headers.authorization || "";
  if(adminHeader || auth.startsWith("AdminBearer ") || req.cookies?.admin_session==="authenticated") { req.isAdmin=true; return next(); }
  return authenticateToken(req,res,next);
};
app.post(
  "/api/messaging/send",
  authenticateAdminOrUser,
  async (req, res) => {
    try {
      if (
        !mongoConnected ||
        !Message ||
        !Conversation
      ) {
        return res.status(503).json({
          success: false,
          error:
            "Messaging database is unavailable."
        });
      }

      const senderEmail =
        normalizePipelineEmail(
          req.adminEmail ||
          req.userEmail
        );

      const {
        conversationId,
        content,
        messageType,
        fileUrl,
        fileName
      } =
        req.body || {};

      // Admin direct-message compatibility.
      if (
        req.isAdmin &&
        !conversationId
      ) {
        const recipientEmail =
          normalizePipelineEmail(
            req.body.recipientEmail
          );

        if (
          !recipientEmail ||
          !String(content || "")
            .trim()
        ) {
          return res.status(400).json({
            success: false,
            error:
              "Recipient and message are required."
          });
        }

        const adminEmail =
          "admin";

        const participants = [
          adminEmail,
          recipientEmail
        ].sort();

        let conversation =
          await Conversation.findOne({
            type: "direct",
            participants: {
              $all: participants
            }
          });

        if (!conversation) {
          conversation =
            await Conversation.create({
              participants,
              type: "direct",
              createdBy:
                adminEmail,
              lastMessageAt:
                new Date()
            });
        }

        const record =
          await Message.create({
            conversationId:
              conversation._id,
            senderEmail:
              adminEmail,
            senderName:
              "Admin",
            receiver:
              recipientEmail,
            content:
              String(content)
                .trim(),
            messageType:
              messageType ||
              "text",
            isRead: false,
            createdAt:
              new Date()
          });

        conversation.lastMessage =
          record._id;
        conversation.lastMessageAt =
          record.createdAt;

        await conversation.save();

        broadcastToUsers(
          [recipientEmail],
          {
            type:
              "new_message",
            conversationId:
              String(
                conversation._id
              ),
            message:
              record.toObject
                ? record.toObject()
                : record
          }
        );

        return res.json({
          success: true,
          message: record,
          conversation
        });
      }

      if (
        !conversationId ||
        !String(content || "")
          .trim()
      ) {
        return res.status(400).json({
          success: false,
          error:
            "Conversation and message content are required."
        });
      }

      const conversation =
        await Conversation.findById(
          conversationId
        );

      if (!conversation) {
        return res.status(404).json({
          success: false,
          error:
            "Conversation not found."
        });
      }

      const isAdmin =
        req.isAdmin === true ||
        Boolean(req.adminEmail);

      const isParticipant =
        (conversation.participants || [])
          .map(normalizePipelineEmail)
          .includes(senderEmail);

      if (
        !isAdmin &&
        !isParticipant
      ) {
        return res.status(403).json({
          success: false,
          error:
            "You do not have access to this conversation."
        });
      }

      // Candidates may write only to broadcast/group candidate conversations.
      // They cannot write to a direct admin conversation.
      if (
        !isAdmin &&
        conversation.type === "direct" &&
        (conversation.participants || [])
          .map(normalizePipelineEmail)
          .some(participant =>
            participant === "admin" ||
            participant.includes("admin@")
          )
      ) {
        return res.status(403).json({
          success: false,
          error:
            "Candidates cannot send direct messages to admin. Use Broadcast instead."
        });
      }

      const message =
        await Message.create({
          conversationId:
            conversation._id,
          senderEmail,
          senderName:
            isAdmin
              ? "Admin"
              : await getUserName(senderEmail),
          content:
            String(content)
              .trim(),
          messageType:
            messageType ||
            "text",
          fileUrl:
            fileUrl ||
            null,
          fileName:
            fileName ||
            null,
          isRead: false,
          createdAt:
            new Date()
        });

      conversation.lastMessage =
        message._id;
      conversation.lastMessageAt =
        message.createdAt;
      conversation.updatedAt =
        new Date();

      await conversation.save();

      broadcastToUsers(
        (conversation.participants || [])
          .filter(
            participant =>
              normalizePipelineEmail(
                participant
              ) !== senderEmail
          ),
        {
          type:
            "new_message",
          conversationId:
            String(
              conversation._id
            ),
          message:
            message.toObject
              ? message.toObject()
              : message
        }
      );

      return res.json({
        success: true,
        message
      });
    } catch (error) {
      console.error(
        "[Messaging] Send:",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message
      });
    }
  }
);

app.get("/api/messaging/history", authenticateAdminOrUser, async(req,res)=>{
  try{
    const email=String(req.userEmail||"").trim().toLowerCase();
    if(!email)return res.status(400).json({success:false,error:"Email is required"});
    const adminEmail="admin@infinitycarepartners.com";
    const conversation=await Conversation.findOne({type:"direct",participants:{$all:[adminEmail,email],$size:2}}).lean();
    if(!conversation)return res.json({success:true,messages:[]});
    const rows=await Message.find({conversationId:conversation._id,isDeleted:{$ne:true}}).sort({createdAt:1}).lean();
    res.json({success:true,messages:rows.map(x=>({id:x._id,from:x.senderEmail===adminEmail?"admin":"user",text:x.content,time:x.createdAt}))});
  }catch(e){res.status(500).json({success:false,error:e.message});}
});



async function getCandidatePipelineAccessPolicy(
  email,
  applicationStatus
) {
  const candidateEmail =
    normalizePipelineEmail(
      email
    );

  const normalized =
    normalizeApplicationStatus(
      extractRecruitPicklistValue(
        applicationStatus
      )
    );

  const now =
    new Date();

  const store =
    mongoConnected &&
    mongoose.connection?.db
      ? mongoose.connection.db
          .collection(
            "candidate_pipeline_access"
          )
      : null;

  const isQualifiedPool =
    [
      "qualified candidate pool",
      "qualified-candidate pool"
    ].includes(
      normalized
    );

  const isNotQualified =
    [
      "unqualified",
      "not qualified to close",
      "not qualified - to close",
      "not qualified-to close",
      "not qualified-to-close"
    ].includes(
      normalized
    );

  if (
    !isQualifiedPool &&
    !isNotQualified
  ) {
    if (store) {
      await store.updateOne(
        {
          candidate_email:
            candidateEmail
        },
        {
          $set: {
            candidate_email:
              candidateEmail,
            application_status:
              normalized,
            restricted:
              false,
            locked:
              false,
            portal_locked:
              false,
            lock_at:
              null,
            status_since:
              null,
            updated_at:
              now
          },
          $setOnInsert: {
            created_at:
              now
          }
        },
        {
          upsert:
            true
        }
      );
    }

    return {
      mode:
        "normal",
      restricted:
        false,
      locked:
        false,
      portal_locked:
        false,
      lock_at:
        null,
      message:
        ""
    };
  }

  const existing =
    store
      ? await store.findOne({
          candidate_email:
            candidateEmail
        })
      : null;

  const sameStatus =
    existing
      ?.application_status ===
    normalized;

  const statusSince =
    sameStatus &&
    existing?.status_since
      ? new Date(
          existing.status_since
        )
      : now;

  const lockAt =
    isNotQualified
      ? new Date(
          statusSince.getTime() +
          5 *
            24 *
            60 *
            60 *
            1000
        )
      : null;

  // Pipeline restriction is immediate.
  const locked =
    true;

  // Whole-portal access only ends for Unqualified, after five days.
  const portalLocked =
    isNotQualified &&
    lockAt &&
    Date.now() >=
      lockAt.getTime();

  const message =
    isQualifiedPool
      ? "There are currently no openings matching your profile. We will notify you when a suitable opening becomes available."
      : portalLocked
        ? "You do not meet the qualification criteria and your 5-day portal access period has ended. Please contact Infinity Care Partners if you need assistance."
        : `You do not meet the qualification criteria. All other pipeline sections are locked, and your portal access will end in 5 days on ${lockAt.toLocaleString(
            "en-US"
          )}.`;

  if (store) {
    await store.updateOne(
      {
        candidate_email:
          candidateEmail
      },
      {
        $set: {
          candidate_email:
            candidateEmail,
          application_status:
            normalized,
          status_since:
            statusSince,
          restricted:
            true,
          locked:
            true,
          portal_locked:
            portalLocked,
          lock_at:
            lockAt,
          updated_at:
            now
        },
        $setOnInsert: {
          created_at:
            now
        }
      },
      {
        upsert:
          true
      }
    );
  }

  if (
    mongoConnected &&
    mongoose.connection?.db
  ) {
    const key =
      isQualifiedPool
        ? `access:qualified-pool:${normalized}`
        : `access:unqualified:${statusSince.toISOString()}`;

    await mongoose.connection.db
      .collection(
        "candidate_updates"
      )
      .updateOne(
        {
          candidate_email:
            candidateEmail,
          notification_key:
            key
        },
        {
          $setOnInsert: {
            candidate_email:
              candidateEmail,
            notification_key:
              key,
            title:
              isQualifiedPool
                ? "Qualified Candidate Pool"
                : "Qualification Criteria Not Met",
            message,
            update_type:
              "access",
            is_read:
              false,
            created_at:
              now
          },
          $set: {
            message,
            updated_at:
              now
          }
        },
        {
          upsert:
            true
        }
      );
  }

  return {
    mode:
      isQualifiedPool
        ? "qualified-pool"
        : "not-qualified",
    restricted:
      true,
    locked:
      true,
    portal_locked:
      portalLocked,
    lock_at:
      lockAt
        ? lockAt.toISOString()
        : null,
    status_since:
      statusSince.toISOString(),
    grace_period_days:
      isNotQualified
        ? 5
        : null,
    message
  };
}


