async function resolveHiringLinkedRecruitCandidate(
  email
) {
  const normalizedEmail =
    normalizePipelineEmail(
      email
    );

  const applications =
    await findRecruitRecordsByEmailRobust(
      "Applications",
      normalizedEmail,
      {
        forceRefresh:
          true
      }
    );

  const sortedApplications =
    [...(applications || [])]
      .sort(
        (a, b) =>
          new Date(
            b.Modified_Time ||
            b.Created_Time ||
            0
          ) -
          new Date(
            a.Modified_Time ||
            a.Created_Time ||
            0
          )
      );

  // Prefer the Candidate lookup stored on the actual Applications record.
  for (
    const applicationSummary of
    sortedApplications
  ) {
    let application =
      applicationSummary;

    try {
      application =
        await fetchFullRecruitRecord(
          "Applications",
          applicationSummary
        );
    } catch (_) {}

    const lookup =
      extractApplicationCandidateLookup(
        application
      );

    if (!lookup?.id) {
      continue;
    }

    try {
      const candidateResponse =
        await makeZohoRecruitApiRequest(
          `/recruit/v2/Candidates/${lookup.id}`,
          {
            params: {
              fields:
                "All_docs_on_file,Attended_Pre_Interview_Call,Email,First_Name,Last_Name,Modified_Time"
            },
            cacheTtlMs: 0,
            forceRefresh: true,
            allowRecruitLiveRefresh: true
          }
        );

      const candidate =
        candidateResponse
          ?.data?.[0] ||
        null;

      if (candidate) {
        return {
          candidate,
          application,
          source:
            "application-linked-candidate"
        };
      }
    } catch (error) {
      console.warn(
        `[Hiring Triggers] Linked Candidate ${lookup.id} fetch failed:`,
        error.message
      );
    }
  }

  // Fallback only when the Application has no usable Candidate lookup.
  const candidateMatches =
    await findRecruitRecordsByEmailRobust(
      "Candidates",
      normalizedEmail,
      {
        forceRefresh:
          true
      }
    );

  const newestCandidate =
    [...(candidateMatches || [])]
      .sort(
        (a, b) =>
          new Date(
            b.Modified_Time ||
            b.Created_Time ||
            0
          ) -
          new Date(
            a.Modified_Time ||
            a.Created_Time ||
            0
          )
      )[0] ||
    null;

  if (!newestCandidate?.id) {
    return {
      candidate: null,
      application:
        sortedApplications[0] ||
        null,
      source:
        "not-found"
    };
  }

  const response =
    await makeZohoRecruitApiRequest(
      `/recruit/v2/Candidates/${newestCandidate.id}`,
      {
        params: {
          fields:
            "All_docs_on_file,Attended_Pre_Interview_Call,Email,First_Name,Last_Name,Modified_Time"
        },
        cacheTtlMs: 0,
        forceRefresh: true,
        allowRecruitLiveRefresh: true
      }
    );

  return {
    candidate:
      response?.data?.[0] ||
      newestCandidate,
    application:
      sortedApplications[0] ||
      null,
    source:
      "candidate-email-fallback"
  };
}

app.get("/api/pipeline/hiring-candidate-triggers", authenticateToken, async (req, res) => {
  try {
    const email =
      await resolveCanonicalPipelineEmail(
        req.userEmail
      );

    const resolved =
      await resolveHiringLinkedRecruitCandidate(
        email
      );

    const candidate =
      resolved.candidate;

    if (!candidate?.id) {
      return res.json({
        success: true,
        found: false,
        module:
          "Candidates",
        resolutionSource:
          resolved.source,
        email,
        fields: {
          All_docs_on_file:
            null,
          Attended_Pre_Interview_Call:
            null
        },
        completion: {
          "Documents Received":
            false,
          "Mandatory Pre-Interview Coaching Call":
            false
        }
      });
    }

    const allDocs =
      candidate
        .All_docs_on_file ??
      candidate
        .All_Docs_on_File ??
      null;

    const attended =
      candidate
        .Attended_Pre_Interview_Call ??
      null;

    const documentsComplete =
      isRecruitCheckboxChecked(
        allDocs
      );

    const coachingComplete =
      isRecruitCheckboxChecked(
        attended
      );

    const now =
      new Date();

    if (
      mongoConnected &&
      PipelineStage
    ) {
      const triggers = [
        {
          stage_name:
            "Documents Received",
          stage_order:
            19,
          field:
            "All_docs_on_file",
          raw:
            allDocs,
          completed:
            documentsComplete
        },
        {
          stage_name:
            "Mandatory Pre-Interview Coaching Call",
          stage_order:
            11.5,
          field:
            "Attended_Pre_Interview_Call",
          raw:
            attended,
          completed:
            coachingComplete
        }
      ];

      for (
        const trigger of
        triggers
      ) {
        const existing =
          await PipelineStage.findOne({
            candidate_email:
              email,
            stage_name:
              trigger.stage_name,
            is_deleted: {
              $ne: true
            }
          });

        await PipelineStage.findOneAndUpdate(
          {
            candidate_email:
              email,
            stage_name:
              trigger.stage_name
          },
          {
            $set: {
              candidate_email:
                email,
              stage_name:
                trigger.stage_name,
              stage_category:
                "Hiring",
              stage_order:
                trigger.stage_order,
              status:
                trigger.completed
                  ? "Completed"
                  : "Not Started",
              completed:
                trigger.completed,
              is_completed:
                trigger.completed,
              completed_date:
                trigger.completed
                  ? (
                      existing
                        ?.completed_date ||
                      now
                    )
                  : null,
              recruit_boolean_field:
                trigger.field,
              recruit_boolean_value:
                trigger.raw,
              completion_source:
                "recruit_linked_candidate_boolean",
              recruit_candidate_id:
                candidate.id,
              recruit_application_id:
                resolved.application?.id ||
                null,
              recruit_resolution_source:
                resolved.source,
              updated_at:
                now,
              is_deleted:
                false
            },
            $setOnInsert: {
              created_at:
                now
            }
          },
          {
            upsert: true,
            new: true
          }
        );
      }
    }

    return res.json({
      success: true,
      found: true,
      module:
        "Candidates",
      resolutionSource:
        resolved.source,
      email,
      candidateRecordId:
        candidate.id,
      applicationRecordId:
        resolved.application?.id ||
        null,
      candidateName:
        [
          candidate.First_Name,
          candidate.Last_Name
        ]
          .filter(Boolean)
          .join(" "),
      candidateEmail:
        candidate.Email ||
        null,
      fields: {
        All_docs_on_file:
          allDocs,
        Attended_Pre_Interview_Call:
          attended
      },
      completion: {
        "Documents Received":
          documentsComplete,
        "Mandatory Pre-Interview Coaching Call":
          coachingComplete
      }
    });
  } catch (error) {
    console.error(
      "[Hiring Candidate Triggers]",
      error
    );

    return res.status(500).json({
      success: false,
      error:
        error.message
    });
  }
});

app.get("/api/pipeline/nclex-status", authenticateToken, async (req, res) => {
  try {
    const email =
      await resolveCanonicalPipelineEmail(
        req.userEmail
      );

    const [
      applicationMatches,
      candidateMatches
    ] = await Promise.all([
      findRecruitRecordsByEmailRobust(
        "Applications",
        email,
        { forceRefresh: true }
      ).catch(() => []),
      findRecruitRecordsByEmailRobust(
        "Candidates",
        email,
        { forceRefresh: true }
      ).catch(() => [])
    ]);

    const newest = records =>
      [...(records || [])].sort(
        (a, b) =>
          new Date(b.Modified_Time || b.Created_Time || 0) -
          new Date(a.Modified_Time || a.Created_Time || 0)
      )[0] || {};

    const applicationSummary = newest(applicationMatches);
    const application =
      applicationSummary?.id
        ? await fetchFullRecruitRecord(
            "Applications",
            applicationSummary,
            { forceRefresh: true }
          )
        : applicationSummary;

    let candidate = newest(candidateMatches);
    const linkedCandidate =
      extractApplicationCandidateLookup(application);

    if (linkedCandidate?.id) {
      const fullCandidate =
        await fetchFullRecruitRecord(
          "Candidates",
          { id: linkedCandidate.id },
          { forceRefresh: true }
        ).catch(() => null);

      if (fullCandidate?.id) {
        candidate = fullCandidate;
      }
    }

    const matches =
      await findNCLEXCustomModule1Records(
        email,
        {
          candidate,
          application,
          forceRefresh: true
        }
      );

    const summary = newest(matches);
    const record =
      summary?.id
        ? await fetchFullRecruitRecord(
            "CustomModule1",
            summary,
            { forceRefresh: true }
          )
        : summary;

    const fields = {
      NCLEX_Pre_Exam: record?.NCLEX_Pre_Exam ?? null,
      Prescreen_Status: record?.Prescreen_Status ?? null,
      Documents_Submitted: record?.Documents_Submitted ?? null,
      Sponsorship_Agreement: record?.Sponsorship_Agreement ?? null,
      Program_Status: record?.Program_Status ?? null,
      Credential_Service: record?.Credential_Service ?? null,
      Credentialing_Status: record?.Credentialing_Status ?? null,
      Credential_Registration_Date: record?.Credential_Registration_Date ?? null,
      Date_Report_Issued: record?.Date_Report_Issued ?? null,
      State_License_Board_of_Registration:
        record?.State_License_Board_of_Registration ?? null,
      Board_Username: record?.Board_Username ?? null,
      Pearson_Vue_Status: record?.Pearson_Vue_Status ?? null,
      Assessments_Completed: record?.Assessments_Completed ?? null,
      Assignments_Completed: record?.Assignments_Completed ?? null,
      Performance_Rating: record?.Performance_Rating ?? null,
      ATT_Received_Date: record?.ATT_Received_Date ?? null,
      NCLEX_Exam_Date: record?.NCLEX_Exam_Date ?? null,
      NCLEX_Status: record?.NCLEX_Status ?? null
    };

    const unwrap = value => {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        return (
          value.value ??
          value.name ??
          value.display_value ??
          value.displayValue ??
          value.label ??
          value.actual_value ??
          value.selected ??
          value.checked ??
          ""
        );
      }
      return value;
    };

    const normalized = value =>
      String(unwrap(value) ?? "").trim().toLowerCase();

    const present = value => {
      const raw = unwrap(value);
      if (raw === null || raw === undefined || raw === false) return false;
      if (Array.isArray(raw)) return raw.some(present);
      return !["", "none", "null", "undefined", "—", "-"].includes(
        String(raw).trim().toLowerCase()
      );
    };

    const truthy = value =>
      value === true ||
      value === 1 ||
      ["true", "yes", "checked", "1"].includes(normalized(value));

    const parseCount = value => {
      const parsed = Number.parseInt(
        normalized(value).replace(/[^0-9]/g, ""),
        10
      );
      return Number.isFinite(parsed) ? parsed : 0;
    };

    const acceptedSponsor = new Set([
      "paid by icp",
      "sponsored by icp",
      "to be sponsored by infinity",
      "paid by infinity"
    ]);

    const ratingPass = ["high", "very high"].includes(
      normalized(fields.Performance_Rating)
    );

    const performanceGate = (assessments, assignments) =>
      parseCount(fields.Assessments_Completed) >= assessments &&
      parseCount(fields.Assignments_Completed) >= assignments &&
      ratingPass;

    const completion = {
      "Complete Pre-assessment":
        ["1st attempt pass", "2nd attempt pass"].includes(
          normalized(fields.NCLEX_Pre_Exam)
        ),
      "Program Prescreen":
        normalized(fields.Prescreen_Status) === "attended",
      "Document Review":
        present(fields.Documents_Submitted),
      "Educational Program Agreement":
        truthy(fields.Sponsorship_Agreement),
      "Program Approval":
        normalized(fields.Program_Status) === "approved",
      "Credential Evaluation Set-up":
        acceptedSponsor.has(normalized(fields.Credential_Service)),
      "Credential Evaluation Completed":
        present(fields.Credential_Registration_Date),
      "CES Report Issued":
        present(fields.Date_Report_Issued),
      "Performance Check 1":
        performanceGate(2, 6),
      "Board Registration":
        acceptedSponsor.has(
          normalized(fields.State_License_Board_of_Registration)
        ),
      "Select Meeting Time":
        false,
      "Performance Check 2":
        performanceGate(4, 15),
      "Board Approval":
        present(fields.Board_Username),
      "Pearson Vue Registration":
        normalized(fields.Pearson_Vue_Status) === "complete",
      "Performance Check 3":
        performanceGate(5, 0),
      "ATT Received":
        present(fields.ATT_Received_Date),
      "Performance Check 4":
        performanceGate(6, 0),
      "Exam Scheduled":
        present(fields.NCLEX_Exam_Date),
      "Exam Results":
        normalized(fields.NCLEX_Status) === "passed"
    };

    const applicationStatus =
      extractRecruitPicklistValue(
        application?.Application_Status
      );

    return res.json({
      success: true,
      module: "CustomModule1",
      recordId: record?.id || null,
      candidateRecordId: candidate?.id || null,
      applicationRecordId: application?.id || null,
      applicationStatus,
      nclexEligible:
        isTransferToICPUSRNStatus(applicationStatus) ||
        Object.values(completion).some(Boolean),
      fields,
      completion
    });
  } catch (error) {
    console.error("[NCLEX CustomModule1 status]", error);
    return res.status(500).json({
      success: false,
      error:
        error.message ||
        "Unable to read CustomModule1 NCLEX fields."
    });
  }
});

app.post("/api/pipeline/acknowledge-field-stage", authenticateToken, async (req, res) => {
  try {
    const email = String(req.userEmail || req.body.email || "").trim().toLowerCase();
    const stageName = String(req.body.stage_name || "").trim();
    if (!email || !stageName) {
      return res.status(400).json({ success: false, error: "Email and stage are required" });
    }

    const now = new Date();
    const update = req.body.allow_continue === true
      ? {
          acknowledged_at: now,
          allow_continue: true,
          updated_at: now
        }
      : {
          status: "Completed",
          completed_date: now,
          acknowledged_at: now,
          timing_status: "Good Standing",
          updated_at: now
        };

    const stage = await PipelineStage.findOneAndUpdate(
      { candidate_email: email, stage_name: stageName },
      { $set: update },
      { new: true }
    );

    return res.json({ success: true, stage, allowContinue: req.body.allow_continue === true });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});


const immigrationRenewalUpload = upload.fields([
  { name: "file_english", maxCount: 1 },
  { name: "file_visaScreen", maxCount: 1 }
]);

app.post(
  "/api/immigration/renew-documents",
  authenticateToken,
  immigrationRenewalUpload,
  async (req, res) => {
    try {
      const email = String(req.userEmail || req.body.candidate_email || "").trim().toLowerCase();
      const deals = await searchDealsByEmail(
        email,
        {
          forceRefresh: true
        }
      );
      const deal = [...(deals || [])].sort(
        (a, b) => new Date(b.Modified_Time || 0) - new Date(a.Modified_Time || 0)
      )[0];

      if (!deal?.id) {
        return res.status(404).json({ success: false, error: "Candidate record not found" });
      }

      const configurations = [
        {
          key: "english",
          file: req.files?.file_english?.[0],
          expiry: req.body.expiry_english,
          expiryField: "IELTS_Scheduled_Exam_Date_if_applicable",
          label: "English Document"
        },
        {
          key: "visaScreen",
          file: req.files?.file_visaScreen?.[0],
          expiry: req.body.expiry_visaScreen,
          expiryField: "Visa_Screen_Exp_Date",
          label: "Visa Screen Document"
        }
      ].filter(item => item.file);

      if (!configurations.length) {
        return res.status(400).json({ success: false, error: "No replacement documents received" });
      }

      const documents = [];
      for (const item of configurations) {
        const uploadResult = await uploadBufferToCrmDeal({
          email,
          buffer: item.file.buffer,
          filename: item.file.originalname,
          mimetype: item.file.mimetype
        });

        documents.push({
          key: item.key,
          success: uploadResult.success === true && uploadResult.verified === true,
          attachment_id: uploadResult.attachment_id,
          file_name: uploadResult.file_name || item.file.originalname
        });
      }

      const token = await getValidZohoToken();
      const updateRecord = { id: deal.id };
      configurations.forEach(item => {
        if (item.expiry) updateRecord[item.expiryField] = item.expiry;
      });

      const updateResponse = await axios.put(
        `${ZOHO_CRM_URL}/crm/v3/Deals`,
        { data: [updateRecord] },
        {
          headers: {
            Authorization: `Zoho-oauthtoken ${token}`,
            "Content-Type": "application/json"
          },
          timeout: 30000
        }
      );

      const result = updateResponse.data?.data?.[0];
      if (!["success", "SUCCESS"].includes(String(result?.status || result?.code))) {
        return res.status(502).json({
          success: false,
          error: result?.message || "Replacement expiry dates could not be updated",
          documents
        });
      }

      return res.json({ success: true, documents });
    } catch (error) {
      console.error("[Immigration Renewal]", error.response?.data || error);
      return res.status(error.response?.status || 500).json({
        success: false,
        error:
          error.response?.data?.data?.[0]?.message ||
          error.response?.data?.message ||
          error.message
      });
    }
  }
);


