app.post("/api/messaging/start-conversation", authenticateAdminOrUser, async (req, res) => {
  try {
    if (!req.isAdmin) {
      return res.status(403).json({
        success: false,
        error: "Users cannot start direct conversations."
      });
    }

    const recipientEmail = String(
      req.body.recipientEmail || ""
    ).trim().toLowerCase();

    if (!recipientEmail) {
      return res.status(400).json({
        success: false,
        error: "Recipient email is required"
      });
    }

    const senderEmail = "admin@infinitycarepartners.com";
    const participants = [senderEmail, recipientEmail].sort();

    let conversation = await Conversation.findOne({
      type: "direct",
      participants: {
        $all: participants,
        $size: 2
      }
    });

    if (!conversation) {
      conversation = await Conversation.create({
        participants,
        type: "direct",
        createdBy: senderEmail,
        lastMessageAt: new Date()
      });
    }

    return res.json({
      success: true,
      conversation
    });
  } catch (error) {
    return res.status(500).json({
      success: false,
      error: error.message
    });
  }
});


const authenticateBroadcastSender = async (
  req,
  res,
  next
) => {
  const authorization = String(
    req.headers.authorization || ""
  );

  // A standard Bearer token always represents a candidate user, even when the
  // browser still has an old Admin session cookie.
  if (authorization.startsWith("Bearer ")) {
    req.isAdmin = false;
    return authenticateToken(req, res, next);
  }

  const adminHeader = String(
    req.headers["x-admin-token"] || ""
  );
  const adminBearer =
    authorization.startsWith("AdminBearer ");
  const adminCookie = String(
    req.headers.cookie || ""
  ).includes("admin_session=authenticated");

  if (
    adminHeader ||
    adminBearer ||
    adminCookie
  ) {
    req.isAdmin = true;
    return next();
  }

  return res.status(401).json({
    success: false,
    error: "Authentication required"
  });
};

app.post("/api/messaging/broadcast", authenticateBroadcastSender, async (req, res) => {
  try {
    const content = String(req.body.content || "").trim();
    const title = String(req.body.title || "").trim();

    if (!content) {
      return res.status(400).json({
        success: false,
        error: "Message is required"
      });
    }

    const senderEmail = req.isAdmin
      ? "admin"
      : String(req.userEmail || "").trim().toLowerCase();

    if (!senderEmail) {
      return res.status(401).json({
        success: false,
        error: "Authentication required"
      });
    }

    const senderName = req.isAdmin
      ? "Admin"
      : String(
          req.body.senderName ||
          senderEmail.split("@")[0] ||
          "Candidate"
        ).trim();

    const userRows = await UserAuth.find(
      {
        email: {
          $exists: true,
          $ne: ""
        }
      },
      {
        email: 1,
        _id: 0
      }
    ).lean();

    const excludedAdminEmails = new Set([
      "admin@infinitycarepartners.com",
      "admin",
      "system"
    ]);

    const recipients = [
      ...new Set(
        userRows
          .map(item =>
            String(item.email || "").trim().toLowerCase()
          )
          .filter(email =>
            email &&
            email !== senderEmail &&
            !excludedAdminEmails.has(email)
          )
      )
    ];

    if (recipients.length === 0) {
      return res.status(400).json({
        success: false,
        error: "No users are available to receive this broadcast"
      });
    }

    const participantNames = new Map();
    participantNames.set(senderEmail, req.isAdmin ? "Admin" : senderName);
    for (const recipient of recipients) {
      participantNames.set(recipient, await getUserName(recipient));
    }

    const conversation = await Conversation.create({
      participants: [senderEmail, ...recipients],
      participantNames,
      type: "broadcast",
      groupName:
        title ||
        (req.isAdmin
          ? "Admin Broadcast"
          : `${senderName} Broadcast`),
      createdBy: senderEmail,
      lastMessageAt: new Date(),
      broadcastAudience: "all_users",
      senderRole: req.isAdmin ? "admin" : "user"
    });

    const message = await Message.create({
      conversationId: conversation._id,
      senderEmail,
      senderName:
        req.isAdmin
          ? "Admin Broadcast"
          : `${senderName} Broadcast`,
      content,
      messageType: "text",
      broadcast: true,
      isRead: false,
      createdAt: new Date()
    });

    conversation.lastMessage = message._id;
    conversation.lastMessageAt = message.createdAt;
    await conversation.save();

    broadcastToUsers([senderEmail, ...recipients], {
      type: "new_message",
      conversationId: String(conversation._id),
      _id: String(message._id),
      senderEmail,
      senderName: message.senderName,
      content,
      messageType: "text",
      broadcast: true,
      createdAt: message.createdAt
    });

    return res.json({
      success: true,
      conversation,
      message,
      recipientCount: recipients.length,
      senderRole: req.isAdmin ? "admin" : "user"
    });
  } catch (error) {
    console.error("[Broadcast]", error);
    return res.status(500).json({
      success: false,
      error: error.message
    });
  }
});


