app.post(
  "/api/admin/documents/:email/:approvalKey/approval",
  adminAuth,
  async (req, res) => {
    try {
      if (!mongoConnected) {
        return res.status(503).json({
          success: false,
          error:
            "Database not connected"
        });
      }

      const email =
        await resolveCanonicalPipelineEmail(
          req.params.email
        );

      const approvalKey =
        decodeURIComponent(
          req.params.approvalKey
        );

      const action =
        String(
          req.body.action ||
          ""
        )
          .trim()
          .toLowerCase();

      const reason =
        String(
          req.body.reason ||
          ""
        ).trim();

      if (
        ![
          "approve",
          "reject"
        ].includes(action)
      ) {
        return res.status(400).json({
          success: false,
          error:
            "Action must be approve or reject"
        });
      }

      const now =
        new Date();

      const document =
        req.body.document ||
        {};

      const approvalStatus =
        action === "approve"
          ? "approved"
          : "rejected";

      const pendingId =
        String(
          document.pending_upload_id ||
          (
            String(
              document.source ||
              ""
            )
              .trim()
              .toLowerCase() ===
            "pending"
              ? (
                  document.attachment_id ||
                  ""
                )
              : ""
          )
        ).trim();

      let recruitUpload =
        null;

      let pendingRecord =
        null;

      if (
        pendingId &&
        mongoose.Types.ObjectId.isValid(
          pendingId
        )
      ) {
        pendingRecord =
          await mongoose.connection.db
            .collection(
              "pending_recruit_document_uploads"
            )
            .findOne({
              _id:
                new mongoose.Types.ObjectId(
                  pendingId
                ),
              candidate_email:
                email
            });
      }

      if (
        action === "approve" &&
        pendingRecord
      ) {
        if (
          !pendingRecord.file_base64
        ) {
          return res.status(409).json({
            success:
              false,
            error:
              "The pending Recruiting document no longer contains file data."
          });
        }

        try {
          recruitUpload =
            await uploadBufferToRecruitCandidate({
              email,
              buffer:
                Buffer.from(
                  pendingRecord.file_base64,
                  "base64"
                ),
              filename:
                pendingRecord.document_name ||
                pendingRecord.original_name ||
                "Recruiting Document",
              mimetype:
                pendingRecord.file_type ||
                "application/octet-stream",
              documentType:
                pendingRecord.document_type ||
                "Other"
            });
        } catch (recruitError) {
          console.error(
            "[Admin Document Approval] Recruit upload failed:",
            recruitError
          );

          return res.status(502).json({
            success:
              false,
            error:
              recruitError.message ||
              "Approval could not be completed because the document was not attached to Zoho Recruit."
          });
        }

        if (
          recruitUpload?.success !==
            true ||
          !recruitUpload
            ?.attachment_id ||
          !recruitUpload
            ?.record_id
        ) {
          return res.status(502).json({
            success:
              false,
            error:
              "Zoho Recruit did not confirm the approved document attachment."
          });
        }

        await logVerifiedDocument({
          email,
          name:
            pendingRecord.document_name ||
            pendingRecord.original_name ||
            "Recruiting Document",
          type:
            pendingRecord.document_type ||
            "Recruiting Document",
          size:
            pendingRecord.file_size ||
            0,
          mimetype:
            pendingRecord.file_type ||
            "application/octet-stream",
          crm:
            null,
          recruit:
            recruitUpload
        });

        await mongoose.connection.db
          .collection(
            "document_library_uploads"
          )
          .updateMany(
            {
              candidate_email:
                email,
              pending_upload_id:
                pendingId
            },
            {
              $set: {
                destination:
                  "recruit",
                source:
                  "recruit",
                recruit_attachment_id:
                  recruitUpload
                    .attachment_id,
                recruit_record_id:
                  recruitUpload
                    .record_id,
                approval_status:
                  "approved",
                already_approved:
                  true,
                approved_at:
                  now,
                approved_by:
                  String(
                    req.admin?.username ||
                    req.admin?.email ||
                    "Admin"
                  ),
                pending_storage:
                  false,
                updated_at:
                  now
              }
            }
          );

        if (
          pendingRecord
            .requirement_key
        ) {
          await mongoose.connection.db
            .collection(
              "hiring_required_documents"
            )
            .updateOne(
              {
                candidate_email:
                  email
              },
              {
                $set: {
                  [`documents.${pendingRecord.requirement_key}.recruit_attachment_id`]:
                    recruitUpload
                      .attachment_id,
                  [`documents.${pendingRecord.requirement_key}.recruit_record_id`]:
                    recruitUpload
                      .record_id,
                  [`documents.${pendingRecord.requirement_key}.verified`]:
                    true,
                  [`documents.${pendingRecord.requirement_key}.approval_status`]:
                    "approved",
                  [`documents.${pendingRecord.requirement_key}.approved_at`]:
                    now,
                  [`documents.${pendingRecord.requirement_key}.approved_by`]:
                    String(
                      req.admin?.username ||
                      req.admin?.email ||
                      "Admin"
                    ),
                  [`documents.${pendingRecord.requirement_key}.rejected_at`]:
                    null,
                  [`documents.${pendingRecord.requirement_key}.rejection_reason`]:
                    null,
                  updated_at:
                    now,
                  approval_updated_at:
                    now
                }
              }
            );
        }

        await mongoose.connection.db
          .collection(
            "pending_recruit_document_uploads"
          )
          .updateOne(
            {
              _id:
                new mongoose.Types.ObjectId(
                  pendingId
                )
            },
            {
              $set: {
                approval_status:
                  "approved",
                status:
                  "Uploaded to Recruit",
                recruit_attachment_id:
                  recruitUpload
                    .attachment_id,
                recruit_record_id:
                  recruitUpload
                    .record_id,
                approved_at:
                  now,
                approved_by:
                  String(
                    req.admin?.username ||
                    req.admin?.email ||
                    "Admin"
                  ),
                updated_at:
                  now
              },
              $unset: {
                file_base64:
                  ""
              }
            }
          );

        await synchronizePipelineFromDocumentLibrary(
          email
        );
      }

      if (
        action === "reject" &&
        pendingRecord
      ) {
        await mongoose.connection.db
          .collection(
            "pending_recruit_document_uploads"
          )
          .updateOne(
            {
              _id:
                pendingRecord._id
            },
            {
              $set: {
                approval_status:
                  "rejected",
                status:
                  "Rejected",
                rejected_at:
                  now,
                rejection_reason:
                  reason,
                updated_at:
                  now
              }
            }
          );

        await mongoose.connection.db
          .collection(
            "document_library_uploads"
          )
          .updateMany(
            {
              candidate_email:
                email,
              pending_upload_id:
                pendingId
            },
            {
              $set: {
                approval_status:
                  "rejected",
                already_approved:
                  false,
                rejected_at:
                  now,
                rejection_reason:
                  reason,
                updated_at:
                  now
              }
            }
          );

        if (
          pendingRecord
            .requirement_key
        ) {
          await mongoose.connection.db
            .collection(
              "hiring_required_documents"
            )
            .updateOne(
              {
                candidate_email:
                  email
              },
              {
                $set: {
                  [`documents.${pendingRecord.requirement_key}.approval_status`]:
                    "rejected",
                  [`documents.${pendingRecord.requirement_key}.verified`]:
                    false,
                  [`documents.${pendingRecord.requirement_key}.rejected_at`]:
                    now,
                  [`documents.${pendingRecord.requirement_key}.rejection_reason`]:
                    reason,
                  updated_at:
                    now,
                  approval_updated_at:
                    now
                }
              }
            );
        }
      }

      await mongoose.connection.db
        .collection(
          "document_approvals"
        )
        .updateOne(
          {
            candidate_email:
              email,
            approval_key:
              approvalKey
          },
          {
            $set: {
              candidate_email:
                email,
              approval_key:
                approvalKey,
              attachment_id:
                recruitUpload?.attachment_id ||
                document.attachment_id ||
                null,
              document_name:
                pendingRecord?.document_name ||
                document.document_name ||
                "Document",
              source:
                recruitUpload?.success === true
                  ? "recruit"
                  : (
                      document.source ||
                      "unknown"
                    ),
              recruit_record_id:
                recruitUpload?.record_id ||
                document.recruit_record_id ||
                null,
              pending_upload_id:
                pendingId ||
                null,
              crm_field_api_name:
                document.crm_field_api_name ||
                null,
              uploaded_at:
                document.uploaded_at ||
                null,
              approval_status:
                approvalStatus,
              approved_at:
                action === "approve"
                  ? now
                  : null,
              approved_by:
                action === "approve"
                  ? String(
                      req.admin?.username ||
                      req.admin?.email ||
                      "Admin"
                    )
                  : null,
              rejected_at:
                action === "reject"
                  ? now
                  : null,
              rejection_reason:
                action === "reject"
                  ? reason
                  : null,
              updated_at:
                now
            },
            $setOnInsert: {
              created_at:
                now
            }
          },
          {
            upsert: true
          }
        );

      return res.json({
        success: true,
        approval_key:
          approvalKey,
        approval_status:
          approvalStatus,
        approved_at:
          action === "approve"
            ? now
            : null,
        rejection_reason:
          action === "reject"
            ? reason
            : null
      });
    } catch (error) {
      console.error(
        "[Admin Document Approval]",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message ||
          "Unable to update approval"
      });
    }
  }
);

