app.post(
  "/api/admin/document-approvals/:email/:requirementKey",
  adminAuth,
  async (req, res) => {
    try {
      if (!mongoConnected) {
        return res.status(503).json({
          success: false,
          error: "Database not connected"
        });
      }

      const email = normalizePipelineEmail(req.params.email);
      const requirementKey = String(req.params.requirementKey || "").trim();
      const action = String(req.body.action || "").trim().toLowerCase();
      const reason = String(req.body.reason || "").trim();

      if (!REQUIRED_DOCUMENT_DEFINITIONS[requirementKey]) {
        return res.status(400).json({
          success: false,
          error: "Unknown required document"
        });
      }

      if (!["approve", "reject"].includes(action)) {
        return res.status(400).json({
          success: false,
          error: "Action must be approve or reject"
        });
      }

      const collection =
        mongoose.connection.db.collection("hiring_required_documents");
      const current = await collection.findOne({
        candidate_email: email
      });
      const document = current?.documents?.[requirementKey];

      if (!document?.verified) {
        return res.status(404).json({
          success: false,
          error: "The candidate has not submitted this document"
        });
      }

      const now = new Date();
      const approvalStatus =
        action === "approve" ? "approved" : "rejected";

      await collection.updateOne(
        { candidate_email: email },
        {
          $set: {
            [`documents.${requirementKey}.approval_status`]:
              approvalStatus,
            [`documents.${requirementKey}.approved_at`]:
              action === "approve" ? now : null,
            [`documents.${requirementKey}.approved_by`]:
              action === "approve"
                ? String(req.admin?.username || req.admin?.email || "Admin")
                : null,
            [`documents.${requirementKey}.rejected_at`]:
              action === "reject" ? now : null,
            [`documents.${requirementKey}.rejection_reason`]:
              action === "reject" ? reason : null,
            approval_updated_at: now
          }
        }
      );

      const summary =
        await getHiringDocumentApprovalSummary(email);

      await collection.updateOne(
        { candidate_email: email },
        {
          $set: {
            all_submitted:
              summary.submitted ===
              REQUIRED_HIRING_DOCUMENT_KEYS.length,
            all_approved: summary.complete,
            completed_at: summary.complete ? now : null
          }
        }
      );

      let stage = null;
      if (summary.complete && PipelineStage) {
        stage = await PipelineStage.findOneAndUpdate(
          {
            candidate_email: email,
            stage_name: {
              $in: [
                "Required Document Upload",
                "Documents Received"
              ]
            }
          },
          {
            $set: {
              status: "Completed",
              completed_date: now,
              updated_at: now,
              timing_status: "Good Standing"
            }
          },
          {
            new: true,
            sort: { stage_order: 1 }
          }
        );

        if (stage) {
          const nextStage = await PipelineStage.findOne({
            candidate_email: email,
            is_deleted: { $ne: true },
            stage_order: { $gt: stage.stage_order },
            status: { $ne: "Completed" }
          }).sort({ stage_order: 1 });

          if (nextStage) {
            const durationHours =
              Math.max(0, Number(nextStage.duration_hours || 0));
            await PipelineStage.findByIdAndUpdate(
              nextStage._id,
              {
                $set: {
                  status: "In Progress",
                  started_at: now,
                  target_date: new Date(
                    now.getTime() +
                    durationHours * 60 * 60 * 1000
                  ),
                  timing_status: "Good Standing",
                  updated_at: now
                }
              }
            );
          }
        }
      }

      return res.json({
        success: true,
        action,
        requirementKey,
        stage,
        ...summary
      });
    } catch (error) {
      console.error("[Document Approval]", error);
      return res.status(500).json({
        success: false,
        error: error.message
      });
    }
  }
);


app.post(
  "/api/messaging/user-broadcast",
  authenticateToken,
  async (req, res) => {
    try {
      const senderEmail =
        normalizePipelineEmail(
          req.userEmail
        );

      const content =
        String(
          req.body.content ||
          ""
        ).trim();

      if (
        !senderEmail ||
        !content
      ) {
        return res.status(400).json({
          success: false,
          error:
            "Message is required"
        });
      }

      const conversation =
        await getOrCreateCommunityConversation();

      const senderName =
        await getUserName(
          senderEmail
        );

      const message =
        await Message.create({
          conversationId:
            conversation._id,
          senderEmail,
          senderName,
          content,
          messageType:
            "text",
          broadcast:
            true,
          isRead:
            false,
          createdAt:
            new Date()
        });

      conversation.lastMessage =
        message._id;
      conversation.lastMessageAt =
        message.createdAt;
      conversation.updatedAt =
        new Date();

      await conversation.save();

      const recipients =
        (conversation.participants || [])
          .filter(
            participant =>
              participant !==
                "admin" &&
              Boolean(
                normalizePipelineEmail(
                  participant
                )
              )
          );

      broadcastToUsers(
        recipients,
        {
          type:
            "new_message",
          conversationId:
            CANDIDATE_COMMUNITY_CONVERSATION_ID,
          message: {
            ...(
              message.toObject
                ? message.toObject()
                : message
            ),
            conversationId:
              CANDIDATE_COMMUNITY_CONVERSATION_ID,
            broadcast:
              true
          }
        }
      );

      return res.json({
        success: true,
        conversation: {
          _id:
            CANDIDATE_COMMUNITY_CONVERSATION_ID,
          type:
            "community",
          groupName:
            "Community Messages"
        },
        message,
        recipientCount:
          Math.max(
            recipients.length - 1,
            0
          )
      });
    } catch (error) {
      console.error(
        "[Community Message]",
        error
      );

      return res.status(500).json({
        success: false,
        error:
          error.message
      });
    }
  }
);


const AFTERCARE_STAGE_CONFIG = [
  { stage_name: "Welcome Call/24 Hour Call", days_from_arrival: 1, stage_order: 41 },
  { stage_name: "Relocation Survey", days_from_arrival: 2, stage_order: 42 },
  { stage_name: "Concierge Debrief", days_from_arrival: 3, stage_order: 43, internal_only: true, hidden_from_candidate: true, candidate_read_only: true },
  { stage_name: "7 Day Call", days_from_arrival: 7, stage_order: 44 },
  { stage_name: "2 Week Call", days_from_arrival: 14, stage_order: 45 },
  { stage_name: "U.S. Integration Call (30 Day Call / Survey)", days_from_arrival: 30, stage_order: 46 },
  { stage_name: "Placement Stability Check-in (90 Day Call)", days_from_arrival: 90, stage_order: 47 },
  { stage_name: "1 Year Survey", days_from_arrival: 365, stage_order: 48 }
];

async function ensureAftercareStageShape(
  candidateEmail
) {
  if (!mongoConnected) {
    return;
  }

  const email =
    normalizePipelineEmail(
      candidateEmail
    );

  const now =
    new Date();

  for (
    const config of
    AFTERCARE_STAGE_CONFIG
  ) {
    await PipelineStage.findOneAndUpdate(
      {
        candidate_email:
          email,
        stage_name:
          config.stage_name
      },
      {
        $set: {
          stage_category:
            "Aftercare",
          stage_order:
            config.stage_order,
          days_from_arrival:
            config.days_from_arrival,
          hidden_from_main_flow:
            config.hidden_from_main_flow === true,
          internal_only:
            config.internal_only === true,
          non_counted_section:
            config.non_counted_section === true,
          updated_at:
            now
        },
        $setOnInsert: {
          candidate_email:
            email,
          stage_name:
            config.stage_name,
          status:
            "Not Started",
          completed_date:
            null,
          is_gate:
            false,
          auto_complete:
            false,
          is_deleted:
            false,
          created_at:
            now
        },
        $set: {
          stage_category:
            "Aftercare",
          stage_order:
            config.stage_order,
          days_from_arrival:
            config.days_from_arrival,
          hidden_from_main_flow:
            config.hidden_from_main_flow === true,
          internal_only:
            config.internal_only === true,
          non_counted_section:
            config.non_counted_section === true,
          updated_at:
            now
        }
      },
      {
        upsert: true,
        new: true
      }
    );
  }

  const desiredNames =
    new Set(
      AFTERCARE_STAGE_CONFIG.map(
        item =>
          item.stage_name
      )
    );

  await PipelineStage.deleteMany({
    candidate_email: email,
    stage_category: "Aftercare",
    stage_name: {
      $nin: [...desiredNames]
    }
  });
}

app.get(
  "/api/pipeline/aftercare-gate",
  authenticateToken,
  async (req, res) => {
    try {
      const email = normalizePipelineEmail(
        req.userEmail
      );

      if (!email) {
        return res.status(400).json({
          success: false,
          error: "Email is required"
        });
      }

      await ensureAftercareStageShape(
        email
      );

      // Query CRM directly instead of depending on a cached comprehensive
      // candidate response.
      const deals =
        await searchDealsByEmail(
          email,
          {
            forceRefresh:
              true
          }
        );

      const latestDealSummary = [...(deals || [])].sort(
        (first, second) => {
          const firstHasArrival =
            first?.Flight_Arrival_Time !== undefined &&
            first?.Flight_Arrival_Time !== null &&
            String(first.Flight_Arrival_Time).trim() !== "";

          const secondHasArrival =
            second?.Flight_Arrival_Time !== undefined &&
            second?.Flight_Arrival_Time !== null &&
            String(second.Flight_Arrival_Time).trim() !== "";

          if (firstHasArrival !== secondHasArrival) {
            return secondHasArrival ? 1 : -1;
          }

          return (
            new Date(
              second.Modified_Time ||
              second.Created_Time ||
              0
            ).getTime() -
            new Date(
              first.Modified_Time ||
              first.Created_Time ||
              0
            ).getTime()
          );
        }
      )[0] || {};

      let latestDeal = latestDealSummary;

      if (latestDealSummary.id) {
        try {
          const zohoToken = await getValidZohoToken();
          const fullDealResponse = await axios.get(
            `${ZOHO_CRM_URL}/crm/v3/Deals/${latestDealSummary.id}`,
            {
              headers: {
                Authorization: `Zoho-oauthtoken ${zohoToken}`
              },
              timeout: 30000
            }
          );

          latestDeal =
            fullDealResponse.data?.data?.[0] ||
            latestDealSummary;
        } catch (fullDealError) {
          console.warn(
            "[Aftercare Gate] Full CRM Deal fetch failed; using search result:",
            fullDealError.message
          );
        }
      }

      let rawArrival =
        latestDeal.Flight_Arrival_Time ||
        null;

      if (!rawArrival) {
        const otherDealSummaries = (deals || [])
          .filter(item => item?.id && String(item.id) !== String(latestDealSummary?.id || ""))
          .slice(0, 4);

        for (const otherSummary of otherDealSummaries) {
          try {
            const zohoToken = await getValidZohoToken();
            const otherResponse = await axios.get(
              `${ZOHO_CRM_URL}/crm/v3/Deals/${otherSummary.id}`,
              {
                headers: {
                  Authorization: `Zoho-oauthtoken ${zohoToken}`
                },
                timeout: 30000
              }
            );

            const otherDeal =
              otherResponse.data?.data?.[0] ||
              otherSummary;

            if (otherDeal?.Flight_Arrival_Time) {
              latestDeal = otherDeal;
              rawArrival = otherDeal.Flight_Arrival_Time;
              break;
            }
          } catch (otherArrivalError) {
            console.warn(
              "[Aftercare Gate] Alternate Deal arrival lookup failed:",
              otherArrivalError.message
            );
          }
        }
      }

      const arrivalDate =
        parseZohoDateTime(
          rawArrival
        );

      const arrivalDateReached =
        isZohoDateTodayOrPast(
          rawArrival
        );

      if (
        !arrivalDate ||
        !arrivalDateReached
      ) {
        await PipelineStage.updateMany(
          {
            candidate_email: email,
            stage_category: "Aftercare",
            is_deleted: { $ne: true }
          },
          {
            $set: {
              aftercare_unlocked: false,
              aftercare_locked: true,
              aftercare_gate_date: null,
              target_date: null,
              updated_at: new Date()
            }
          }
        );

        return res.json({
          success: true,
          unlocked: false,
          arrivalDate:
            arrivalDate
              ? arrivalDate.toISOString()
              : null,
          rawArrival:
            rawArrival ||
            null,
          sourceField:
            "Flight_Arrival_Time",
          comparisonMode:
            "calendar_date_today_or_past",
          todayForArrivalTimezone:
            rawArrival
              ? getZohoDateKeyForNow(
                  rawArrival
                )
              : null,
          reason:
            arrivalDate
              ? "arrival_calendar_date_is_in_the_future"
              : "arrival_not_available"
        });
      }

      const aftercareStages = await PipelineStage.find({
        candidate_email: email,
        stage_category: "Aftercare",
        is_deleted: { $ne: true }
      });

      const now = new Date();

      for (const stage of aftercareStages) {
        const daysFromArrival = Number(
          stage.days_from_arrival || 0
        );

        const targetDate = new Date(
          arrivalDate.getTime() +
          daysFromArrival * 24 * 60 * 60 * 1000
        );

        const stageUpdate = {
          aftercare_unlocked: true,
          aftercare_locked: false,
          aftercare_gate_date: arrivalDate,
          target_date: targetDate,
          updated_at: now
        };

        // The first Aftercare item is immediately available at arrival.
        if (
          daysFromArrival === 0 &&
          !isPipelineStageCompletedRecord(stage)
        ) {
          stageUpdate.status =
            stage.status === "Completed"
              ? "Completed"
              : "In Progress";
          stageUpdate.started_at =
            stage.started_at || arrivalDate;
        }

        await PipelineStage.findByIdAndUpdate(
          stage._id,
          {
            $set: stageUpdate
          }
        );
      }

      return res.json({
        success: true,
        unlocked: true,
        arrivalDate:
          arrivalDate.toISOString(),
        rawArrival,
        sourceField:
          "Flight_Arrival_Time",
        comparisonMode:
          "calendar_date_today_or_past",
        todayForArrivalTimezone:
          getZohoDateKeyForNow(
            rawArrival
          )
      });
    } catch (error) {
      console.error(
        "[Aftercare Gate] Error:",
        error.response?.data || error
      );

      return res.status(500).json({
        success: false,
        error:
          error.response?.data?.message ||
          error.message ||
          "Unable to evaluate Aftercare gate"
      });
    }
  }
);



app.post(
  "/api/pipeline/deploymate-complete",
  authenticateToken,
  async (req, res) => {
    try {
      const email = normalizePipelineEmail(req.userEmail);

      if (!email) {
        return res.status(400).json({
          success: false,
          error: "Authenticated candidate email is required."
        });
      }

      const now = new Date();

      const stage = await PipelineStage.findOneAndUpdate(
        {
          candidate_email: email,
          stage_name: "deployMate Ready",
          is_deleted: { $ne: true }
        },
        {
          $set: {
            status: "Completed",
            completed: true,
            is_completed: true,
            completed_date: now,
            completion_source: "candidate_deploymate_link",
            source_trigger_unlocked: true,
            trigger_unlocked: true,
            updated_at: now
          },
          $setOnInsert: {
            candidate_email: email,
            stage_name: "deployMate Ready",
            stage_category: "Deployment",
            stage_order: 37,
            is_deleted: false,
            created_at: now
          }
        },
        {
          upsert: true,
          new: true,
          setDefaultsOnInsert: true
        }
      );

      invalidateCandidateDetailsCache?.(email);

      broadcastToUsers(
        [email],
        {
          type: "pipeline-updated",
          event: "deploymate-completed",
          source: "candidate_action",
          candidateEmail: email,
          stageStatus: {
            "deployMate Ready": {
              stage_name: "deployMate Ready",
              completed: true,
              is_completed: true,
              status: "Completed",
              unlocked: true,
              completed_date: now.toISOString()
            }
          },
          completionMap: {
            "deployMate Ready": true
          },
          changedFields: {},
          timestamp: now.toISOString()
        }
      );

      return res.json({
        success: true,
        stage
      });
    } catch (error) {
      console.error("[deployMate Completion]", error);
      return res.status(500).json({
        success: false,
        error: error?.message || "Unable to complete deployMate stage."
      });
    }
  }
);

app.post(
  "/api/pipeline/acknowledge-welcome-packet",
  authenticateToken,
  async (req, res) => {
    try {
      const email =
        normalizePipelineEmail(
          req.userEmail
        );

      if (!email) {
        return res.status(400).json({
          success: false,
          error: "Authenticated candidate email is required"
        });
      }

      if (!mongoConnected || !PipelineStage) {
        return res.status(503).json({
          success: false,
          error: "Pipeline database is unavailable"
        });
      }

      const now = new Date();

      let stage = await PipelineStage.findOneAndUpdate(
        {
          candidate_email: email,
          stage_name: "Arrival Itinerary",
          is_deleted: { $ne: true }
        },
        {
          $set: {
            stage_name: "Arrival Itinerary",
            stage_category: "Deployment",
            stage_order: 38,
            status: "Completed",
            completed: true,
            is_completed: true,
            completed_date: now,
            acknowledged_at: now,
            acknowledged_by: email,
            acknowledgement_source: "welcome_packet",
            source_trigger_unlocked: true,
            trigger_unlocked: true,
            timing_status: "Good Standing",
            updated_at: now
          },
          $setOnInsert: {
            candidate_email: email,
            created_at: now,
            is_deleted: false
          }
        },
        {
          new: true,
          upsert: true,
          setDefaultsOnInsert: true
        }
      );

      await PipelineStage.deleteMany({
        candidate_email: email,
        stage_name: {
          $in: [
            "ICP Welcome Packet",
            "ICP Welcome Packet & Itinerary",
            "Welcome Packet"
          ]
        }
      }).catch(error =>
        console.warn(
          "[Welcome Packet Acknowledgement] Legacy-row cleanup failed:",
          error.message
        )
      );

      pipelineFieldStatusResponseCache?.delete?.(email);
      pipelineLiveRefreshAt?.delete?.(email);
      pipelineLiveCrmStateCache?.delete?.(email);
      invalidateCandidateDetailsCache?.(email);

      const completedDate =
        stage?.completed_date instanceof Date
          ? stage.completed_date.toISOString()
          : (stage?.completed_date || now.toISOString());

      const realtimeStage = {
        stage_name: "Arrival Itinerary",
        completed: true,
        is_completed: true,
        status: "Completed",
        completed_date: completedDate,
        acknowledged_at: now.toISOString(),
        unlocked: true,
        source_fields: ["candidate_acknowledgement"]
      };

      const realtimeDeliveries =
        broadcastToUsers(
          [email],
          {
            type: "pipeline-updated",
            event: "welcome-packet-acknowledged",
            source: "candidate_action",
            candidateEmail: email,
            stageStatus: {
              "Arrival Itinerary": realtimeStage
            },
            completionMap: {
              "Arrival Itinerary": true
            },
            changedFields: {},
            timestamp: now.toISOString()
          }
        );

      const nextStage = await PipelineStage.findOne({
        candidate_email: email,
        stage_name: "Receipt Submission",
        is_deleted: { $ne: true }
      });

      if (
        nextStage &&
        nextStage.completed !== true &&
        nextStage.is_completed !== true
      ) {
        await PipelineStage.findByIdAndUpdate(
          nextStage._id,
          {
            $set: {
              status: "In Progress",
              started_at: nextStage.started_at || now,
              source_trigger_unlocked: true,
              trigger_unlocked: true,
              timing_status: "Good Standing",
              updated_at: now
            }
          }
        );
      }

      return res.json({
        success: true,
        stage,
        stage_name: "Arrival Itinerary",
        completed: true,
        completed_date: completedDate,
        acknowledged_at: now.toISOString(),
        realtimeDeliveries,
        nextStage: nextStage ? "Receipt Submission" : null
      });
    } catch (error) {
      console.error("[Welcome Packet Acknowledgement]", error);
      return res.status(500).json({
        success: false,
        error: error.message || "Unable to acknowledge the Welcome Packet"
      });
    }
  }
);

